(90455, 30182, 'es', 'Galápagos Land Iguana', 'The Galápagos Land Iguana is a very large species of lizard in the family Iguanidae. Galápagos Land Iguanas are large, yellow lizards, one of three species of land iguanas. Being cold-blooded, they absorb heat from the sun by basking on volcanic rock, and at night sleep in burrows to conserve their body heat. These iguanas also enjoy a symbiotic relationship with birds; the birds remove parasites and ticks, providing relief to the iguanas and food for the birds.\n\nLand Iguanas are primarily herbivorous, however, some individuals may be carnivores supplementing their diet with insects, centipedes, and carrion. They obtain the majority of their moisture from the prickly-pear cactus, which makes up 80% of its diet.\n\n'),
(90996, 209, 'en', 'Aardwolf', 'The aardwolf looks a bit like a small hyena but mainly feeds on termites. With its long tongue, it licks the insects straight out of their mounds, making it quite the specialist. In your zoo, it sniffs the ground attentively and is always delighted to find a hidden snack.'),
(90997, 209, 'de', 'Erdwolf', 'Der Erdwolf sieht ein bisschen aus wie eine kleine Hyäne, frisst aber vor allem Termiten. Mit seiner langen Zunge leckt er die Insekten aus ihren Bauten und ist damit ein ganz besonderer Spezialist. In deinem Zoo schnuppert er aufmerksam am Boden und freut sich über jedes Futterversteck.'),
(90998, 209, 'da', 'Jordulv', 'Jordulven ligner lidt en lille hyæne, men lever primært af termitter. Med sin lange tunge slikker den insekterne ud af deres boliger. I din zoo snuser den opmærksomt til jorden og fryder sig over hvert futterskjul.'),
(90999, 30129, 'en', 'Adélie Penguin', 'Adélie Penguins is a species of penguin common along the entire coast of the Antarctic continent, which is the only place where it is found.  They spend the winter offshore in the seas surrounding the Antarctic pack ice. The adult is black on the head, throat and upperparts, with snowy white underparts. It has a conspicuous white eye ring around a black iris. \n\nAdélies feed on tiny aquatic creatures, such as shrimp-like krill, but also eat fish and squid.'),
(91000, 30129, 'de', 'Adélie Penguin', 'Adélie Penguins is a species of penguin common along the entire coast of the Antarctic continent, which is the only place where it is found.  They spend the winter offshore in the seas surrounding the Antarctic pack ice. The adult is black on the head, throat and upperparts, with snowy white underparts. It has a conspicuous white eye ring around a black iris. \n\nAdélies feed on tiny aquatic creatures, such as shrimp-like krill, but also eat fish and squid.'),
(91001, 30129, 'da', 'Adélie Penguin', 'Adélie Penguins is a species of penguin common along the entire coast of the Antarctic continent, which is the only place where it is found.  They spend the winter offshore in the seas surrounding the Antarctic pack ice. The adult is black on the head, throat and upperparts, with snowy white underparts. It has a conspicuous white eye ring around a black iris. \n\nAdélies feed on tiny aquatic creatures, such as shrimp-like krill, but also eat fish and squid.'),
(91002, 501, 'en', 'African Civet', 'The African Civet is a nocturnal predator with a distinctive, pungent scent. Its secretions were once even used in perfume production. In your zoo, it slips quietly through the night enclosures and mostly stays in the half‑dark.'),
(91003, 501, 'de', 'Afrikanische Zibetkatze', 'Die Afrikanische Zibetkatze ist ein nachtaktives Raubtier mit eigenwilligem Duft. Früher wurden ihre Duftstoffe sogar in der Parfümherstellung genutzt. In deinem Zoo streift sie leise durch die Nachtbereiche und hält sich meist im Halbdunkel.'),
(91004, 501, 'da', 'Gnuer', 'Gnuerne vandrer i enorme flokke over Afrikas savanner og er essentielle for økosystemets balance. Deres massive migrationer er et af naturens største spektakler.'),
(91005, 805, 'en', 'African Penguin', 'The jackass penguin gets its name from the bright markings around its eyes. It lives along the coasts of South Africa. In your zoo it spreads cheer with its waddling walk and graceful dives.'),
(91006, 805, 'de', 'Brillenpinguin', 'Der Brillenpinguin verdankt seinen Namen einer hellen Zeichnung um die Augen. Er lebt an den Küsten Südafrikas. In deinem Zoo sorgt er mit seinen watschelnden Bewegungen und eleganten Tauchgängen für gute Laune.'),
(91007, 805, 'da', 'Delfin', 'Delfiner er ekstremt intelligente havpattedyr med komplekse sociale strukturer. De kommunikerer ved hjælp af et rigt repertoire af kliks, fløjt og andre lyde. De er kendte for at hjælpe nødlidende svømmere.'),
(91008, 401, 'en', 'African wild ass', 'The African wild ass is the wild ancestor of our domestic donkeys and adapted to dry steppe regions. It often has gray fur with dark legs and shoulder stripes. In your zoo it shows its robust side and occasionally calls across the enclosure with a loud bray.'),
(91009, 401, 'de', 'Afrikanischer Esel', 'Der Afrikanische Esel ist der wilde Vorfahr unserer Hausesel und an trockene Steppengebiete angepasst. Er besitzt oft ein graues Fell mit dunklen Beinen und Schulterstreifen. In deinem Zoo zeigt er seine robuste Seite und ruft gelegentlich mit kräftigem I-A über die Anlage.'),
(91010, 401, 'da', 'Afrikansk vildesel', 'Det afrikanske vildesel er forfader til vores tamæsler og tilpasset tørre steppeegne. Det har ofte gråt pels med mørke ben og skulderstriper. I din zoo viser det sin robuste side og brøler lejlighedsvis kraftigt over anlægget.'),
(91011, 505, 'en', 'African Wild Dog', 'The African Wild Dog is called several other names, including \"Painted Hunting Dog” and “Cape Hunting Dog.”  They are found primarily in eastern and southern Africa.  African Wild Dogs live in tightly knit social groups of between two and 27 individuals. Their short coat hair is in yellow, gray, white and black patches. No two dogs have the same markings and colorations, making it easy for conservationists to identify individuals. \n\nAfrican Wild Dogs are highly specialized for a carnivorous diet. They hunt gazelles and other antelopes, warthogs, wildebeest and their calves, ostrich, and calves of African buffalo. \n\nThe African Wild Dog (Lycaon pictus) is strongly endangered/listed as Endangered on the IUCN Red List due to illegal human predation.'),
(91012, 505, 'de', 'African Wild Dog', 'The African Wild Dog is called several other names, including \"Painted Hunting Dog” and “Cape Hunting Dog.”  They are found primarily in eastern and southern Africa.  African Wild Dogs live in tightly knit social groups of between two and 27 individuals. Their short coat hair is in yellow, gray, white and black patches. No two dogs have the same markings and colorations, making it easy for conservationists to identify individuals. \n\nAfrican Wild Dogs are highly specialized for a carnivorous diet. They hunt gazelles and other antelopes, warthogs, wildebeest and their calves, ostrich, and calves of African buffalo. \n\nThe African Wild Dog (Lycaon pictus) is strongly endangered/listed as Endangered on the IUCN Red List due to illegal human predation.'),
(91013, 505, 'da', 'African Wild Dog', 'The African Wild Dog is called several other names, including \"Painted Hunting Dog” and “Cape Hunting Dog.”  They are found primarily in eastern and southern Africa.  African Wild Dogs live in tightly knit social groups of between two and 27 individuals. Their short coat hair is in yellow, gray, white and black patches. No two dogs have the same markings and colorations, making it easy for conservationists to identify individuals. \n\nAfrican Wild Dogs are highly specialized for a carnivorous diet. They hunt gazelles and other antelopes, warthogs, wildebeest and their calves, ostrich, and calves of African buffalo. \n\nThe African Wild Dog (Lycaon pictus) is strongly endangered/listed as Endangered on the IUCN Red List due to illegal human predation.'),
(91014, 30126, 'en', 'African Wolf', 'The African Wolf, also known as the African Golden Wolf, is a canid native to sub-Saharan Africa. It inhabits savannas, woodlands, and arid deserts. With golden-brown fur, pointed ears, and a bushy tail, it resembles a mix of wolf and jackal. It\'s known for its adaptability and social behavior in packs.\n\nIts diet mainly consists of small mammals like rodents and hares, birds, reptiles, and occasionally fruits or insects, supplemented by scavenging.'),
(91015, 30126, 'de', 'African Wolf', 'The African Wolf, also known as the African Golden Wolf, is a canid native to sub-Saharan Africa. It inhabits savannas, woodlands, and arid deserts. With golden-brown fur, pointed ears, and a bushy tail, it resembles a mix of wolf and jackal. It\'s known for its adaptability and social behavior in packs.\n\nIts diet mainly consists of small mammals like rodents and hares, birds, reptiles, and occasionally fruits or insects, supplemented by scavenging.'),
(91016, 30126, 'da', 'African Wolf', 'The African Wolf, also known as the African Golden Wolf, is a canid native to sub-Saharan Africa. It inhabits savannas, woodlands, and arid deserts. With golden-brown fur, pointed ears, and a bushy tail, it resembles a mix of wolf and jackal. It\'s known for its adaptability and social behavior in packs.\n\nIts diet mainly consists of small mammals like rodents and hares, birds, reptiles, and occasionally fruits or insects, supplemented by scavenging.'),
(91020, 129, 'en', 'Alligator Snapping Turtle', 'The Snapping Turtle is an impressively large freshwater turtle with a powerful jaw. It seems sluggish but can snap lightning-fast when prey is within reach. In the zoo, it often lies on the pond bottom or suns on a rock while visitors admire its prehistoric look.'),
(91021, 129, 'de', 'Schnappschildkröte', 'Die Schnappschildkröte ist eine beeindruckend große Süßwasserschildkröte mit kräftigem Kiefer. Sie wirkt träge, kann aber blitzschnell zuschnappen, wenn Beute in Reichweite kommt. Im Zoo liegt sie oft am Beckenboden oder sonnt sich auf einem Stein, während Besucher ihren urzeitlichen Look bestaunen.'),
(91022, 129, 'da', 'Alligatorskilpadde', 'Alligatorskilpadden er en imponerende stor ferskvandsskilpadde med kraftige kæber. Den virker doven, men kan hugge til lynhurtigt, når bytte er inden for rækkevidde. I din zoo ligger den ofte på bunden af bassinet.'),
(91023, 402, 'en', 'Alpaca', 'The alpaca, with its fluffy fur and gentle look, is a favorite among many visitors. It comes from the Andes and is kept mainly for its soft wool. In your zoo it strolls curiously through its enclosure and happily poses for photos from a respectful distance.'),
(91024, 402, 'de', 'Alpaka', 'Das Alpaka ist mit seinem flauschigen Fell und dem sanften Blick ein Liebling vieler Besucher. Es stammt aus den Anden und wird vor allem wegen seiner weichen Wolle gehalten. In deinem Zoo spaziert es neugierig durch das Gehege und lässt sich mit etwas Sicherheitsabstand gern fotografieren.'),
(91025, 402, 'da', 'Alpaka', 'Alpakaen med sit fluffy pels og bløde blik er en favorit hos mange besøgende. Den stammer fra Andesbjergene og holdes primært for sin bløde uld. I din zoo slentrer den nysgerrigt igennem sit anlæg og lader sig gerne fotografere på respektful afstand.'),
(91026, 404, 'en', 'Alpine Ibex', 'The Alpine ibex is a true climbing expert that effortlessly scales steep rock faces. Its powerful horns and sturdy body make it unmistakable. In your zoo it uses rocky structures with ease and shows visitors what balance really means.'),
(91027, 404, 'de', 'Alpensteinbock', 'Der Alpensteinbock ist ein Kletterkünstler, der steile Felswände mühelos erklimmt. Seine mächtigen Hörner und der kräftige Körperbau machen ihn unverwechselbar. In deinem Zoo nutzt er Felsstrukturen mit Leichtigkeit und zeigt Besuchern, was Balance bedeutet.'),
(91028, 404, 'da', 'Alpenstenbuk', 'Alpenstenbukken er en klatreekspert, der ubesværet klatrer ad stejle klippevægge. Dens kraftige horn og robuste krop gør den umiskendelig. I din zoo bruger den klippestrukturer med lethed og viser besøgende, hvad balance virkelig betyder.'),
(91029, 30127, 'en', 'Alpine Marmot', 'The Alpine Marmot is a large ground-dwelling squirrel, from the genus of marmots. An adult Alpine Marmot is between 43 and 73 cm (17–29 in) in head-and-body length and the tail measures from 13 to 20 cm (5–8 in), its coat is a mixture of blonde, reddish and dark gray fur. \nAlpine Marmots eat plants such as grasses and herbs, as well as grain, insects, spiders and worms. \n\nThese animals are excellent diggers, their habitat is typically sub-alpine and alpine meadows and pastures, where they live in colonies in rocky areas in alluvial soil in deep burrow systems.'),
(91030, 30127, 'de', 'Alpine Marmot', 'The Alpine Marmot is a large ground-dwelling squirrel, from the genus of marmots. An adult Alpine Marmot is between 43 and 73 cm (17–29 in) in head-and-body length and the tail measures from 13 to 20 cm (5–8 in), its coat is a mixture of blonde, reddish and dark gray fur. \nAlpine Marmots eat plants such as grasses and herbs, as well as grain, insects, spiders and worms. \n\nThese animals are excellent diggers, their habitat is typically sub-alpine and alpine meadows and pastures, where they live in colonies in rocky areas in alluvial soil in deep burrow systems.'),
(91031, 30127, 'da', 'Alpine Marmot', 'The Alpine Marmot is a large ground-dwelling squirrel, from the genus of marmots. An adult Alpine Marmot is between 43 and 73 cm (17–29 in) in head-and-body length and the tail measures from 13 to 20 cm (5–8 in), its coat is a mixture of blonde, reddish and dark gray fur. \nAlpine Marmots eat plants such as grasses and herbs, as well as grain, insects, spiders and worms. \n\nThese animals are excellent diggers, their habitat is typically sub-alpine and alpine meadows and pastures, where they live in colonies in rocky areas in alluvial soil in deep burrow systems.'),
(91032, 801, 'en', 'Amazon River Dolphin', 'The Amazon river dolphin, also called Boto, has a pinkish hue in the murky river water. It lives in the rivers of the Amazon basin. In your zoo it enchants visitors with its playful nature and special shades of color.'),
(91033, 801, 'de', 'Amazonas Delfin', 'Der Amazonas-Delfin, auch Boto genannt, besitzt eine rosa Färbung im trüben Flusswasser. Er lebt in den Flüssen des Amazonasbeckens. In deinem Zoo verzaubert er Besucher mit seiner verspielten Art und den besonderen Farbnuancen.'),
(91034, 801, 'da', 'Stor hvid haj', 'Den store hvide haj er et af havets mest frygtede rovdyr. Den kan vokse til over 6 meter og er udstyret med rækker af udskiftelige tænder. Den er faktisk ikke specielt interesseret i at spise mennesker.'),
(91035, 234, 'en', 'American Badger', 'The silver badger is a small, badger-like predator with striking fur markings. It lives a secretive life and is mostly active at dusk. In the zoo it digs eagerly in the ground and only occasionally rewards patient visitors with a glimpse.'),
(91036, 234, 'de', 'Silberdachs', 'Der Silberdachs ist ein kleiner, dachsartiger Räuber mit auffälliger Fellzeichnung. Er lebt zurückgezogen und ist meist in der Dämmerung aktiv. Im Zoo gräbt er eifrig im Boden und zeigt sich nur gelegentlich den geduldigen Besuchern.'),
(91037, 234, 'da', 'Amerikansk grævling', 'Den amerikanske sølvgrævling er et lille, grævlingelignende rovdyr med iøjnefaldende pelsmarkering. Den lever skjult og er primært aktiv i tusmørket. I din zoo graver den ivrigt i jorden og viser sig kun lejlighedsvis for tålmodige besøgende.'),
(91044, 210, 'en', 'American Hog-Nosed Skunk', 'The hog-nosed skunk gets its name from its slightly pig-like snout combined with the classic skunk markings. It\'s nocturnal and relies on its famous scent defense when threatened. In your zoo, it usually appears in the evening hours and charms visitors with its clumsy, endearing walk.'),
(91045, 210, 'de', 'Ferkelskunk', 'Der Ferkelskunk verdankt seinen Namen seiner leicht schweineartigen Schnauze, kombiniert mit der typischen Skunk-Zeichnung. Er ist nachtaktiv und verlässt sich bei Gefahr auf seinen berühmten Duftverteidigungs-Trick. Im Zoo zeigt er sich meist in den Abendstunden und sorgt mit seinem tapsigen Gang für viel Interesse.'),
(91046, 210, 'da', 'Grisestinkdyr', 'Griselugtedyret er nattaktivt og baserer sig ved fare på sin berømte duftforsvar. I din zoo viser det sig normalt i aftentimerne og charmerer besøgende med sin kluntede, elskelige gang.'),
(91047, 30130, 'en', 'Amethyst Starling', 'The Amethyst Starling, also called purple starling, is a small, dazzling iridescent bird with glossy violet-purple plumage that shifts colors in sunlight, a yellow eye, and black wings/tail. They are found in woodlands and savannas of sub-Saharan Africa. Males display shimmering feathers in courtship. \n\nAmethyst Starling mainly eat fruits, berries, nectar, and insects like termites.\n\n'),
(91048, 30130, 'de', 'Amethyst Starling', 'The Amethyst Starling, also called purple starling, is a small, dazzling iridescent bird with glossy violet-purple plumage that shifts colors in sunlight, a yellow eye, and black wings/tail. They are found in woodlands and savannas of sub-Saharan Africa. Males display shimmering feathers in courtship. \n\nAmethyst Starling mainly eat fruits, berries, nectar, and insects like termites.\n\n'),
(91049, 30130, 'da', 'Amethyst Starling', 'The Amethyst Starling, also called purple starling, is a small, dazzling iridescent bird with glossy violet-purple plumage that shifts colors in sunlight, a yellow eye, and black wings/tail. They are found in woodlands and savannas of sub-Saharan Africa. Males display shimmering feathers in courtship. \n\nAmethyst Starling mainly eat fruits, berries, nectar, and insects like termites.\n\n'),
(91050, 30131, 'en', 'Andean Condor', 'The Andean Condor is a large black vulture with a ruff of white feathers surrounding the base of the neck and, especially in the male, large white patches on the wings. The head and neck are nearly featherless and are a dull red color, which may flush and therefore change color in response to the bird\'s emotional state. In the male, there is a wattle on the neck and a large, dark red comb or caruncle on the crown of the head. The female condor is smaller than the male, which is an exception to the rule among birds of prey.\n\nAndean Condors are scavengers and feed mainly on carrion preferring large carcasses. However, they will also raid the nests of smaller birds to feed on the eggs and have been observed to do some hunting of small, live animals, such as rodents, birds, and rabbits.\n\n'),
(91051, 30131, 'de', 'Andean Condor', 'The Andean Condor is a large black vulture with a ruff of white feathers surrounding the base of the neck and, especially in the male, large white patches on the wings. The head and neck are nearly featherless and are a dull red color, which may flush and therefore change color in response to the bird\'s emotional state. In the male, there is a wattle on the neck and a large, dark red comb or caruncle on the crown of the head. The female condor is smaller than the male, which is an exception to the rule among birds of prey.\n\nAndean Condors are scavengers and feed mainly on carrion preferring large carcasses. However, they will also raid the nests of smaller birds to feed on the eggs and have been observed to do some hunting of small, live animals, such as rodents, birds, and rabbits.\n\n'),
(91052, 30131, 'da', 'Andean Condor', 'The Andean Condor is a large black vulture with a ruff of white feathers surrounding the base of the neck and, especially in the male, large white patches on the wings. The head and neck are nearly featherless and are a dull red color, which may flush and therefore change color in response to the bird\'s emotional state. In the male, there is a wattle on the neck and a large, dark red comb or caruncle on the crown of the head. The female condor is smaller than the male, which is an exception to the rule among birds of prey.\n\nAndean Condors are scavengers and feed mainly on carrion preferring large carcasses. However, they will also raid the nests of smaller birds to feed on the eggs and have been observed to do some hunting of small, live animals, such as rodents, birds, and rabbits.\n\n'),
(91053, 204, 'en', 'Angora Goat', 'The Angora goat is known for its long, curly coat from which fine mohair wool is harvested. Originating from Turkey, it loves barren, dry landscapes. In the zoo, it looks especially endearing with its fluffy hairstyle and enjoys leisurely cud-chewing in the sun.'),
(91054, 204, 'de', 'Angoraziege', 'Die Angoraziege ist für ihr langes, lockiges Fell bekannt, aus dem die edle Mohair-Wolle gewonnen wird. Sie stammt ursprünglich aus der Türkei und liebt karge, trockene Landschaften. Im Zoo wirkt sie mit ihrer Wuschelfrisur besonders sympathisch und genießt entspanntes Wiederkäuen in der Sonne.'),
(91055, 204, 'da', 'Angoraged', 'Angorageden er kendt for sit lange, krøllede pels, fra hvilken den fine mohairuld udvindes. I din zoo ser den særlig elskelig ud med sin fluffy frisure og nyder afslappet at tygge drøv i solen.'),
(91056, 102, 'en', 'Angora Rabbit', 'The Angora rabbit sports particularly long and fluffy fur that makes it look like a walking cloud. Originally, its wool was used to produce fine yarns, but in the zoo, it can just be cuddly. Visitors love watching it munch comfortably and occasionally disappear into its soft fur.'),
(91057, 102, 'de', 'Angorakaninchen', 'Das Angorakaninchen trägt ein besonders langes und flauschiges Fell, das es aussehen lässt wie eine laufende Wolke. Ursprünglich wurde seine Wolle zur Herstellung feiner Garne genutzt, doch im Zoo darf es einfach nur kuschelig sein. Besucher beobachten gerne, wie es gemütlich knabbert und zwischendurch in seinem weichen Pelz verschwindet.'),
(91058, 102, 'da', 'Angorakanin', 'Angorakaninen bærer et særlig langt og fluffy pels, der får det til at se ud som en levende sky. I din zoo sidder det afslappet og gnaver sig igennem store portioner grøntsager.'),
(91059, 30132, 'en', 'Animal Template', ''),
(91060, 30132, 'de', 'Animal Template', ''),
(91061, 30132, 'da', 'Animal Template', ''),
(91062, 30134, 'en', 'Ankole Watusi', 'The Ankole Watusi is a striking African cattle breed renowned for its massive, lyre-shaped horns and elegant stature. It has a sleek coat that can be red, brown, black, or mottled, with long legs, a slender build, and a calm demeanor. They are herded in small groups and were historically guarded by Maasai/Watusi warriors against lions, using their horns as weapons.\n\nTheir diet consists mainly of grasses and shrubs, and they have minimal water requirements.\n\n'),
(91063, 30134, 'de', 'Ankole Watusi', 'The Ankole Watusi is a striking African cattle breed renowned for its massive, lyre-shaped horns and elegant stature. It has a sleek coat that can be red, brown, black, or mottled, with long legs, a slender build, and a calm demeanor. They are herded in small groups and were historically guarded by Maasai/Watusi warriors against lions, using their horns as weapons.\n\nTheir diet consists mainly of grasses and shrubs, and they have minimal water requirements.\n\n'),
(91064, 30134, 'da', 'Ankole Watusi', 'The Ankole Watusi is a striking African cattle breed renowned for its massive, lyre-shaped horns and elegant stature. It has a sleek coat that can be red, brown, black, or mottled, with long legs, a slender build, and a calm demeanor. They are herded in small groups and were historically guarded by Maasai/Watusi warriors against lions, using their horns as weapons.\n\nTheir diet consists mainly of grasses and shrubs, and they have minimal water requirements.\n\n'),
(91065, 30135, 'en', 'Arabian Tahr', 'The Arabian Tahr is a small, rugged wild goat with a stocky build, a shaggy coat ranging from reddish-brown to dark gray, and curved horns that are larger in males. It is found only in the mountainous regions of Oman and the UAE. These animals live in small herds on steep, rocky slopes and are secretive and agile, expertly balancing on cliffs.\n\nThe Arabian Tahr primarily feeds on grasses, herbs, leaves, and shrubs.\n\n'),
(91066, 30135, 'de', 'Arabian Tahr', 'The Arabian Tahr is a small, rugged wild goat with a stocky build, a shaggy coat ranging from reddish-brown to dark gray, and curved horns that are larger in males. It is found only in the mountainous regions of Oman and the UAE. These animals live in small herds on steep, rocky slopes and are secretive and agile, expertly balancing on cliffs.\n\nThe Arabian Tahr primarily feeds on grasses, herbs, leaves, and shrubs.\n\n'),
(91067, 30135, 'da', 'Arabian Tahr', 'The Arabian Tahr is a small, rugged wild goat with a stocky build, a shaggy coat ranging from reddish-brown to dark gray, and curved horns that are larger in males. It is found only in the mountainous regions of Oman and the UAE. These animals live in small herds on steep, rocky slopes and are secretive and agile, expertly balancing on cliffs.\n\nThe Arabian Tahr primarily feeds on grasses, herbs, leaves, and shrubs.\n\n'),
(91068, 713, 'en', 'Arctic Fox', 'The Arctic fox changes his coat from white to brown with the seasons. He is perfectly adapted to Arctic conditions. In your zoo, he shines with fluffy winter fur and a quick, lively spirit.'),
(91069, 713, 'de', 'Polarfuchs', 'Der Polarfuchs wechselt je nach Jahreszeit die Fellfarbe von weiß zu braun. Er ist perfekt an arktische Bedingungen angepasst. In deinem Zoo glänzt er mit flauschigem Winterfell und flinkem Wesen.'),
(91070, 713, 'da', 'Sneleopard', 'Sneleoparden er en af Asiens mest undvigende store katte og lever i de bjerge og plateau\'er i Centralasien. Den er fortrinligt tilpasset til kold, bjergagtig terræn og er et symbol på styrke og skønhed.'),
(91071, 702, 'en', 'Arctic Ground Squirrel', 'The arctic ground squirrel is a small rodent from the cold regions of the north. He hibernates for a long winter and carefully stores up reserves beforehand. In your zoo, he seems especially lively in summer and zips eagerly through his enclosure.'),
(91072, 702, 'de', 'Arktischer Ziesel', 'Der Arktische Ziesel ist ein kleines Nagetier aus den kalten Regionen des Nordens. Er hält lange Winterschlaf und speichert zuvor ordentlich Reserven. In deinem Zoo wirkt er im Sommer besonders aktiv und flitzt emsig durch sein Gehege.'),
(91073, 702, 'da', 'Valsros', 'Hvalrossen er let genkendelig på sine lange stødbånd, der kan blive over en meter lange. De er sociale dyr og lever i store kolonier på arktiske strande og isflager. Stødbåndene bruges til at hive sig op på is.'),
(91074, 30136, 'en', 'Arctic Tern', 'The Arctic Tern is a small to medium-sized seabird known for its remarkable migratory behavior, traveling the longest migration of any bird species. Arctic Terns have a slender body, long wings, and a distinctive forked tail. They are primarily white with a black cap on their head, a grayish back, and a red bill. Their plumage is adapted for life at sea, allowing them to be agile fliers and skilled hunters.\n\nArctic terns are carnivores (piscivores). These birds feed upon small species of fish (sand launaes, sand eels, and capelins) as well as crayfish.\n\n'),
(91075, 30136, 'de', 'Arctic Tern', 'The Arctic Tern is a small to medium-sized seabird known for its remarkable migratory behavior, traveling the longest migration of any bird species. Arctic Terns have a slender body, long wings, and a distinctive forked tail. They are primarily white with a black cap on their head, a grayish back, and a red bill. Their plumage is adapted for life at sea, allowing them to be agile fliers and skilled hunters.\n\nArctic terns are carnivores (piscivores). These birds feed upon small species of fish (sand launaes, sand eels, and capelins) as well as crayfish.\n\n'),
(91076, 30136, 'da', 'Arctic Tern', 'The Arctic Tern is a small to medium-sized seabird known for its remarkable migratory behavior, traveling the longest migration of any bird species. Arctic Terns have a slender body, long wings, and a distinctive forked tail. They are primarily white with a black cap on their head, a grayish back, and a red bill. Their plumage is adapted for life at sea, allowing them to be agile fliers and skilled hunters.\n\nArctic terns are carnivores (piscivores). These birds feed upon small species of fish (sand launaes, sand eels, and capelins) as well as crayfish.\n\n'),
(91077, 714, 'en', 'Arctic Wolf', 'The polar wolf is adapted to the cold of the high north and wears a thick, white coat. He lives in packs and hunts together. In your zoo, he shows his social side and moves gracefully through the snow.'),
(91078, 714, 'de', 'Polarwolf ', 'Der Polarwolf ist an die Kälte des hohen Nordens angepasst und trägt ein dichtes, weißes Fell. Er lebt in Rudeln und jagt gemeinsam. In deinem Zoo zeigt er seine soziale Seite und bewegt sich elegant durch den Schnee.'),
(91079, 714, 'da', 'Narval', 'Narvalen er en arktisk hval berømt for sin lange, spiralformede stød. Faktisk er dette et forlænget fortand. Narvalen bruger det til at kommunikere og muligvis til at navigere i det arktiske hav.'),
(91080, 406, 'en', 'Argali', 'The argali is the largest wild sheep in the world and inhabits the mountains of Central Asia. Its impressive, spirally twisted horns can grow very large. In your zoo it calmly trots over rocky enclosure areas and proudly displays its magnificent horns.'),
(91081, 406, 'de', 'Argali', 'Der Argali ist das größte Wildschaf der Welt und bewohnt die Gebirge Zentralasiens. Seine eindrucksvollen, spiralig gedrehten Hörner können sehr groß werden. In deinem Zoo trottet er ruhig über felsige Gehegebereiche und zeigt stolz seine Hornpracht.'),
(91082, 406, 'da', 'Argali', 'Argalien er verdens største vildtfår og bebor bjergene i Centralasien. Dens imponerende, spiralelformede horn kan blive meget store. I din zoo trotter den roligt over klippede anlægsområder og viser stolt sin flotte hornpryd.'),
(91083, 30137, 'en', 'Argentine Black and White Tegu', 'The Argentine Black and White Tegu is a large, robust lizard native to South America. Known for its striking black and white coloration, this species features a pattern of bold black and white bands or spots, making it visually distinctive. These lizards can grow up to 1.2 meters (4 feet) in length and are known to dig burrows, which they use for shelter and to escape extreme temperatures. \n\nArgentine Black and White Tegus are omnivorous, feeding on a varied diet that includes fruits, insects, and small animals.\n\n'),
(91084, 30137, 'de', 'Argentine Black and White Tegu', 'The Argentine Black and White Tegu is a large, robust lizard native to South America. Known for its striking black and white coloration, this species features a pattern of bold black and white bands or spots, making it visually distinctive. These lizards can grow up to 1.2 meters (4 feet) in length and are known to dig burrows, which they use for shelter and to escape extreme temperatures. \n\nArgentine Black and White Tegus are omnivorous, feeding on a varied diet that includes fruits, insects, and small animals.\n\n'),
(91085, 30137, 'da', 'Argentine Black and White Tegu', 'The Argentine Black and White Tegu is a large, robust lizard native to South America. Known for its striking black and white coloration, this species features a pattern of bold black and white bands or spots, making it visually distinctive. These lizards can grow up to 1.2 meters (4 feet) in length and are known to dig burrows, which they use for shelter and to escape extreme temperatures. \n\nArgentine Black and White Tegus are omnivorous, feeding on a varied diet that includes fruits, insects, and small animals.\n\n'),
(91086, 216, 'en', 'Armadillo', 'The armadillo wears a bony armor that makes it look like a small living shield. Some species can even roll up into a ball when they feel threatened. In the zoo it scurries through its enclosure on short legs and digs curiously in the ground for food.'),
(91087, 216, 'de', 'Gürteltier', 'Das Gürteltier trägt eine knöcherne Panzerung, die es wie ein kleines lebendes Schild aussehen lässt. Einige Arten können sich bei Gefahr sogar zu einer Kugel zusammenrollen. Im Zoo trippelt es auf kurzen Beinchen durchs Gehege und gräbt neugierig nach Futter im Boden.'),
(91088, 216, 'da', 'Bæltedyr', 'Bæltedyret bærer en knogleagtig pansring, der får det til at ligne et lille levende skjold. Nogle arter kan endda rulle sig til en bold ved fare. I din zoo tripper det på korte ben igennem indhegningen og graver nysgerrigt i jorden.'),
(91089, 1206, 'en', 'Armadillo Girdled Lizard', 'The armadillo girdled lizard is a reptile with ring-shaped scales. When threatened, it curls up and bites its own tail for protection. In your zoo, it looks just like a tiny living dragon.'),
(91090, 1206, 'de', 'Panzergürtelschweif', 'Der Panzergürtelschweif ist eine Echse mit ringförmig angeordneten Schuppen. Bei Gefahr rollt sie sich teilweise zusammen und beißt in den eigenen Schwanz. In deinem Zoo sieht sie aus wie ein kleiner lebender Drachen.'),
(91091, 1206, 'da', 'Bjerg-løve', 'Bjerg-løven, eller pumaen, er en af de mest tilpasningsdygtige store katte i Amerika. Den lever i et enormt geografisk område fra Canada til Sydamerika og er ekspert til at jage i klippede terræner.'),
(91092, 656, 'en', 'Asian Elephant', 'The Asian elephant is slightly smaller than its African cousin and has smaller ears. It inhabits the forests and grasslands of Asia. In your zoo, it displays great skill with its trunk and a strong social bond within its herd.'),
(91093, 656, 'de', 'Asiatischer Elefant', 'Der Asiatische Elefant ist etwas kleiner als sein afrikanischer Verwandter und hat kleinere Ohren. Er lebt in Wäldern und Graslandschaften Asiens. In deinem Zoo zeigt er seine Geschicklichkeit mit dem Rüssel und seine soziale Seite im Herdenverband.'),
(91094, 656, 'da', 'Spindeldyr', 'Kæmpe huntsman-edderkoppen er en af verdens største edderkopper med et benspand på op til 30 cm. De er nattaktive jægere og bruger hastighed og styrke frem for et spind til at fange bytte.'),
(91095, 1204, 'en', 'Asian Garden Dormouse', 'The long-eared jerboa is a tiny desert rodent with oversized ears. It is nocturnal and loves to burrow into the sand. In your zoo, it displays its fascinating desert life in miniature form.'),
(91096, 1204, 'de', 'Löffelbilch', 'Der Löffelbilch ist ein kleines Wüstennagetier mit großen Ohren. Er ist nachtaktiv und gräbt sich gerne ein. In deinem Zoo zeigt er sein Wüstenleben im Miniaturformat.'),
(91097, 1204, 'da', 'Klippeegern', 'Klippe-egernet er et lille, agilestgjort pattedyr, der lever i klippede habitater i Nordamerika. Det lagrer føde og opbygger gemmer til vinteren. Det er et opportunistisk dyr, der spiser frø, nødder, insekter og æg.'),
(91098, 30138, 'en', 'Asian Golden Cat', 'The Asian Golden Cat is a medium-sized wild cat native to the forests of Southeast Asia. It has a distinctive coat that ranges from golden to reddish-brown, often with darker spots or stripes. Its build is muscular, with a broad head and short legs. The Asian Golden Cat typically weighs between 8 to 16 kg (18 to 35 lbs) and has a body length of about 70 to 100 cm (28 to 39 inches), with a long tail that can add an additional 60 cm (24 inches).\n\nThe Asian Golden Cat is a carnivore, primarily preying on small to medium-sized mammals, birds, and reptiles.\n\n'),
(91099, 30138, 'de', 'Asian Golden Cat', 'The Asian Golden Cat is a medium-sized wild cat native to the forests of Southeast Asia. It has a distinctive coat that ranges from golden to reddish-brown, often with darker spots or stripes. Its build is muscular, with a broad head and short legs. The Asian Golden Cat typically weighs between 8 to 16 kg (18 to 35 lbs) and has a body length of about 70 to 100 cm (28 to 39 inches), with a long tail that can add an additional 60 cm (24 inches).\n\nThe Asian Golden Cat is a carnivore, primarily preying on small to medium-sized mammals, birds, and reptiles.\n\n'),
(91100, 30138, 'da', 'Asian Golden Cat', 'The Asian Golden Cat is a medium-sized wild cat native to the forests of Southeast Asia. It has a distinctive coat that ranges from golden to reddish-brown, often with darker spots or stripes. Its build is muscular, with a broad head and short legs. The Asian Golden Cat typically weighs between 8 to 16 kg (18 to 35 lbs) and has a body length of about 70 to 100 cm (28 to 39 inches), with a long tail that can add an additional 60 cm (24 inches).\n\nThe Asian Golden Cat is a carnivore, primarily preying on small to medium-sized mammals, birds, and reptiles.\n\n'),
(91101, 804, 'en', 'Australian Pelican', 'The spectacle pelican has bright markings around its eyes that look like glasses. It is a skilled fisher and uses its throat pouch to catch prey. In your zoo it impresses visitors with its fishing skills in the water basin.'),
(91102, 804, 'de', 'Brillenpelikan', 'Der Brillenpelikan hat eine helle Zeichnung um die Augen, die an eine Brille erinnert. Er ist ein geschickter Fischer und nutzt seinen Kehlsack zum Beute fangen. In deinem Zoo beeindruckt er beim Fischen im Wasserbecken.'),
(91103, 804, 'da', 'Otøm', 'Havotteren er en lille pattedyr, der lever primært i havet og er kendt for at sove flydende på ryggen, ofte holder i hænderne med en partner. Den er een af de få dyr, der bruger redskaber.'),
(91104, 30139, 'en', 'Australian Sea Lion', 'The Australian Sea Lion is a rare, small eared seal found only in southern Australia. Males reach 2.5 m (8 ft 2 in) long and 300 kg (660 lbs) with a thick neck mane, dark brown coat, blunt muzzle and prominent forehead. Females are smaller at 1.8 m (5 ft 11 in) and 100 kg (220 lbs) with lighter reddish fur. Both have external ear flaps and paddle-like flippers. Endangered with ~20,000 left. \n\nAustralian Sea Lions eat fish like Australian salmon and mullet, plus squid, octopus, and cuttlefish.\n\n'),
(91105, 30139, 'de', 'Australian Sea Lion', 'The Australian Sea Lion is a rare, small eared seal found only in southern Australia. Males reach 2.5 m (8 ft 2 in) long and 300 kg (660 lbs) with a thick neck mane, dark brown coat, blunt muzzle and prominent forehead. Females are smaller at 1.8 m (5 ft 11 in) and 100 kg (220 lbs) with lighter reddish fur. Both have external ear flaps and paddle-like flippers. Endangered with ~20,000 left. \n\nAustralian Sea Lions eat fish like Australian salmon and mullet, plus squid, octopus, and cuttlefish.\n\n'),
(91106, 30139, 'da', 'Australian Sea Lion', 'The Australian Sea Lion is a rare, small eared seal found only in southern Australia. Males reach 2.5 m (8 ft 2 in) long and 300 kg (660 lbs) with a thick neck mane, dark brown coat, blunt muzzle and prominent forehead. Females are smaller at 1.8 m (5 ft 11 in) and 100 kg (220 lbs) with lighter reddish fur. Both have external ear flaps and paddle-like flippers. Endangered with ~20,000 left. \n\nAustralian Sea Lions eat fish like Australian salmon and mullet, plus squid, octopus, and cuttlefish.\n\n'),
(91107, 2101, 'en', 'Axolotl', 'The axolotl is a special type of salamander that remains in its larval stage underwater. It can regenerate lost body parts. In your zoo, it greets visitors with its charming, almost smiling face from the aquarium.'),
(91108, 2101, 'de', 'Axolotl', 'Der Axolotl ist ein besonderer Schwanzlurch, der sein Larvenstadium im Wasser beibehält. Er kann verlorene Körperteile regenerieren. In deinem Zoo lächelt er mit seinem typischen Gesichtsausdruck aus dem Aquarium.'),
(91109, 2101, 'da', 'Ørred', 'Ørreden er en yndet sportsfisk og lever i klare, kolde ferskvandsstrømme og søer. Den er meget sensitiv over for vandkvalitet og er en god indikator for et sundt vandmiljø. Den er en aktiv jæger.'),
(91113, 528, 'en', 'Bactrian Camel', 'The Bactrian camel is a camel with two humps that lives in cold deserts and steppes. Its thick coat protects it from extreme temperatures. In your zoo it proudly shows off its shaggy fur and ambles lazily through the enclosure.'),
(91114, 528, 'de', 'Trampeltier', 'Das Trampeltier ist ein Kamel mit zwei Höckern und lebt in kalten Wüsten und Steppen. Sein dichtes Fell schützt es vor extremen Temperaturen. In deinem Zoo präsentiert es stolz sein zotteliges Fell und trottet gemütlich durch das Gehege.'),
(91115, 528, 'da', 'Serval', 'Servalen er en mellemstor afrikansk kat med exceptionelt store ører, der giver den en overlegent hørelse til at lokalisere bytte. Den kan springe op til 3 meter i luften for at fange fugle.'),
(91116, 430, 'en', 'Bald Eagle', 'The bald eagle, national symbol of the United States, is a powerful fish hunter. Its white head and tail stand out sharply against its dark body. In your zoo, it captivates visitors with its soaring flights and piercing gaze.'),
(91117, 430, 'de', 'Weißkopfseeadler', 'Der Weißkopfseeadler ist das Wappentier der USA und ein mächtiger Fischjäger. Mit seinem weißen Kopf und Schwanz hebt er sich deutlich vom dunklen Körper ab. In deinem Zoo zieht er mit seinen Flügen und seinem scharfen Blick alle Aufmerksamkeit auf sich.'),
(91118, 430, 'da', 'Hvidhovedet havørn', 'Den hvidhovedet havørn er USA\'s nationalsymbol og en mægtig fiskejæger. Dens hvide hoved og hale skiller sig skarpt ud mod den mørke krop. I din zoo fanger den al opmærksomhed med sine flyvninger og sit gennemtrængende blik.'),
(91119, 642, 'en', 'Bald Uakari', 'The red uakari is a monkey with a vivid red face and a short tail. It lives in the flooded forests of the Amazon. In your zoo, its bright face—almost as if painted—makes it stand out from afar.'),
(91120, 642, 'de', 'Roter Uakari', 'Der Rote Uakari ist ein Affe mit leuchtend rotem Gesicht und kurzem Schwanz. Er lebt in den Überschwemmungswäldern Amazoniens. In deinem Zoo fällt er besonders durch sein intensives Gesicht auf, das wie geschminkt wirkt.'),
(91121, 642, 'da', 'Piranha', 'Piranhaen har et rygte for at være et af de farligste dyr i Amazonfloden. Selv om de er aggressive og har skarpe tænder, er angreb på mennesker faktisk meget sjældne under normale omstændigheder.'),
(91122, 534, 'en', 'Banded Mongoose', 'The zebra mongoose has a striped coat that slightly resembles a zebra. It lives in groups and is constantly on the move. In your zoo it dashes from shelter to shelter and hardly ever lets boredom set in.'),
(91123, 534, 'de', 'Zebramanguste', 'Die Zebramanguste hat ein gestreiftes Fell, das ein wenig an ein Zebra erinnert. Sie lebt in Gruppen und ist ständig in Bewegun cookie g. In deinem Zoo rennt sie von Unterschlupf zu Unterschlupf und lässt kaum Langeweile aufkommen.'),
(91124, 534, 'da', 'Vildhund', 'Den afrikanske vildhund er et af Afrikas mest effektive rovdyr og har en jagtsuccesrate på op til 80%. Den lever i tætte, kooperative flokke med komplekse sociale strukturer.'),
(91125, 601, 'en', 'Banteng', 'The banteng is a wild cattle species from Southeast Asia with elegantly curved horns. It lives in forests and open landscapes. In your zoo it shows its powerful side but mostly stays calm and composed.'),
(91126, 601, 'de', 'Banteng', 'Der Banteng ist ein wilder Rindertyp aus Südostasien mit elegant geschwungenen Hörnern. Er lebt in Wäldern und offenen Landschaften. In deinem Zoo zeigt er seine kraftvolle Seite, bleibt aber meist ruhig und gelassen.'),
(91127, 601, 'da', 'Orangutang', 'Orangutangerne er de nærmeste slægtninge til mennesket blandt de store aber og lever næsten udelukkende i trætoppene. De er kendte for deres ekstraordinære intelligens og brug af redskaber.'),
(91128, 723, 'en', 'Barnacle Goose', 'The snow goose has a striking black‑and‑white head pattern. She breeds in the far north and winters further south. In your zoo, she forms a lively, noisy group in pond enclosures.'),
(91129, 723, 'de', 'Weißwangengans', 'Die Weißwangengans hat eine markante, schwarz-weiße Kopfzeichnung. Sie brütet im hohen Norden und überwintert weiter südlich. In deinem Zoo bildet sie in Teichanlagen eine lebhafte, schnatternde Gruppe.'),
(91130, 723, 'da', 'Isbjørn (arktisk)', 'Den hvide bjørn er et andet navn for isbjørnen og er et ikonisk symbol på Arktis. Klimaforandringerne udgør en alvorlig trussel mod denne art, da havisen, den afhænger af, smelter hurtigere end nogensinde.'),
(91131, 519, 'en', 'Bat-Eared Fox', 'The Bat‑eared Fox, also called Löffelhund, is a small wild dog with large ears that resemble spoons. It feeds mainly on insects and is nocturnal. In your zoo, it listens in all directions with its giant ear‑antennas and looks especially cute.'),
(91132, 519, 'de', 'Löffelhund', 'Der Löffelhund ist ein kleiner Wildhund mit großen Ohren, die an Löffel erinnern. Er ernährt sich vor allem von Insekten und ist nachtaktiv. In deinem Zoo lauscht er mit seinen Riesenohr-Antennen in alle Richtungen und wirkt dabei besonders putzig.'),
(91133, 519, 'da', 'Struds', 'Strudsen er verdens største fugl og kan ikke flyve, men er til gengæld verdens hurtigste tvebenede dyr. Den kan løbe med op til 70 km/t og har de største øjne af alle landdyr.'),
(91134, 30140, 'en', 'Bay Cat', 'The Bay Cat is a small, elusive wild cat native to Borneo. It has a sleek, reddish-brown coat with darker spots and stripes, and a long tail. Typically weighing between 3 to 5 kg (6.6 to 11 lbs), it is known for its solitary and nocturnal behavior. Due to habitat loss and hunting, it is considered endangered.\n\nThe Bay Cat primarily inhabits tropical rainforests, where it preys on small mammals, birds, and reptiles.\n\n'),
(91135, 30140, 'de', 'Bay Cat', 'The Bay Cat is a small, elusive wild cat native to Borneo. It has a sleek, reddish-brown coat with darker spots and stripes, and a long tail. Typically weighing between 3 to 5 kg (6.6 to 11 lbs), it is known for its solitary and nocturnal behavior. Due to habitat loss and hunting, it is considered endangered.\n\nThe Bay Cat primarily inhabits tropical rainforests, where it preys on small mammals, birds, and reptiles.\n\n'),
(91136, 30140, 'da', 'Bay Cat', 'The Bay Cat is a small, elusive wild cat native to Borneo. It has a sleek, reddish-brown coat with darker spots and stripes, and a long tail. Typically weighing between 3 to 5 kg (6.6 to 11 lbs), it is known for its solitary and nocturnal behavior. Due to habitat loss and hunting, it is considered endangered.\n\nThe Bay Cat primarily inhabits tropical rainforests, where it preys on small mammals, birds, and reptiles.\n\n'),
(91137, 602, 'en', 'Bearded Pig', 'The banded pig carries a striking beard of long hairs on its snout. It lives in the forests of Southeast Asia and loves humid habitats. In your zoo it forages curiously and roots in the soil with its bearded face.'),
(91138, 602, 'de', 'Bartschwein', 'Das Bartschwein trägt einen auffälligen „Bart“ aus langen Haaren an der Schnauze. Es lebt in den Wäldern Südostasiens und liebt feuchte Lebensräume. In deinem Zoo stöbert es neugierig und wühlt mit seinem bärtigen Gesicht im Boden.');
INSERT INTO `animaltext` (`id`, `animalId`, `languageCode`, `animalName`, `animalDescription`) VALUES
(91139, 602, 'da', 'Gorilla', 'Gorillaen er den største levende primat og lever i tætte familiegrupper ledet af en dominerende sølvryg-han. På trods af sit skræmmende udseende er gorillaen grundlæggende et fredeligt, planteæder.'),
(91140, 408, 'en', 'Bearded Vulture', 'The bearded vulture is a powerful bird of prey specialized in feeding on bones. It drops bones from great heights to reach the nutritious marrow inside. In your zoo it soars in wide circles over the aviary and displays its impressive silhouette.'),
(91141, 408, 'de', 'Bartgeier', 'Der Bartgeier ist ein mächtiger Greifvogel, der sich auf Knochen spezialisiert hat. Er lässt Knochen aus großer Höhe fallen, um an das nahrhafte Mark zu gelangen. In deinem Zoo segelt er in weiten Kreisen über die Voliere und zeigt seine imposante Silhouette.'),
(91142, 408, 'da', 'Lammegrib', 'Lammegribben er en mægtig rovfugl specialiseret i at spise ben. Den slipper knogler fra stor højde for at nå det næringsrige marv. I din zoo sejler den i vide cirkler over volieren og viser sin imponerende silhuet.'),
(91143, 103, 'en', 'Beaver', 'The beaver is a true master builder, using its strong teeth to fell trees and construct dams. In nature, it shapes entire river landscapes and creates new habitats for many other species. In your zoo, it delights guests as it drags branches, dives underwater, and works on its lodge.'),
(91144, 103, 'de', 'Biber', 'Der Biber ist ein wahrer Baumeister und nutzt seine starken Zähne, um Bäume zu fällen und Dämme zu errichten. In der Natur gestaltet er ganze Flusslandschaften um und schafft neue Lebensräume für viele andere Arten. In deinem Zoo begeistert er die Gäste, wenn er Zweige schleppt, untertaucht und an seinem Bau arbeitet.'),
(91145, 103, 'da', 'Bæver', 'Bæveren er en ægte mester-bygger og bruger sine stærke tænder til at fælde træer og bygge dæmninger. I din zoo fascinerer den gæsterne, når den slæber grene og arbejder på sin hule.'),
(91146, 803, 'en', 'Beluga Whale', 'The beluga whale is a white whale from the Arctic Ocean. It can communicate with a wide range of sounds and is sometimes called the ‘canary of the sea’. In your zoo it fascinates visitors with its gentle appearance and friendly facial expression.'),
(91147, 803, 'de', 'Belugawal', 'Der Belugawal ist ein weißer Wal aus dem arktischen Meer. Er kann mit einer Vielzahl von Lauten kommunizieren und wird manchmal „Kanarienvogel der Meere“ genannt. In deinem Zoo fasziniert er mit seiner sanften Erscheinung und den freundlichen Gesichtszügen.'),
(91148, 803, 'da', 'Søhest', 'Søhesten er en unik fisk, hvor hannerne bærer og føder ungerne. Den er en langsom svømmer og bruger sin griberhalede til at holde fast i koraller og havgræs for at undgå at blive revet væk af strømme.'),
(91149, 30128, 'en', 'Bengal Fox', 'The Bengal Fox is a small, slender fox with a narrow, pointed face, large upright ears, and a long, bushy tail tipped in black. Its coat is sandy gray to pale brown, blending well with dry grasslands and scrub habitats. The legs are relatively long and thin, giving it a light, agile look, and the eyes are dark and expressive.\n\nThe Bengal fox feeds on small mammals, insects, birds, reptiles, and fruits.'),
(91150, 30128, 'de', 'Bengal Fox', 'The Bengal Fox is a small, slender fox with a narrow, pointed face, large upright ears, and a long, bushy tail tipped in black. Its coat is sandy gray to pale brown, blending well with dry grasslands and scrub habitats. The legs are relatively long and thin, giving it a light, agile look, and the eyes are dark and expressive.\n\nThe Bengal fox feeds on small mammals, insects, birds, reptiles, and fruits.'),
(91151, 30128, 'da', 'Bengal Fox', 'The Bengal Fox is a small, slender fox with a narrow, pointed face, large upright ears, and a long, bushy tail tipped in black. Its coat is sandy gray to pale brown, blending well with dry grasslands and scrub habitats. The legs are relatively long and thin, giving it a light, agile look, and the eyes are dark and expressive.\n\nThe Bengal fox feeds on small mammals, insects, birds, reptiles, and fruits.'),
(91152, 30141, 'en', 'Bengal Slow Loris', 'The Bengal Slow Loris is a small, nocturnal primate native to the forests of Southeast Asia. Characterized by its large, round eyes and a distinctive facial pattern, this species has a slow, deliberate movement style, which helps it navigate its arboreal habitat. The Bengal Slow Loris is known for its unique defense mechanism: it secretes a toxic substance from its elbow glands, which it can apply to its fur or deliver through bites.\n\nPrimarily herbivorous, it feeds on fruits, leaves, and insects.\n\n'),
(91153, 30141, 'de', 'Bengal Slow Loris', 'The Bengal Slow Loris is a small, nocturnal primate native to the forests of Southeast Asia. Characterized by its large, round eyes and a distinctive facial pattern, this species has a slow, deliberate movement style, which helps it navigate its arboreal habitat. The Bengal Slow Loris is known for its unique defense mechanism: it secretes a toxic substance from its elbow glands, which it can apply to its fur or deliver through bites.\n\nPrimarily herbivorous, it feeds on fruits, leaves, and insects.\n\n'),
(91154, 30141, 'da', 'Bengal Slow Loris', 'The Bengal Slow Loris is a small, nocturnal primate native to the forests of Southeast Asia. Characterized by its large, round eyes and a distinctive facial pattern, this species has a slow, deliberate movement style, which helps it navigate its arboreal habitat. The Bengal Slow Loris is known for its unique defense mechanism: it secretes a toxic substance from its elbow glands, which it can apply to its fur or deliver through bites.\n\nPrimarily herbivorous, it feeds on fruits, leaves, and insects.\n\n'),
(91155, 622, 'en', 'Bengal Tiger', 'The Siberian tiger is a subspecies of tiger and is especially powerfully built. With its orange‑black striped pattern it is an iconic big cat. In your zoo it prowls majestically through the enclosure and sometimes lets out a deep roar.'),
(91156, 622, 'de', 'Königstiger', 'Der Königstiger ist eine Unterart des Tigers und besonders kräftig gebaut. Mit seinem orange-schwarzen Streifenmuster ist er ein ikonischer Großkatzenvertreter. In deinem Zoo schleicht er majestätisch durchs Gehege und lässt manchmal ein tiefes Brüllen hören.'),
(91157, 622, 'da', 'Kæmpesalamander', 'Den kinesiske kæmpesalamander er det største nulevende padde og kan blive op til 1,8 meter lang. Den er en levende fossil, da dens form næsten ikke har ændret sig i 170 millioner år. Den er stærkt truet.'),
(91158, 30142, 'en', 'Bilby', 'The Bilby, also known as the Greater Bilby, is a nocturnal marsupial native to Australia. It is a medium-sized animal, measuring 29–55 cm (11–22 inches) in body length with a tail of 20–34 cm (8–13 inches). The Bilby has distinctive large ears for heat dissipation and hearing, a long pointed snout, silky blue-grey fur with white underparts, and powerful forelimbs with long claws for digging. \n\nIts diet is omnivorous, consisting of insects, seeds, bulbs, fruit, fungi, and small vertebrates. \n\n'),
(91159, 30142, 'de', 'Bilby', 'The Bilby, also known as the Greater Bilby, is a nocturnal marsupial native to Australia. It is a medium-sized animal, measuring 29–55 cm (11–22 inches) in body length with a tail of 20–34 cm (8–13 inches). The Bilby has distinctive large ears for heat dissipation and hearing, a long pointed snout, silky blue-grey fur with white underparts, and powerful forelimbs with long claws for digging. \n\nIts diet is omnivorous, consisting of insects, seeds, bulbs, fruit, fungi, and small vertebrates. \n\n'),
(91160, 30142, 'da', 'Bilby', 'The Bilby, also known as the Greater Bilby, is a nocturnal marsupial native to Australia. It is a medium-sized animal, measuring 29–55 cm (11–22 inches) in body length with a tail of 20–34 cm (8–13 inches). The Bilby has distinctive large ears for heat dissipation and hearing, a long pointed snout, silky blue-grey fur with white underparts, and powerful forelimbs with long claws for digging. \n\nIts diet is omnivorous, consisting of insects, seeds, bulbs, fruit, fungi, and small vertebrates. \n\n'),
(91161, 604, 'en', 'Binturong', 'The binturong, also called bearcat, has a long prehensile tail and supposedly smells like freshly popped popcorn. It loves to climb and spends most of its time in the trees. In your zoo it hangs relaxed in the branches and sniffs curiously at the air.'),
(91162, 604, 'de', 'Binturong', 'Der Binturong, auch Schuppentierkatze genannt, hat einen langen Greifschwanz und riecht angeblich nach frischem Popcorn. Er klettert gern und ist vor allem in Bäumen unterwegs. In deinem Zoo hängt er entspannt im Geäst und schnuppert neugierig in die Luft.'),
(91163, 604, 'da', 'Bonobo', 'Bonoboen er nært beslægtet med chimpansen, men har en anderledes social struktur domineret af hunner. De er kendte for at bruge social adfærd til at løse konflikter frem for aggression.'),
(91164, 645, 'en', 'Black Bearded Saki', 'The black-faced saki—often called the \'devil monkey\'—owes its dramatic name to its dark face and piercing eyes. Otherwise, it’s a social and lively primate. In your zoo, it shows off its active social life, proving it’s far from sinister despite the name.'),
(91165, 645, 'de', 'Satansaffe', 'Der Satansaffe trägt seinen dramatischen Namen wegen seines dunklen Gesichtes und der intensiven Augen. Er ist ansonsten jedoch ein ganz normaler, sozial lebender Affe. In deinem Zoo zeigt er lebhaftes Sozialverhalten und beweist, dass sein Name Programm, aber nicht bösartig ist.'),
(91166, 645, 'da', 'Kæmpe-hundegekko', 'Tokay-geckoen er en af de største geckoarter og er opkaldt efter dens karakteristiske \"to-kay\" lyd. Den er nattaktiv og lever i regnskove og huse i Sydøst-Asien. Den har et kraftigt bid.'),
(91167, 30143, 'en', 'Black Mamba', 'The Black Mamba is one of the world\'s most venomous snakes, known for its speed and agility. Native to sub-Saharan Africa, it can reach lengths of up to 4.3 meters (14 feet) and is characterized by its sleek, black coloration and a distinctive olive-brown body. Despite its fearsome reputation, it is generally shy and prefers to avoid human contact.\n\nThe Black Mamba primarily feeds on small mammals, such as rodents and birds, using its potent venom to immobilize prey.\n\n'),
(91168, 30143, 'de', 'Black Mamba', 'The Black Mamba is one of the world\'s most venomous snakes, known for its speed and agility. Native to sub-Saharan Africa, it can reach lengths of up to 4.3 meters (14 feet) and is characterized by its sleek, black coloration and a distinctive olive-brown body. Despite its fearsome reputation, it is generally shy and prefers to avoid human contact.\n\nThe Black Mamba primarily feeds on small mammals, such as rodents and birds, using its potent venom to immobilize prey.\n\n'),
(91169, 30143, 'da', 'Black Mamba', 'The Black Mamba is one of the world\'s most venomous snakes, known for its speed and agility. Native to sub-Saharan Africa, it can reach lengths of up to 4.3 meters (14 feet) and is characterized by its sleek, black coloration and a distinctive olive-brown body. Despite its fearsome reputation, it is generally shy and prefers to avoid human contact.\n\nThe Black Mamba primarily feeds on small mammals, such as rodents and birds, using its potent venom to immobilize prey.\n\n'),
(91170, 527, 'en', 'Black Rhinoceros', 'The black rhinoceros has a pointed upper lip that helps it grasp leaves. It is highly endangered and the focus of many conservation projects. In your zoo it is an impressive ambassador for species protection.'),
(91171, 527, 'de', 'Spitzmaulnaßhorn', 'Das Spitzmaulnashorn hat ein spitz zulaufendes Oberlippenmaul, das beim Greifen von Blättern hilft. Es ist stark bedroht und steht im Mittelpunkt vieler Schutzprojekte. In deinem Zoo ist es ein eindrucksvoller Botschafter für den Artenschutz.'),
(91172, 527, 'da', 'Oryx', 'Oryxen er en robust antilope tilpasset til at overleve i tørre ørkener og savanner. Dens lange, rette horn var sandsynligvis inspirationen bag myten om enhjørningen.'),
(91173, 343, 'en', 'Black Stork', 'The black stork is much shyer than its white relative and lives mainly in undisturbed forests. Its dark plumage shimmers with metallic tones in the sun. In your zoo it moves about quietly and reservedly – a special discovery for observant visitors.'),
(91174, 343, 'de', 'Schwarzstorch', 'Der Schwarzstorch ist scheuer als sein weißer Verwandter und lebt überwiegend in ungestörten Wäldern. Sein dunkles Gefieder schimmert in der Sonne metallisch. In deinem Zoo bewegt er sich ruhig und zurückhaltend, eine besondere Entdeckung für aufmerksame Besucher.'),
(91175, 343, 'da', 'Sort stork', 'Den sorte stork er mere sky end sin hvide slægtning og lever primært i uforstyrrede skove. Dens mørke fjerkjole skimrer metallisk i solen. I din zoo bevæger den sig roligt og tilbageholdent – en særlig opdagelse for opmærksomme besøgende.'),
(91176, 536, 'en', 'Black Wildebeest', 'The white‑tailed gnu is a species of gnu with a striking light tail. It lives in African savannas and often moves in large herds. In your zoo it creates a lot of dynamism with its lively nature and occasional playful leaps.'),
(91177, 536, 'de', 'Weissschwanzgnu', 'Das Weißschwanzgnu ist eine Gnuart mit auffällig hellem Schweif. Es lebt in afrikanischen Savannen und zieht oft in großen Herden umher. In deinem Zoo sorgt es mit seiner lebhaften Art und gelegentlichen Bocksprüngen für viel Dynamik.'),
(91178, 536, 'da', 'Hanuman-abe', 'Bavianen er en af Afrikas mest udbredte primater og er tilpasset til både åbne savanner og klipper. De lever i store sociale grupper med komplekse hierarkier.'),
(91179, 30144, 'en', 'Black-Backed Jackal', 'The Black-Backed Jackal is a medium-sized canid native to southern and eastern Africa. Characterized by its distinctive black saddle-like patch on its back, it has a slender body, long legs, and a bushy tail. They are known for their adaptability to various habitats, including savannas, grasslands, and arid regions. Socially, they can be found in monogamous pairs or small family groups, often exhibiting vocal communication through a range of calls.\n\nBlack-Backed Jackals are opportunistic omnivores, feeding on small mammals, birds, insects, and fruits. \n\n'),
(91180, 30144, 'de', 'Black-Backed Jackal', 'The Black-Backed Jackal is a medium-sized canid native to southern and eastern Africa. Characterized by its distinctive black saddle-like patch on its back, it has a slender body, long legs, and a bushy tail. They are known for their adaptability to various habitats, including savannas, grasslands, and arid regions. Socially, they can be found in monogamous pairs or small family groups, often exhibiting vocal communication through a range of calls.\n\nBlack-Backed Jackals are opportunistic omnivores, feeding on small mammals, birds, insects, and fruits. \n\n'),
(91181, 30144, 'da', 'Black-Backed Jackal', 'The Black-Backed Jackal is a medium-sized canid native to southern and eastern Africa. Characterized by its distinctive black saddle-like patch on its back, it has a slender body, long legs, and a bushy tail. They are known for their adaptability to various habitats, including savannas, grasslands, and arid regions. Socially, they can be found in monogamous pairs or small family groups, often exhibiting vocal communication through a range of calls.\n\nBlack-Backed Jackals are opportunistic omnivores, feeding on small mammals, birds, insects, and fruits. \n\n'),
(91182, 30145, 'en', 'Black-Browed Albatross', 'The Black-Browed Albatross is a medium-sized albatross, measuring 80–95 cm (31–37 in) in length. It has a white head with a distinctive black brow, a dark grey back and upper wings, and a bright yellow-orange bill tipped with reddish-orange. These birds are superb long-distance fliers, soaring effortlessly over the southern oceans, and can live for more than 70 years.\n\nThe Black-Browed Albatross feeds mainly on fish, squid, and crustaceans, often snatching prey from the ocean surface or scavenging near fishing boats.\n\n'),
(91183, 30145, 'de', 'Black-Browed Albatross', 'The Black-Browed Albatross is a medium-sized albatross, measuring 80–95 cm (31–37 in) in length. It has a white head with a distinctive black brow, a dark grey back and upper wings, and a bright yellow-orange bill tipped with reddish-orange. These birds are superb long-distance fliers, soaring effortlessly over the southern oceans, and can live for more than 70 years.\n\nThe Black-Browed Albatross feeds mainly on fish, squid, and crustaceans, often snatching prey from the ocean surface or scavenging near fishing boats.\n\n'),
(91184, 30145, 'da', 'Black-Browed Albatross', 'The Black-Browed Albatross is a medium-sized albatross, measuring 80–95 cm (31–37 in) in length. It has a white head with a distinctive black brow, a dark grey back and upper wings, and a bright yellow-orange bill tipped with reddish-orange. These birds are superb long-distance fliers, soaring effortlessly over the southern oceans, and can live for more than 70 years.\n\nThe Black-Browed Albatross feeds mainly on fish, squid, and crustaceans, often snatching prey from the ocean surface or scavenging near fishing boats.\n\n'),
(91185, 30146, 'en', 'Black-Faced Spoonbill', 'The Black-Faced Spoonbill is a critically endangered wading bird native to coastal regions of East Asia. It has striking white plumage, a distinctive black face and bill tip, and a long, spoon-shaped bill. Adults stand about 70-80 cm (28-31 inches) tall with a wingspan of 110-120 cm (43-47 inches).\n\nIts diet consists mainly of small fish, crustaceans, and insects, which it catches by sweeping its spoon-shaped bill through shallow water.\n\n'),
(91186, 30146, 'de', 'Black-Faced Spoonbill', 'The Black-Faced Spoonbill is a critically endangered wading bird native to coastal regions of East Asia. It has striking white plumage, a distinctive black face and bill tip, and a long, spoon-shaped bill. Adults stand about 70-80 cm (28-31 inches) tall with a wingspan of 110-120 cm (43-47 inches).\n\nIts diet consists mainly of small fish, crustaceans, and insects, which it catches by sweeping its spoon-shaped bill through shallow water.\n\n'),
(91187, 30146, 'da', 'Black-Faced Spoonbill', 'The Black-Faced Spoonbill is a critically endangered wading bird native to coastal regions of East Asia. It has striking white plumage, a distinctive black face and bill tip, and a long, spoon-shaped bill. Adults stand about 70-80 cm (28-31 inches) tall with a wingspan of 110-120 cm (43-47 inches).\n\nIts diet consists mainly of small fish, crustaceans, and insects, which it catches by sweeping its spoon-shaped bill through shallow water.\n\n'),
(91188, 231, 'en', 'Black-Footed Cat', 'The black-footed cat is one of Africa’s smallest wild cats and yet a very successful huntress. It is nocturnal and moves silently through grass and scrub. In your zoo it appears mainly at dusk and enchants everyone with its mix of cuteness and wild spirit.'),
(91189, 231, 'de', 'Schwarzfußkatze', 'Die Schwarzfußkatze gehört zu den kleinsten Wildkatzen Afrikas und ist trotzdem eine sehr erfolgreiche Jägerin. Sie ist nachtaktiv und bewegt sich leise durch Gras und Buschwerk. In deinem Zoo zeigt sie sich vor allem in der Dämmerung und begeistert durch ihre Mischung aus Niedlichkeit und Wildheit.'),
(91190, 231, 'da', 'Sortfodet kat', 'Sortfodekatten er en af Afrikas mindste vildkatte og er alligevel en meget succesfuld jæger. Den er nattaktiv og bevæger sig stille igennem græs og krat. I din zoo viser den sig primært i tusmørket og begejstrer med sin blanding af sødheds og vildhed.'),
(91191, 30147, 'en', 'Black-Headed Ibis', 'The Black-Headed Ibis is a slender wading bird with a long, thin, down-curved black bill adapted for probing. It has a glossy black head and neck, contrasting with its predominantly white body plumage. The wings and scapulars are black with an iridescent green-purple sheen in flight.\n\nForages by sweeping bill side-to-side in mud/shallows for insects, earthworms, crustaceans, frogs, and small fish.\n\n'),
(91192, 30147, 'de', 'Black-Headed Ibis', 'The Black-Headed Ibis is a slender wading bird with a long, thin, down-curved black bill adapted for probing. It has a glossy black head and neck, contrasting with its predominantly white body plumage. The wings and scapulars are black with an iridescent green-purple sheen in flight.\n\nForages by sweeping bill side-to-side in mud/shallows for insects, earthworms, crustaceans, frogs, and small fish.\n\n'),
(91193, 30147, 'da', 'Black-Headed Ibis', 'The Black-Headed Ibis is a slender wading bird with a long, thin, down-curved black bill adapted for probing. It has a glossy black head and neck, contrasting with its predominantly white body plumage. The wings and scapulars are black with an iridescent green-purple sheen in flight.\n\nForages by sweeping bill side-to-side in mud/shallows for insects, earthworms, crustaceans, frogs, and small fish.\n\n'),
(91194, 834, 'en', 'Black-Necked Swan', 'The black-necked swan, as its name suggests, has a black neck and a white body. It lives in South America. In your zoo, it provides an elegant contrast to white swans.'),
(91195, 834, 'de', 'Schwarzhalsschwan', 'Der Schwarzhalsschwan hat, wie der Name sagt, einen schwarzen Hals und weißen Körper. Er lebt in Südamerika. In deinem Zoo bildet er einen eleganten Kontrast zu weißen Schwänen.'),
(91196, 834, 'da', 'Klovnefisk', 'Klovnefisken er berømt fra animationsfilmen \"Finding Nemo\". Den lever i symbiose med søanemoner og er en af de eneste fisk, der er immune over for søanemoners gift. Den kan skifte køn i løbet af sit liv.'),
(91197, 218, 'en', 'Blackbuck', 'The blackbuck is a nimble antelope from the open landscapes of India. Males have dark coats and striking, twisted horns, while females are more lightly colored. In your zoo they dash playfully around the exhibit and challenge each other to little races.'),
(91198, 218, 'de', 'Hirschziegenantilope', 'Die Hirschziegenantilope ist eine flinke Antilope aus den offenen Landschaften Indiens. Männchen tragen ein dunkles Fell und auffällige, gedrehte Hörner, während Weibchen eher hell gefärbt sind. In deinem Zoo flitzen sie bei guter Laune über die Anlage und liefern sich kleine Wettrennen.'),
(91199, 218, 'da', 'Sortbuk', 'Sortbukken er en hurtig antilope fra Indiens åbne landskaber. Hannen bærer mørkt pels og iøjnefaldende snoede horn, mens hunnen er lysere farvet. I din zoo drager de vilde løb i godt humør over anlægget.'),
(91200, 303, 'en', 'Blue Iguana', 'The blue iguana is an endangered lizard from the Cayman Islands and stands out thanks to its bluish coloration. It loves rocky, sunny spots and feeds mainly on plants. In your zoo it likes to sit on high rocks and watch its surroundings from a safe vantage point.'),
(91201, 303, 'de', 'Blauer Leguan', 'Der Blaue Leguan ist eine bedrohte Echsenart von den Kaimaninseln und fällt durch seine bläuliche Färbung auf. Er liebt felsige, sonnige Plätze und ernährt sich hauptsächlich pflanzlich. In deinem Zoo sitzt er gerne auf erhöhten Steinen und beobachtet seine Umgebung aus sicherer Position.'),
(91202, 303, 'da', 'Blå leguan', 'Den blå leguan er en truet øgleart fra Cayman-øerne, der er kendt for sin blålige farve. Den elsker solrige stenpladser. I din zoo sidder den gerne på varme sten og observerer omgivelserne fra sin høje position.'),
(91203, 605, 'en', 'Blue-Eyed Black Lemur', 'The blue‑eyed lemur is a lemur with striking blue eyes—a real rarity in the animal kingdom. It comes from Madagascar and is highly endangered. In your zoo it fascinates visitors with its intense gaze and lively climbing skills.'),
(91204, 605, 'de', 'Blauaugenmaki', 'Der Blauaugenmaki ist ein Lemur mit auffallend blauen Augen – eine echte Besonderheit im Tierreich. Er stammt aus Madagaskar und ist stark bedroht. In deinem Zoo fasziniert er Besucher mit seinem intensiven Blick und lebhaften Kletterkünsten.'),
(91205, 605, 'da', 'Gibboner', 'Gibbonerne er de mest akrobatiske primater og bevæger sig gennem junglen ved brachiation — at svinge fra gren til gren med armene. De er også kendte for deres komplekse sangkommunikation.'),
(91206, 104, 'en', 'Blue-Footed Booby', 'The Blue-footed Booby is famous for its striking, bright blue feet, with which it performs real dance shows during courtship. It usually lives along the Pacific coasts and is a skilled diver that hunts fish by plunging from great heights into the water. In the zoo, its waddling gait and proud display of its colorful feet bring smiles to many faces.'),
(91207, 104, 'de', 'Blaufußtölpel', 'Der Blaufußtölpel ist vor allem für seine auffälligen, leuchtend blauen Füße bekannt, mit denen er bei der Balz richtige Tanzshows aufführt. Er lebt normalerweise an den Küsten des Pazifiks und ist ein geschickter Taucher, der Fische aus großer Höhe ins Wasser stürzend jagt. Im Zoo sorgt sein watschelnder Gang und das stolze Präsentieren seiner bunten Füße für viele lächelnde Gesichter.'),
(91208, 104, 'da', 'Blåfodet sule', 'Den blåfodede sule er berømt for sine iøjnefaldende, lysende blå fødder, som den bruger til at imponere sin make. I din zoo vugger den med sine farverige fødder og frembringer mange smilende ansigter.'),
(91209, 205, 'en', 'Bongo Antelope', 'The Bongo antelope is one of Africa\'s largest and most colorful antelopes. Its reddish-brown coat with white stripes helps it camouflage in dense forests. In your zoo, it quietly circles around, impressing with its long horns and elegant markings.'),
(91210, 205, 'de', 'Bongo Antilope', 'Die Bongo-Antilope ist eine der größten und farbenprächtigsten Antilopen Afrikas. Ihr rotbraunes Fell mit weißen Streifen hilft ihr, sich im dichten Wald zu tarnen. In deinem Zoo zieht sie ruhig ihre Runden und beeindruckt mit ihren langen Hörnern und der edlen Zeichnung.'),
(91211, 205, 'da', 'Bongo', 'Bongoen er en af Afrikas største og farverigste antilopearter. Dens rødbrun pels med hvide striber hjælper den med at camouflere sig i den tætte skov. I din zoo går den roligt rundt og imponerer med sine lange horn.'),
(91212, 30148, 'en', 'Bontebok', 'Bontebok is a South African antelope with distinctive purplish-brown coat and white markings on face, rump and belly. It stands 70-90 cm (28-35 in) tall at shoulder and weighs 50-75 kg (110-165 lbs). Males display prominent lyre-shaped horns measuring up to 40 cm (16 in). Once nearly extinct, these social herd animals now flourish in protected reserves.\n\nBontebok grazes on short grasses in fynbos habitat.\n'),
(91213, 30148, 'de', 'Bontebok', 'Bontebok is a South African antelope with distinctive purplish-brown coat and white markings on face, rump and belly. It stands 70-90 cm (28-35 in) tall at shoulder and weighs 50-75 kg (110-165 lbs). Males display prominent lyre-shaped horns measuring up to 40 cm (16 in). Once nearly extinct, these social herd animals now flourish in protected reserves.\n\nBontebok grazes on short grasses in fynbos habitat.\n'),
(91214, 30148, 'da', 'Bontebok', 'Bontebok is a South African antelope with distinctive purplish-brown coat and white markings on face, rump and belly. It stands 70-90 cm (28-35 in) tall at shoulder and weighs 50-75 kg (110-165 lbs). Males display prominent lyre-shaped horns measuring up to 40 cm (16 in). Once nearly extinct, these social herd animals now flourish in protected reserves.\n\nBontebok grazes on short grasses in fynbos habitat.\n'),
(91215, 30149, 'en', 'Borneo Elephant', 'The Borneo Elephant is a subspecies of the  found primarily on the island of Borneo. It is the smallest subspecies of Asian elephants, with adults typically standing about 2 to 2.5 meters (6.6 to 8.2 feet) tall at the shoulder and weighing between 400 to 1,000 kg (880 to 2,200 lbs). They are characterized by their smaller size, larger ears, and relatively straight tusks compared to other Asian elephants. \n\nBorneo Elephants primarily feed on a diet of leaves, fruits, and bark. \n\n'),
(91216, 30149, 'de', 'Borneo Elephant', 'The Borneo Elephant is a subspecies of the  found primarily on the island of Borneo. It is the smallest subspecies of Asian elephants, with adults typically standing about 2 to 2.5 meters (6.6 to 8.2 feet) tall at the shoulder and weighing between 400 to 1,000 kg (880 to 2,200 lbs). They are characterized by their smaller size, larger ears, and relatively straight tusks compared to other Asian elephants. \n\nBorneo Elephants primarily feed on a diet of leaves, fruits, and bark. \n\n'),
(91217, 30149, 'da', 'Borneo Elephant', 'The Borneo Elephant is a subspecies of the  found primarily on the island of Borneo. It is the smallest subspecies of Asian elephants, with adults typically standing about 2 to 2.5 meters (6.6 to 8.2 feet) tall at the shoulder and weighing between 400 to 1,000 kg (880 to 2,200 lbs). They are characterized by their smaller size, larger ears, and relatively straight tusks compared to other Asian elephants. \n\nBorneo Elephants primarily feed on a diet of leaves, fruits, and bark. \n\n'),
(91218, 30150, 'en', 'Bottle Nosed Dolphin', 'The Bottlenose Dolphin, which is the most widely recognized dolphin species, is found worldwide in warm and temperate seas. The dolphin\'s skin is dark gray on its back and pale gray on its flanks. Visually, the species is distinguishable from other dolphins by its elongated rostrum. Bottlenose Dolphins have the longest social memories of any nonhuman species. They have been shown to recognize the unique whistles of individual dolphins they once associated with some 20 years after becoming separated from them.\n\nTheir diet consists mainly of small fish, occasionally also squid, crabs, octopus, and other similar animals.\n\n'),
(91219, 30150, 'de', 'Bottle Nosed Dolphin', 'The Bottlenose Dolphin, which is the most widely recognized dolphin species, is found worldwide in warm and temperate seas. The dolphin\'s skin is dark gray on its back and pale gray on its flanks. Visually, the species is distinguishable from other dolphins by its elongated rostrum. Bottlenose Dolphins have the longest social memories of any nonhuman species. They have been shown to recognize the unique whistles of individual dolphins they once associated with some 20 years after becoming separated from them.\n\nTheir diet consists mainly of small fish, occasionally also squid, crabs, octopus, and other similar animals.\n\n'),
(91220, 30150, 'da', 'Bottle Nosed Dolphin', 'The Bottlenose Dolphin, which is the most widely recognized dolphin species, is found worldwide in warm and temperate seas. The dolphin\'s skin is dark gray on its back and pale gray on its flanks. Visually, the species is distinguishable from other dolphins by its elongated rostrum. Bottlenose Dolphins have the longest social memories of any nonhuman species. They have been shown to recognize the unique whistles of individual dolphins they once associated with some 20 years after becoming separated from them.\n\nTheir diet consists mainly of small fish, occasionally also squid, crabs, octopus, and other similar animals.\n\n'),
(91221, 30151, 'en', 'Bowhead Whale', 'The Bowhead Whale is a massive, dark‑colored Arctic whale with a huge, bow‑shaped head that makes up nearly a third of its body. It has no dorsal fin, a thick, rounded body covered in dense blubber, and a strongly arched jaw that holds the longest baleen plates of any whale.\n\nBowhead whales are filter feeders that consume zooplankton such as copepods, krill, and other small crustaceans.\n\n'),
(91222, 30151, 'de', 'Bowhead Whale', 'The Bowhead Whale is a massive, dark‑colored Arctic whale with a huge, bow‑shaped head that makes up nearly a third of its body. It has no dorsal fin, a thick, rounded body covered in dense blubber, and a strongly arched jaw that holds the longest baleen plates of any whale.\n\nBowhead whales are filter feeders that consume zooplankton such as copepods, krill, and other small crustaceans.\n\n'),
(91223, 30151, 'da', 'Bowhead Whale', 'The Bowhead Whale is a massive, dark‑colored Arctic whale with a huge, bow‑shaped head that makes up nearly a third of its body. It has no dorsal fin, a thick, rounded body covered in dense blubber, and a strongly arched jaw that holds the longest baleen plates of any whale.\n\nBowhead whales are filter feeders that consume zooplankton such as copepods, krill, and other small crustaceans.\n\n'),
(91224, 30152, 'en', 'Brahma Chicken', 'The Brahma Chicken is a large breed known for its impressive size, gentle temperament, and distinctive feathered legs. They have a striking appearance with a broad body, a short neck, and a feathered crest, and they come in several color varieties, including light, dark, and buff. Brahma Chickens are also known for their hardiness in various climates, making them a popular choice among poultry enthusiasts.\n\nThe diet of Brahma Chickens should consist of high-quality layer feed, supplemented with grains, fresh vegetables and fruits, grit for digestion.\n\n'),
(91225, 30152, 'de', 'Brahma Chicken', 'The Brahma Chicken is a large breed known for its impressive size, gentle temperament, and distinctive feathered legs. They have a striking appearance with a broad body, a short neck, and a feathered crest, and they come in several color varieties, including light, dark, and buff. Brahma Chickens are also known for their hardiness in various climates, making them a popular choice among poultry enthusiasts.\n\nThe diet of Brahma Chickens should consist of high-quality layer feed, supplemented with grains, fresh vegetables and fruits, grit for digestion.\n\n'),
(91226, 30152, 'da', 'Brahma Chicken', 'The Brahma Chicken is a large breed known for its impressive size, gentle temperament, and distinctive feathered legs. They have a striking appearance with a broad body, a short neck, and a feathered crest, and they come in several color varieties, including light, dark, and buff. Brahma Chickens are also known for their hardiness in various climates, making them a popular choice among poultry enthusiasts.\n\nThe diet of Brahma Chickens should consist of high-quality layer feed, supplemented with grains, fresh vegetables and fruits, grit for digestion.\n\n'),
(91227, 525, 'en', 'Brown Hyena', 'The striped hyena has long, shaggy fur with dark stripes. It is mainly a scavenger, but also eats smaller prey animals. In your zoo it wanders calmly through the enclosure and shows off its important talent as nature’s clean‑up crew.'),
(91228, 525, 'de', 'Schabrackenhyäne', 'Die Schabrackenhyäne trägt ein langes, struppiges Fell mit dunklen Streifen. Sie ist hauptsächlich Aasfresserin, frisst aber auch kleinere Beutetiere. In deinem Zoo streift sie gemächlich durch das Gehege und zeigt ihr wichtiges Talent als „Aufräumdienst“ der Natur.'),
(91229, 525, 'da', 'Kuduer', 'Kuduen er en stor antilope, der er kendetegnet ved hannens imponerende, spiralformede horn, der kan blive over 1,8 meter lange. Den er sky og lever typisk i tæt buskads.'),
(91230, 323, 'en', 'Brushtail Possum', 'The common brushtail possum, also called kusu, is a nocturnal marsupial native to Australia and New Guinea. It mostly lives in trees and uses its grasping tail when climbing. In your zoo it is a quiet roommate that roams curiously through its enclosure at night.'),
(91231, 323, 'de', 'Kusu', 'Der Kusu, auch Possum genannt, ist ein nachtaktives Beuteltier, das in Australien und Neuguinea zuhause ist. Er lebt meist in Bäumen und nutzt seinen Greifschwanz beim Klettern. In deinem Zoo ist er ein leiser Mitbewohner, der nachts neugierig durch sein Gehege streift.'),
(91232, 323, 'da', 'Buskhaleopossum', 'Buskhaleopossumen er et nattaktivt pungdyr hjemmehørende i Australien og New Guinea. Det lever mest i træer og bruger sin gribehale til at klatre. I din zoo er det en stille nattebeboer, der strejfer nysgerrigt rundt i sit anlæg.'),
(91233, 339, 'en', 'Bush Dog', 'The bush dog is a small, stocky wild dog from South America with short legs. It hunts in packs and is especially well adapted to life in dense forests. In your zoo it is almost always on the move, showing just how much energy can fit into a small body.'),
(91234, 339, 'de', 'Waldhund', 'Der Waldhund ist ein kleiner, stämmiger Wildhund aus Südamerika mit kurzen Beinen. Er jagt im Rudel und ist besonders an das Leben im dichten Wald angepasst. In deinem Zoo ist er fast immer in Bewegung und zeigt, wie viel Energie in einem kleinen Körper stecken kann.'),
(91235, 339, 'da', 'Skovhund', 'Skovhunden er en lille, bastant vildhund fra Sydamerika med korte ben. Den jager i flokke og er særligt godt tilpasset til livet i den tætte skov. I din zoo er den næsten altid i bevægelse og viser, hvor meget energi der kan gemme sig i en lille krop.'),
(91236, 30153, 'en', 'Californian Rabbit', 'The Californian Rabbit is a domesticated breed known for its distinctive appearance and friendly temperament. They are characterized by their white fur with black, gray, or chocolate markings on the ears, nose, and feet. Californian rabbits are medium to large in size, typically weighing between 8 to 10 pounds (3.6 to 4.5 kg).\n\nThe diet of Californian Rabbits should consist primarily of high-quality hay, fresh leafy vegetables, limited pellets, and fresh water.\n\n'),
(91237, 30153, 'de', 'Californian Rabbit', 'The Californian Rabbit is a domesticated breed known for its distinctive appearance and friendly temperament. They are characterized by their white fur with black, gray, or chocolate markings on the ears, nose, and feet. Californian rabbits are medium to large in size, typically weighing between 8 to 10 pounds (3.6 to 4.5 kg).\n\nThe diet of Californian Rabbits should consist primarily of high-quality hay, fresh leafy vegetables, limited pellets, and fresh water.\n\n'),
(91238, 30153, 'da', 'Californian Rabbit', 'The Californian Rabbit is a domesticated breed known for its distinctive appearance and friendly temperament. They are characterized by their white fur with black, gray, or chocolate markings on the ears, nose, and feet. Californian rabbits are medium to large in size, typically weighing between 8 to 10 pounds (3.6 to 4.5 kg).\n\nThe diet of Californian Rabbits should consist primarily of high-quality hay, fresh leafy vegetables, limited pellets, and fresh water.\n\n'),
(91239, 710, 'en', 'Canadian Lynx', 'The Canadian lynx has especially large paws that act like snowshoes. He lives in northern forests and hunts mainly snowshoe hares. In your zoo, his tufted ears and thick fur make him look particularly graceful.'),
(91240, 710, 'de', 'Kanadischer Luchs', 'Der Kanadische Luchs besitzt besonders große Pfoten, die wie Schneeschuhe wirken. Er lebt in nordischen Wäldern und jagt vor allem Schneehasen. In deinem Zoo wirkt er durch seine Pinselohren und das dichte Fell besonders anmutig.'),
(91241, 710, 'da', 'Rensdyr', 'Rensdyret er det eneste hjorteartede dyr, hvor begge køn bærer gevir. Det er perfekt tilpasset til livet i den arktiske tundra og har brede, hule hover der hjælper med at grave i sne for at finde planter.'),
(91242, 338, 'en', 'Canadian Porcupine', 'The North American porcupine, or urson, is armed with long, sharp quills for defense. It moves rather slowly and spends much of its time in trees. In your zoo it climbs branches at a relaxed pace, letting its quills shimmer in the light – though it is definitely not for petting.'),
(91243, 338, 'de', 'Urson', 'Der Urson ist ein nordamerikanisches Stachelschwein mit langen, spitzen Stacheln zur Verteidigung. Er bewegt sich eher langsam und verbringt viel Zeit in Bäumen. In deinem Zoo klettert er gemütlich auf Äste und lässt seine Stacheln im Licht schimmern – anfassen sollte man ihn aber lieber nicht.'),
(91244, 338, 'da', 'Nordamerikansk pindsvineaber', 'Det nordamerikanske pindsvin er udstyret med lange, skarpe pigge til forsvar. Det bevæger sig forholdsvis langsomt og tilbringer meget tid i træerne. I din zoo klatrer det ad grene i et roligt tempo og lader piggene glimte i lyset – man bør dog hellere ikke røre ved det.'),
(91245, 30154, 'en', 'Cape Fox', 'The Cape Fox is a small, agile canid native to southern Africa, particularly found in the Cape region. It has a slender body, long legs, and a bushy tail, with a coat that is typically grayish-brown with a lighter underbelly. Cape Foxes are primarily nocturnal and are known for their adaptability to various habitats, including grasslands and savannas. \n\nCape Foxe are omnivorous, feeding on small mammals, birds, insects, and fruits.\n\n'),
(91246, 30154, 'de', 'Cape Fox', 'The Cape Fox is a small, agile canid native to southern Africa, particularly found in the Cape region. It has a slender body, long legs, and a bushy tail, with a coat that is typically grayish-brown with a lighter underbelly. Cape Foxes are primarily nocturnal and are known for their adaptability to various habitats, including grasslands and savannas. \n\nCape Foxe are omnivorous, feeding on small mammals, birds, insects, and fruits.\n\n'),
(91247, 30154, 'da', 'Cape Fox', 'The Cape Fox is a small, agile canid native to southern Africa, particularly found in the Cape region. It has a slender body, long legs, and a bushy tail, with a coat that is typically grayish-brown with a lighter underbelly. Cape Foxes are primarily nocturnal and are known for their adaptability to various habitats, including grasslands and savannas. \n\nCape Foxe are omnivorous, feeding on small mammals, birds, insects, and fruits.\n\n'),
(91248, 206, 'en', 'Capybara', 'The capybara is the largest rodent in the world and a true water lover. It lives in South America and spends much of its time splashing around in rivers and swamps. In your zoo, it likes to doze half-soaked by the shore, unfazed by anything around it.'),
(91249, 206, 'de', 'Capybara', 'Das Capybara ist das größte Nagetier der Welt und ein echter Wassersportfan. Es lebt in Südamerika und verbringt viel Zeit planschend in Flüssen und Sümpfen. In deinem Zoo döst es gerne halbnass am Ufer und lässt sich von nichts aus der Ruhe bringen.'),
(91250, 206, 'da', 'Flodsvin', 'Flodsvinet er verdens største gnaver og er en ivrig vandentusiast. Det lever i Sydamerika og tilbringer meget tid plaskende i floder og sumpe. I din zoo slumrer det halvvådt ved bredden og lader ingenting rokke det ud af ligevægten.'),
(91251, 30155, 'en', 'Caquetá Titi Monkey', 'The Caquetá Titi Monkey is a small, endangered primate endemic to the Caquetá region of Colombia. With a body length of 30-40 cm (12-16 inches), and weighing 1-1.5 kg (2.2-3.3 lbs), it has soft, reddish-brown fur, a rounded head, and large eyes adapted for its arboreal lifestyle.\n\nCaquetá Titi Monkeys are omnivorous, primarily fruits and insects, supplemented by leaves, seeds, and small vertebrates.\n\n'),
(91252, 30155, 'de', 'Caquetá Titi Monkey', 'The Caquetá Titi Monkey is a small, endangered primate endemic to the Caquetá region of Colombia. With a body length of 30-40 cm (12-16 inches), and weighing 1-1.5 kg (2.2-3.3 lbs), it has soft, reddish-brown fur, a rounded head, and large eyes adapted for its arboreal lifestyle.\n\nCaquetá Titi Monkeys are omnivorous, primarily fruits and insects, supplemented by leaves, seeds, and small vertebrates.\n\n'),
(91253, 30155, 'da', 'Caquetá Titi Monkey', 'The Caquetá Titi Monkey is a small, endangered primate endemic to the Caquetá region of Colombia. With a body length of 30-40 cm (12-16 inches), and weighing 1-1.5 kg (2.2-3.3 lbs), it has soft, reddish-brown fur, a rounded head, and large eyes adapted for its arboreal lifestyle.\n\nCaquetá Titi Monkeys are omnivorous, primarily fruits and insects, supplemented by leaves, seeds, and small vertebrates.\n\n'),
(91254, 219, 'en', 'Caracal', 'The caracal is an elegant wild cat with distinctive black tufted ears. It can catch birds in mid-air with impressive jumps. In your zoo it prowls quietly through its enclosure, climbs with ease and proudly shows off its ear tufts again and again.'),
(91255, 219, 'de', 'Karakal', 'Der Karakal ist eine elegante Wildkatze mit markanten, schwarzen Pinselohren. Er kann mit beeindruckenden Sprüngen Vögel im Flug fangen. In deinem Zoo schleicht er leise durchs Gehege, klettert geschickt und präsentiert immer wieder stolz seine Ohrpinsel.'),
(91256, 219, 'da', 'Karakal', 'Karakalen er en elegant vildkat med markante, sorte penselører. Den kan med imponerende spring fange fugle i flugten. I din zoo sniger den sig stille igennem indhegningen, klatrer dygtigt og viser stolt sine ørepensler.'),
(91257, 30156, 'en', 'Caribou', 'The Caribou is a large Arctic deer adapted to cold climates. Their coats change color with the seasons, brown in summer and grey in winter, with white rumps and chests. Both sexes grow antlers, though males’ are larger and more branched. They are known for long migrations, sometimes in groups of up to 500,000 individuals.\n\nThe Caribou is a herbivore that feeds mainly on lichens, mosses, grasses, leaves, and twigs, digging through snow with its hooves to reach food.\n\n'),
(91258, 30156, 'de', 'Caribou', 'The Caribou is a large Arctic deer adapted to cold climates. Their coats change color with the seasons, brown in summer and grey in winter, with white rumps and chests. Both sexes grow antlers, though males’ are larger and more branched. They are known for long migrations, sometimes in groups of up to 500,000 individuals.\n\nThe Caribou is a herbivore that feeds mainly on lichens, mosses, grasses, leaves, and twigs, digging through snow with its hooves to reach food.\n\n'),
(91259, 30156, 'da', 'Caribou', 'The Caribou is a large Arctic deer adapted to cold climates. Their coats change color with the seasons, brown in summer and grey in winter, with white rumps and chests. Both sexes grow antlers, though males’ are larger and more branched. They are known for long migrations, sometimes in groups of up to 500,000 individuals.\n\nThe Caribou is a herbivore that feeds mainly on lichens, mosses, grasses, leaves, and twigs, digging through snow with its hooves to reach food.\n\n'),
(91260, 30157, 'en', 'Chaco Eagle', 'The Chaco Eagle is a large bird of prey found primarily in the Chaco region of South America. Characterized by its striking dark brown plumage and distinctive white head and tail, the Chaco Eagle is known for its powerful build and impressive wingspan, which can reach up to 6 feet (1.8 meters).  The Chaco Eagle is considered a near-threatened species due to habitat loss and hunting pressures, making conservation efforts essential for its survival.\n\nThis eagle primarily feeds on small to medium-sized mammals, reptiles, and birds, often hunting from a perch or soaring high in the sky.\n\n'),
(91261, 30157, 'de', 'Chaco Eagle', 'The Chaco Eagle is a large bird of prey found primarily in the Chaco region of South America. Characterized by its striking dark brown plumage and distinctive white head and tail, the Chaco Eagle is known for its powerful build and impressive wingspan, which can reach up to 6 feet (1.8 meters).  The Chaco Eagle is considered a near-threatened species due to habitat loss and hunting pressures, making conservation efforts essential for its survival.\n\nThis eagle primarily feeds on small to medium-sized mammals, reptiles, and birds, often hunting from a perch or soaring high in the sky.\n\n'),
(91262, 30157, 'da', 'Chaco Eagle', 'The Chaco Eagle is a large bird of prey found primarily in the Chaco region of South America. Characterized by its striking dark brown plumage and distinctive white head and tail, the Chaco Eagle is known for its powerful build and impressive wingspan, which can reach up to 6 feet (1.8 meters).  The Chaco Eagle is considered a near-threatened species due to habitat loss and hunting pressures, making conservation efforts essential for its survival.\n\nThis eagle primarily feeds on small to medium-sized mammals, reptiles, and birds, often hunting from a perch or soaring high in the sky.\n\n'),
(91266, 213, 'en', 'Cheetah', 'The cheetah is the fastest land animal in the world, capable of reaching astonishing top speeds in seconds. Its slender body and long legs are built perfectly for sprinting. In your zoo, it often rests calmly, though its watchful eyes reveal it\'s always ready to burst into motion at any moment.'),
(91267, 213, 'de', 'Gepard', 'Der Gepard ist das schnellste Landtier der Welt und erreicht in kurzer Zeit beeindruckende Spitzengeschwindigkeiten. Sein schlanker Körper und die langen Beine sind perfekt auf den Sprint ausgelegt. Im Zoo sieht man ihn oft ruhig ruhen, doch seine wachsamen Augen verraten, dass jederzeit ein Sprint möglich wäre.'),
(91268, 213, 'da', 'Gepard', 'Geparden er verdens hurtigste landdyr og kan nå imponerende tophastigheder på rekordtid. I din zoo hviler den ofte roligt, men dens vågne øjne afslører, at et sprint er muligt til enhver tid.'),
(91269, 332, 'en', 'Chimpanzee', 'The chimpanzee is one of our closest relatives and impresses with its intelligence. In groups it has a complex social structure and uses tools in everyday life. In your zoo it climbs, plays, quarrels and makes up again – almost like a tiny monkey city.'),
(91270, 332, 'de', 'Schimpanse', 'Der Schimpanse ist einer unserer nächsten Verwandten und beeindruckt durch seine Intelligenz. In Gruppen besitzt er eine komplexe Sozialstruktur und nutzt Werkzeuge im Alltag. In deinem Zoo klettert er, spielt, streitet und versöhnt sich – fast wie eine kleine Affenstadt.'),
(91271, 332, 'da', 'Chimpanse', 'Chimpansen er en af vores nærmeste slægtninge og imponerer med sin intelligens. I grupper har den en kompleks social struktur og bruger redskaber i hverdagen. I din zoo klatrer den, leger, skændes og forlignes – næsten som en lille abeby.');
INSERT INTO `animaltext` (`id`, `animalId`, `languageCode`, `animalName`, `animalDescription`) VALUES
(91272, 30158, 'en', 'Chinstrap Penguin', 'The Chinstrap Penguin is a medium-sized penguin species found primarily in the sub-Antarctic region. It is easily identifiable by the distinctive narrow black band that runs under its head, resembling a chinstrap, which gives the species its name. They have a sleek, streamlined body, with a black back, white belly, and a characteristic black cap on their head.\n\nChinstrap Penguins are carnivores (piscivores). They have a very simple diet, typically consisting of aquatic animals such as small fish and roaming marine crustaceans, including krill.\n\n'),
(91273, 30158, 'de', 'Chinstrap Penguin', 'The Chinstrap Penguin is a medium-sized penguin species found primarily in the sub-Antarctic region. It is easily identifiable by the distinctive narrow black band that runs under its head, resembling a chinstrap, which gives the species its name. They have a sleek, streamlined body, with a black back, white belly, and a characteristic black cap on their head.\n\nChinstrap Penguins are carnivores (piscivores). They have a very simple diet, typically consisting of aquatic animals such as small fish and roaming marine crustaceans, including krill.\n\n'),
(91274, 30158, 'da', 'Chinstrap Penguin', 'The Chinstrap Penguin is a medium-sized penguin species found primarily in the sub-Antarctic region. It is easily identifiable by the distinctive narrow black band that runs under its head, resembling a chinstrap, which gives the species its name. They have a sleek, streamlined body, with a black back, white belly, and a characteristic black cap on their head.\n\nChinstrap Penguins are carnivores (piscivores). They have a very simple diet, typically consisting of aquatic animals such as small fish and roaming marine crustaceans, including krill.\n\n'),
(91275, 631, 'en', 'Clouded Leopard', 'The clouded leopard is a medium‑sized big cat with large, cloud‑like spots. It lives in the forests of Asia and is an excellent climber. In your zoo it moves skillfully through the branches and appears almost ghostly quiet.'),
(91276, 631, 'de', 'Nebelparder', 'Der Nebelparder ist eine mittelgroße Großkatze mit großen, nebelartigen Flecken. Er lebt in den Wäldern Asiens und ist ein hervorragender Kletterer. In deinem Zoo bewegt er sich geschickt im Geäst und wirkt dabei fast geisterhaft leise.'),
(91277, 631, 'da', 'Mandrilbavian', 'Mandrilen er den største aber i verden og er kendetegnet ved hannernes farverige ansigt og bagdel. Disse livlige farver er tegn på dominans og sundhed og er mere intense, når hannen er ophidset.'),
(91281, 119, 'en', 'Coati', 'The Coati has a long, flexible snout and is a curious acrobat in the enclosure. It\'s at home in Central and South America and constantly on the lookout for insects, fruits, and small treats. In the zoo, it climbs skillfully on branches, sniffs everywhere, and provides plenty of entertainment with its sociable nature.'),
(91282, 119, 'de', 'Nasenbär', 'Der Nasenbär ist mit seiner langen, beweglichen Schnauze ein neugieriger Akrobat im Gehege. Er ist in Mittel- und Südamerika zuhause und ständig auf der Suche nach Insekten, Früchten und kleinen Leckerbissen. Im Zoo klettert er geschickt auf Äste, schnüffelt überall herum und sorgt mit seinem geselligen Wesen für viel Unterhaltung.'),
(91283, 119, 'da', 'Næsebjørn', 'Næsebjørnen har en lang, bevægelig snude og er en nysgerrig akrobat i indhegningen. Den er hjemme i Syd- og Mellemamerika og er konstant på udkig efter insekter og lækkerier. I din zoo klatrer den dygtigt op i grene og snuser overalt.'),
(91284, 217, 'en', 'Collared Peccary', 'The collared peccary is a pig-like animal from North and South America. It gets its name from the lighter ring of fur around its neck. In your zoo it rummages through the enclosure in groups and communicates with growling and grunting sounds.'),
(91285, 217, 'de', 'Halsbandpekari', 'Der Halsbandpekari ist ein wildschweinähnliches Tier aus Nord- und Südamerika. Seinen Namen verdankt er dem helleren Fellring um den Hals. In deinem Zoo durchstöbert er in Gruppen das Gehege und kommuniziert mit knurrenden und grunzenden Lauten.'),
(91286, 217, 'da', 'Halsbånds-pekari', 'Halsbåndspekari er et vildsvinelignende dyr fra Nord- og Sydamerika. Det skylder sit navn den lysere pelskrans om halsen. I din zoo søger det i grupper igennem indhegningen og kommunikerer med knurrende lyde.'),
(91287, 30159, 'en', 'Commerson\'s Dolphin', 'Commerson\'s Dolphin is a small oceanic dolphin of the genus Cephalorhynchus. These dolphins have a black head, dorsal fin, and fluke, with a white throat and body. Their black and white pattern varies with age, sex, and geographic location. Males and females are easily distinguished by the different shape of the black blotch on the belly. It is shaped like a teardrop in males but is more rounded in females.\n\nCommerson’s Dolphins eat a wide variety of coastal prey including schooling fish such as hake, sardines, silversides and anchovies; squids, marine worms, shrimps and occasionally seaweed. \n\n'),
(91288, 30159, 'de', 'Commerson\'s Dolphin', 'Commerson\'s Dolphin is a small oceanic dolphin of the genus Cephalorhynchus. These dolphins have a black head, dorsal fin, and fluke, with a white throat and body. Their black and white pattern varies with age, sex, and geographic location. Males and females are easily distinguished by the different shape of the black blotch on the belly. It is shaped like a teardrop in males but is more rounded in females.\n\nCommerson’s Dolphins eat a wide variety of coastal prey including schooling fish such as hake, sardines, silversides and anchovies; squids, marine worms, shrimps and occasionally seaweed. \n\n'),
(91289, 30159, 'da', 'Commerson\'s Dolphin', 'Commerson\'s Dolphin is a small oceanic dolphin of the genus Cephalorhynchus. These dolphins have a black head, dorsal fin, and fluke, with a white throat and body. Their black and white pattern varies with age, sex, and geographic location. Males and females are easily distinguished by the different shape of the black blotch on the belly. It is shaped like a teardrop in males but is more rounded in females.\n\nCommerson’s Dolphins eat a wide variety of coastal prey including schooling fish such as hake, sardines, silversides and anchovies; squids, marine worms, shrimps and occasionally seaweed. \n\n'),
(91290, 315, 'en', 'Common Genet', 'The genet is a slender, nocturnal predator with a long tail and a beautiful spotted coat. It is an excellent climber and roams its territory at night in search of food. In your zoo it needs plenty of hiding places and shows off its elegance especially in the evening hours.'),
(91291, 315, 'de', 'Ginsterkatze', 'Die Ginsterkatze ist ein schlankes, nachtaktives Raubtier mit langem Schwanz und schöner Fleckenzeichnung. Sie klettert hervorragend und streift nachts auf Nahrungssuche durch ihr Revier. In deinem Zoo braucht sie viele Verstecke und zeigt ihre Eleganz vor allem in den Abendstunden.'),
(91292, 315, 'da', 'Genette', 'Genetten er et slankbygget, nattaktivt rovdyr med en lang hale og smukt plettet pels. Den er en fremragende klatrer og strejfer om natten i sit territorium på jagt efter føde. I din zoo har den brug for mange skjulesteder og viser sin elegance særligt i aftentimerne.'),
(91293, 30160, 'en', 'Common Kestrel', 'The Common Kestrel is a small bird of prey found across Europe, Asia, and parts of Africa. The male has a reddish-brown plumage with a gray head, while the female is more uniformly brown. Kestrels are known for their keen eyesight and ability to spot prey from great heights. They typically nest in cliffs, trees, or man-made structures, making them adaptable to various environments.\n\nCommon Kestrel often hunts small mammals, birds, and insects.\n\n'),
(91294, 30160, 'de', 'Common Kestrel', 'The Common Kestrel is a small bird of prey found across Europe, Asia, and parts of Africa. The male has a reddish-brown plumage with a gray head, while the female is more uniformly brown. Kestrels are known for their keen eyesight and ability to spot prey from great heights. They typically nest in cliffs, trees, or man-made structures, making them adaptable to various environments.\n\nCommon Kestrel often hunts small mammals, birds, and insects.\n\n'),
(91295, 30160, 'da', 'Common Kestrel', 'The Common Kestrel is a small bird of prey found across Europe, Asia, and parts of Africa. The male has a reddish-brown plumage with a gray head, while the female is more uniformly brown. Kestrels are known for their keen eyesight and ability to spot prey from great heights. They typically nest in cliffs, trees, or man-made structures, making them adaptable to various environments.\n\nCommon Kestrel often hunts small mammals, birds, and insects.\n\n'),
(91296, 30161, 'en', 'Common Murre', 'The Common Murre is a large seabird belonging to the auk family. The bird\'s distinctive appearance features a dark brown or black head and back, with a white belly and a sharp, pointed bill. It typically measures about 16 to 18 inches (40 to 46 cm) in length and has a wingspan of approximately 26 to 30 inches (66 to 76 cm). \n\nCommon Murres are carnivores (piscivores). Capelin and sand lances are a favorite food, but what the main prey is at any one time depends much on what is available in quantity. \n\n'),
(91297, 30161, 'de', 'Common Murre', 'The Common Murre is a large seabird belonging to the auk family. The bird\'s distinctive appearance features a dark brown or black head and back, with a white belly and a sharp, pointed bill. It typically measures about 16 to 18 inches (40 to 46 cm) in length and has a wingspan of approximately 26 to 30 inches (66 to 76 cm). \n\nCommon Murres are carnivores (piscivores). Capelin and sand lances are a favorite food, but what the main prey is at any one time depends much on what is available in quantity. \n\n'),
(91298, 30161, 'da', 'Common Murre', 'The Common Murre is a large seabird belonging to the auk family. The bird\'s distinctive appearance features a dark brown or black head and back, with a white belly and a sharp, pointed bill. It typically measures about 16 to 18 inches (40 to 46 cm) in length and has a wingspan of approximately 26 to 30 inches (66 to 76 cm). \n\nCommon Murres are carnivores (piscivores). Capelin and sand lances are a favorite food, but what the main prey is at any one time depends much on what is available in quantity. \n\n'),
(91299, 503, 'en', 'Common Ostrich', 'The African Ostrich is the largest living bird and a fast runner. Even though it cannot fly, it reaches impressive speeds when fleeing. In your zoo, it likes to race across the enclosure and curiously peek over the fence.'),
(91300, 503, 'de', 'Afrikanischer Strauß', 'Der Afrikanische Strauß ist der größte lebende Vogel und ein schneller Läufer. Obwohl er nicht fliegen kann, erreicht er beeindruckende Geschwindigkeiten auf der Flucht. In deinem Zoo rennt er gerne über die Anlage und schaut neugierig über den Zaun.'),
(91301, 503, 'da', 'Gepard', 'Gepardens er det hurtigste landpattedyr på Jorden og kan nå hastigheder på op til 120 km/t. Dens slanke krop og lange ben er perfekt tilpasset til højthastighedsjagt på åbne sletter.'),
(91302, 30162, 'en', 'Common Vampire Bat', 'The Common Vampire Bat is a small, leaf-nosed bat native to Latin America. It is short-haired, with silver-gray fur on its undersides, demarcated from the darker fur on its back. A well-developed, clawed thumb on each wing is used to climb onto prey and assist the animal in take-off. While most other bats have almost completely lost the ability to maneuver on land, vampire bats are an exception. They can run using a unique, bounding gait in which the forelimbs are used instead of the hindlimbs to propel forward, as the wings are much more powerful than the legs.\n\nCommon Vampire Bats are carnivores and feed primarily on mammalian blood, particularly that of livestock such as cattle and horses.\n\n'),
(91303, 30162, 'de', 'Common Vampire Bat', 'The Common Vampire Bat is a small, leaf-nosed bat native to Latin America. It is short-haired, with silver-gray fur on its undersides, demarcated from the darker fur on its back. A well-developed, clawed thumb on each wing is used to climb onto prey and assist the animal in take-off. While most other bats have almost completely lost the ability to maneuver on land, vampire bats are an exception. They can run using a unique, bounding gait in which the forelimbs are used instead of the hindlimbs to propel forward, as the wings are much more powerful than the legs.\n\nCommon Vampire Bats are carnivores and feed primarily on mammalian blood, particularly that of livestock such as cattle and horses.\n\n'),
(91304, 30162, 'da', 'Common Vampire Bat', 'The Common Vampire Bat is a small, leaf-nosed bat native to Latin America. It is short-haired, with silver-gray fur on its undersides, demarcated from the darker fur on its back. A well-developed, clawed thumb on each wing is used to climb onto prey and assist the animal in take-off. While most other bats have almost completely lost the ability to maneuver on land, vampire bats are an exception. They can run using a unique, bounding gait in which the forelimbs are used instead of the hindlimbs to propel forward, as the wings are much more powerful than the legs.\n\nCommon Vampire Bats are carnivores and feed primarily on mammalian blood, particularly that of livestock such as cattle and horses.\n\n'),
(91305, 30163, 'en', 'Common Wombat', 'Common Wombats are short-legged, muscular quadrupedal marsupials that are native to Australia. As a matter of fact, the Common wombat is the largest burrowing herbivorous mammal in the world. Common Wombats are sturdy and built close to the ground. They are distinguished from both Hairy-Nosed Wombats by their bald nose. They are about 1 m (40 in) in length with small, stubby tails and weigh between 20 and 35 kg (44 and 77 lb).\n\nThe Common Wombat is an herbivorous (folivorous) animal, primarily feeding upon grass and moss. The diet of this animal also includes shrubs, roots, and barks. \n\n'),
(91306, 30163, 'de', 'Common Wombat', 'Common Wombats are short-legged, muscular quadrupedal marsupials that are native to Australia. As a matter of fact, the Common wombat is the largest burrowing herbivorous mammal in the world. Common Wombats are sturdy and built close to the ground. They are distinguished from both Hairy-Nosed Wombats by their bald nose. They are about 1 m (40 in) in length with small, stubby tails and weigh between 20 and 35 kg (44 and 77 lb).\n\nThe Common Wombat is an herbivorous (folivorous) animal, primarily feeding upon grass and moss. The diet of this animal also includes shrubs, roots, and barks. \n\n'),
(91307, 30163, 'da', 'Common Wombat', 'Common Wombats are short-legged, muscular quadrupedal marsupials that are native to Australia. As a matter of fact, the Common wombat is the largest burrowing herbivorous mammal in the world. Common Wombats are sturdy and built close to the ground. They are distinguished from both Hairy-Nosed Wombats by their bald nose. They are about 1 m (40 in) in length with small, stubby tails and weigh between 20 and 35 kg (44 and 77 lb).\n\nThe Common Wombat is an herbivorous (folivorous) animal, primarily feeding upon grass and moss. The diet of this animal also includes shrubs, roots, and barks. \n\n'),
(91308, 30164, 'en', 'Common Woolly Monkey', 'The Common Woolly Monkey is a large, arboreal primate native to the Amazon rainforest in South America, known for its thick, woolly fur and prehensile tail used for grasping branches. Weighing 5-9 kg (11-20 lbs) and measuring up to 70 cm (28 inches) in body length, it has grayish-brown fur, a long snout, and a lifespan of 20-30 years in the wild.\n\nCommon Woolly Monkeys are primarily frugivorous (fruit-eating), supplemented by leaves, seeds, and insects.\n\n'),
(91309, 30164, 'de', 'Common Woolly Monkey', 'The Common Woolly Monkey is a large, arboreal primate native to the Amazon rainforest in South America, known for its thick, woolly fur and prehensile tail used for grasping branches. Weighing 5-9 kg (11-20 lbs) and measuring up to 70 cm (28 inches) in body length, it has grayish-brown fur, a long snout, and a lifespan of 20-30 years in the wild.\n\nCommon Woolly Monkeys are primarily frugivorous (fruit-eating), supplemented by leaves, seeds, and insects.\n\n'),
(91310, 30164, 'da', 'Common Woolly Monkey', 'The Common Woolly Monkey is a large, arboreal primate native to the Amazon rainforest in South America, known for its thick, woolly fur and prehensile tail used for grasping branches. Weighing 5-9 kg (11-20 lbs) and measuring up to 70 cm (28 inches) in body length, it has grayish-brown fur, a long snout, and a lifespan of 20-30 years in the wild.\n\nCommon Woolly Monkeys are primarily frugivorous (fruit-eating), supplemented by leaves, seeds, and insects.\n\n'),
(91311, 2206, 'en', 'Compass Jellyfish', 'The compass jellyfish has radial patterns reminiscent of a compass. Its long tentacles float elegantly in the water. In your zoo, it looks like a floating star in the jellyfish aquarium.'),
(91312, 2206, 'de', 'Kompassqualle', 'Die Kompassqualle besitzt strahlenförmige Muster, die an einen Kompass erinnern. Ihre langen Tentakel schweben elegant im Wasser. In deinem Zoo wirkt sie wie ein schwebender Stern im Quallenaquarium.'),
(91313, 2206, 'da', 'Sværdfisk (tropisk)', 'Svæversugervisens er ikke relateret til den store sværdfisk. Disse farverige, livlige fisk er populære akvariefisk og føddes levende. Hanmerne har en karakteristisk forlænget havfinne, der bruges til at tiltrække hunner.'),
(91314, 30165, 'en', 'Coral Catshark', 'The Coral Catshark is a small species of shark found in the shallow waters of the coral reefs in the western Pacific and Indian Oceans. Typically reaching lengths of up to 1.2 meters (4 feet), this shark is characterized by its slender body, large eyes, and distinctive pattern of dark brown or black spots and stripes on a lighter background, which provides effective camouflage among the coral.\n\nCoral Catsharks are nocturnal and primarily feed on small fish, crustaceans, and invertebrates, using their keen sense of smell to locate prey. \n\n'),
(91315, 30165, 'de', 'Coral Catshark', 'The Coral Catshark is a small species of shark found in the shallow waters of the coral reefs in the western Pacific and Indian Oceans. Typically reaching lengths of up to 1.2 meters (4 feet), this shark is characterized by its slender body, large eyes, and distinctive pattern of dark brown or black spots and stripes on a lighter background, which provides effective camouflage among the coral.\n\nCoral Catsharks are nocturnal and primarily feed on small fish, crustaceans, and invertebrates, using their keen sense of smell to locate prey. \n\n'),
(91316, 30165, 'da', 'Coral Catshark', 'The Coral Catshark is a small species of shark found in the shallow waters of the coral reefs in the western Pacific and Indian Oceans. Typically reaching lengths of up to 1.2 meters (4 feet), this shark is characterized by its slender body, large eyes, and distinctive pattern of dark brown or black spots and stripes on a lighter background, which provides effective camouflage among the coral.\n\nCoral Catsharks are nocturnal and primarily feed on small fish, crustaceans, and invertebrates, using their keen sense of smell to locate prey. \n\n'),
(91317, 425, 'en', 'Cougar', 'The puma, also known as the mountain lion, inhabits a wide range of environments from rainforests to high mountains. It is an adaptable loner and a powerful sprinter. In your zoo, it moves gracefully through its enclosure, showing off its impressive athleticism.'),
(91318, 425, 'de', 'Puma', 'Der Puma, auch Berglöwe genannt, bewohnt viele Lebensräume vom Regenwald bis in Hochgebirge. Er ist ein anpassungsfähiger Einzelgänger und ein kraftvoller Sprinter. In deinem Zoo bewegt er sich geschmeidig durch die Anlage und zeigt seine beeindruckende Athletik.'),
(91319, 425, 'da', 'Puma', 'Pumaen, også kaldet bjørneløve, bor i mange levesteder fra regnskov til højbjerge. Den er en tilpasningsdygtig enspænder og en kraftfuld sprinter. I din zoo bevæger den sig smidig igennem anlægget og viser sin imponerende atletik.'),
(91320, 623, 'en', 'Crab-Eating Raccoon', 'The crab‑eating raccoon is a close relative of the raccoon and loves water. With its dexterous paws it feels around in the water for crabs and other treats. In your zoo it splashes joyfully in the water basins and searches every feeding hiding spot.'),
(91321, 623, 'de', 'Krabbenwaschbär', 'Der Krabbenwaschbär ist ein naher Verwandter des Waschbären und liebt Wasser. Mit seinen geschickten Pfoten tastet er im Wasser nach Krabben und anderen Leckerbissen. In deinem Zoo plantscht er begeistert in Wasserbecken und durchsucht jedes Futterversteck.'),
(91322, 623, 'da', 'Varanus', 'Varanerne er en gruppe store øgler, der er hjemmehørende i Afrika, Asien og Australien. De er kendte for deres todelte tunger, der bruges til at \"lugte\" luften. Komodovaranen er den største firben i verden.'),
(91323, 413, 'en', 'Crested Porcupine', 'The common porcupine wears an impressive armor made of long, sharp spines. When threatened, it raises them and rattles them as a warning. In your zoo it instantly draws attention with its striking silhouette.'),
(91324, 413, 'de', 'Gewöhnliches Stachelschwein', 'Das Gewöhnliche Stachelschwein trägt eine eindrucksvolle Rüstung aus langen, spitzen Stacheln. Bei Gefahr stellt es diese auf und rasselt zur Warnung. In deinem Zoo zieht es dank seiner spektakulären Silhouette sofort die Aufmerksamkeit auf sich.'),
(91325, 413, 'da', 'Almindeligt pindsvin', 'Det almindelige pindsvin bærer en imponerende rustning af lange, skarpe pigge. Når det trues, rejser det dem og rasler dem som advarsel. I din zoo tiltrækker det øjeblikkeligt opmærksomhed med sin spektakulære silhuet.'),
(91326, 203, 'en', 'Culpeo', 'The Andean fox lives in South America\'s high altitudes, perfectly adapted to the harsh climate. Its dense fur protects against cold, and it\'s both hunter and scavenger. In your zoo, it roams curiously through the enclosure, watching everything with alert, clever eyes.'),
(91327, 203, 'de', 'Andenfuchs', 'Der Andenfuchs lebt in den Höhenlagen Südamerikas und ist perfekt an das raue Klima angepasst. Sein dichtes Fell schützt ihn vor Kälte, und er ist sowohl Jäger als auch Aasfresser. In deinem Zoo streift er neugierig durch das Gehege und beobachtet alles mit wachen, klugen Augen.'),
(91328, 203, 'da', 'Andesræv', 'Andesræven lever i højlandet i Sydamerika og er perfekt tilpasset det barske klima med sit tykke pels. I din zoo strejfer den nysgerrigt rundt i indhegningen og holder øje med alt med kloge øjne.'),
(91329, 650, 'en', 'Cuscus', 'The spotted cuscus is an arboreal marsupial with a beautifully spotted coat. It lives in New Guinea and feeds on leaves and fruit. In your zoo, it climbs slowly and carefully through the branches and sleeps hidden during the day.'),
(91330, 650, 'de', 'Tüpfelkuskus', 'Der Tüpfelkuskus ist ein baumbewohnendes Beuteltier mit geflecktem Fell. Er lebt in Neuguinea und ernährt sich von Blättern und Früchten. In deinem Zoo klettert er langsam und bedacht durch das Geäst und schläft tagsüber gerne versteckt.'),
(91331, 650, 'da', 'Kæmpe-pungdyr', 'Den store myresluger er et unikt pattedyr uden tænder. Den har en lang, klistret tunge på op til 60 cm, der bruges til at fange myrer og termitter. Den kan spise op til 35.000 insekter om dagen.'),
(91332, 30166, 'en', 'Dalmatian Pelican', 'The Dalmatian Pelican is the largest freshwater bird in Europe and one of the world\'s heaviest flying birds, known for its massive size, elegant white plumage, and distinctive yellow gular pouch used for scooping fish. They have mostly white feathers with black flight feathers visible in flight, a pale yellow bill and pouch, and curly nape feathers during breeding season, giving a \"curly-headed\" look.\n\nPrimarily piscivorous, consuming fish like carp and perch; occasionally takes amphibians or crustaceans.\n\n'),
(91333, 30166, 'de', 'Dalmatian Pelican', 'The Dalmatian Pelican is the largest freshwater bird in Europe and one of the world\'s heaviest flying birds, known for its massive size, elegant white plumage, and distinctive yellow gular pouch used for scooping fish. They have mostly white feathers with black flight feathers visible in flight, a pale yellow bill and pouch, and curly nape feathers during breeding season, giving a \"curly-headed\" look.\n\nPrimarily piscivorous, consuming fish like carp and perch; occasionally takes amphibians or crustaceans.\n\n'),
(91334, 30166, 'da', 'Dalmatian Pelican', 'The Dalmatian Pelican is the largest freshwater bird in Europe and one of the world\'s heaviest flying birds, known for its massive size, elegant white plumage, and distinctive yellow gular pouch used for scooping fish. They have mostly white feathers with black flight feathers visible in flight, a pale yellow bill and pouch, and curly nape feathers during breeding season, giving a \"curly-headed\" look.\n\nPrimarily piscivorous, consuming fish like carp and perch; occasionally takes amphibians or crustaceans.\n\n'),
(91335, 30167, 'en', 'De Brazza\'s Monkey', 'De Brazza\'s Monkeys, locally known as swamp monkeys, are primates which are named after the Italian-French explorer Pierre Savorgnan de Brazza. Their scientific species name, \'\'neglectus,\'\' which means to pay no attention to, was given to them because of their ability to hide from both humans and predators. It can be differentiated from other monkeys by its orange diadem and white beard. Although these primates are generally arboreal, they can also spend their time in water and on the ground.\n\nAs omnivorous animals, De Brazza\'s Monkeys feed upon a wide variety of food, including leaves, flowers and mushrooms, supplementing this diet with occasional beetles, termites, and worms. However, their main food is fruits.\n\n'),
(91336, 30167, 'de', 'De Brazza\'s Monkey', 'De Brazza\'s Monkeys, locally known as swamp monkeys, are primates which are named after the Italian-French explorer Pierre Savorgnan de Brazza. Their scientific species name, \'\'neglectus,\'\' which means to pay no attention to, was given to them because of their ability to hide from both humans and predators. It can be differentiated from other monkeys by its orange diadem and white beard. Although these primates are generally arboreal, they can also spend their time in water and on the ground.\n\nAs omnivorous animals, De Brazza\'s Monkeys feed upon a wide variety of food, including leaves, flowers and mushrooms, supplementing this diet with occasional beetles, termites, and worms. However, their main food is fruits.\n\n'),
(91337, 30167, 'da', 'De Brazza\'s Monkey', 'De Brazza\'s Monkeys, locally known as swamp monkeys, are primates which are named after the Italian-French explorer Pierre Savorgnan de Brazza. Their scientific species name, \'\'neglectus,\'\' which means to pay no attention to, was given to them because of their ability to hide from both humans and predators. It can be differentiated from other monkeys by its orange diadem and white beard. Although these primates are generally arboreal, they can also spend their time in water and on the ground.\n\nAs omnivorous animals, De Brazza\'s Monkeys feed upon a wide variety of food, including leaves, flowers and mushrooms, supplementing this diet with occasional beetles, termites, and worms. However, their main food is fruits.\n\n'),
(91338, 427, 'en', 'Dhole', 'The dhole, or Asiatic wild dog, is a highly social predator that hunts in packs. Its reddish coat and pointed ears make it easily recognizable. In your zoo, it demonstrates its teamwork within the pack and is always on the move.'),
(91339, 427, 'de', 'Rothund', 'Der Rothund ist ein sozialer Wildhund aus Asien, der im Rudel jagt. Sein rostrotes Fell und die spitzen Ohren machen ihn leicht erkennbar. In deinem Zoo zeigt er seine Teamfähigkeit im Rudel und ist ständig in Bewegung.'),
(91340, 427, 'da', 'Dhol', 'Dholen er en meget social asiatisk vildhund, der jager i flokke. Dens rødlige pels og spidse ører gør den let genkendelig. I din zoo demonstrerer den sin teamwork i flokken og er altid i bevægelse.'),
(91341, 207, 'en', 'Dikdik', 'The dik-dik is a tiny antelope species with big eyes and a slightly elongated nose. It lives in the bushlands of Africa and prefers the shade of low shrubs. In your zoo, it darts nimbly through the undergrowth, melting visitors\' hearts in an instant.'),
(91342, 207, 'de', 'Dikdik', 'Das Dikdik ist eine winzige Antilopenart mit großen Augen und einer leicht verlängerten Schnauze. Es lebt in den Buschlandschaften Afrikas und bleibt am liebsten im Schatten niedriger Büsche. In deinem Zoo huscht es flink durchs Unterholz und lässt die Herzen der Besucher im Nu dahinschmelzen.'),
(91343, 207, 'da', 'Dikdik', 'Dikdikken er en bitte lille antilopeart med store øjne og en let forlænget snude. Den lever i Afrikas busklandskaber og foretrækker skyggen af lave buske. I din zoo piler den rask igennem buskadset og smelter besøgendes hjerter på stedet.'),
(91344, 30168, 'en', 'Dingo', 'The Dingo is a medium-sized canine that possesses a lean, hardy body adapted for speed, agility, and stamina. The Dingo\'s main coat colorations are light ginger or tan, black and tan, or creamy white. The head is the widest part of the body, wedge-shaped, and large in proportion to the body\n\nDingoes are effective predators, and their diet primarily consists of mammalian prey. The most common targets are medium to large-sized animals, including various species of kangaroos and wallabies.\n\n'),
(91345, 30168, 'de', 'Dingo', 'The Dingo is a medium-sized canine that possesses a lean, hardy body adapted for speed, agility, and stamina. The Dingo\'s main coat colorations are light ginger or tan, black and tan, or creamy white. The head is the widest part of the body, wedge-shaped, and large in proportion to the body\n\nDingoes are effective predators, and their diet primarily consists of mammalian prey. The most common targets are medium to large-sized animals, including various species of kangaroos and wallabies.\n\n'),
(91346, 30168, 'da', 'Dingo', 'The Dingo is a medium-sized canine that possesses a lean, hardy body adapted for speed, agility, and stamina. The Dingo\'s main coat colorations are light ginger or tan, black and tan, or creamy white. The head is the widest part of the body, wedge-shaped, and large in proportion to the body\n\nDingoes are effective predators, and their diet primarily consists of mammalian prey. The most common targets are medium to large-sized animals, including various species of kangaroos and wallabies.\n\n'),
(91347, 2103, 'en', 'Discus', 'The discus fish is a round, brilliantly colored ornamental fish from the Amazon. It glides gracefully through the water and prefers living in groups. In your zoo, its aquarium looks like a living painting.'),
(91348, 2103, 'de', 'Diskusfisch', 'Der Diskusfisch ist ein runder, farbenprächtiger Zierfisch aus dem Amazonas. Er hat ruhige Schwimmbewegungen und lebt gerne im Schwarm. In deinem Zoo wirkt sein Aquarium wie ein lebendes Gemälde.'),
(91349, 2103, 'da', 'Bæver', 'Bæveren er en ingeniør-dyr, der bygger dæmninger og løber for at skabe sin eget vandmiljø. Bæver-dæmninger kan ændre hele landskaber og skabe habitater for mange andre dyrearter. Den er et nøgleartsdyr.'),
(91350, 110, 'en', 'Domestic Goat', 'The domestic goat is a climbing enthusiast that tries almost anything that comes its way. For a long time, it has provided humans with milk, meat, and wool, but it\'s also popular as a character animal. In your zoo, it jumps on rocks, scratches against posts, and bleats friendly at visitors.'),
(91351, 110, 'de', 'Hausziege', 'Die Hausziege ist eine kletterfreudige Genießerin, die fast alles probiert, was ihr vor die Schnauze kommt. Seit langer Zeit liefert sie den Menschen Milch, Fleisch und Wolle, ist aber auch als Charaktertier beliebt. In deinem Zoo springt sie auf Felsen, kratzt sich an Pfosten und meckert die Besucher freundlich an.'),
(91352, 110, 'da', 'Husged', 'Husgedet er en klatreentutiast, der prøver næsten alt, hvad der kommer den for snuden. I din zoo hopper den på klipper, ridser sig mod pæle og bræger venligt til besøgende.'),
(91353, 109, 'en', 'Domestic Pig', 'The domestic pig is an intelligent and curious animal that loves to rummage the ground with its fine snout in search of treats. It has been kept in agriculture for centuries, but in the zoo, it can just be a pig. Visitors enjoy watching it sloppily wallow in the mud or contentedly doze side by side with its fellows.'),
(91354, 109, 'de', 'Hausschwein', 'Das Hausschwein ist ein intelligentes und neugieriges Tier, das gerne mit seiner feinen Schnauze den Boden nach Leckereien durchwühlt. In der Landwirtschaft wird es seit Jahrhunderten gehalten, doch im Zoo darf es einfach Schwein sein. Besucher beobachten gerne, wie es schmatzend im Schlamm wühlt oder zufrieden Seite an Seite mit seinen Artgenossen döst.'),
(91355, 109, 'da', 'Husgris', 'Husgrisen er et intelligent og nysgerrigt dyr, der elsker at rode i jorden med sin fine tryne. I din zoo kan man se den trippe glad i mudder og give fornøjede gryntelyde fra sig.'),
(91356, 619, 'en', 'Douc', 'The colobus monkey, also called clothing monkey, has long, high‑contrast fur. It originates from the forests of Africa and lives in social groups. In your zoo it swings elegantly from branch to branch and displays its striking \'clothing\'.'),
(91357, 619, 'de', 'Kleideraffe', 'Der Kleideraffe, auch Kleideraffe genannt, besitzt langes, kontrastreiches Fell. Er stammt aus den Wäldern Afrikas und lebt in sozialen Gruppen. In deinem Zoo schwingt er elegant von Ast zu Ast und zeigt seine auffällige „Kleidung“.'),
(91358, 619, 'da', 'Kolibri', 'Kolibrien er den eneste fugl, der kan flyve baglæns. Dens hjerte slår over 1200 gange i minuttet under flyvning. Den slår vingerne op til 80 gange i sekundet og lever primært af blomsterens nektar.'),
(91359, 508, 'en', 'Dromedary', 'The Dromedary is a desert animal with a single hump that serves as a fat store. It is perfectly adapted to heat and dryness and can go a long time without water. In your zoo, it strolls lazily through the sand enclosure and always looks a bit relaxed and sleepy.'),
(91360, 508, 'de', 'Dromedar', 'Das Dromedar ist ein Wüstentier mit nur einem Höcker, der als Fettspeicher dient. Es ist perfekt an Hitze und Trockenheit angepasst und kann lange ohne Wasser auskommen. In deinem Zoo schlendert es gemächlich durch das Sandgehege und wirkt immer ein wenig entspannt verschlafen.'),
(91361, 508, 'da', 'Afrikaansk olifant', 'Den afrikanske elefant er det største landdyr på Jorden. Disse intelligente dyr lever i komplekse familiegrupper ledet af en erfaren hunelefant og kommunikerer via infralyd.'),
(91362, 808, 'en', 'Dugong', 'The dugong is also known as the ‘sea cow’ and feeds on seagrass. It lives in warm coastal waters. In your zoo it glides peacefully through the water and creates a calm, serene mood.'),
(91363, 808, 'de', 'Dugong', 'Der Dugong wird auch als „Seekuh“ bezeichnet und ernährt sich von Seegras. Er lebt in warmen Küstengewässern. In deinem Zoo gleitet er ruhig durchs Wasser und verbreitet eine friedliche Stimmung.'),
(91364, 808, 'da', 'Havskildpadde', 'Havskildpadder er overlevende fra en svunden tid og har ikke ændret sig markant i over 100 millioner år. De navigerer utroligt præcist og vender altid tilbage til den strand, hvor de blev født, for at lægge æg.'),
(91365, 2202, 'en', 'Dumbo Octopus', 'The Dumbo octopus is a deep-sea octopus with ear-like fins. This makes it look especially cute. In your zoo, it shows how quirky deep-sea creatures can be.'),
(91366, 2202, 'de', 'Dumbo-Oktopus', 'Der Dumbo-Oktopus ist ein Tiefsee-Oktopus mit ohrenähnlichen Flossen. Er sieht dadurch besonders niedlich aus. In deinem Zoo zeigt er, wie skurril Tiefseebewohner sein können.'),
(91367, 2202, 'da', 'Havsedderkop', 'Loligos er en gruppe mellemstore blekksprutter, der lever i kystzone-vand. De er aktive jægere og svømmere og er vigtige kommercielle fiskeri-mål. De bruger bioluminescens til at kommunikere.'),
(91371, 1118, 'en', 'Eastern Chipmunk', 'The Chipmunk is a small rodent with striking stripes. It stores food in its cheek pouches. In your zoo, it’s always busy and a delight to watch.'),
(91372, 1118, 'de', 'Streifen-Backenhörnchen', 'Das Streifen-Backenhörnchen ist ein kleines Nagetier mit auffälligen Streifen. Es sammelt Nahrung in seinen Backentaschen. In deinem Zoo ist es ständig beschäftigt und eine Freude beim Beobachten.'),
(91373, 1118, 'da', 'Tropisk fugl', 'Tropiske fugle omfatter en enorm mangfoldighed af arter med lysende farver og komplekse opkald. Fra paradisfugle til tukaner er de tit nøglesprednere af frugtfrø i regnskovene.'),
(91374, 122, 'en', 'Eastern Grass Owl', 'The Eastern Grass Owl is an inconspicuous night moth that becomes active mainly at night. It lives in grasslands and fields and is an important part of the food chain. In your zoo, it flutters quietly through the evening air, creating a moody ambiance as a small, special guest.'),
(91375, 122, 'de', 'Östliche Graseule', 'Die Östliche Graseule ist ein unscheinbarer Nachtfalter, der vor allem nachts aktiv wird. Sie lebt in Graslandschaften und Feldern und ist ein wichtiger Teil der Nahrungskette. In deinem Zoo flattert sie leise durch die Abendluft und sorgt als kleiner, besonderer Gast für ein stimmungsvolles Ambiente.'),
(91376, 122, 'da', 'Østlig graseule', 'Den østlige graseule er en uanseelig natteugle, der primært er aktiv om natten. Den lever i græsmarker og er en vigtig del af fødekæden. I din zoo flakser den stille igennem aftenluftens stemningsfulde omgivelser.'),
(91377, 30170, 'en', 'Eastern Grey Kangaroo', 'The Eastern Grey Kangaroo is Australia’s largest marsupial. It has silvery-grey fur with a paler underbelly; males often have reddish fur on their forearms and shoulders. They have large, muscular hind legs for jumping (up to 9 m/30 ft in a single bound at speeds of 50 km/h or 30 mph), a long, thick tail for balance, and short forelimbs.\n\nEastern Grey Kangaroos are herbivorous browsers, feeding on grasses, forbs, leaves, and shrubs.\n\n'),
(91378, 30170, 'de', 'Eastern Grey Kangaroo', 'The Eastern Grey Kangaroo is Australia’s largest marsupial. It has silvery-grey fur with a paler underbelly; males often have reddish fur on their forearms and shoulders. They have large, muscular hind legs for jumping (up to 9 m/30 ft in a single bound at speeds of 50 km/h or 30 mph), a long, thick tail for balance, and short forelimbs.\n\nEastern Grey Kangaroos are herbivorous browsers, feeding on grasses, forbs, leaves, and shrubs.\n\n'),
(91379, 30170, 'da', 'Eastern Grey Kangaroo', 'The Eastern Grey Kangaroo is Australia’s largest marsupial. It has silvery-grey fur with a paler underbelly; males often have reddish fur on their forearms and shoulders. They have large, muscular hind legs for jumping (up to 9 m/30 ft in a single bound at speeds of 50 km/h or 30 mph), a long, thick tail for balance, and short forelimbs.\n\nEastern Grey Kangaroos are herbivorous browsers, feeding on grasses, forbs, leaves, and shrubs.\n\n'),
(91380, 835, 'en', 'Elephant Seal', 'The elephant seal is the largest species of seal, with males sporting a trunk-like nose. It inhabits cool coastal areas and can dive to great depths. In your zoo, its size and loud calls make it truly impressive.'),
(91381, 835, 'de', 'See-Elefant', 'Der See-Elefant ist die größte Robbenart und hat beim Männchen einen rüsselartigen Nasenaufsatz. Er lebt an kühlen Küsten und kann tief tauchen. In deinem Zoo wirkt er mit seiner Größe und den lauten Rufen besonders beeindruckend.'),
(91382, 835, 'da', 'Havlampret', 'Havlampretten er en primitiv, ålformet fisk uden kæbe. Den er en parasit, der fæstner sig til andre fisk med sin sugekopmund og lever af deres blod og kroppsvæsker. Den er et levende fossil.'),
(91383, 502, 'en', 'African Elephant', 'The African Elephant is the largest land mammal in the world. Its enormous ears and impressive tusks make it unmistakable. In your zoo, it is the gentle giant that plays with its trunk, bathes, and leaves visitors deeply impressed.'),
(91384, 502, 'de', 'Afrikanischer Elefant', 'Der Afrikanische Elefant ist das größte Landsäugetier der Welt. Seine riesigen Ohren und die imposanten Stoßzähne machen ihn unverwechselbar. In deinem Zoo ist er der sanfte Riese, der mit dem Rüssel spielt, badet und Besucher nachhaltig beeindruckt.'),
(91385, 502, 'da', 'Zebra', 'Zebraens sorte og hvide striber er unikke som et fingeraftryk og hjælper med at forvirre rovdyr. De lever i tætte familiegrupper og kommunikerer via lyde og kropssprog.'),
(91386, 30171, 'en', 'Emperor Penguin', 'The Emperor Penguin is the tallest and heaviest of all living penguin species and is endemic to Antarctica, reaching nearly 100 pounds at the largest (45 kgs). The Emperor Penguin has streamlined plumage, consisting of shiny, water-repellent feathers, which prevent the skin from getting wet. The blackish-blue head is covered with large white and yellow markings on the ears. The upperparts are blue-grey while the underparts are white. These flightless birds can stay underwater for up to 18 minutes when hunting for food. Emperor Penguins regularly live to 20 years in the wild.\n\nThis penguin is a carnivore (piscivore and molluscivore), feeding exclusively upon aquatic animals. Their diet mainly consists of krill and fish, supplemented with squid and crustaceans.\n\n'),
(91387, 30171, 'de', 'Emperor Penguin', 'The Emperor Penguin is the tallest and heaviest of all living penguin species and is endemic to Antarctica, reaching nearly 100 pounds at the largest (45 kgs). The Emperor Penguin has streamlined plumage, consisting of shiny, water-repellent feathers, which prevent the skin from getting wet. The blackish-blue head is covered with large white and yellow markings on the ears. The upperparts are blue-grey while the underparts are white. These flightless birds can stay underwater for up to 18 minutes when hunting for food. Emperor Penguins regularly live to 20 years in the wild.\n\nThis penguin is a carnivore (piscivore and molluscivore), feeding exclusively upon aquatic animals. Their diet mainly consists of krill and fish, supplemented with squid and crustaceans.\n\n'),
(91388, 30171, 'da', 'Emperor Penguin', 'The Emperor Penguin is the tallest and heaviest of all living penguin species and is endemic to Antarctica, reaching nearly 100 pounds at the largest (45 kgs). The Emperor Penguin has streamlined plumage, consisting of shiny, water-repellent feathers, which prevent the skin from getting wet. The blackish-blue head is covered with large white and yellow markings on the ears. The upperparts are blue-grey while the underparts are white. These flightless birds can stay underwater for up to 18 minutes when hunting for food. Emperor Penguins regularly live to 20 years in the wild.\n\nThis penguin is a carnivore (piscivore and molluscivore), feeding exclusively upon aquatic animals. Their diet mainly consists of krill and fish, supplemented with squid and crustaceans.\n\n'),
(91389, 1108, 'en', 'Emperor Scorpion', 'The Emperor Scorpion is one of the largest scorpions in the world. Under UV light, it glows with an eerie brilliance. In your zoo’s terrarium, it commands both cautious respect and deep fascination.'),
(91390, 1108, 'de', 'Kaiserskorpion', 'Der Kaiserskorpion ist einer der größten Skorpione der Welt. Unter UV-Licht leuchtet er geheimnisvoll. In deinem Zoo sorgt er im Terrarienbereich für vorsichtigen Respekt und Faszination.'),
(91391, 1108, 'da', 'Blad-halegekko', 'Den sataniske bladhale-gekko er opkaldt efter sit djævelske udseende med sine rødorangerede øjne og hornlignende øjenbryn. Dens hale ligner et tørret blad med stor præcision, inklusiv bidspor.'),
(91392, 617, 'en', 'Emperor Tamarin', 'The emperor tamarin has an impressively long, white mustache. It lives in South American rainforests and moves nimbly between the trees. In your zoo it jumps lively through the enclosure and proudly shows off its imperial facial hairstyle.'),
(91393, 617, 'de', 'Kaiserschnurrbarttamarin', 'Der Kaiserschnurrbarttamarin trägt einen beeindruckend langen, weißen Schnurrbart. Er lebt in südamerikanischen Regenwäldern und bewegt sich flink zwischen den Bäumen. In deinem Zoo springt er lebhaft durch das Gehege und präsentiert stolz seine kaiserliche Gesichtsfrisur.'),
(91394, 617, 'da', 'Tukan', 'Tukanens enorme, farverige næb kan udgøre op til en tredjedel af dens samlede kroplængde. Det tjener som en termoregulerende enhed og bruges til at nå frugt på svage grene.'),
(91395, 208, 'en', 'Emu', 'The emu is the second-largest bird in the world and a close relative of the ostrich. In Australia, it roams open landscapes and can run at impressive speeds. In your zoo, it patrols curiously along the fence, watching its visitors with keen eyes.'),
(91396, 208, 'de', 'Emu', 'Der Emu ist der zweitgrößte Vogel der Welt und ein naher Verwandter des Straußes. In Australien streift er durch offene Landschaften und kann erstaunlich schnell laufen. Im Zoo marschiert er neugierig am Zaun entlang und beobachtet seine Besucher mit wachen Augen.'),
(91397, 208, 'da', 'Emu', 'Emuen er verdens næststørste fugl og en nær slægtning til struds. I Australien strejfer den åbne landskaber og kan løbe overraskende hurtigt. I din zoo marcherer den nysgerrigt langs hegnet og betragter sine besøgende med kloge øjne.'),
(91398, 30172, 'en', 'Erect-Crested Penguin', 'The Erect-Crested Penguin is a medium-sized penguin endemic to the New Zealand region and only breeds on the Bounty and Antipodes Islands. It is easily recognizable by its striking yellow crest feathers that stand upright on its head. It has black upper parts, white underparts and a yellow eye stripe. Adults typically weigh between 5.5 to 8.5 pounds (2.5 to 4 kg) and measure about 20 to 25 inches (50 to 65 cm) in height.\n\nErect-Crested Penguins are carnivores (piscivores). The diet of these birds primarily consists of fish, krill, crustaceans and cephalopods.\n\n'),
(91399, 30172, 'de', 'Erect-Crested Penguin', 'The Erect-Crested Penguin is a medium-sized penguin endemic to the New Zealand region and only breeds on the Bounty and Antipodes Islands. It is easily recognizable by its striking yellow crest feathers that stand upright on its head. It has black upper parts, white underparts and a yellow eye stripe. Adults typically weigh between 5.5 to 8.5 pounds (2.5 to 4 kg) and measure about 20 to 25 inches (50 to 65 cm) in height.\n\nErect-Crested Penguins are carnivores (piscivores). The diet of these birds primarily consists of fish, krill, crustaceans and cephalopods.\n\n'),
(91400, 30172, 'da', 'Erect-Crested Penguin', 'The Erect-Crested Penguin is a medium-sized penguin endemic to the New Zealand region and only breeds on the Bounty and Antipodes Islands. It is easily recognizable by its striking yellow crest feathers that stand upright on its head. It has black upper parts, white underparts and a yellow eye stripe. Adults typically weigh between 5.5 to 8.5 pounds (2.5 to 4 kg) and measure about 20 to 25 inches (50 to 65 cm) in height.\n\nErect-Crested Penguins are carnivores (piscivores). The diet of these birds primarily consists of fish, krill, crustaceans and cephalopods.\n\n'),
(91401, 30173, 'en', 'Ethiopian Lion', 'The Ethiopian Lion is a subspecies of lion native to Ethiopia and parts of East Africa. It features a distinctive dark mane in males, tawny fur, and powerful build. Adults stand about 110-120 cm (43-47 inches) tall at the shoulder and weigh 150-250 kg (330-550 pounds) for males, with females smaller. \n\nIts diet primarily consists of large ungulates like zebras, antelopes, and wildebeest, which it hunts in prides using coordinated strategies.\n\n'),
(91402, 30173, 'de', 'Ethiopian Lion', 'The Ethiopian Lion is a subspecies of lion native to Ethiopia and parts of East Africa. It features a distinctive dark mane in males, tawny fur, and powerful build. Adults stand about 110-120 cm (43-47 inches) tall at the shoulder and weigh 150-250 kg (330-550 pounds) for males, with females smaller. \n\nIts diet primarily consists of large ungulates like zebras, antelopes, and wildebeest, which it hunts in prides using coordinated strategies.\n\n'),
(91403, 30173, 'da', 'Ethiopian Lion', 'The Ethiopian Lion is a subspecies of lion native to Ethiopia and parts of East Africa. It features a distinctive dark mane in males, tawny fur, and powerful build. Adults stand about 110-120 cm (43-47 inches) tall at the shoulder and weigh 150-250 kg (330-550 pounds) for males, with females smaller. \n\nIts diet primarily consists of large ungulates like zebras, antelopes, and wildebeest, which it hunts in prides using coordinated strategies.\n\n'),
(91404, 30174, 'en', 'Ethiopian Wolf', 'The Ethiopian Wolf is a canine native to the Ethiopian Highlands. Ethiopian wolves are slender, long-limbed canids. Their coats are reddish, with white marks on their legs, tail, belly, face, and chin. On the face are white markings, which include, below the eyes, a characteristic white crescent, and on the cheeks a white spot. It is one of the world\'s rarest canids, and Africa\'s most endangered carnivore.\n\nEthiopian Wolves are carnivorous and they mainly eat the rodents that are plentiful within their range. They hunt and eat hares, common grass rats, and giant mole rats. \n\n');
INSERT INTO `animaltext` (`id`, `animalId`, `languageCode`, `animalName`, `animalDescription`) VALUES
(91405, 30174, 'de', 'Ethiopian Wolf', 'The Ethiopian Wolf is a canine native to the Ethiopian Highlands. Ethiopian wolves are slender, long-limbed canids. Their coats are reddish, with white marks on their legs, tail, belly, face, and chin. On the face are white markings, which include, below the eyes, a characteristic white crescent, and on the cheeks a white spot. It is one of the world\'s rarest canids, and Africa\'s most endangered carnivore.\n\nEthiopian Wolves are carnivorous and they mainly eat the rodents that are plentiful within their range. They hunt and eat hares, common grass rats, and giant mole rats. \n\n'),
(91406, 30174, 'da', 'Ethiopian Wolf', 'The Ethiopian Wolf is a canine native to the Ethiopian Highlands. Ethiopian wolves are slender, long-limbed canids. Their coats are reddish, with white marks on their legs, tail, belly, face, and chin. On the face are white markings, which include, below the eyes, a characteristic white crescent, and on the cheeks a white spot. It is one of the world\'s rarest canids, and Africa\'s most endangered carnivore.\n\nEthiopian Wolves are carnivorous and they mainly eat the rodents that are plentiful within their range. They hunt and eat hares, common grass rats, and giant mole rats. \n\n'),
(91407, 30175, 'en', 'Eurasian Golden Oriole', 'The Eurasian Golden Oriole is a striking yellow-and-black bird with vibrant golden-yellow plumage, black wings, and a black eye stripe, resembling a tropical vision in Europe\'s temperate forests. Males are brighter; females greenish-yellow. They are known for its fluty, bubbling song and agile, undulating flight. \n\nEurasian Golden Oriole\'s diet mainly consists of insects like caterpillars, plus fruits, berries, and nectar.\n\n'),
(91408, 30175, 'de', 'Eurasian Golden Oriole', 'The Eurasian Golden Oriole is a striking yellow-and-black bird with vibrant golden-yellow plumage, black wings, and a black eye stripe, resembling a tropical vision in Europe\'s temperate forests. Males are brighter; females greenish-yellow. They are known for its fluty, bubbling song and agile, undulating flight. \n\nEurasian Golden Oriole\'s diet mainly consists of insects like caterpillars, plus fruits, berries, and nectar.\n\n'),
(91409, 30175, 'da', 'Eurasian Golden Oriole', 'The Eurasian Golden Oriole is a striking yellow-and-black bird with vibrant golden-yellow plumage, black wings, and a black eye stripe, resembling a tropical vision in Europe\'s temperate forests. Males are brighter; females greenish-yellow. They are known for its fluty, bubbling song and agile, undulating flight. \n\nEurasian Golden Oriole\'s diet mainly consists of insects like caterpillars, plus fruits, berries, and nectar.\n\n'),
(91410, 30176, 'en', 'Eurasian Hoopoe', 'The Eurasian Hoopoe is a colorful Old World bird with a striking cinnamon-pink body, black-and-white striped wings, and a long, erectile crest resembling a fan.  Known for its distinctive \"hoop-hoop\" call and undulating flight, it inhabits open woodlands, grasslands, and farmlands. Migratory in parts of its range.\n\nThe Eurasian Hoopoe\'s diet consists primarily of insects (80-90%), such as large grubs, pupae, beetles, ants, wasps, and caterpillars.\n\n'),
(91411, 30176, 'de', 'Eurasian Hoopoe', 'The Eurasian Hoopoe is a colorful Old World bird with a striking cinnamon-pink body, black-and-white striped wings, and a long, erectile crest resembling a fan.  Known for its distinctive \"hoop-hoop\" call and undulating flight, it inhabits open woodlands, grasslands, and farmlands. Migratory in parts of its range.\n\nThe Eurasian Hoopoe\'s diet consists primarily of insects (80-90%), such as large grubs, pupae, beetles, ants, wasps, and caterpillars.\n\n'),
(91412, 30176, 'da', 'Eurasian Hoopoe', 'The Eurasian Hoopoe is a colorful Old World bird with a striking cinnamon-pink body, black-and-white striped wings, and a long, erectile crest resembling a fan.  Known for its distinctive \"hoop-hoop\" call and undulating flight, it inhabits open woodlands, grasslands, and farmlands. Migratory in parts of its range.\n\nThe Eurasian Hoopoe\'s diet consists primarily of insects (80-90%), such as large grubs, pupae, beetles, ants, wasps, and caterpillars.\n\n'),
(91413, 310, 'en', 'European Badger', 'The European badger is a nocturnal carnivore with a characteristic black-and-white face pattern. It lives in extensive burrow systems and is a diligent digger. In your zoo you can watch it rooting around in the soil or dozing comfortably in its den.'),
(91414, 310, 'de', 'Europäischer Dachs', 'Der Europäische Dachs ist ein nachtaktives Raubtier mit charakteristischer schwarz-weißer Kopfmusterung. Er lebt in weit verzweigten Bauen und ist ein fleißiger Gräber. In deinem Zoo kann man ihn beim Wühlen im Boden und beim gemütlichen Dösen in seinem Bau beobachten.'),
(91415, 310, 'da', 'Europæisk grævling', 'Den europæiske grævling er et nattaktivt rovdyr med karakteristisk sort-hvid hovedmønster. Den lever i vidtforgrenede gravesystemer og er en flittig graver. I din zoo kan man se den rode i jorden og hvile komfortabelt i sin hule.'),
(91416, 1120, 'en', 'European Hamster', 'The European Hamster is larger than its pet relatives and lives in the wild. It has colorful fur and enjoys storing food in its burrow. In your zoo, it shows its hardworking side as it gathers and hides its treats.'),
(91417, 1120, 'de', 'Europäischer Hamster', 'Der Europäische Hamster ist größer als seine Heimtier-Verwandten und wildlebend. Er ist farbenfroh gefärbt und liebt Vorräte in seinem Bau. In deinem Zoo zeigt er seine fleißige Seite beim Sammeln und Verstecken von Futter.'),
(91418, 1120, 'da', 'Moskito', 'Myg er faktisk det dødligste dyr i verden for menneskene, da de overfører sygdomme som malaria, dengue og gul feber. Kun hunmyg stikker, mens hanmygene udelukkende lever af plantenektar.'),
(91419, 30177, 'en', 'European Mouflon', 'The European Mouflon is a small, wild sheep subspecies native to the Mediterranean islands of Sardinia and Corsica. It is considered the ancestor of domestic , known for its agile, mountain-dwelling lifestyle. They have reddish-brown coats with white underbellies, dark leg stripes, and large, curved horns in rams (up to 80 cm (32 inches) long) for defense and display.\n\nThe European Mouflon is a herbivorous grazer and browser, adapted to nutrient-poor Mediterranean vegetation. \n\n'),
(91420, 30177, 'de', 'European Mouflon', 'The European Mouflon is a small, wild sheep subspecies native to the Mediterranean islands of Sardinia and Corsica. It is considered the ancestor of domestic , known for its agile, mountain-dwelling lifestyle. They have reddish-brown coats with white underbellies, dark leg stripes, and large, curved horns in rams (up to 80 cm (32 inches) long) for defense and display.\n\nThe European Mouflon is a herbivorous grazer and browser, adapted to nutrient-poor Mediterranean vegetation. \n\n'),
(91421, 30177, 'da', 'European Mouflon', 'The European Mouflon is a small, wild sheep subspecies native to the Mediterranean islands of Sardinia and Corsica. It is considered the ancestor of domestic , known for its agile, mountain-dwelling lifestyle. They have reddish-brown coats with white underbellies, dark leg stripes, and large, curved horns in rams (up to 80 cm (32 inches) long) for defense and display.\n\nThe European Mouflon is a herbivorous grazer and browser, adapted to nutrient-poor Mediterranean vegetation. \n\n'),
(91422, 309, 'en', 'European Wildcat', 'The European wildcat looks very similar to a house cat, but is more strongly built and extremely shy. It lives in forests and usually avoids contact with humans. In your zoo it needs lots of hiding places and rewards you with rare but all the more exciting sightings.'),
(91423, 309, 'de', 'Europäische Wildkatze', 'Die Europäische Wildkatze ähnelt stark einer Hauskatze, ist aber kräftiger gebaut und sehr scheu. Sie bewohnt Wälder und meidet meist den Kontakt zum Menschen. In deinem Zoo braucht sie viele Verstecke und revanchiert sich mit seltenen, dafür umso spannenderen Sichtungen.'),
(91424, 309, 'da', 'Europæisk vildkat', 'Den europæiske vildkat ligner meget en huskat, men er kraftigere bygget og meget sky. Den lever i skove og undgår normalt kontakt med mennesker. I din zoo har den brug for mange skjulesteder og belønner tålmodige besøgende med sjældne, spændende sightings.'),
(91425, 2102, 'en', 'Everglades Crayfish', 'The blue Florida crayfish is a vivid blue freshwater crustacean from North America. In the aquarium, its color really stands out. In your zoo, it moves its claws skillfully and adds a vibrant splash of color to the water.'),
(91426, 2102, 'de', 'Blauer Floridakrebs', 'Der Blaue Floridakrebs ist ein leuchtend blauer Flusskrebs. Er stammt aus Nordamerika und ist im Aquarium besonders auffällig. In deinem Zoo bewegt er seine Scheren geschickt und sorgt für farbige Akzente im Wasser.'),
(91427, 2102, 'da', 'Flodskilpadde', 'Ferskvandsskildpadder lever i floder, søer og moser overalt i verden. De er tilpasset til at klatre op på sten og grene for at solle sig og er vigtige dele af ferskvandsøkosystemet.'),
(91428, 105, 'en', 'Fallow Deer', 'The Fallow Deer is an elegant forest dweller with a characteristic shovel-shaped antler. Its spotted coat reminds of sunspots in the woods, providing good camouflage in nature. In your zoo, it moves calmly through the enclosure, sniffs at grasses, and impresses visitors with its majestic presence.'),
(91429, 105, 'de', 'Damhirsch', 'Der Damhirsch ist ein eleganter Waldbewohner mit einem charakteristischen, schaufelförmigen Geweih. Seine gefleckte Decke erinnert an Sonnenflecken im Wald und bietet ihm in der Natur gute Tarnung. In deinem Zoo zieht er ruhig durchs Gehege, schnuppert an Gräsern und beeindruckt die Besucher mit seinem majestätischen Auftreten.'),
(91430, 105, 'da', 'Dådyr', 'Dådyret er en elegant skovboer med karakteristiske skovlformede gevir og et plettet skind. I din zoo bevæger det sig roligt gennem indhegningen og imponerer besøgende med sin majestætiske fremtræden.'),
(91431, 30178, 'en', 'Fea\'s Muntjac', 'Fea\'s Muntjac, also known as the Fea\'s barking deer, is a small species of deer found primarily in the forests of Southeast Asia. It is characterized by its compact size, typically standing about 60 to 80 cm (24 to 31 inches) at the shoulder and weighing between 15 to 25 kg (33 to 55 lbs). Fea\'s muntjac has a reddish-brown coat, with lighter underparts and distinctive facial markings. Males possess small antlers that are shed annually, while females are antlerless.\n\nFea\'s Muntjac is primarily herbivorous, feeding on leaves, fruits, and other vegetation.\n\n'),
(91432, 30178, 'de', 'Fea\'s Muntjac', 'Fea\'s Muntjac, also known as the Fea\'s barking deer, is a small species of deer found primarily in the forests of Southeast Asia. It is characterized by its compact size, typically standing about 60 to 80 cm (24 to 31 inches) at the shoulder and weighing between 15 to 25 kg (33 to 55 lbs). Fea\'s muntjac has a reddish-brown coat, with lighter underparts and distinctive facial markings. Males possess small antlers that are shed annually, while females are antlerless.\n\nFea\'s Muntjac is primarily herbivorous, feeding on leaves, fruits, and other vegetation.\n\n'),
(91433, 30178, 'da', 'Fea\'s Muntjac', 'Fea\'s Muntjac, also known as the Fea\'s barking deer, is a small species of deer found primarily in the forests of Southeast Asia. It is characterized by its compact size, typically standing about 60 to 80 cm (24 to 31 inches) at the shoulder and weighing between 15 to 25 kg (33 to 55 lbs). Fea\'s muntjac has a reddish-brown coat, with lighter underparts and distinctive facial markings. Males possess small antlers that are shed annually, while females are antlerless.\n\nFea\'s Muntjac is primarily herbivorous, feeding on leaves, fruits, and other vegetation.\n\n'),
(91434, 511, 'en', 'Fennec Fox', 'The Fennec Fox is a desert fox with enormous ears that help it stay cool. It is nocturnal and highly adapted to life in dry regions. In your zoo, it looks especially cute and mysterious with its big ear‑jewelry.'),
(91435, 511, 'de', 'Fennek', 'Der Fennek ist ein Wüstenfuchs mit riesigen Ohren, die ihm beim Kühlen helfen. Er ist nachtaktiv und sehr an das Leben in trockenen Regionen angepasst. In deinem Zoo wirkt er mit seinem großen Ohr-Schmuck besonders niedlich und geheimnisvoll.'),
(91436, 511, 'da', 'Kenguruugle', 'Det er et nataktivt dyr med en lang snude og klistret tunge, der bruges til at fange myrer og termitter. Dens kraftige klør graver hurtigt underjordiske huler.'),
(91437, 1117, 'en', 'Ferret Badger', 'The Sun Bear is a small member of the marten family with a light patch on its chest. It\'s an agile climber and skilled hunter. In your zoo, it’s a lively and inquisitive resident of the predator house.'),
(91438, 1117, 'de', 'Sonnendachs', 'Der Sonnendachs ist ein kleiner Marder mit hellem Fleck auf der Brust. Er ist ein geschickter Kletterer und Jäger. In deinem Zoo ist er ein lebhafter, neugieriger Bewohner des Raubtierhauses.'),
(91439, 1117, 'da', 'Skovjordsbi', 'Skovbiller er en ekstremt mangfoldig gruppe insekter der er tilpasset til livet i skovmiljøet. De spiller en vigtig rolle i nedbrydning af organisk materiale og som fødekilde for mange dyr.'),
(91440, 30179, 'en', 'Ferruginous Hawk', 'The Ferruginous Hawk is a large, powerful North American hawk with two color morphs. Light morphs have rusty-red (ferruginous) upperparts, a white breast, and rufous leg feathers; dark morphs are overall brown. Found in open grasslands, deserts, and prairies of western North America. \n\nFerruginous Hawk hunts small mammals like rabbits, ground squirrels, and mice; also birds and insects.\n\n'),
(91441, 30179, 'de', 'Ferruginous Hawk', 'The Ferruginous Hawk is a large, powerful North American hawk with two color morphs. Light morphs have rusty-red (ferruginous) upperparts, a white breast, and rufous leg feathers; dark morphs are overall brown. Found in open grasslands, deserts, and prairies of western North America. \n\nFerruginous Hawk hunts small mammals like rabbits, ground squirrels, and mice; also birds and insects.\n\n'),
(91442, 30179, 'da', 'Ferruginous Hawk', 'The Ferruginous Hawk is a large, powerful North American hawk with two color morphs. Light morphs have rusty-red (ferruginous) upperparts, a white breast, and rufous leg feathers; dark morphs are overall brown. Found in open grasslands, deserts, and prairies of western North America. \n\nFerruginous Hawk hunts small mammals like rabbits, ground squirrels, and mice; also birds and insects.\n\n'),
(91443, 1103, 'en', 'Fire Salamander', 'The Fire Salamander is a strikingly black-and-yellow colored amphibian species. Its coloration warns predators of its toxicity. In your zoo, it lives in moist terrariums and loves to show itself after an artificial \'rain shower.\''),
(91444, 1103, 'de', 'Feuersalamander', 'Der Feuersalamander ist eine auffällig schwarz-gelb gefärbte Amphibienart. Seine Färbung warnt Fressfeinde vor seiner Giftigkeit. In deinem Zoo lebt er in feuchten Terrarien und zeigt sich gern nach einem künstlichen „Regenguss“.'),
(91445, 1103, 'da', 'Bladinsekt', 'Bladinsektet er et af de mest imponerende eksempler på kamouflage i naturen. Dens krop ligner et grønt blad med årer, og dens ben ligner bladrande. Den svinger endda sagte for at efterligne et blad i vinden.'),
(91449, 211, 'en', 'Flamingo', 'The flamingo, with its pink feathers and long legs, is a true star among waterbirds. Its color comes from the pigments in its food, like tiny crustaceans. In your zoo, it loves standing on one leg in the water, turning its colorful colony into a perfect holiday scene.'),
(91450, 211, 'de', 'Flamingo', 'Der Flamingo ist mit seinem rosa Gefieder und den langen Beinen ein echter Star unter den Wasservögeln. Seine Farbe erhält er aus den Farbstoffen seiner Nahrung, etwa kleinen Krebstieren. In deinem Zoo steht er gerne auf einem Bein im Wasser und sorgt mit seiner bunten Kolonie für Urlaubsstimmung.'),
(91451, 211, 'da', 'Flamingo', 'Flamingoen med sit lyserøde fjerdragt og lange ben er en rigtig stjerne blandt vandfuglene. Dens farve stammer fra pigmenterne i dens føde. I din zoo står den gerne på ét ben i vandet og skaber feriefølelse med sin farverige koloni.'),
(91452, 608, 'en', 'Flying Fox', 'The spectacled flying fox is a bat with a “glasses‑like” pattern around its eyes. It feeds on fruit and plays an important role in pollination. In your zoo it hangs upside‑down in the bat area and nibbles on sweet fruits.'),
(91453, 608, 'de', 'Brillenflughund', 'Der Brillenflughund ist eine Fledermaus mit brilleähnlicher Zeichnung um die Augen. Er ernährt sich von Früchten und spielt eine wichtige Rolle bei der Bestäubung. In deinem Zoo hängt er kopfüber im Fledermausbereich und knabbert an süßen Früchten.'),
(91454, 608, 'da', 'Puma', 'Pumaen er det næststørste kattedyr i Amerika og er en mester til at tilpasse sig forskellige levesteder, fra tætte jungler til åbne prærier. Den kan springe op til 6 meter vandret.'),
(91455, 30180, 'en', 'Fossa', 'The Fossa is a sleek, agile predator endemic to Madagascar\'s forests, resembling a cross between a cat and a mongoose. Measuring 70-80 cm (28-31 inches) in body length plus a 65 cm (26 inches) tail, and weighing 5-10 kg (11-22 lbs), Fossas have reddish-brown fur, a pointed snout, and retractable claws. Fossas are expert climbers and swimmers, using their acute senses to track prey.\n\nAs the top predator in its ecosystem, it preys on lemurs, birds, and small mammals.\n\n'),
(91456, 30180, 'de', 'Fossa', 'The Fossa is a sleek, agile predator endemic to Madagascar\'s forests, resembling a cross between a cat and a mongoose. Measuring 70-80 cm (28-31 inches) in body length plus a 65 cm (26 inches) tail, and weighing 5-10 kg (11-22 lbs), Fossas have reddish-brown fur, a pointed snout, and retractable claws. Fossas are expert climbers and swimmers, using their acute senses to track prey.\n\nAs the top predator in its ecosystem, it preys on lemurs, birds, and small mammals.\n\n'),
(91457, 30180, 'da', 'Fossa', 'The Fossa is a sleek, agile predator endemic to Madagascar\'s forests, resembling a cross between a cat and a mongoose. Measuring 70-80 cm (28-31 inches) in body length plus a 65 cm (26 inches) tail, and weighing 5-10 kg (11-22 lbs), Fossas have reddish-brown fur, a pointed snout, and retractable claws. Fossas are expert climbers and swimmers, using their acute senses to track prey.\n\nAs the top predator in its ecosystem, it preys on lemurs, birds, and small mammals.\n\n'),
(91458, 30181, 'en', 'Galah', 'The Galah, also known as the Rose-Breasted Cockatoo, is a medium-sized parrot native to Australia. Recognizable by its striking pink and grey plumage, the Galah has a distinctive crest that can be raised or lowered. Adults typically measure about 32 to 38 cm (12 to 15 inches) in length. They are highly social birds, often found in large flocks, and are known for their playful and intelligent behavior.\n\nGalahs primarily feed on seeds, fruits, and nuts, using their strong beaks to crack open hard shells.\n\n'),
(91459, 30181, 'de', 'Galah', 'The Galah, also known as the Rose-Breasted Cockatoo, is a medium-sized parrot native to Australia. Recognizable by its striking pink and grey plumage, the Galah has a distinctive crest that can be raised or lowered. Adults typically measure about 32 to 38 cm (12 to 15 inches) in length. They are highly social birds, often found in large flocks, and are known for their playful and intelligent behavior.\n\nGalahs primarily feed on seeds, fruits, and nuts, using their strong beaks to crack open hard shells.\n\n'),
(91460, 30181, 'da', 'Galah', 'The Galah, also known as the Rose-Breasted Cockatoo, is a medium-sized parrot native to Australia. Recognizable by its striking pink and grey plumage, the Galah has a distinctive crest that can be raised or lowered. Adults typically measure about 32 to 38 cm (12 to 15 inches) in length. They are highly social birds, often found in large flocks, and are known for their playful and intelligent behavior.\n\nGalahs primarily feed on seeds, fruits, and nuts, using their strong beaks to crack open hard shells.\n\n'),
(91461, 241, 'en', 'Galapagos Land Iguana', 'The tree iguana is a sturdy lizard with a distinctive head and rough, scaly skin. It loves warm, dry habitats and spends a lot of time basking in the sun. In your zoo it likes to lie motionless on a branch, looking like a small living statue.'),
(91462, 241, 'de', 'Drusenkopf', 'Der Drusenkopf ist eine robuste Echse mit markantem Kopf und rauer Schuppenhaut. Er liebt warme, trockene Lebensräume und verbringt viel Zeit beim Sonnenbaden. In deinem Zoo liegt er gerne regungslos auf einem Ast und wirkt wie eine kleine, lebendige Statue.'),
(91463, 241, 'da', 'Galápagos landleguaan', 'Galápagos-landleguanen er en robust øgle med markant hoved og ru skælhud. Den elsker varme, tørre levesteder og tilbringer meget tid med at sole sig. I din zoo sidder den gerne ubevægeligt på en gren og virker som en lille, levende statue.'),
(91464, 228, 'en', 'Galápagos Pink Land Iguana', 'The rosada tree iguana is a strikingly colored lizard with bright patches of skin. It loves sunny spots where it can regulate its body temperature. In your zoo it likes to sit on warm rocks and calmly watch everything going on around it.'),
(91465, 228, 'de', 'Rosada-Drusenkopf', 'Der Rosada-Drusenkopf ist eine auffällig gefärbte Echse mit leuchtenden Hautbereichen. Er liebt sonnige Plätze, auf denen er seine Körpertemperatur regulieren kann. In deinem Zoo sitzt er gerne auf warmen Steinen und beobachtet das Treiben mit stoischer Ruhe.'),
(91466, 228, 'da', 'Galápagos rosenrød landleguaan', 'Galápagos-rosaiguan er en iøjnefaldende farvet øgle med lysende hudpartier. Den elsker solrige pladser, hvor den kan regulere sin kropstemperatur. I din zoo sidder den gerne på varme sten og betragter aktiviteten med stoisk ro.'),
(91467, 30183, 'en', 'Ganges River Dolphin', 'The Ganges River Dolphin is a freshwater dolphin species native to the Ganges. They are typically grayish in color, with some individuals exhibiting a pinkish hue, especially when they are excited or agitated. They can grow up to 2.5 to 3 meters (8 to 10 feet) in length and weigh between 100 to 150 kg (220 to 330 lbs). These dolphins are known for their echolocation abilities, which they use to navigate and hunt in the murky waters of their river habitats.\n\nThe Ganges River Dolphin primarily feeds on a variety of fish and invertebrates found in its freshwater habitat.\n\n'),
(91468, 30183, 'de', 'Ganges River Dolphin', 'The Ganges River Dolphin is a freshwater dolphin species native to the Ganges. They are typically grayish in color, with some individuals exhibiting a pinkish hue, especially when they are excited or agitated. They can grow up to 2.5 to 3 meters (8 to 10 feet) in length and weigh between 100 to 150 kg (220 to 330 lbs). These dolphins are known for their echolocation abilities, which they use to navigate and hunt in the murky waters of their river habitats.\n\nThe Ganges River Dolphin primarily feeds on a variety of fish and invertebrates found in its freshwater habitat.\n\n'),
(91469, 30183, 'da', 'Ganges River Dolphin', 'The Ganges River Dolphin is a freshwater dolphin species native to the Ganges. They are typically grayish in color, with some individuals exhibiting a pinkish hue, especially when they are excited or agitated. They can grow up to 2.5 to 3 meters (8 to 10 feet) in length and weigh between 100 to 150 kg (220 to 330 lbs). These dolphins are known for their echolocation abilities, which they use to navigate and hunt in the murky waters of their river habitats.\n\nThe Ganges River Dolphin primarily feeds on a variety of fish and invertebrates found in its freshwater habitat.\n\n'),
(91470, 30184, 'en', 'Gaur', 'The Gaur, also known as the Indian Bison, is a large wild cattle species native to South Asia and Southeast Asia. It is characterized by its massive build, dark brown to black coat, and distinctive white markings on its legs and face.  Both males and females possess long, curved horns that can grow up to 3 feet (about 1 meter) in length. \n\nGaurs are herbivorous and primarily inhabit forests and grasslands, where they graze on a variety of vegetation. \n\n'),
(91471, 30184, 'de', 'Gaur', 'The Gaur, also known as the Indian Bison, is a large wild cattle species native to South Asia and Southeast Asia. It is characterized by its massive build, dark brown to black coat, and distinctive white markings on its legs and face.  Both males and females possess long, curved horns that can grow up to 3 feet (about 1 meter) in length. \n\nGaurs are herbivorous and primarily inhabit forests and grasslands, where they graze on a variety of vegetation. \n\n'),
(91472, 30184, 'da', 'Gaur', 'The Gaur, also known as the Indian Bison, is a large wild cattle species native to South Asia and Southeast Asia. It is characterized by its massive build, dark brown to black coat, and distinctive white markings on its legs and face.  Both males and females possess long, curved horns that can grow up to 3 feet (about 1 meter) in length. \n\nGaurs are herbivorous and primarily inhabit forests and grasslands, where they graze on a variety of vegetation. \n\n'),
(91473, 513, 'en', 'Gerenuk', 'The Gerenuk, also called giraffe gazelle, has an especially long neck and can even stand upright to feed. It lives in dry areas of Africa and gets by on little water. In your zoo, it often stands on its hind legs to reach leaves, drawing admiring stares.'),
(91474, 513, 'de', 'Giraffengazelle', 'Die Giraffengazelle, auch Gerenuk genannt, hat einen besonders langen Hals und kann sich zum Fressen sogar aufrichten. Sie lebt in trockenen Gebieten Afrikas und kommt mit wenig Wasser aus. In deinem Zoo steht sie oft auf den Hinterbeinen, um an Blätter zu gelangen, und sorgt damit für staunende Blicke.'),
(91475, 513, 'da', 'Gepardgazelle', 'Thomsons gazelle er en af de hurtigste dyr på savannen og er kendetegnet ved sit karakteristiske sorte sideband. Den er et vigtigt byttedyr for mange afrikanske rovdyr.'),
(91476, 812, 'en', 'Gharial', 'The Ganges gharial is a fish‑eating reptile with a long, narrow snout full of teeth. It lives in the rivers of the Indian subcontinent. In your zoo it swims calmly while proudly displaying its impressive teeth.'),
(91477, 812, 'de', 'Gangesgavial', 'Der Gangesgavial ist ein Fischfresser mit langem, schmalem Schnabel voller Zähne. Er lebt in Flüssen des indischen Subkontinents. In deinem Zoo schwimmt er ruhig und zeigt dabei sein beeindruckendes Gebiss.'),
(91478, 812, 'da', 'Laks', 'Laksen er berømt for sin episke rejse fra havet tilbage til sin fødeguld for at yngle. Denne rejse mod strømen kan være over 1000 km lang. Laksen spiser ikke under denne vandring og lever af sine fedtreserver.'),
(91479, 302, 'en', 'Ghost Bat', 'The Australian ghost bat has long, narrow wings and a rather mysterious name. It is nocturnal and hunts insects in flight with great precision. In your zoo it is mostly active in the dark, filling the bat house with soft, fluttering wings.'),
(91480, 302, 'de', 'Australische Gespenstfledermaus', 'Die Australische Gespenstfledermaus hat lange, schmale Flügel und einen etwas geheimnisvollen Namen. Sie ist nachtaktiv und jagt Insekten mit großer Präzision im Flug. In deinem Zoo ist sie vor allem in der Dunkelheit unterwegs und sorgt im Fledermaushaus für leises Flattern.'),
(91481, 302, 'da', 'Australsk spøgelsesfladdermus', 'Den australske spøgelsesfladdermus har lange, smalle vinger og jager insekter med stor præcision i natten. I din zoo flakser den stille rundt i fladdermusehuset og er mest aktiv i mørket.'),
(91482, 514, 'en', 'Giant Anteater', 'The Giant Anteater is unmistakable with its long snout and bushy tail plume. Its favorite foods are ants and termites, which it collects with its sticky tongue. In your zoo, it trots leisurely through the enclosure and looks like a friendly, slightly unusual visitor.'),
(91483, 514, 'de', 'Großer Ameisenbär', 'Der Große Ameisenbär ist mit seiner langen Schnauze und der buschigen Schwanzfahne unverwechselbar. Seine Lieblingsspeisen sind Ameisen und Termiten, die er mit seiner klebrigen Zunge aufnimmt. In deinem Zoo stapft er gemächlich durchs Gehege und wirkt wie ein freundlicher, etwas ungewöhnlicher Besucher.'),
(91484, 514, 'da', 'Bøffel', 'Den afrikanske bøffel er et af de farligste dyr i Afrika. Tyre er berygtet for at angribe jægere og har en fejltagende hukommelse for dem, der har skadet dem.'),
(91485, 522, 'en', 'Giant Eland', 'The Giant Eland is the largest antelope species in the world. Despite its size, it is agile and can make impressive leaps. In your zoo, it moves majestically through the enclosure and impresses with its gentle strength.'),
(91486, 522, 'de', 'Riesen-Elenantilope', 'Die Riesen-Elenantilope ist die größte Antilopenart der Welt. Trotz ihrer Größe ist sie flink und kann beachtliche Sprünge machen. In deinem Zoo bewegt sie sich majestätisch durch das Gehege und beeindruckt mit ihrer sanften Kraft.'),
(91487, 522, 'da', 'Termit-myresluger', 'Pangolinens skæl er lavet af keratin — det samme som menneskelige negle. Truet af krybskytteri bruger den sin lange, klistrede tunge til at spise tusindvis af insekter om dagen.'),
(91488, 827, 'en', 'Giant Freshwater Stingray', 'The giant freshwater stingray lives in large rivers of Asia. It can reach enormous sizes yet is often hard to spot. In your zoo it is an impressive, but calm giant.'),
(91489, 827, 'de', 'Riesen-Süßwasserstechrochen', 'Der Riesen-Süßwasserstechrochen lebt in großen Flüssen Asiens. Er kann enorme Größen erreichen und ist dennoch oft schwer zu entdecken. In deinem Zoo ist er ein beeindruckender, aber ruhiger Riese.'),
(91490, 827, 'da', 'Havørn', 'Havørnen er en imponerende rovfugl med et vingefang på op til 2,4 meter. Den er Europas største ørn og er ekspert i at fange fisk fra vandoverfladen med sine kraftige kløer.'),
(91491, 610, 'en', 'Giant Golden-Crowned Flying Fox', 'The golden‑crowned fruit bat is a large, fruit‑eating flying fox with a golden head coloration. It comes from the Philippines and is highly endangered. In your zoo it is an important reminder of the need to protect tropical forests.'),
(91492, 610, 'de', 'Goldkronen-Flughund', 'Der Goldkronen-Flughund ist ein großer, fruchtfressender Flughund mit goldener Kopffärbung. Er stammt aus den Philippinen und ist stark bedroht. In deinem Zoo ist er ein wichtiger Hinweis auf den Schutz tropischer Wälder.'),
(91493, 610, 'da', 'Kaiman', 'Kaimanerne er mindre krokodilleidler fra Mellem- og Sydamerika. De er nære slægtninge til alligatorer og er vigtige rovdyr i det tropiske ferskvandsmiljø. De fleste arter er truede.'),
(91494, 826, 'en', 'Giant Oceanic Manta Ray', 'The giant manta ray is a large ray with a majestic wingspan. It filters plankton from the water. In your zoo it glides through the pool like an underwater glider.'),
(91495, 826, 'de', 'Riesenmanta', 'Der Riesenmanta ist ein großer Rochen mit majestätischer Spannweite. Er filtert Plankton aus dem Wasser. In deinem Zoo gleitet er schwebend durch das Becken und wirkt wie ein Unterwassersegelflugzeug.'),
(91496, 826, 'da', 'Elektrisk ål', 'Den elektriske ål er faktisk ikke en ægte ål, men en fisk der kan generere elektriske stød på op til 600 volt. Den bruger disse stød til at bedøve bytte, forsvare sig og navigere i mudret vand.'),
(91497, 640, 'en', 'Giant Otter', 'The giant otter is the largest otter in the world and lives in the rivers of South America. Highly social, it hunts fish in teams. In your zoo, it splashes playfully in the water and chats noisily with its group.'),
(91498, 640, 'de', 'Riesenotter', 'Der Riesenotter ist der größte Otter der Welt und lebt in den Flüssen Südamerikas. Er ist sehr sozial und jagt Fische im Team. In deinem Zoo planscht er ausgelassen im Wasser und kommuniziert mit vielen Lauten mit seiner Gruppe.'),
(91499, 640, 'da', 'Flyveagern', 'Den flyveagern flyver ikke rigtigt, men glider ved hjælp af en hudfold kaldet patagium, der strækker sig fra håndled til ankel. Den kan glide op til 150 meter fra et enkelt udgangspunkt.'),
(91500, 612, 'en', 'Giant Otter Shrew', 'The giant otter‑shrew is a small, semi‑aquatic mammal with a streamlined body. It hunts insects and small prey in the water. In your zoo it darts smoothly through the water and creates lively underwater action.'),
(91501, 612, 'de', 'Große Otterspitzmaus', 'Die Große Otterspitzmaus ist ein kleines, semiaquatisches Säugetier mit stromlinienförmigem Körper. Sie jagt im Wasser nach Insekten und kleinen Beutetieren. In deinem Zoo flitzt sie geschmeidig durchs Wasser und sorgt für lebhafte Unterwasseraktionen.'),
(91502, 612, 'da', 'Kamælon', 'Kamæleonen er en mester til at skifte farve, men ikke bare for at camouflere sig — farveændringerne bruges primært til kommunikation og temperaturregulering. Hvert øje kan rotere uafhængigt.'),
(91503, 107, 'en', 'Giant Panda', 'The Giant Panda, with its black-and-white fur, is one of the most famous symbols of species conservation. Despite its size, it mainly feeds on bamboo and spends many hours a day munching cozily. In your zoo, it often sits relaxed, holding a bamboo stalk in its paws, enchanting visitors with its peaceful nature.'),
(91504, 107, 'de', 'Großer Panda', 'Der Große Panda ist mit seinem schwarz-weißen Fell eines der bekanntesten Symbole für den Artenschutz. Trotz seiner Größe ernährt er sich hauptsächlich von Bambus und verbringt viele Stunden am Tag mit gemütlichem Knabbern. In deinem Zoo sitzt er oft entspannt herum, hält eine Bambusstange in den Pfoten und verzaubert die Besucher mit seinem friedlichen Wesen.'),
(91505, 107, 'da', 'Kæmpepanda', 'Kæmpepandaen er med sit sort-hvide pels et af de mest kendte symboler på artsbeskyttelse. I din zoo sidder den afslappet og holder en bambusstang i sine poter, og tryllebinder besøgende med sit fredelige væsen.'),
(91506, 126, 'en', 'Giant Rabbit', 'The Giant Rabbit does its name justice and weighs considerably more than its smaller relatives. Despite its size, it\'s usually gentle and loves cozy resting spots. In your zoo, it sits relaxed in the straw, slowly munching through large portions of veggies.'),
(91507, 126, 'de', 'Riesenkaninchen', 'Das Riesenkaninchen macht seinem Namen alle Ehre und bringt deutlich mehr Gewicht auf die Waage als seine kleineren Verwandten. Trotz seiner Größe ist es meist sanftmütig und liebt gemütliche Ruheplätze. In deinem Zoo sitzt es gerne entspannt im Stroh und knabbert sich langsam durch große Portionen Gemüse.'),
(91508, 126, 'da', 'Kæmpekanin', 'Kæmpekaninen lever op til sit navn og vejer betydeligt mere end sine mindre slægtninge. Til trods for sin størrelse er det normalt sagtmodigt og elsker hyggelige hvilepladser. I din zoo sidder det afslappet i halmen og gnaver langsomt grøntsager.'),
(91509, 1116, 'en', 'Giant Sengi', 'The Elephant Shrew is a tiny mammal with a long, flexible snout. It uses it to sniff out insects and other small creatures. In your zoo, it darts around its enclosure, exploring every corner with curiosity.'),
(91510, 1116, 'de', 'Rüsselhündchen', 'Das Rüsselhündchen ist ein kleines Säugetier mit langem, beweglichem Rüssel. Es nutzt ihn, um Insekten und andere Kleintiere aufzuspüren. In deinem Zoo flitzt es durch sein Gehege und sucht neugierig jede Ecke ab.'),
(91511, 1116, 'da', 'Svævefrø', 'Wallaces flyvende frø bruger sin store, heftede tæer som faldskærm til at glide fra træ til træ. Den er hjemmehørende i regnskove i Sydøstasien og kan dække afstande på op til 15 meter i ét spring.'),
(91512, 227, 'en', 'Giant Tortoise', 'The giant tortoise can reach an extremely old age and is known for its calm, leisurely nature. It lives on islands such as the Galápagos and moves at its own very relaxed pace. In your zoo it slowly plods through its realm, showing that it is perfectly fine to take life easy.'),
(91513, 227, 'de', 'Riesenschildkröte', 'Die Riesenschildkröte kann extrem alt werden und ist für ihr ruhiges, gemächliches Wesen bekannt. Sie lebt auf Inseln wie den Galapagos-Inseln und bewegt sich in ihrem eigenen, sehr gemütlichen Tempo. In deinem Zoo stapft sie langsam durch ihr Reich und zeigt, dass man es im Leben auch mal ruhig angehen darf.'),
(91514, 227, 'da', 'Kæmpeskildpadde', 'Kæmpeskildpadden kan blive ekstremt gammel og er kendt for sit rolige, langsomme væsen. Den lever på øer som Galápagosøerne og bevæger sig i sit eget, meget hyggelige tempo. I din zoo vader den langsomt igennem sit rige.'),
(91515, 30185, 'en', 'Gila Monster', 'The Gila Monster is a large, venomous lizard native to the southwestern United States and northwestern Mexico. It is characterized by its distinctive black body adorned with bright orange or pink patterns. Gila monsters are primarily nocturnal and spend much of their time burrowing underground. Their venom, delivered through grooves in their teeth, is used primarily for defense and to subdue prey.\n\nThe Gila monster is a carnivorous lizard with a diet primarily consisting of small mammals, such as rodents, and birds, including their eggs.\n\n'),
(91516, 30185, 'de', 'Gila Monster', 'The Gila Monster is a large, venomous lizard native to the southwestern United States and northwestern Mexico. It is characterized by its distinctive black body adorned with bright orange or pink patterns. Gila monsters are primarily nocturnal and spend much of their time burrowing underground. Their venom, delivered through grooves in their teeth, is used primarily for defense and to subdue prey.\n\nThe Gila monster is a carnivorous lizard with a diet primarily consisting of small mammals, such as rodents, and birds, including their eggs.\n\n'),
(91517, 30185, 'da', 'Gila Monster', 'The Gila Monster is a large, venomous lizard native to the southwestern United States and northwestern Mexico. It is characterized by its distinctive black body adorned with bright orange or pink patterns. Gila monsters are primarily nocturnal and spend much of their time burrowing underground. Their venom, delivered through grooves in their teeth, is used primarily for defense and to subdue prey.\n\nThe Gila monster is a carnivorous lizard with a diet primarily consisting of small mammals, such as rodents, and birds, including their eggs.\n\n'),
(91518, 214, 'en', 'Golden Pheasant', 'The golden pheasant impresses with its colorful plumage and golden crest on its head. It originally comes from the forests of China, but today it can be seen in parks and zoos all over the world. In your zoo it struts through its enclosure like a little king, showing off its shimmering colors.'),
(91519, 214, 'de', 'Goldfasan', 'Der Goldfasan beeindruckt mit seinem bunten Gefieder und dem goldenen Schopf auf dem Kopf. Ursprünglich stammt er aus den Wäldern Chinas, ist aber heute weltweit in Parks und Zoos zu sehen. In deinem Zoo stolziert er wie ein kleiner König durch das Gehege und zeigt seine schillernden Farben.'),
(91520, 214, 'da', 'Guldfasan', 'Guldfasanen imponerer med sit farverige fjerdragt og gyldne top på hovedet. Oprindeligt stammer den fra Kinas skove, men kan nu ses i parker og zoologiske haver verden over. I din zoo promenerer den som en lille konger igennem indhegningen.'),
(91521, 414, 'en', 'Golden Snub-Nosed Monkey', 'The golden snub‑nosed monkey is a rare monkey from the mountain forests of China with striking golden fur. Its short, upturned snout gives it a unique face. In your zoo it climbs through the enclosure in groups and amazes visitors with its appearance.'),
(91522, 414, 'de', 'Goldstumpfnase', 'Die Goldstumpfnase ist ein seltener Affe aus den Bergwäldern Chinas mit auffälligem, goldenen Fell. Ihr kurzer, nach oben gerichteter Nasenstumpf verleiht ihr ein einzigartiges Gesicht. In deinem Zoo klettert sie in Gruppen durch das Gehege und sorgt mit ihrem Aussehen für Staunen.'),
(91523, 414, 'da', 'Gylden stumpnæseabe', 'Den gyldne stumpnæseabe er en sjælden abe fra bjergskove i Kina med iøjnefaldende gyldent pels. Dens korte, opadvendte næsestump giver den et unikt ansigt. I din zoo klatrer den i grupper igennem sit anlæg og forbløffer besøgende med sit udseende.'),
(91524, 415, 'en', 'Golden Takin', 'The golden takin is a massive hoofed mammal from the Himalayas whose golden fur stands out vividly. It looks like a mix between a goat and a gnu and is perfectly adapted to high mountain regions. In your zoo it likes to stand on elevated platforms and lets the wind blow through its fur.'),
(91525, 415, 'de', 'Goldtakin', 'Der Goldtakin ist ein massives Huftier aus dem Himalaya, dessen goldenes Fell besonders auffällt. Er wirkt wie eine Mischung aus Ziege und Gnu und ist perfekt an das Hochgebirge angepasst. In deinem Zoo steht er gerne auf erhöhten Plattformen und lässt sich den Wind durchs Fell wehen.'),
(91526, 415, 'da', 'Guldtakin', 'Guldtakinen er et massivt hovdyr fra Himalaya, hvis gyldne pels er særlig iøjnefaldende. Det ligner en blanding af ged og gnu og er perfekt tilpasset til høje bjerge. I din zoo nyder det at stå på forhøjede platforme og lade vinden blæse igennem pelsen.'),
(91527, 30186, 'en', 'Golden-Bellied Mangabey', 'The Golden-Bellied Mangabey is a medium-sized Old World monkey with olive-gray upperparts, bright golden-orange fur on its belly and inner limbs, and a dark face with a pale brow ridge. Found only in the forests of the Congo River basin in the Democratic Republic of the Congo. Lives in groups near riverbanks and swampy rainforests.\n\nGolden-Bellied Mangabey mainly eats fruits, seeds, leaves, insects, and small invertebrates. \n\n'),
(91528, 30186, 'de', 'Golden-Bellied Mangabey', 'The Golden-Bellied Mangabey is a medium-sized Old World monkey with olive-gray upperparts, bright golden-orange fur on its belly and inner limbs, and a dark face with a pale brow ridge. Found only in the forests of the Congo River basin in the Democratic Republic of the Congo. Lives in groups near riverbanks and swampy rainforests.\n\nGolden-Bellied Mangabey mainly eats fruits, seeds, leaves, insects, and small invertebrates. \n\n'),
(91529, 30186, 'da', 'Golden-Bellied Mangabey', 'The Golden-Bellied Mangabey is a medium-sized Old World monkey with olive-gray upperparts, bright golden-orange fur on its belly and inner limbs, and a dark face with a pale brow ridge. Found only in the forests of the Congo River basin in the Democratic Republic of the Congo. Lives in groups near riverbanks and swampy rainforests.\n\nGolden-Bellied Mangabey mainly eats fruits, seeds, leaves, insects, and small invertebrates. \n\n'),
(91530, 2104, 'en', 'Goldfish', 'The goldfish is one of the most well-known aquarium fish. It was bred from wild carp centuries ago. In your zoo, it swims gracefully in clear tanks and delights especially the younger visitors.'),
(91531, 2104, 'de', 'Goldfisch', 'Der Goldfisch ist einer der bekanntesten Aquarienfische. Er wurde schon vor Jahrhunderten aus Wildkarpfen herausgezüchtet. In deinem Zoo schwimmt er in klaren Becken und begeistert vor allem junge Besucher.'),
(91532, 2104, 'da', 'Gedde', 'Gedden er et toprovdyr i det europæiske ferskvand og er berømt for sin aggression og sit bid. Den er et populært mål for sportsfiskere og kan leve i over 25 år. Den er en ambush-jæger med et kraftigt bid.'),
(91533, 316, 'en', 'Goodfellow Tree Kangaroo', 'Goodfellow\'s tree-kangaroo, unlike most of its relatives, spends most of its life in the trees. It comes from the rainforests of New Guinea and has a dense, reddish-brown coat. In your zoo it climbs skilfully from branch to branch, almost like a kangaroo in climbing mode.'),
(91534, 316, 'de', 'Goodfellow-Baumkänguru', 'Das Goodfellow-Baumkänguru lebt anders als seine Verwandten meist in den Bäumen. Es stammt aus den Regenwäldern Neuguineas und besitzt ein dichtes, rotbraunes Fell. In deinem Zoo klettert es geschickt von Ast zu Ast und wirkt fast wie ein Känguru im Klettermodus.'),
(91535, 316, 'da', 'Goodfellows trækanguru', 'Goodfellow\'s trækanguru lever, i modsætning til sine slægtninge, mest i træerne. Den stammer fra regnskovene i Ny Guinea og har et tykt rødbrunt pels. I din zoo klatrer den dygtigt fra gren til gren og ser næsten ud som en kenguru i klatretilstand.'),
(91536, 426, 'en', 'Great Blue Turaco', 'The Great Turaco is a colorful African bird with a sturdy body and a loud call. Its green and blue plumage shines beautifully in the sunlight. In your zoo, it hops skillfully from branch to branch and delights visitors with its distinctive calls.'),
(91537, 426, 'de', 'Riesenturako', 'Der Riesenturako ist ein farbenfroher Vogel Afrikas mit kräftigem Körper und lautem Ruf. Sein grünes und blaues Gefieder leuchtet im Sonnenlicht. In deinem Zoo springt er geschickt von Ast zu Ast und gibt seine markanten Rufe zum Besten.'),
(91538, 426, 'da', 'Kæmpeturak', 'Kæmpeturakoen er en farverig afrikansk fugl med en kraftig krop og et højt skrig. Dens grønne og blå fjerkjole skinner i solskinnet. I din zoo hopper den dygtigt fra gren til gren og bevilger besøgende sine karakteristiske råb.'),
(91539, 842, 'en', 'Great White Shark', 'The great white shark is one of the best-known sharks and a top predator of the oceans. It has a powerful bite and sharp senses. In your zoo, it inspires both awe and chills.'),
(91540, 842, 'de', 'Weißer Hai', 'Der Weiße Hai ist einer der bekanntesten Haie und ein Spitzenprädator der Ozeane. Er hat ein kraftvolles Gebiss und scharfe Sinne. In deinem Zoo sorgt er für Gänsehaut und Bewunderung zugleich.'),
(91541, 842, 'da', 'Søhest (pygmæ)', 'Det pygmæiske søheste er et af verdens mindste fisk og kan være kun 1,5 cm lang. Det er en mester i kamouflage og er næsten umulig at se mod sin koralbaggrund. Det er sent opdaget af videnskaben.'),
(91542, 317, 'en', 'Greater Bird-of-Paradise', 'The greater bird-of-paradise is famous for its spectacular courtship plumage and elaborate dances. It lives in the forests of New Guinea and puts on a real show during the mating season. In your zoo it enchants everyone who sees it with its colors and graceful movements.'),
(91543, 317, 'de', 'Großer Paradiesvogel', 'Der Große Paradiesvogel ist berühmt für sein spektakuläres Balzgefieder und kunstvolle Tänze. Er lebt in den Wäldern Neuguineas und zeigt zur Paarungszeit eine richtige Show. In deinem Zoo verzaubert er mit seinen Farben und eleganten Bewegungen alle, die ihn sehen.'),
(91544, 317, 'da', 'Stor paradisfugl', 'Den store paradisfugl er berømt for sit spektakulære balzgefieder og kunstfærdige danse. Den lever i skovene i Ny Guinea og opfører en rigtig forestilling i parringssæsonen. I din zoo tryllebinder den med sine farver og yndefulde bevægelser alle, der ser den.'),
(91545, 30187, 'en', 'Greater Hog Badger', 'The Greater Hog Badger is a medium-sized mammal native to Southeast Asia. It has a distinctive appearance, characterized by a stocky body, short legs, and a broad, flat snout resembling that of a hog. The fur is coarse and typically grayish-brown, with lighter underparts. They are primarily nocturnal and are known for their burrowing habits, often creating extensive tunnel systems. \n\nGreater Hog Badgers are omnivorous, feeding on a varied diet that includes insects, small mammals, fruits, and roots.\n\n'),
(91546, 30187, 'de', 'Greater Hog Badger', 'The Greater Hog Badger is a medium-sized mammal native to Southeast Asia. It has a distinctive appearance, characterized by a stocky body, short legs, and a broad, flat snout resembling that of a hog. The fur is coarse and typically grayish-brown, with lighter underparts. They are primarily nocturnal and are known for their burrowing habits, often creating extensive tunnel systems. \n\nGreater Hog Badgers are omnivorous, feeding on a varied diet that includes insects, small mammals, fruits, and roots.\n\n'),
(91547, 30187, 'da', 'Greater Hog Badger', 'The Greater Hog Badger is a medium-sized mammal native to Southeast Asia. It has a distinctive appearance, characterized by a stocky body, short legs, and a broad, flat snout resembling that of a hog. The fur is coarse and typically grayish-brown, with lighter underparts. They are primarily nocturnal and are known for their burrowing habits, often creating extensive tunnel systems. \n\nGreater Hog Badgers are omnivorous, feeding on a varied diet that includes insects, small mammals, fruits, and roots.\n\n'),
(91548, 518, 'en', 'Greater Kudu', 'The Greater Kudu is an impressive antelope with meter‑long, spiraled horns. Its striped flank adds extra elegance. In your zoo, its royal appearance instantly draws every eye.'),
(91549, 518, 'de', 'Kap-Großkudu', 'Der Kap-Großkudu ist eine beeindruckende Antilope mit meterlangen, spiralig gedrehten Hörnern. Seine gestreifte Flanke sorgt für zusätzliche Eleganz. In deinem Zoo zieht er mit seinem königlichen Aussehen sofort alle Blicke auf sich.'),
(91550, 518, 'da', 'Sekretærfugl', 'Sekretærfuglen er en usædvanlig rovfugl, der foretrækker at jage til fods. Den er berømt for sine lange ben og sin evne til at stampe slanger ihjel med kraftige spark.'),
(91551, 30188, 'en', 'Greater Rhea', 'The Greater Rhea is a large, flightless bird native to South America, primarily found in open grasslands and savannas. Standing up to 1.5 meters (5 feet) tall, it has long legs, a long neck, and a large body covered in soft, grayish-brown feathers. Greater Rheas are social animals, often seen in groups, and are known for their strong running abilities. \n\nGreater Rheas are omnivorous, feeding on a diet of plants, seeds, insects, and small animals. \n\n');
INSERT INTO `animaltext` (`id`, `animalId`, `languageCode`, `animalName`, `animalDescription`) VALUES
(91552, 30188, 'de', 'Greater Rhea', 'The Greater Rhea is a large, flightless bird native to South America, primarily found in open grasslands and savannas. Standing up to 1.5 meters (5 feet) tall, it has long legs, a long neck, and a large body covered in soft, grayish-brown feathers. Greater Rheas are social animals, often seen in groups, and are known for their strong running abilities. \n\nGreater Rheas are omnivorous, feeding on a diet of plants, seeds, insects, and small animals. \n\n'),
(91553, 30188, 'da', 'Greater Rhea', 'The Greater Rhea is a large, flightless bird native to South America, primarily found in open grasslands and savannas. Standing up to 1.5 meters (5 feet) tall, it has long legs, a long neck, and a large body covered in soft, grayish-brown feathers. Greater Rheas are social animals, often seen in groups, and are known for their strong running abilities. \n\nGreater Rheas are omnivorous, feeding on a diet of plants, seeds, insects, and small animals. \n\n'),
(91554, 30189, 'en', 'Greater Sage Grouse', 'The Greater Sage-Grouse is a large, ground‑dwelling bird. Males have a mottled mix of brown, gray, black, and white, with a large white chest, and two yellowish air sacs on the breast used during courtship displays. Females are more cryptic, with mottled gray‑brown‑black plumage that blends into sagebrush habitats for nesting protection.\n\nThe species is herbivorous, feeding primarily on sagebrush, especially in winter.\n\n'),
(91555, 30189, 'de', 'Greater Sage Grouse', 'The Greater Sage-Grouse is a large, ground‑dwelling bird. Males have a mottled mix of brown, gray, black, and white, with a large white chest, and two yellowish air sacs on the breast used during courtship displays. Females are more cryptic, with mottled gray‑brown‑black plumage that blends into sagebrush habitats for nesting protection.\n\nThe species is herbivorous, feeding primarily on sagebrush, especially in winter.\n\n'),
(91556, 30189, 'da', 'Greater Sage Grouse', 'The Greater Sage-Grouse is a large, ground‑dwelling bird. Males have a mottled mix of brown, gray, black, and white, with a large white chest, and two yellowish air sacs on the breast used during courtship displays. Females are more cryptic, with mottled gray‑brown‑black plumage that blends into sagebrush habitats for nesting protection.\n\nThe species is herbivorous, feeding primarily on sagebrush, especially in winter.\n\n'),
(91557, 611, 'en', 'Green Anaconda', 'The giant anaconda is one of the heaviest snakes in the world and lives in the swamps of South America. It is a skilled ambush hunter that waits for prey in the water. In your zoo it glides slowly through the water basin and creates a real jungle atmosphere.'),
(91558, 611, 'de', 'Große Anakonda', 'Die Große Anakonda ist eine der schwersten Schlangen der Welt und lebt in den Sümpfen Südamerikas. Sie ist eine geschickte Lauerjägerin, die im Wasser auf Beute wartet. In deinem Zoo zieht sie gemächlich durchs Wasserbecken und vermittelt echte Dschungelstimmung.'),
(91559, 611, 'da', 'Flyvende frø', 'Den flyvende frø bruger sin store, halvt sammenvoksede tæer som faldskærm til at glide fra træ til træ. Den er en mester i kamouflage og er hjemmehørende i regnskovene i Sydøstasien.'),
(91560, 1105, 'en', 'Green-and-Black Poison Dart Frog', 'The Golden Tree Frog is a small, brightly colored frog from the tropics. Its vivid hues warn of its toxicity. In your zoo, it shines like a tiny gemstone in the terrarium.'),
(91561, 1105, 'de', 'Goldbaumsteiger', 'Der Goldbaumsteiger ist ein kleiner, leuchtend gefärbter Frosch aus den Tropen. Seine kräftigen Farben warnen vor seiner Giftigkeit. In deinem Zoo strahlt er wie ein winziger Edelstein im Terrarium.'),
(91562, 1105, 'da', 'Bille (hjort)', 'Hjortebillen er en af Europas største biller og er kendetegnet ved hannernes enormous gevir-lignende kæber. Disse bruges til kamp om hunner. Larven lever op til 5 år i rådnende træ.'),
(91563, 30190, 'en', 'Grey-Crowned Crane', 'The Grey-Crowned Crane (Balearica regulorum) is a bird in the crane family, Gruidae. It is found in eastern and southern Africa, and is the national bird of Uganda. One of 15 species of crane, these long-legged birds have gray bodies, white wings with brown and gold feathers, white cheeks, and bright red gular sacs underneath their chins. Most strikingly, a spray of stiff golden feathers forms a crown around their heads.\n\nGrey-Crowned Cranes are omnivores. They forage for grass seeds, small toads, insects, and other invertebrates. \n\nAccording to the IUCN Red List, they are classified as Endangered and their numbers today are decreasing.\n\n'),
(91564, 30190, 'de', 'Grey-Crowned Crane', 'The Grey-Crowned Crane (Balearica regulorum) is a bird in the crane family, Gruidae. It is found in eastern and southern Africa, and is the national bird of Uganda. One of 15 species of crane, these long-legged birds have gray bodies, white wings with brown and gold feathers, white cheeks, and bright red gular sacs underneath their chins. Most strikingly, a spray of stiff golden feathers forms a crown around their heads.\n\nGrey-Crowned Cranes are omnivores. They forage for grass seeds, small toads, insects, and other invertebrates. \n\nAccording to the IUCN Red List, they are classified as Endangered and their numbers today are decreasing.\n\n'),
(91565, 30190, 'da', 'Grey-Crowned Crane', 'The Grey-Crowned Crane (Balearica regulorum) is a bird in the crane family, Gruidae. It is found in eastern and southern Africa, and is the national bird of Uganda. One of 15 species of crane, these long-legged birds have gray bodies, white wings with brown and gold feathers, white cheeks, and bright red gular sacs underneath their chins. Most strikingly, a spray of stiff golden feathers forms a crown around their heads.\n\nGrey-Crowned Cranes are omnivores. They forage for grass seeds, small toads, insects, and other invertebrates. \n\nAccording to the IUCN Red List, they are classified as Endangered and their numbers today are decreasing.\n\n'),
(91566, 30191, 'en', 'Grizzly Bear', 'The Grizzly Bear is a population or subspecies of the Brown Bear that is found in North America. Although variable in color from blond to nearly black, Grizzly Bear fur is typically brown with darker legs and commonly white or blond-tipped fur on the flank and back. Grizzlies are characterized by their distinctive hump on the shoulders, which is made up of muscle used for digging and foraging. \n\nGrizzly Bears are omnivorous, feeding on a varied diet that includes berries, fish, small mammals, and carrion.\n\n'),
(91567, 30191, 'de', 'Grizzly Bear', 'The Grizzly Bear is a population or subspecies of the Brown Bear that is found in North America. Although variable in color from blond to nearly black, Grizzly Bear fur is typically brown with darker legs and commonly white or blond-tipped fur on the flank and back. Grizzlies are characterized by their distinctive hump on the shoulders, which is made up of muscle used for digging and foraging. \n\nGrizzly Bears are omnivorous, feeding on a varied diet that includes berries, fish, small mammals, and carrion.\n\n'),
(91568, 30191, 'da', 'Grizzly Bear', 'The Grizzly Bear is a population or subspecies of the Brown Bear that is found in North America. Although variable in color from blond to nearly black, Grizzly Bear fur is typically brown with darker legs and commonly white or blond-tipped fur on the flank and back. Grizzlies are characterized by their distinctive hump on the shoulders, which is made up of muscle used for digging and foraging. \n\nGrizzly Bears are omnivorous, feeding on a varied diet that includes berries, fish, small mammals, and carrion.\n\n'),
(91569, 236, 'en', 'Ground Pangolin', 'The steppe pangolin is completely covered in horn plates and looks almost like a living pine cone. When threatened it curls up into a tight ball. In your zoo it moves about quietly, snuffling for insects and looking like a creature from another time.'),
(91570, 236, 'de', 'Steppenschuppentier', 'Das Steppenschuppentier ist vollständig mit Hornschuppen bedeckt und sieht fast aus wie ein lebender Tannenzapfen. Bei Gefahr rollt es sich zu einer festen Kugel zusammen. In deinem Zoo schleicht es ruhig umher, schnüffelt nach Insekten und wirkt wie ein Wesen aus einer anderen Zeit.'),
(91571, 236, 'da', 'Steppe-skæludyr', 'Steppeskæludyret er helt dækket af hornplader og ser næsten ud som en levende kogle. Ved fare ruller det sig til en fast bold. I din zoo sniger det sig stille rundt, snuser efter insekter og ser ud som en skabning fra en anden tid.'),
(91572, 30192, 'en', 'Guanaco', 'The Guanaco is a wild camelid native to the Andean regions of South America. It has a slender build with long legs, a long neck, and reddish-brown to gray fur, often with a white underbelly. Guanacos are known for their agility in rugged terrains and are the ancestors of domesticated llamas and alpacas.\n\nIts diet primarily consists of grasses, herbs, and shrubs, which it grazes on in open grasslands and mountainous areas.\n\n'),
(91573, 30192, 'de', 'Guanaco', 'The Guanaco is a wild camelid native to the Andean regions of South America. It has a slender build with long legs, a long neck, and reddish-brown to gray fur, often with a white underbelly. Guanacos are known for their agility in rugged terrains and are the ancestors of domesticated llamas and alpacas.\n\nIts diet primarily consists of grasses, herbs, and shrubs, which it grazes on in open grasslands and mountainous areas.\n\n'),
(91574, 30192, 'da', 'Guanaco', 'The Guanaco is a wild camelid native to the Andean regions of South America. It has a slender build with long legs, a long neck, and reddish-brown to gray fur, often with a white underbelly. Guanacos are known for their agility in rugged terrains and are the ancestors of domesticated llamas and alpacas.\n\nIts diet primarily consists of grasses, herbs, and shrubs, which it grazes on in open grasslands and mountainous areas.\n\n'),
(91575, 628, 'en', 'Guereza', 'The mantled guereza has long black‑and‑white fur with a flowing mantle. It lives in the forests of Africa and feeds mainly on leaves. In your zoo it jumps elegantly from branch to branch and lets its fur flow behind like a cloak.'),
(91576, 628, 'de', 'Mantelaffe', 'Der Mantelaffe besitzt ein langes, schwarz-weißes Fell mit wehendem Mantel. Er lebt in den Wäldern Afrikas und ernährt sich überwiegend von Blättern. In deinem Zoo springt er elegant von Ast zu Ast und lässt sein Fell wie einen Umhang hinter sich herwehen.'),
(91577, 628, 'da', 'Kæmpeblæksprutte', 'Kæmpeblæksprutten er et af oceanets mest mystiske skabninger. Den kan blive op til 13 meter lang og har de største øjne i dyreriget. Den lever dybt i havet og er sjældent observeret levende.'),
(91578, 30193, 'en', 'Gyrfalcon', 'The Gyrfalcon is the largest of the falcon species. It is a very polymorphic species, so its plumage varies greatly. The archetypal morphs are called \"white\", \"silver\", \"brown\", and \"black\", though they can be coloured on a spectrum from all-white to very dark. Juveniles are darker and browner than adults. Like in other falcons, the female is much larger than the male. Gyrfalcon is the official bird of Canada\'s Northwest Territories. For centuries, it has been valued as a hunting bird, and in the medieval era, the gyrfalcon was considered a royal bird.\n\nGyrfalcons are strictly carnivores. Typical prey includes the ptarmigan and waterfowl, which they may take in flight; they also take fish and mammals.\n\n'),
(91579, 30193, 'de', 'Gyrfalcon', 'The Gyrfalcon is the largest of the falcon species. It is a very polymorphic species, so its plumage varies greatly. The archetypal morphs are called \"white\", \"silver\", \"brown\", and \"black\", though they can be coloured on a spectrum from all-white to very dark. Juveniles are darker and browner than adults. Like in other falcons, the female is much larger than the male. Gyrfalcon is the official bird of Canada\'s Northwest Territories. For centuries, it has been valued as a hunting bird, and in the medieval era, the gyrfalcon was considered a royal bird.\n\nGyrfalcons are strictly carnivores. Typical prey includes the ptarmigan and waterfowl, which they may take in flight; they also take fish and mammals.\n\n'),
(91580, 30193, 'da', 'Gyrfalcon', 'The Gyrfalcon is the largest of the falcon species. It is a very polymorphic species, so its plumage varies greatly. The archetypal morphs are called \"white\", \"silver\", \"brown\", and \"black\", though they can be coloured on a spectrum from all-white to very dark. Juveniles are darker and browner than adults. Like in other falcons, the female is much larger than the male. Gyrfalcon is the official bird of Canada\'s Northwest Territories. For centuries, it has been valued as a hunting bird, and in the medieval era, the gyrfalcon was considered a royal bird.\n\nGyrfalcons are strictly carnivores. Typical prey includes the ptarmigan and waterfowl, which they may take in flight; they also take fish and mammals.\n\n'),
(91581, 814, 'en', 'Hammerhead Shark', 'The hammerhead shark has a characteristically broadened head with eyes set far to the sides. This shape helps it navigate and hunt for prey. In your zoo it circles majestically and gives visitors goosebumps.'),
(91582, 814, 'de', 'Hammerhai', 'Der Hammerhai besitzt einen charakteristisch verbreiterten Kopf mit seitlich versetzten Augen. Diese Form hilft ihm bei der Orientierung und Beutesuche. In deinem Zoo zieht er majestätisch seine Kreise und sorgt für Gänsehautmomente.'),
(91583, 814, 'da', 'Hornfisk', 'Hornfiskens er en langstrakt, sølvskinnende fisk med et karakteristisk langt næb. Den lever i åbent hav og er berømt for sin evne til at springe over vandoverfladen. Den er en populær sportsfisk.'),
(91584, 30194, 'en', 'Harp Seal', 'The Harp Seal is a species of earless seal, or true seal, native to the northernmost Atlantic Ocean and Arctic Ocean. They have a unique coloration that varies with age. Adult Harp Seals have a silvery-gray coat with a characteristic dark \"harp\" pattern on their back, while pups are born with a white, fluffy coat that helps them blend into the ice. Adult Harp Seals typically weigh between 300 to 400 pounds (136 to 181 kg) and measure about 5 to 6.5 feet (1.5 to 2 meters) in length.\n\nHarp Seals are carnivorous (piscivorous) animals, eating fish, including capelin, herring, cod, Arctic cod and halibut, and crabs and other invertebrates.\n\n'),
(91585, 30194, 'de', 'Harp Seal', 'The Harp Seal is a species of earless seal, or true seal, native to the northernmost Atlantic Ocean and Arctic Ocean. They have a unique coloration that varies with age. Adult Harp Seals have a silvery-gray coat with a characteristic dark \"harp\" pattern on their back, while pups are born with a white, fluffy coat that helps them blend into the ice. Adult Harp Seals typically weigh between 300 to 400 pounds (136 to 181 kg) and measure about 5 to 6.5 feet (1.5 to 2 meters) in length.\n\nHarp Seals are carnivorous (piscivorous) animals, eating fish, including capelin, herring, cod, Arctic cod and halibut, and crabs and other invertebrates.\n\n'),
(91586, 30194, 'da', 'Harp Seal', 'The Harp Seal is a species of earless seal, or true seal, native to the northernmost Atlantic Ocean and Arctic Ocean. They have a unique coloration that varies with age. Adult Harp Seals have a silvery-gray coat with a characteristic dark \"harp\" pattern on their back, while pups are born with a white, fluffy coat that helps them blend into the ice. Adult Harp Seals typically weigh between 300 to 400 pounds (136 to 181 kg) and measure about 5 to 6.5 feet (1.5 to 2 meters) in length.\n\nHarp Seals are carnivorous (piscivorous) animals, eating fish, including capelin, herring, cod, Arctic cod and halibut, and crabs and other invertebrates.\n\n'),
(91587, 613, 'en', 'Harpy Eagle', 'The harpy is a powerful bird of prey from the rainforests of South and Central America. With its strong claws it can seize even large prey. In your zoo it impresses with its majestic appearance and piercing gaze.'),
(91588, 613, 'de', 'Harpyie', 'Die Harpyie ist ein mächtiger Greifvogel aus den Regenwäldern Süd- und Mittelamerikas. Mit ihren kräftigen Krallen kann sie selbst größere Beutetiere packen. In deinem Zoo beeindruckt sie mit ihrer majestätischen Erscheinung und dem eindringlichen Blick.'),
(91589, 613, 'da', 'Boa constrictor', 'Boa constrictoren er en stor, ikke-giftig slange, der kvæler sit bytte. Den er nattaktiv og en dygtig svømmer. Unge er levende, og hunner kan få op til 60 unger i en fødsel.'),
(91590, 30195, 'en', 'Hawksbill Sea Turtle', 'The Hawksbill Sea Turtle is a critically endangered sea turtle. It\'s appearance is similar to that of other marine turtles. In general, it has a flattened body shape, a protective carapace, and flipper-like limbs, adapted for swimming in the open ocean. It is easily distinguished from other sea turtles by its sharp, curving beak with prominent tomium, and the saw-like appearance of its shell margins. Hawksbill shells slightly change colors, depending on water temperature.\n\nHawksbill Sea Turtles are omnivores and feed mainly on sponges. They will also eat sea invertebrates, such as sea jellies, mollusks, fish, crustaceans, marine algae, and other sea animals and plants. \n\n'),
(91591, 30195, 'de', 'Hawksbill Sea Turtle', 'The Hawksbill Sea Turtle is a critically endangered sea turtle. It\'s appearance is similar to that of other marine turtles. In general, it has a flattened body shape, a protective carapace, and flipper-like limbs, adapted for swimming in the open ocean. It is easily distinguished from other sea turtles by its sharp, curving beak with prominent tomium, and the saw-like appearance of its shell margins. Hawksbill shells slightly change colors, depending on water temperature.\n\nHawksbill Sea Turtles are omnivores and feed mainly on sponges. They will also eat sea invertebrates, such as sea jellies, mollusks, fish, crustaceans, marine algae, and other sea animals and plants. \n\n'),
(91592, 30195, 'da', 'Hawksbill Sea Turtle', 'The Hawksbill Sea Turtle is a critically endangered sea turtle. It\'s appearance is similar to that of other marine turtles. In general, it has a flattened body shape, a protective carapace, and flipper-like limbs, adapted for swimming in the open ocean. It is easily distinguished from other sea turtles by its sharp, curving beak with prominent tomium, and the saw-like appearance of its shell margins. Hawksbill shells slightly change colors, depending on water temperature.\n\nHawksbill Sea Turtles are omnivores and feed mainly on sponges. They will also eat sea invertebrates, such as sea jellies, mollusks, fish, crustaceans, marine algae, and other sea animals and plants. \n\n'),
(91593, 1106, 'en', 'Hazel Dormouse', 'The dormouse is a small rodent that loves to live in hedges and forests. It hibernates during the cold months and is especially active in warmer seasons. In your zoo, it shows off its climbing skills among the tangled branches.'),
(91594, 1106, 'de', 'Haselmaus', 'Die Haselmaus ist ein kleines Nagetier, das gerne in Hecken und Wäldern lebt. Sie hält Winterschlaf und ist vor allem in der warmen Jahreszeit aktiv. In deinem Zoo zeigt sie ihre Kletterfreude in verzweigten Ästen.'),
(91595, 1106, 'da', 'Natravne', 'Natravnen er en kryptisk, nattaktiv fugl, der er næsten umulig at se om dagen takket være sin mønstrede, barkfarvede fjerdragt. Den jager insekter om natten ved at fange dem i luften med sin brede mund.'),
(91596, 130, 'en', 'Highland Cattle', 'The Scottish Highland Cow is a real eye-catcher with its long fur and mighty horns. It comes from the rugged regions of Scotland and is well-adapted to wind and weather. In your zoo, it appears cozy and peaceful as it slowly grazes the grass with its fur blowing in the wind.'),
(91597, 130, 'de', 'Schottisches Hochlandrind', 'Das Schottische Hochlandrind ist mit seinem langen Fell und den mächtigen Hörnern ein echter Hingucker. Es stammt aus den rauen Regionen Schottlands und ist an Wind und Wetter bestens angepasst. In deinem Zoo wirkt es gemütlich und friedlich, während es langsam das Gras abweidet und sein Fell im Wind weht.'),
(91598, 130, 'da', 'Skotsk Højlandskvæg', 'Det skotske Højlandskvæg er med sit lange pels og mægtige horn en rigtig øjenfanger. Det stammer fra de ru regioner i Skotland og er godt tilpasset blæst og vejr. I din zoo virker det hyggeligt og fredeligt, mens det langsomt afgræsser området.'),
(91599, 704, 'en', 'Himalayan Monal', 'The glossy pheasant is known for his shimmering plumage and lives in the mountains of Asia. He glows in many colors, especially in the sunlight. In your zoo, he walks proudly through the enclosure and loves to show off his best side.'),
(91600, 704, 'de', 'Glanzfasan', 'Der Glanzfasan ist für sein schillerndes Gefieder bekannt, das in den Bergen Asiens zu Hause ist. Er leuchtet in vielen Farben, besonders bei Sonneneinstrahlung. In deinem Zoo spaziert er stolz durch das Gehege und zeigt sich gern von seiner besten Seite.'),
(91601, 704, 'da', 'Pingvin', 'Pingviner er fugle, der ikke kan flyve, men er exceptionelt gode svømmere. De tilbringer størstedelen af deres liv i havet og kan dykke til dybder på over 500 meter. De lever i store kolonier.'),
(91602, 705, 'en', 'Himalayan Tahr', 'The Himalayan tahr is a sure‑footed hoofed animal from the mountains of Asia. His thick coat protects him from cold and wind. In your zoo, he uses every rocky structure and shows impressive balance.'),
(91603, 705, 'de', 'Himalaya-Tahr', 'Der Himalaya-Tahr ist ein klettergewandtes Huftier aus den Bergen Asiens. Sein dichtes Fell schützt es vor Kälte und Wind. In deinem Zoo nutzt es jede Felsstruktur und beweist beeindruckende Trittsicherheit.'),
(91604, 705, 'da', 'Kejserpingvin', 'Kejserpingvinen er den største pingvinart og lever i Antarktis. Under den kolde antarktiske vinter ruger hannerne på de æg, som hunnerne har lagt, og balancerer dem på fødderne for at holde dem varme.'),
(91605, 512, 'en', 'Hippopotamus', 'The Hippopotamus spends most of the day in the water and comes ashore mainly at night to graze. Despite its placid appearance, it can be very fast and powerful. In your zoo, it bubbles in the water enclosure, yawns impressively wide, and enjoys splashing a little.'),
(91606, 512, 'de', 'Flusspferd', 'Das Flusspferd verbringt den größten Teil des Tages im Wasser und kommt vor allem nachts zum Grasen an Land. Trotz seines gemütlichen Aussehens kann es sehr schnell und kraftvoll sein. In deinem Zoo blubbert es im Wasserbecken, gähnt beeindruckend weit und spritzt gern ein wenig.'),
(91607, 512, 'da', 'Jordegern', 'Jordegernet er et lille, socialt gnaverdyr, der lever i kolonier under jorden. Det er meget vogtsomt og bruger forskellige alarmlyde til at advare sine artsfæller om rovdyr.'),
(91608, 515, 'en', 'Honey Badger', 'The Honey Badger, also called Ratel, is regarded as very fearless and tenacious. It feeds on honey, insects, and even venomous snakes. In your zoo, it shows its strong character and is a small but impressive predator.'),
(91609, 515, 'de', 'Honigdach', 'Der Honigdachs, auch Ratel genannt, gilt als sehr furchtlos und wehrhaft. Er ernährt sich von Honig, Insekten und sogar giftigen Schlangen. In deinem Zoo zeigt er seinen starken Charakter und ist ein kleiner, aber beeindruckender Räuber.'),
(91610, 515, 'da', 'Stribet hyæne', 'I modsætning til den plettet hyæne er den stribede hyæne mere tilbagetrukken og lever alene eller i små grupper. Den er primært en ådselæder og spiller en vigtig rolle i sit økosystem.'),
(91611, 817, 'en', 'Hooded Seal', 'The hooded seal is a seal species in which males have an inflatable swelling on the head. They use this during courtship as an impressive showpiece. In your zoo this special feature draws many amazed faces.'),
(91612, 817, 'de', 'Klappmütze', 'Die Klappmütze ist eine Robbenart, bei der Männchen eine aufblasbare Kopfwulst besitzen. Diese nutzen sie bei der Balz als beeindruckende Showeinlage. In deinem Zoo sorgt dieses besondere Feature für viele erstaunte Gesichter.'),
(91613, 817, 'da', 'Puffin', 'Lunden er en farverig havfugl med en karakteristisk orange næb, der bruges til at bære fisk. Den er en exceptionel svømmer og dykker og kan nå dybder på over 60 meter. Den lever i kystklipperederkolonier.'),
(91614, 1202, 'en', 'Horned Lizard', 'The Horned Lizard is a small, stout-bodied reptile. Some species can even squirt blood from their eyes when threatened. In your zoo, it prefers to stay calm and rely on its camouflage.'),
(91615, 1202, 'de', 'Krötenechse', 'Die Krötenechse ist eine kleine Echse mit gedrungener Körperform. Einige Arten können bei Gefahr Blut aus den Augen spritzen. In deinem Zoo bleibt sie lieber ruhig und vertraut auf ihre Tarnung.'),
(91616, 1202, 'da', 'Klippegedebok', 'Stenbukken er et imponerende klatrende pattedyr tilpasset til bjergklippehabitat. Den kan klatre på næsten lodrette klippevægge og springe fra afsats til afsats med utrolig præcision. Hannernes horn kan blive over en meter lange.'),
(91617, 124, 'en', 'Horse', 'The horse has accompanied humans for millennia as a riding, working, and friendship animal. It\'s an enduring runner with a fine sense for moods. In your zoo, it gallops across the paddock, plays with its kind, or lets the sun pleasantly warm its back.'),
(91618, 124, 'de', 'Pferd', 'Das Pferd begleitet den Menschen seit Jahrtausenden als Reit-, Arbeits- und Freundschaftstier. Es ist ein ausdauernder Läufer mit feinem Gespür für Stimmungen. In deinem Zoo galoppiert es über die Koppel, spielt mit Artgenossen oder lässt sich genüsslich den Rücken von der Sonne wärmen.'),
(91619, 124, 'da', 'Hest', 'Hesten har ledsaget mennesket i årtusinder som ride-, arbejds- og venskabsdyr. I din zoo galopperer den over indhegningen, leger med artsfæller eller lader solen varme ryggen.'),
(91620, 328, 'en', 'Howler Monkey', 'The red howler monkey is known for its loud calls that echo far through the rainforest. It lives in the treetops and feeds mainly on leaves. In your zoo it lets its deep voice ring out and reminds everyone that a monkey enclosure is never truly quiet.'),
(91621, 328, 'de', 'Roter Brüllaffe', 'Der Rote Brüllaffe ist für seine lauten Rufe bekannt, die weit durch den Regenwald hallen. Er lebt in Bäumen und ernährt sich vor allem von Blättern. In deinem Zoo lässt er seine tiefe Stimme erklingen und erinnert alle daran, dass ein Affengehege nie wirklich leise ist.'),
(91622, 328, 'da', 'Rød brølabe', 'Den røde brølabe er kendt for sine høje råb, der runger langt gennem regnskoven. Den lever i trætoppene og ernærer sig primært af blade. I din zoo lader den sin dybe stemme runge og minder alle om, at et abe-anlæg aldrig er virkelig stille.'),
(91623, 806, 'en', 'Humpback Whale', 'The humpback whale is famous for its spectacular leaps and songs. It migrates long distances between feeding and breeding grounds. In your zoo it stands as a symbol for the fascination of the great oceans.'),
(91624, 806, 'de', 'Buckelwal', 'Der Buckelwal ist bekannt für seine spektakulären Sprünge und Gesänge. Er wandert weite Strecken zwischen Nahrungs- und Fortpflanzungsgebieten. In deinem Zoo steht er stellvertretend für die Faszination der großen Ozeane.'),
(91625, 806, 'da', 'Blaahval', 'Blåhvalen er det største dyr, der nogensinde har levet på Jordendens overflade. Den kan blive op til 33 meter lang og veje over 150 ton. Dens hjerte er på størrelse med en lille bil.'),
(91626, 30196, 'en', 'Iberian Lynx', 'The Iberian Lynx is a critically endangered wild cat native to the Iberian Peninsula in southwestern Europe. Adults measure 65–110 cm (26–43 inches) in length and weigh 9–15 kg (20–33 lbs). The Iberian Lynx has distinctive short, tawny fur with dark spots, tufted ears, a short \"bobbed\" tail, and long legs with powerful hindquarters.\n\nIberian Lynx diet consists almost exclusively of European rabbits (up to 80–90% of its diet), supplemented by birds, reptiles, and small mammals.\n\n'),
(91627, 30196, 'de', 'Iberian Lynx', 'The Iberian Lynx is a critically endangered wild cat native to the Iberian Peninsula in southwestern Europe. Adults measure 65–110 cm (26–43 inches) in length and weigh 9–15 kg (20–33 lbs). The Iberian Lynx has distinctive short, tawny fur with dark spots, tufted ears, a short \"bobbed\" tail, and long legs with powerful hindquarters.\n\nIberian Lynx diet consists almost exclusively of European rabbits (up to 80–90% of its diet), supplemented by birds, reptiles, and small mammals.\n\n'),
(91628, 30196, 'da', 'Iberian Lynx', 'The Iberian Lynx is a critically endangered wild cat native to the Iberian Peninsula in southwestern Europe. Adults measure 65–110 cm (26–43 inches) in length and weigh 9–15 kg (20–33 lbs). The Iberian Lynx has distinctive short, tawny fur with dark spots, tufted ears, a short \"bobbed\" tail, and long legs with powerful hindquarters.\n\nIberian Lynx diet consists almost exclusively of European rabbits (up to 80–90% of its diet), supplemented by birds, reptiles, and small mammals.\n\n'),
(91629, 1107, 'en', 'Ili Pika', 'The Ili Pika is a small mammal from the mountain regions of China. It is rare and was discovered only recently. In your zoo, it’s a tiny but truly special resident for real connoisseurs.'),
(91630, 1107, 'de', 'Ili-Pfeifhase', 'Der Ili-Pfeifhase ist ein kleines Säugetier aus Gebirgsregionen Chinas. Er ist selten und wurde erst spät entdeckt. In deinem Zoo ist er ein kleiner, aber sehr besonderer Bewohner für Kenner.'),
(91631, 1107, 'da', 'Krypslange', 'Den grønne mamba er en langstrakt, livlig giftig slange, der lever i trætoppene i de tropiske regnskove i Afrika. Dens intense grønne farve giver perfekt camouflage mod det grønne løv.'),
(91632, 516, 'en', 'Impala', 'The Impala is an elegant antelope from Africa, famous for its long leaps. Moving in herds, it uses its speed to escape predators. In your zoo, it bounds lightly through the enclosure and always seems alert.'),
(91633, 516, 'de', 'Impala', 'Das Impala ist eine elegante Antilope Afrikas, bekannt für ihre weiten Sprünge. In Herden unterwegs, nutzt es seine Schnelligkeit, um Fressfeinden zu entkommen. In deinem Zoo springt es leichtfüßig durch das Gehege und wirkt immer wachsam.'),
(91634, 516, 'da', 'Ørken-vortesvín', 'Vortesvinet er et hårdfør dyr, der tilpasser sig godt til tørre savanner. Det graver underjordiske huler og lever i familiegrupper, og er kendetegnet ved sine karakteristiske vorter og store hugtænder.'),
(91635, 306, 'en', 'Indian Cobra', 'The Indian cobra is one of the best-known cobras and displays its typical hood when it feels threatened. On this hood there is often a pattern that looks like a pair of glasses. In your zoo it lives behind secure glass and fascinates visitors with its elegant yet very respectable presence.'),
(91636, 306, 'de', 'Brillenschlange', 'Die Brillenschlange ist eine der bekanntesten Kobras und zeigt bei Bedrohung ihre typische Nackenhaube. Auf dieser Haube ist häufig ein musterähnlicher „Brillenfleck“ zu sehen. In deinem Zoo lebt sie hinter sicheren Scheiben und fasziniert Besucher mit ihrer eleganten, aber respektgebietenden Erscheinung.'),
(91637, 306, 'da', 'Brilleslange', 'Brilleslangen er en af de mest kendte kobra-arter og breder sin hætte ud, når den trues. Den halvcirkelformede tegning på hætten ligner et par briller. I din zoo lever den bag sikre glasruder og fascinerer med sin elegante, men respektindgydende fremtræden.'),
(91638, 639, 'en', 'Indian Giant Squirrel', 'The giant squirrel is a large squirrel with a colorful coat pattern. It lives in trees and can leap impressive distances between branches. In your zoo, its vivid colors and agility never fail to amaze visitors.'),
(91639, 639, 'de', 'Riesenkönigshörnchen', 'Das Riesenkönigshörnchen ist ein großes Hörnchen mit bunter Fellzeichnung. Es lebt in Bäumen und kann weite Sprünge zwischen Ästen schaffen. In deinem Zoo sorgt es mit seiner Farbigkeit und Agilität für viel Staunen.'),
(91640, 639, 'da', 'Leopard (sort)', 'Den sorte panter er ikke en separat art, men en melansitisk form af leoparden eller jaguaren. Dens mørke farve skyldes en genetisk mutation. I svagt lys kan du stadig se dens pletter.'),
(91641, 123, 'en', 'Indian Rhinoceros', 'The Armored Rhino gets its name from its thick skin folds that look like plates of armor. It hails from Asia and spends a lot of time in mud and water holes. In your zoo, it plods leisurely through the enclosure, rubs against trees, and enjoys a refreshing mud bath.'),
(91642, 123, 'de', 'Panzernashorn', 'Das Panzernashorn trägt seinen Namen wegen der dicken, in Platten wirkenden Hautfalten, die wie eine Rüstung aussehen. Es stammt aus Asien und verbringt viel Zeit in Schlamm- und Wasserlöchern. In deinem Zoo stapft es gemächlich durchs Gehege, schubbert sich an Bäumen und genießt ein erfrischendes Schlamm-Bad.'),
(91643, 123, 'da', 'Indisk næsehorn', 'Det indiske næsehorn bærer sit navn på grund af sine tykke hudfolde, der ligner panserpladerne. Det bruger meget tid i mudderpøle. I din zoo staver det roligt rundt i indhegningen og nyder et forfriskende mudderbad.'),
(91644, 320, 'en', 'Indian Star Tortoise', 'The Indian star tortoise is easy to recognize by its striking, star-patterned shell. It comes from the dry regions of India and Sri Lanka. In the zoo it moves slowly, and every step shows off the artistic design of its shell.'),
(91645, 320, 'de', 'Indische Sternschildkröte', 'Die Indische Sternschildkröte erkennt man an ihrem auffälligen, sternförmig gemusterten Panzer. Sie stammt aus trockenen Regionen Indiens und Sri Lankas. Im Zoo bewegt sie sich gemächlich, doch jeder Schritt präsentiert ihr kunstvolles Panzerdesign.'),
(91646, 320, 'da', 'Indisk stjerneskildpadde', 'Den indiske stjerneskildpadde er nem at genkende på sin iøjnefaldende, stjernernede panser. Den stammer fra tørre regioner i Indien og Sri Lanka. I din zoo bevæger den sig langsomt, men hvert skridt fremviser det kunstfærdige design på dens panser.'),
(91647, 30197, 'en', 'Indo-Pacific Sailfish', 'The Indo-Pacific Sailfish is a sailfish native to the Indian and Pacific Oceans. They are easily recognizable by their long, slender bodies, large dorsal fins (or sails), and elongated bills. Indo-Pacific Sailfish can reach lengths of up to 3.4 meters (11 feet) and weigh as much as 100 kg (220 lbs). They are known for their remarkable swimming abilities, capable of reaching speeds of up to 68 miles per hour (110 km/h), making them one of the fastest fish in the ocean. \n\nIndo-Pacific Sailfish primarily feed on smaller fish and squid, using their speed and bill to slash through schools of prey. \n\n'),
(91648, 30197, 'de', 'Indo-Pacific Sailfish', 'The Indo-Pacific Sailfish is a sailfish native to the Indian and Pacific Oceans. They are easily recognizable by their long, slender bodies, large dorsal fins (or sails), and elongated bills. Indo-Pacific Sailfish can reach lengths of up to 3.4 meters (11 feet) and weigh as much as 100 kg (220 lbs). They are known for their remarkable swimming abilities, capable of reaching speeds of up to 68 miles per hour (110 km/h), making them one of the fastest fish in the ocean. \n\nIndo-Pacific Sailfish primarily feed on smaller fish and squid, using their speed and bill to slash through schools of prey. \n\n'),
(91649, 30197, 'da', 'Indo-Pacific Sailfish', 'The Indo-Pacific Sailfish is a sailfish native to the Indian and Pacific Oceans. They are easily recognizable by their long, slender bodies, large dorsal fins (or sails), and elongated bills. Indo-Pacific Sailfish can reach lengths of up to 3.4 meters (11 feet) and weigh as much as 100 kg (220 lbs). They are known for their remarkable swimming abilities, capable of reaching speeds of up to 68 miles per hour (110 km/h), making them one of the fastest fish in the ocean. \n\nIndo-Pacific Sailfish primarily feed on smaller fish and squid, using their speed and bill to slash through schools of prey. \n\n'),
(91650, 30198, 'en', 'Indri', 'The Indri is the largest living species of lemur, native exclusively to Madagascar\'s eastern rainforests. Known for its striking black-and-white coloration, large yellow eyes, and lack of a tail, it is a diurnal, arboreal primate that lives in small family groups. Adults weigh 6-9.5 kg (13-21 lbs) and stand about 64-72 cm (25-28 in) tall, with a silky, woolly coat.\n\nThe Indri is a herbivorous lemur with a primarily folivorous diet, consisting mainly of leaves, supplemented by fruits, seeds, flowers, and occasional bark or buds.\n\n'),
(91651, 30198, 'de', 'Indri', 'The Indri is the largest living species of lemur, native exclusively to Madagascar\'s eastern rainforests. Known for its striking black-and-white coloration, large yellow eyes, and lack of a tail, it is a diurnal, arboreal primate that lives in small family groups. Adults weigh 6-9.5 kg (13-21 lbs) and stand about 64-72 cm (25-28 in) tall, with a silky, woolly coat.\n\nThe Indri is a herbivorous lemur with a primarily folivorous diet, consisting mainly of leaves, supplemented by fruits, seeds, flowers, and occasional bark or buds.\n\n'),
(91652, 30198, 'da', 'Indri', 'The Indri is the largest living species of lemur, native exclusively to Madagascar\'s eastern rainforests. Known for its striking black-and-white coloration, large yellow eyes, and lack of a tail, it is a diurnal, arboreal primate that lives in small family groups. Adults weigh 6-9.5 kg (13-21 lbs) and stand about 64-72 cm (25-28 in) tall, with a silky, woolly coat.\n\nThe Indri is a herbivorous lemur with a primarily folivorous diet, consisting mainly of leaves, supplemented by fruits, seeds, flowers, and occasional bark or buds.\n\n'),
(91653, 815, 'en', 'Irrawaddy Dolphin', 'The Irrawaddy dolphin has a rounded head and lives in river mouths and coastal waters of Asia. It is rather shy and rare. In your zoo it is a quiet but very special resident of the sea world.'),
(91654, 815, 'de', 'Irawadidelfin', 'Der Irawadidelfin hat einen rundlichen Kopf und lebt in Flussmündungen und Küstengewässern Asiens. Er ist eher scheu und selten. In deinem Zoo ist er ein stiller, aber sehr besonderer Meeresbewohner.'),
(91655, 815, 'da', 'Sværdfisk', 'Sværdfisken er en stor, hurtig rovfisk opkaldt efter dens lange, sværdlignende overbid. Den er en af de hurtigste fisk i havet og kan svømme med hastigheder på over 97 km/t.'),
(91656, 112, 'en', 'Jaguarundi', 'The Jaguarundi is a slender, small-looking wild cat with an unusually long body and short fur. It mainly lives in Central and South America and is a skilled hunter both on the ground and in bushes. In your zoo, it sneaks silently through the enclosure, pops up between plants, and disappears almost soundlessly again.'),
(91657, 112, 'de', 'Jaguarundi', 'Der Jaguarundi ist eine schlanke, klein wirkende Wildkatze mit ungewöhnlich langem Körper und kurzem Fell. Er lebt vor allem in Mittel- und Südamerika und ist ein geschickter Jäger, der sowohl am Boden als auch in Büschen unterwegs ist. In deinem Zoo schleicht er lautlos durchs Gehege, taucht zwischen Pflanzen auf und verschwindet fast geräuschlos wieder.'),
(91658, 112, 'da', 'Jaguarundi', 'Jaguarundien er en smidig, lille vildkat med usædvanlig langt krop og korte pels. I din zoo sniger den sig lydløst rundt i indhegningen og dukker op mellem planter for pludselig at forsvinde igen.'),
(91659, 708, 'en', 'Japanese Macaque', 'The Japanese macaque is known as the „snow monkey“ because he lives in cool regions and uses hot springs. He has thick fur and strong social bonds. In your zoo, he loves to play in the snow in winter and huddles close with his group.'),
(91660, 708, 'de', 'Japanmakak', 'Der Japanmakak ist bekannt als „Schneeaffe“, da er auch in kühlen Regionen lebt und heiße Quellen nutzt. Er besitzt dichtes Fell und ausgeprägte soziale Strukturen. In deinem Zoo spielt er im Winter gern im Schnee und kuschelt eng mit seiner Gruppe.'),
(91661, 708, 'da', 'Arktisk ulv', 'Den arktiske ulv er en underart af ulven tilpasset til det arktiske miljø. Den lever i de øde tundraer i det høje arktis, hvor den jager moskusokser og rensdyr. Den kan modstå hårde arktiske vintre.'),
(91662, 707, 'en', 'Japanese Serow', 'The Japanese serow is a goat‑like animal that lives in Japan’s mountain forests. He climbs skillfully and wears a thick coat. In your zoo, he shows off his climbing skills on rocky structures.'),
(91663, 707, 'de', 'Japanischer Serau', 'Der Japanische Serau ist ein ziegenähnliches Tier, das in Japans Bergwäldern lebt. Er klettert geschickt und hat ein dichtes Fell. In deinem Zoo zeigt er seine Kletterfähigkeiten auf felsigen Anlagen.'),
(91664, 707, 'da', 'Polarræv', 'Polarræven er en mester til at overleve i ekstreme arktiske forhold. Dens tykke pelaje skifter farve fra hvid om vinteren til brun eller grå om sommeren. Den kan modstå temperaturer ned til -70°C.'),
(91665, 30199, 'en', 'Jentink\'s Duiker', 'Jentink\'s Duiker is a forest-dwelling duiker found in the southern parts of Liberia, Cote d\'Ivoire and Sierra Leone. Jentink\'s duikers stand around 80 cm (31 in) tall at the shoulder and weigh about 70 kg (150 lb), making them the largest species of the duikers. They are gray from the shoulders back and dark black from the shoulders forward. A white band goes over the shoulders, between the two colours and joining the white undersides. Jentink\'s Duikers have long, thin horns, which curl back a little at the ends, and reach between 14 and 21 cm (5.5 and 8.3 in).\n\nJentink\'s Duiker is mainly frugivorous, but during the rainy season they come out of the forest at night and feeds on shoots of shrubs and young trees.\n\n'),
(91666, 30199, 'de', 'Jentink\'s Duiker', 'Jentink\'s Duiker is a forest-dwelling duiker found in the southern parts of Liberia, Cote d\'Ivoire and Sierra Leone. Jentink\'s duikers stand around 80 cm (31 in) tall at the shoulder and weigh about 70 kg (150 lb), making them the largest species of the duikers. They are gray from the shoulders back and dark black from the shoulders forward. A white band goes over the shoulders, between the two colours and joining the white undersides. Jentink\'s Duikers have long, thin horns, which curl back a little at the ends, and reach between 14 and 21 cm (5.5 and 8.3 in).\n\nJentink\'s Duiker is mainly frugivorous, but during the rainy season they come out of the forest at night and feeds on shoots of shrubs and young trees.\n\n'),
(91667, 30199, 'da', 'Jentink\'s Duiker', 'Jentink\'s Duiker is a forest-dwelling duiker found in the southern parts of Liberia, Cote d\'Ivoire and Sierra Leone. Jentink\'s duikers stand around 80 cm (31 in) tall at the shoulder and weigh about 70 kg (150 lb), making them the largest species of the duikers. They are gray from the shoulders back and dark black from the shoulders forward. A white band goes over the shoulders, between the two colours and joining the white undersides. Jentink\'s Duikers have long, thin horns, which curl back a little at the ends, and reach between 14 and 21 cm (5.5 and 8.3 in).\n\nJentink\'s Duiker is mainly frugivorous, but during the rainy season they come out of the forest at night and feeds on shoots of shrubs and young trees.\n\n'),
(91668, 127, 'en', 'Jungle Cat', 'The Reed Cat is a shy wildcat that prefers reed areas and water edges. Its mostly solid-colored fur provides good camouflage in tall grass. In the zoo, it moves quietly and cautiously, listens attentively, and shows itself to visitors only after some patience.'),
(91669, 127, 'de', 'Rohrkatze', 'Die Rohrkatze ist eine scheue Wildkatze, die bevorzugt in Schilfgebieten und an Gewässerrändern lebt. Ihr Fell ist meist einfarbig und bietet gute Tarnung im hohen Gras. Im Zoo bewegt sie sich ruhig und vorsichtig, lauscht aufmerksam und zeigt sich Besuchern oft erst nach etwas Geduld.'),
(91670, 127, 'da', 'Sumpkat', 'Sumpkatten er en sky vildkat, der foretrækker sivarealer og vandkanter. Dens ensfarvet pels giver god camouflage i det høje græs. I din zoo bevæger den sig roligt og forsigtigt, og besøgende skal have tålmodighed for at se den.'),
(91671, 618, 'en', 'Kakapo', 'The kakapo is a flightless parrot from New Zealand and highly endangered. It is nocturnal, curious, and has moss‑green camouflage plumage. In your zoo it is a very special guest and a favorite ambassador for species conservation.'),
(91672, 618, 'de', 'Kakapo', 'Der Kakapo ist ein flugunfähiger Papagei aus Neuseeland und stark bedroht. Er ist nachtaktiv, neugierig und besitzt ein moosgrünes Tarngefieder. In deinem Zoo ist er ein ganz besonderer Gast und ein Sympathieträger für den Artenschutz.'),
(91673, 618, 'da', 'Ara-papegøje', 'Ara-papegøjerne er de største papegøjer i verden og er kendte for deres strålende farvepragtige fjer. De er ekstremt intelligente, lever i par og kan opnå en alder på over 60 år.'),
(91674, 824, 'en', 'King Eider', 'The harlequin duck has a spectacular, colorful feather pattern on the male’s head. It breeds in Arctic regions. In your zoo it brings a lot of color to the cold pools with its quirky look.'),
(91675, 824, 'de', 'Prachteiderente', 'Die Prachteiderente trägt beim Männchen ein spektakuläres, buntes Federkleid am Kopf. Sie brütet in arktischen Regionen. In deinem Zoo bringt sie mit ihrem kuriosen Aussehen viel Farbe in kalte Becken.'),
(91676, 824, 'da', 'Kobbe', 'Den almindelige sæl er en af de hyppigst sete havpattedyr i europæiske farvande. Den er nysgerrig af natur og er ofte set på sandbanker. Dens store øjne er tilpasset til at se godt under vand i svagt lys.'),
(91677, 30200, 'en', 'King Penguin', 'The King Penguin is the second-largest penguin species, standing up to 100 cm (39 in) tall. It is easily recognized by its sleek black back, white belly, and vivid orange-yellow patches on the sides of its head and upper chest. Unlike many birds, they do not build nests; instead, they incubate their single egg on their feet under a fold of skin.\n\nThe King Penguin feeds mainly on small fish, squid, and krill, diving deep into the ocean to catch its prey.\n\n'),
(91678, 30200, 'de', 'King Penguin', 'The King Penguin is the second-largest penguin species, standing up to 100 cm (39 in) tall. It is easily recognized by its sleek black back, white belly, and vivid orange-yellow patches on the sides of its head and upper chest. Unlike many birds, they do not build nests; instead, they incubate their single egg on their feet under a fold of skin.\n\nThe King Penguin feeds mainly on small fish, squid, and krill, diving deep into the ocean to catch its prey.\n\n'),
(91679, 30200, 'da', 'King Penguin', 'The King Penguin is the second-largest penguin species, standing up to 100 cm (39 in) tall. It is easily recognized by its sleek black back, white belly, and vivid orange-yellow patches on the sides of its head and upper chest. Unlike many birds, they do not build nests; instead, they incubate their single egg on their feet under a fold of skin.\n\nThe King Penguin feeds mainly on small fish, squid, and krill, diving deep into the ocean to catch its prey.\n\n'),
(91680, 30201, 'en', 'Kingfisher', 'The Kingfisher is a small, vividly colored bird with glossy turquoise-blue upperparts, iridescent wings, a bright orange-red breast, and a long, straight dagger-like bill. It has a white neck patch and blue-black feet. Famous for its shrill, piercing whistle call. \n\nThe Kingfisher\'s diet consists mainly of small fish, aquatic insects, and crustaceans, caught by diving headfirst from a perch over rivers, streams, and coasts.\n\n'),
(91681, 30201, 'de', 'Kingfisher', 'The Kingfisher is a small, vividly colored bird with glossy turquoise-blue upperparts, iridescent wings, a bright orange-red breast, and a long, straight dagger-like bill. It has a white neck patch and blue-black feet. Famous for its shrill, piercing whistle call. \n\nThe Kingfisher\'s diet consists mainly of small fish, aquatic insects, and crustaceans, caught by diving headfirst from a perch over rivers, streams, and coasts.\n\n'),
(91682, 30201, 'da', 'Kingfisher', 'The Kingfisher is a small, vividly colored bird with glossy turquoise-blue upperparts, iridescent wings, a bright orange-red breast, and a long, straight dagger-like bill. It has a white neck patch and blue-black feet. Famous for its shrill, piercing whistle call. \n\nThe Kingfisher\'s diet consists mainly of small fish, aquatic insects, and crustaceans, caught by diving headfirst from a perch over rivers, streams, and coasts.\n\n'),
(91683, 653, 'en', 'Kinkajou', 'The kinkajou, also known as the honey bear, is a nocturnal tree-dweller with a prehensile tail. It loves fruit and nectar and moves quietly through the trees. In your zoo, it shows off its climbing talents mostly after dark.'),
(91684, 653, 'de', 'Wickelbär', 'Der Wickelbär, auch Kinkajou genannt, ist ein nachtaktives Baumtier mit Greifschwanz. Er liebt Früchte und Nektar und bewegt sich leise durch das Geäst. In deinem Zoo zeigt er seine geschickten Kletterkünste vor allem nachts.'),
(91685, 653, 'da', 'Skovkat', 'Ocelotten er en mellemstor plettet kat fra Amerika. Den er nattaktiv og lever i tætte regnskove og buskadser. Den er en dygtig klatrer og svømmer og jager en bred vifte af bytte.'),
(91686, 321, 'en', 'Kiwi', 'The kiwi is a flightless bird from New Zealand and the country\'s national animal. It has bristle-like feathers and uses its long beak to probe the soil for food. In your zoo it lives in a darkened area and mostly appears during special night-time tours.'),
(91687, 321, 'de', 'Kiwi', 'Der Kiwi ist ein flugunfähiger Vogel aus Neuseeland und Nationaltier des Landes. Er hat ein borstenartiges Gefieder und nutzt seinen langen Schnabel, um im Boden nach Nahrung zu stochern. In deinem Zoo lebt er in einem abgedunkelten Bereich und zeigt sich vor allem bei Nachtaktiv-Führungen.');
INSERT INTO `animaltext` (`id`, `animalId`, `languageCode`, `animalName`, `animalDescription`) VALUES
(91688, 321, 'da', 'Kiwi', 'Kiwien er en flyveudygtig fugl fra New Zealand og landets nationale dyr. Den har børsteagtige fjer og bruger sit lange næb til at rode i jorden efter mad. I din zoo lever den i et mørklagt område og ses mest under særlige nattevisninger.'),
(91689, 318, 'en', 'Knobbed Hornbill', 'The helmeted hornbill has a striking horn-like casque on its beak that gives it its name. It lives in tropical forests and feeds on fruit and small animals. In your zoo it flies through its aviary with powerful wingbeats and calls loudly across the space.'),
(91690, 318, 'de', 'Helmhornvogel', 'Der Helmhornvogel trägt einen auffälligen Hornaufsatz auf seinem Schnabel, der ihm seinen Namen gibt. Er lebt in tropischen Wäldern und ernährt sich von Früchten und kleinen Tieren. In deinem Zoo fliegt er mit kräftigen Flügelschlägen durchs Volierengehege und ruft laut in den Raum.'),
(91691, 318, 'da', 'Hjelmnæbbet næsehornsfugl', 'Helmhornfuglen bærer et iøjnefaldende hornformet kasket på sit næb. Den lever i tropiske skove og spiser frugter og småkryb. I din zoo flyver den igennem sin voliere med kraftige vingeslag og kalder højlydt ud i rummet.'),
(91692, 322, 'en', 'Koala', 'The koala is a marsupial from Australia that spends most of its time in eucalyptus trees. It sleeps up to 20 hours a day and always looks wonderfully relaxed. In your zoo it lounges comfortably in forked branches, nibbles on eucalyptus leaves and radiates pure calm.'),
(91693, 322, 'de', 'Koala', 'Der Koala ist ein Beuteltier aus Australien, das die meiste Zeit in Eukalyptusbäumen verbringt. Er schläft bis zu 20 Stunden am Tag und wirkt dabei immer herrlich entspannt. In deinem Zoo hängt er gemütlich in Astgabeln, knabbert an Eukalyptusblättern und versprüht pure Gelassenheit.'),
(91694, 322, 'da', 'Koala', 'Koalaen er et pungdyr fra Australien, der tilbringer det meste af sin tid i eukalyptustræer. Den sover op til 20 timer om dagen og ser altid vidunderligt afslappet ud. I din zoo hænger den komfortabelt i forgrenede grene, gnasker på eukalyptusblade og udstråler ren ro.'),
(91695, 418, 'en', 'Kodiak Bear', 'The Kodiak bear is one of the largest brown bears in the world and lives on the Kodiak Islands in Alaska. It feeds on fish, berries, and whatever else nature provides. In your zoo it impresses with its massive build and especially enjoys water pools and feeding games.'),
(91696, 418, 'de', 'Kodiakbär', 'Der Kodiakbär ist einer der größten Braunbären der Welt und lebt auf den Kodiakinseln in Alaska. Er ernährt sich von Fischen, Beeren und anderem, was die Natur hergibt. In deinem Zoo beeindruckt er mit seiner massigen Statur und genießt besonders gern Wasserbecken und Futterspiele.'),
(91697, 418, 'da', 'Kodiak-bjørn', 'Kodiakbjørnen er en af de største brunbjørne i verden og lever på Kodiakøerne i Alaska. Den lever af fisk, bær og alt andet, som naturen giver. I din zoo imponerer den med sin massive statur og nyder særlig godt vandpøle og fødespil.'),
(91701, 30202, 'en', 'Lady Amherst\'s Pheasant', 'Lady Amherst\'s Pheasant is a bird of the order Galliformes and the family Phasianidae. The adult male is 100–120 cm (40-48 in.) in length, its tail accounting for 80 cm (31 in) of the total length. It is unmistakable with its nuchal cape white black, with a red crest. The long grey tail and rump is red, blue, dark green, white and yellow plumage. The \"cape\" can be raised in display. This species is closely related to the , but has a yellow eye, blue-green bare skin around it.\n\nThey feed on the ground on grain, leaves and invertebrates, but roost in trees at night.\n\n'),
(91702, 30202, 'de', 'Lady Amherst\'s Pheasant', 'Lady Amherst\'s Pheasant is a bird of the order Galliformes and the family Phasianidae. The adult male is 100–120 cm (40-48 in.) in length, its tail accounting for 80 cm (31 in) of the total length. It is unmistakable with its nuchal cape white black, with a red crest. The long grey tail and rump is red, blue, dark green, white and yellow plumage. The \"cape\" can be raised in display. This species is closely related to the , but has a yellow eye, blue-green bare skin around it.\n\nThey feed on the ground on grain, leaves and invertebrates, but roost in trees at night.\n\n'),
(91703, 30202, 'da', 'Lady Amherst\'s Pheasant', 'Lady Amherst\'s Pheasant is a bird of the order Galliformes and the family Phasianidae. The adult male is 100–120 cm (40-48 in.) in length, its tail accounting for 80 cm (31 in) of the total length. It is unmistakable with its nuchal cape white black, with a red crest. The long grey tail and rump is red, blue, dark green, white and yellow plumage. The \"cape\" can be raised in display. This species is closely related to the , but has a yellow eye, blue-green bare skin around it.\n\nThey feed on the ground on grain, leaves and invertebrates, but roost in trees at night.\n\n'),
(91704, 651, 'en', 'Lar Gibbon', 'The white-handed gibbon is an acrobatic tree-dweller with white hands and feet. It moves gracefully through the treetops by swinging from branch to branch and sings loud duets. In your zoo, it elegantly swings between ropes and branches, filling the air with its distinctive calls.'),
(91705, 651, 'de', 'Weißhand-Gibbon', 'Der Weißhand-Gibbon ist ein akrobatischer Baumkletterer mit weißen Händen und Füßen. Er bewegt sich armhangelnd durch die Baumkronen und singt laute Duette. In deinem Zoo schwingt er elegant zwischen Seilen und Ästen und begleitet den Besuch mit seinen typischen Rufen.'),
(91706, 651, 'da', 'Kæmpe-bjørnebæver', 'Den kæmpe-otter er den største artful otter og kan blive op til 1,7 meter lang. Den er et socialt dyr, der lever i familiegrupper og er en dygtig jæger af fisk og krebsdyr i Sydamerikas floder.'),
(91707, 2203, 'en', 'Leafy Seadragon', 'The great ragfish has long skin appendages that make it look like drifting seagrass. It lives in cool ocean regions. In your zoo, it\'s a master of camouflage in seagrass tanks.'),
(91708, 2203, 'de', 'Großer Fetzenfisch', 'Der Große Fetzenfisch hat lange Hautfortsätze, die ihn wie treibendes Seegras aussehen lassen. Er lebt in kühlen Meeresregionen. In deinem Zoo ist er ein Meister der Tarnung in Seegrasbecken.'),
(91709, 2203, 'da', 'Havguldfisk', 'Guldfisken er en af de mest populære akvariefisk og stammer fra Asiatiske karpefisk. Trods dens korte hukommelse-rygte kan den faktisk huske ting i op til 5 måneder. Den findes i mange varianter.'),
(91710, 1112, 'en', 'Least Weasel', 'The Least Weasel is the smallest member of the weasel family. It hunts nimble rodents and moves with incredible speed. In your zoo, it’s a tiny, restless little predator.'),
(91711, 1112, 'de', 'Mauswiesel', 'Das Mauswiesel ist der kleinste Vertreter der Marderfamilie. Es jagt flinke Nager und ist selbst sehr schnell. In deinem Zoo ist es ein winziger, wuseliger Räuber.'),
(91712, 1112, 'da', 'Træslangeorm', 'Vinstokkeslangen er en slank, brun-grøn slange, der ligner en vinstok til forveksling. Den er en mester i statics-kamouflage og forbliver ubevægelig i timevis for at narre fugle og frøer.'),
(91713, 30203, 'en', 'Leatherback Sea Turtle', 'The Leatherback Sea Turtle is the largest of all sea turtles, distinguished by its unique, flexible, leather-like shell featuring seven longitudinal ridges instead of hard plates. It has a dark gray to black coloration with white spots and a pinkish snout. This species is found in tropical and temperate oceans worldwide.\n\nLeatherback Sea Turtle mainly eats jellyfish and other soft-bodied sea creatures; also tunicates, sponges, and fish.\n\n'),
(91714, 30203, 'de', 'Leatherback Sea Turtle', 'The Leatherback Sea Turtle is the largest of all sea turtles, distinguished by its unique, flexible, leather-like shell featuring seven longitudinal ridges instead of hard plates. It has a dark gray to black coloration with white spots and a pinkish snout. This species is found in tropical and temperate oceans worldwide.\n\nLeatherback Sea Turtle mainly eats jellyfish and other soft-bodied sea creatures; also tunicates, sponges, and fish.\n\n'),
(91715, 30203, 'da', 'Leatherback Sea Turtle', 'The Leatherback Sea Turtle is the largest of all sea turtles, distinguished by its unique, flexible, leather-like shell featuring seven longitudinal ridges instead of hard plates. It has a dark gray to black coloration with white spots and a pinkish snout. This species is found in tropical and temperate oceans worldwide.\n\nLeatherback Sea Turtle mainly eats jellyfish and other soft-bodied sea creatures; also tunicates, sponges, and fish.\n\n'),
(91716, 419, 'en', 'Leopard', 'The leopard is a skillful hunter that likes to use trees as resting spots and lookouts. Its spotted fur provides perfect camouflage in the dappled shade of the forest. In your zoo it often lies relaxed on high platforms and watches everything from a safe vantage point.'),
(91717, 419, 'de', 'Leopard', 'Der Leopard ist ein geschickter Jäger, der Bäume gern als Ruheplatz und Ausguck nutzt. Sein geflecktes Fell ist eine perfekte Tarnung im Schattenspiel des Waldes. In deinem Zoo liegt er oft entspannt auf hohen Plattformen und beobachtet alles aus sicherer Höhe.'),
(91718, 419, 'da', 'Leopard', 'Leoparden er en dygtig jæger, der gerne bruger træer som hvileplads og udkigspost. Dens plettede pels er en perfekt camouflage i skovens skyggeleg. I din zoo ligger den ofte afslappet på høje platforme og betragter alt fra sikker højde.'),
(91719, 836, 'en', 'Leopard Seal', 'The leopard seal is a large and predatory seal from Antarctica. Its spotted coat resembles that of a leopard. In your zoo, it represents the wild and untamed spirit of the polar seas.'),
(91720, 836, 'de', 'Seeleopard', 'Der Seeleopard ist ein großer, räuberischer Robbenverwandter der Antarktis. Er hat ein geflecktes Fell, das an Leoparden erinnert. In deinem Zoo zeigt er die wilde Seite der Polarmeere.'),
(91721, 836, 'da', 'Svæv', 'Svømmekrabben er en aktiv jæger, der er tilpasset til at svømme ved hjælp af sine flade bagben. Den er en vigtig del af kystøkosystemet og er en populær spise-krabke i mange kulturer.'),
(91722, 30204, 'en', 'Leopard Tortoise', 'The Leopard Tortoise is a large, herbivorous tortoise native to the savannas and grasslands of Africa. Characterized by its distinctive, patterned shell with yellow and black markings, it can grow up to 18 inches (0.45 meters) in length. These tortoises are known for their gentle temperament and can live for several decades. \n\nLeopard Tortoises primarily feed on grasses, leaves, and flowers, and require a warm, dry habitat to thrive.\n\n'),
(91723, 30204, 'de', 'Leopard Tortoise', 'The Leopard Tortoise is a large, herbivorous tortoise native to the savannas and grasslands of Africa. Characterized by its distinctive, patterned shell with yellow and black markings, it can grow up to 18 inches (0.45 meters) in length. These tortoises are known for their gentle temperament and can live for several decades. \n\nLeopard Tortoises primarily feed on grasses, leaves, and flowers, and require a warm, dry habitat to thrive.\n\n'),
(91724, 30204, 'da', 'Leopard Tortoise', 'The Leopard Tortoise is a large, herbivorous tortoise native to the savannas and grasslands of Africa. Characterized by its distinctive, patterned shell with yellow and black markings, it can grow up to 18 inches (0.45 meters) in length. These tortoises are known for their gentle temperament and can live for several decades. \n\nLeopard Tortoises primarily feed on grasses, leaves, and flowers, and require a warm, dry habitat to thrive.\n\n'),
(91725, 240, 'en', 'Lesser Flamingo', 'The lesser flamingo is smaller than its famous relatives, but all the more intensely pink. It lives in large colonies on the salty lakes of Africa. In your zoo it forms a bustling, colorful carpet of long legs and neck.'),
(91726, 240, 'de', 'Zwergflamingo', 'Der Zwergflamingo ist kleiner als seine berühmten Verwandten, dafür aber umso intensiver rosa gefärbt. Er lebt in großen Kolonien an salzhaltigen Seen Afrikas. In deinem Zoo bildet er einen wuseligen, farbenfrohen Teppich aus langen Beinen und gebogenen Hälsen.'),
(91727, 240, 'da', 'Dværgflamingo', 'Dværgflamingoen er mindre end sine berømte slægtninge, men til gengæld desto mere intenst lyserød. Den lever i store kolonier ved saltholdige søer i Afrika. I din zoo danner den et travlt, farverigt tæppe af lange ben og buede halse.'),
(91728, 30205, 'en', 'Lesser Hedgehog Tenrec', 'The Lesser Hedgehog Tenrec is a stout-bodied, nocturnal mammal endemic to Madagascar. The Lesser Hedgehog Tenrec is a shrew-like mammal, small with a long whiskered snout. Its back, sides and tail have dark brown to black, sharp, dense, white-tipped spikes. Its underside is paler and does not have spikes. Unlike their cousin hedgehogs, tenrecs are excellent climbers, and use their long toes to hold onto branches.\n\nLesser Hedgehog Tenrec are omnivores, eating insects and their larvae, spiders, eggs, and occasionally fruit.\n\n'),
(91729, 30205, 'de', 'Lesser Hedgehog Tenrec', 'The Lesser Hedgehog Tenrec is a stout-bodied, nocturnal mammal endemic to Madagascar. The Lesser Hedgehog Tenrec is a shrew-like mammal, small with a long whiskered snout. Its back, sides and tail have dark brown to black, sharp, dense, white-tipped spikes. Its underside is paler and does not have spikes. Unlike their cousin hedgehogs, tenrecs are excellent climbers, and use their long toes to hold onto branches.\n\nLesser Hedgehog Tenrec are omnivores, eating insects and their larvae, spiders, eggs, and occasionally fruit.\n\n'),
(91730, 30205, 'da', 'Lesser Hedgehog Tenrec', 'The Lesser Hedgehog Tenrec is a stout-bodied, nocturnal mammal endemic to Madagascar. The Lesser Hedgehog Tenrec is a shrew-like mammal, small with a long whiskered snout. Its back, sides and tail have dark brown to black, sharp, dense, white-tipped spikes. Its underside is paler and does not have spikes. Unlike their cousin hedgehogs, tenrecs are excellent climbers, and use their long toes to hold onto branches.\n\nLesser Hedgehog Tenrec are omnivores, eating insects and their larvae, spiders, eggs, and occasionally fruit.\n\n'),
(91731, 520, 'en', 'Lion', 'The Lion truly deserves the title \"King of the Beasts.\" Living in prides, it rests a lot but is incredibly powerful when hunting. In your zoo, lions love to bask in the sun, roar impressively, and show their majestic presence.'),
(91732, 520, 'de', 'Löwe', 'Der Löwe trägt nicht umsonst den Titel „König der Tiere“. In Rudeln lebend, ruht er viel, ist aber bei der Jagd unglaublich kraftvoll. In deinem Zoo liegen Löwen gerne in der Sonne, brüllen eindrucksvoll und zeigen ihre majestätische Präsenz.'),
(91733, 520, 'da', 'Pelikaner', 'Pelikanens kendetegnende pungstrube kan holde op til tre gange så meget som dens mave. Disse sociale fugle jager ofte i gruppe og samarbejder om at drive fisk ind i lavt vand.'),
(91734, 625, 'en', 'Lion Tamarin', 'The lion tamarin is a small monkey with an impressive mane around its face. Its golden or reddish fur resembles a tiny lion. In your zoo it darts through the branches and is a particularly photogenic member of the monkey family.'),
(91735, 625, 'de', 'Löwenäffchen', 'Das Löwenäffchen ist ein kleiner Affe mit beeindruckender Mähne um das Gesicht. Sein goldenes oder rötliches Fell erinnert an einen winzigen Löwen. In deinem Zoo flitzt es durch das Geäst und ist ein besonders fotogenes Mitglied der Affenfamilie.'),
(91736, 625, 'da', 'Isbjørn', 'Isbjørnen er verdens største landrovdyr og er perfekt tilpasset til det arktiske miljø. Dens hvide pels er faktisk gennemsigtig og hul, og dens hud er sort for at absorbere varme.'),
(91737, 221, 'en', 'Llama', 'The llama is a typical inhabitant of the Andes and has served the local people as a pack animal for centuries. It is known for its soft wool – and for spitting when it feels annoyed. In your zoo its curious nature and funny hairstyle keep visitors smiling again and again.'),
(91738, 221, 'de', 'Lama', 'Das Lama ist ein typischer Bewohner der Anden und seit Jahrhunderten ein Lasttier der dortigen Bevölkerung. Es ist bekannt für sein weiches Fell – und für das gelegentliche Spucken, wenn es sich gestört fühlt. In deinem Zoo sorgt es mit seiner neugierigen Art und der lustigen Frisur immer wieder für Lacher.'),
(91739, 221, 'da', 'Lama', 'Lamaen er en typisk beboer af Andesbjergene og har i århundreder tjent lokalbefolkningens lastdyr. Den er kendt for sin bløde uld og for den lejlighedsvise spytten, hvis den føler sig generet. I din zoo slentre den nysgerrigt rundt og frembringer altid latter.'),
(91740, 30206, 'en', 'Loggerhead Sea Turtle', 'The Loggerhead Sea Turtle is a large species of sea turtle found in temperate and subtropical oceans worldwide. Adults typically measure 90–110 cm (35–43 inches) in shell length and weigh between 100–200 kg (220–440 lbs). They have a reddish-brown carapace with five pairs of scales and flippers adapted for long-distance swimming.\n\nTheir diet is omnivorous, consisting mainly of jellyfish, crabs, fish, mollusks, and sea plants. \n\n'),
(91741, 30206, 'de', 'Loggerhead Sea Turtle', 'The Loggerhead Sea Turtle is a large species of sea turtle found in temperate and subtropical oceans worldwide. Adults typically measure 90–110 cm (35–43 inches) in shell length and weigh between 100–200 kg (220–440 lbs). They have a reddish-brown carapace with five pairs of scales and flippers adapted for long-distance swimming.\n\nTheir diet is omnivorous, consisting mainly of jellyfish, crabs, fish, mollusks, and sea plants. \n\n'),
(91742, 30206, 'da', 'Loggerhead Sea Turtle', 'The Loggerhead Sea Turtle is a large species of sea turtle found in temperate and subtropical oceans worldwide. Adults typically measure 90–110 cm (35–43 inches) in shell length and weigh between 100–200 kg (220–440 lbs). They have a reddish-brown carapace with five pairs of scales and flippers adapted for long-distance swimming.\n\nTheir diet is omnivorous, consisting mainly of jellyfish, crabs, fish, mollusks, and sea plants. \n\n'),
(91743, 1203, 'en', 'Long-Eared Hedgehog', 'The Long-Eared Hedgehog is an insect-eater with remarkably large ears. It uses them for cooling and for keen listening. In your zoo, it’s a spiky little night explorer.'),
(91744, 1203, 'de', 'Langohrigel', 'Der Langohrigel ist ein Insektenfresser mit auffällig großen Ohren. Er nutzt sie zur Kühlung und zum Lauschen. In deinem Zoo ist er ein nächtlicher, pieksiger kleiner Entdecker.'),
(91745, 1203, 'da', 'Ørkenpyton', 'Ørkenpythoner er store kvælerslanger tilpasset til et liv i ørkenens klippeterræn. De er termofile og tilbringer kolde perioder i huler og revner. De kan gå måneder uden at spise efter et stort måltid.'),
(91746, 30207, 'en', 'Long-Eared Jerboa', 'The Long-Eared Jerboa is a small, nocturnal rodent native to the deserts of Central Asia. Known for its distinctive long ears and large hind legs, this agile creature is well-adapted for jumping and navigating its arid environment. The fur color of the Long-Eared Jerboa is typically a sandy or light brown shade, which helps it blend into its desert environment.\n\nLong-Eared Jerboa primarily feeds on seeds, insects, and other plant materials\n\n'),
(91747, 30207, 'de', 'Long-Eared Jerboa', 'The Long-Eared Jerboa is a small, nocturnal rodent native to the deserts of Central Asia. Known for its distinctive long ears and large hind legs, this agile creature is well-adapted for jumping and navigating its arid environment. The fur color of the Long-Eared Jerboa is typically a sandy or light brown shade, which helps it blend into its desert environment.\n\nLong-Eared Jerboa primarily feeds on seeds, insects, and other plant materials\n\n'),
(91748, 30207, 'da', 'Long-Eared Jerboa', 'The Long-Eared Jerboa is a small, nocturnal rodent native to the deserts of Central Asia. Known for its distinctive long ears and large hind legs, this agile creature is well-adapted for jumping and navigating its arid environment. The fur color of the Long-Eared Jerboa is typically a sandy or light brown shade, which helps it blend into its desert environment.\n\nLong-Eared Jerboa primarily feeds on seeds, insects, and other plant materials\n\n'),
(91749, 201, 'en', 'Long-Legged Buzzard', 'The Common Buzzard is a powerful bird of prey that circles majestically in the sky with its broad wings. It inhabits open landscapes and mountains, keeping a sharp eye out for prey. In your zoo, it impresses with its piercing gaze and impressive wingspan during training flights.'),
(91750, 201, 'de', 'Adlerbussard', 'Der Adlerbussard ist ein kräftiger Greifvogel, der mit seinen breiten Flügeln majestätisch am Himmel kreist. Er bewohnt offene Landschaften und Gebirge und hält aufmerksam Ausschau nach Beute. In deinem Zoo beeindruckt er mit durchdringendem Blick und eindrucksvoller Spannweite bei Trainingsflügen.'),
(91751, 201, 'da', 'Langtbenet musvåge', 'Adlervågen er en kraftig rovfugl, der majestætisk kredser over himlen med sine brede vinger. I din zoo imponerer den med sit gennemtrængende blik og imponerende vingefang under træningsflyvninger.'),
(91752, 30208, 'en', 'Long-Tailed Chinchilla', 'The Long-Tailed Chinchilla is a small rodent native to the Andes mountains in South America. Recognized for its soft, dense fur, this species has a long, bushy tail that aids in balance and agility. Their fur color is typically a soft gray, which can vary in shade from light to dark. Long-Tailed Chinchillas are social animals, often found in groups. Due to habitat loss and hunting for their fur, they are considered vulnerable in the wild. \n\nLong-Tailed Chinchilla primarily feed on grasses, seeds, and other plant materials.\n\n'),
(91753, 30208, 'de', 'Long-Tailed Chinchilla', 'The Long-Tailed Chinchilla is a small rodent native to the Andes mountains in South America. Recognized for its soft, dense fur, this species has a long, bushy tail that aids in balance and agility. Their fur color is typically a soft gray, which can vary in shade from light to dark. Long-Tailed Chinchillas are social animals, often found in groups. Due to habitat loss and hunting for their fur, they are considered vulnerable in the wild. \n\nLong-Tailed Chinchilla primarily feed on grasses, seeds, and other plant materials.\n\n'),
(91754, 30208, 'da', 'Long-Tailed Chinchilla', 'The Long-Tailed Chinchilla is a small rodent native to the Andes mountains in South America. Recognized for its soft, dense fur, this species has a long, bushy tail that aids in balance and agility. Their fur color is typically a soft gray, which can vary in shade from light to dark. Long-Tailed Chinchillas are social animals, often found in groups. Due to habitat loss and hunting for their fur, they are considered vulnerable in the wild. \n\nLong-Tailed Chinchilla primarily feed on grasses, seeds, and other plant materials.\n\n'),
(91755, 30209, 'en', 'Lop Rabbit', 'The Lop Rabbit is a popular breed known for its distinctive floppy ears that hang down beside its head. These rabbits have a compact, rounded body and a friendly, gentle temperament. Lop Rabbits come in various colors and patterns, and they typically weigh between 1.5 to 4.5 kilograms (3 to 10 pounds), depending on the specific variety (such as the Mini Lop or French Lop). \n\nLop Rabbits primarily eat a herbivorous diet consisting of grasses, wild herbs, leafy greens, and young shoots. \n\n'),
(91756, 30209, 'de', 'Lop Rabbit', 'The Lop Rabbit is a popular breed known for its distinctive floppy ears that hang down beside its head. These rabbits have a compact, rounded body and a friendly, gentle temperament. Lop Rabbits come in various colors and patterns, and they typically weigh between 1.5 to 4.5 kilograms (3 to 10 pounds), depending on the specific variety (such as the Mini Lop or French Lop). \n\nLop Rabbits primarily eat a herbivorous diet consisting of grasses, wild herbs, leafy greens, and young shoots. \n\n'),
(91757, 30209, 'da', 'Lop Rabbit', 'The Lop Rabbit is a popular breed known for its distinctive floppy ears that hang down beside its head. These rabbits have a compact, rounded body and a friendly, gentle temperament. Lop Rabbits come in various colors and patterns, and they typically weigh between 1.5 to 4.5 kilograms (3 to 10 pounds), depending on the specific variety (such as the Mini Lop or French Lop). \n\nLop Rabbits primarily eat a herbivorous diet consisting of grasses, wild herbs, leafy greens, and young shoots. \n\n'),
(91758, 1102, 'en', 'Lowland Streaked Tenrec', 'The Striped Tenrec is a small, hedgehog-like animal from Madagascar. It sports striking stripes on its back and can raise spines when in danger. In your zoo, it\'s an exotic, nocturnal resident.'),
(91759, 1102, 'de', 'Eigentlicher Streifentenrek', 'Der Eigentliche Streifentenrek ist ein kleines, igelähnliches Tier aus Madagaskar. Er trägt auffällige Streifen auf dem Rücken und kann bei Gefahr Stacheln aufstellen. In deinem Zoo ist er ein exotischer, nachtaktiver Bewohner.'),
(91760, 1102, 'da', 'Stokinsekt', 'Stokinsekter er mestre i formbaseret kamouflage og kan ligne grene, stængler eller bark til forveksling. De er nattaktive og forbliver næsten ubevægelige om dagen for at undgå at blive opdaget.'),
(91761, 2204, 'en', 'Luna Lionfish', 'The Japanese lionfish is a poisonous reef dweller with long, ray-like fins. Its patterning warns predators. In your zoo, it looks like living fireworks in the water.'),
(91762, 2204, 'de', 'Japanischer-Feuerfisch', 'Der Japanische Feuerfisch ist ein giftiger Riffbewohner mit langen, strahlenartigen Flossen. Seine Musterung warnt Fressfeinde. In deinem Zoo wirkt er wie ein lebendes Feuerwerk im Wasser.'),
(91763, 2204, 'da', 'Barracuda', 'Barracudaen er en langstrakt, hurtig rovfisk kendetegnet ved sine skarpe tænder og intense starer. Den er en opportunistisk jæger og lever i varme saltvandshave. Den er generelt ufarlig for svømmere.'),
(91764, 420, 'en', 'Lynx', 'The lynx is the largest wild cat in Europe and easily recognized by its tufted ears. It is a silent hunter that usually moves about at twilight. In your zoo it needs secluded retreats and rewards patient visitors with a quiet, graceful appearance.'),
(91765, 420, 'de', 'Luchs', 'Der Luchs ist die größte europäische Wildkatze und an seinen Pinselohren gut zu erkennen. Er ist ein lautloser Jäger, der meist in der Dämmerung unterwegs ist. In deinem Zoo braucht er Rückzugsräume und belohnt geduldige Besucher mit einem leisen Auftritt.'),
(91766, 420, 'da', 'Los', 'Lossen er den største europæiske vildkat og let genkendelig på sine fjertoppede ører. Den er en lydløs jæger, der normalt er aktiv i tusmørket. I din zoo har den brug for afsondrede tilflugtsteder og belønner tålmodige besøgende med en stille, yndefuld fremtræden.'),
(91767, 1110, 'en', 'Madagascar Day Gecko', 'The Madagascar Day Gecko is bright green and active during the day. It lives among plants and hunts insects. In your zoo, it brings a splash of tropical color to the terrarium.'),
(91768, 1110, 'de', 'Madagasker-Taggecko', 'Der Madagaskar-Taggecko ist leuchtend grün und tagsüber aktiv. Er lebt auf Pflanzen und jagt Insekten. In deinem Zoo bringt er tropische Farbe ins Terrarium.'),
(91769, 1110, 'da', 'Træfrø', 'Træfrøer er tilpasset til livet i trætoppene med klisterede fingerskiver, der giver dem mulighed for at klatre på næsten enhver overflade. Mange arter har levende farver som advarsel om giftighed.'),
(91770, 30210, 'en', 'Magnificent Frigatebird', 'Magnificent Frigatebird is a striking tropical seabird known for its massive wingspan of 89-114 cm (35-45 in) and graceful soaring flight. They have a long, hooked bill, deeply forked tail. Males dazzle with glossy black plumage and a bright red inflatable throat pouch they puff up like a balloon during breeding displays.\n\nThey mainly eat flying fish and squid that they snatch from the ocean surface while soaring.\n\n'),
(91771, 30210, 'de', 'Magnificent Frigatebird', 'Magnificent Frigatebird is a striking tropical seabird known for its massive wingspan of 89-114 cm (35-45 in) and graceful soaring flight. They have a long, hooked bill, deeply forked tail. Males dazzle with glossy black plumage and a bright red inflatable throat pouch they puff up like a balloon during breeding displays.\n\nThey mainly eat flying fish and squid that they snatch from the ocean surface while soaring.\n\n'),
(91772, 30210, 'da', 'Magnificent Frigatebird', 'Magnificent Frigatebird is a striking tropical seabird known for its massive wingspan of 89-114 cm (35-45 in) and graceful soaring flight. They have a long, hooked bill, deeply forked tail. Males dazzle with glossy black plumage and a bright red inflatable throat pouch they puff up like a balloon during breeding displays.\n\nThey mainly eat flying fish and squid that they snatch from the ocean surface while soaring.\n\n'),
(91773, 626, 'en', 'Maikong', 'The crab‑eating fox, also called maikong, is a small wild dog from South America. It is flexible in its foraging and uses various habitats. In your zoo it moves quietly and usually stays close to cover.'),
(91774, 626, 'de', 'Maikong', 'Der Maikong, auch Krabbenfuchs genannt, ist ein kleiner Wildhund aus Südamerika. Er ist flexibel bei der Nahrungssuche und nutzt verschiedene Lebensräume. In deinem Zoo bewegt er sich leise und bleibt meist in der Nähe von Deckung.'),
(91775, 626, 'da', 'Slangepapegøje', 'Giftslangerne er en stor gruppe slanger med et stort udvalg af giftsystemer. Fra de neurotoksiske kobraer til de hæmotoksiske hugorme. De spiller en vigtig rolle i at kontrollere gnaver-bestande.'),
(91776, 30211, 'en', 'Malayan Tiger', 'The Malayan Tiger is a critically endangered subspecies of tiger native to the Malay Peninsula, known for its striking orange coat with black stripes, powerful build, and solitary hunting prowess. Males can reach 2.5-3 meters (8-10 feet) in length and weigh 100-150 kg (220-330 lbs), while females are slightly smaller at 2-2.5 meters and 75-120 kg; they have a lifespan of 15-20 years in the wild.\n\nMalayan Tigers are carnivorous, preying on deer, wild boar, tapirs, and smaller mammals.\n\n'),
(91777, 30211, 'de', 'Malayan Tiger', 'The Malayan Tiger is a critically endangered subspecies of tiger native to the Malay Peninsula, known for its striking orange coat with black stripes, powerful build, and solitary hunting prowess. Males can reach 2.5-3 meters (8-10 feet) in length and weigh 100-150 kg (220-330 lbs), while females are slightly smaller at 2-2.5 meters and 75-120 kg; they have a lifespan of 15-20 years in the wild.\n\nMalayan Tigers are carnivorous, preying on deer, wild boar, tapirs, and smaller mammals.\n\n'),
(91778, 30211, 'da', 'Malayan Tiger', 'The Malayan Tiger is a critically endangered subspecies of tiger native to the Malay Peninsula, known for its striking orange coat with black stripes, powerful build, and solitary hunting prowess. Males can reach 2.5-3 meters (8-10 feet) in length and weigh 100-150 kg (220-330 lbs), while females are slightly smaller at 2-2.5 meters and 75-120 kg; they have a lifespan of 15-20 years in the wild.\n\nMalayan Tigers are carnivorous, preying on deer, wild boar, tapirs, and smaller mammals.\n\n'),
(91779, 830, 'en', 'Manatee', 'The round-tailed manatee is a gentle herbivore of shallow waters. It moves slowly and serenely through its habitat. In your zoo, it’s a calm and friendly underwater resident.'),
(91780, 830, 'de', 'Rundschwanzseekuh', 'Die Rundschwanzseekuh ist eine friedliche Pflanzenfresserin der Flachgewässer. Sie gleitet langsam durchs Wasser und wirkt sehr gelassen. In deinem Zoo ist sie ein ruhiger, sympathischer Unterwasserbewohner.'),
(91781, 830, 'da', 'Stikling', 'Stiklingen er en lille sødvandsfisk, berømt for hannernes imponerende redebyggeri og forældreomsorg. Hannen bygger en rede af planter og vogter æggene alene, mens hunnen søger en ny partner.'),
(91782, 819, 'en', 'Mandarin Duck', 'The mandarin duck is one of the most colorful duck species in the world. The male wears a spectacular feather coat during the breeding season. In your zoo it looks like a small, living paintbox on the water.'),
(91783, 819, 'de', 'Mandarinente', 'Die Mandarinente ist eine der buntesten Entenarten der Welt. Das Männchen trägt zur Balzzeit ein spektakuläres Federkleid. In deinem Zoo wirkt sie wie ein kleiner, lebender Farbkasten auf dem Wasser.'),
(91784, 819, 'da', 'Hvid haj', 'Tyrehajen er en af de farligste hajarter for mennesker på grund af dens aggressive natur og tilbøjelighed til at svømme ind i lavt, varmt vand og endda i floder. Den kan tolerere ferskvand i lange perioder.'),
(91785, 30212, 'en', 'Mandarinfish', 'The Mandarinfish is a small, brightly colored member of the dragonet family. Its vivid coloration sports a bright blue background, with swirly orange stripes and a blue-greenish face with bold blue stripes. The eyes are usually red with black pupils.\n\nMandarinfish are reef dwellers, preferring sheltered lagoons and inshore reefs. They are not easily seen due to their bottom-feeding habit and their small size (reaching only about 6 cm). \n\nThey feed primarily on small crustaceans and other invertebrates.\n\n'),
(91786, 30212, 'de', 'Mandarinfish', 'The Mandarinfish is a small, brightly colored member of the dragonet family. Its vivid coloration sports a bright blue background, with swirly orange stripes and a blue-greenish face with bold blue stripes. The eyes are usually red with black pupils.\n\nMandarinfish are reef dwellers, preferring sheltered lagoons and inshore reefs. They are not easily seen due to their bottom-feeding habit and their small size (reaching only about 6 cm). \n\nThey feed primarily on small crustaceans and other invertebrates.\n\n'),
(91787, 30212, 'da', 'Mandarinfish', 'The Mandarinfish is a small, brightly colored member of the dragonet family. Its vivid coloration sports a bright blue background, with swirly orange stripes and a blue-greenish face with bold blue stripes. The eyes are usually red with black pupils.\n\nMandarinfish are reef dwellers, preferring sheltered lagoons and inshore reefs. They are not easily seen due to their bottom-feeding habit and their small size (reaching only about 6 cm). \n\nThey feed primarily on small crustaceans and other invertebrates.\n\n'),
(91788, 627, 'en', 'Mandrill', 'The mandrill is one of the most colorful monkeys, with a bright blue‑red muzzle. It lives in African rainforests and is an extremely social animal. In your zoo it is a colorful star that rarely goes unnoticed.'),
(91789, 627, 'de', 'Mandrill', 'Der Mandrill ist einer der buntesten Affen überhaupt, mit leuchtend blau-roter Schnauze. Er lebt in afrikanischen Regenwäldern und ist ein äußerst soziales Tier. In deinem Zoo ist er ein farbenfroher Star, der selten unbemerkt bleibt.'),
(91790, 627, 'da', 'Pungrokke', 'Pungrokken er i stand til at generere elektriske stød på op til 220 volt for at bedøve bytte og afskrække rovdyr. Denne elektriske sans er også et fint navigations- og kommunikationsværktøj.'),
(91791, 1111, 'en', 'Maned Rat', 'The Crested Rat wears a striking coat of long back hairs. It can absorb plant toxins into its fur to defend itself. In your zoo, it’s a small but truly fascinating subject of research.'),
(91792, 1111, 'de', 'Mähnenratte', 'Die Mähnenratte trägt ein auffälliges, langes Rückenhaarkleid. Sie kann Gift aus Pflanzen in ihr Fell einlagern, um sich zu schützen. In deinem Zoo ist sie ein kleines, aber sehr spannendes Forschungsobjekt.'),
(91793, 1111, 'da', 'Jaguar-gecko', 'Tokay-geckoen er en af de største geckoarter med karakteristiske blå pletter på rød-brun baggrund. Den er territorial og har et kraftigt bid. Den er berømt for dens høje, karakteristiske \"to-kay\" opkald.'),
(91794, 117, 'en', 'Maned Wolf', 'The Maned Wolf is not a real wolf but its own species of wild dog with very long legs and brightly red fur. It lives in the grasslands of South America and is rather a shy loner. In the zoo, it sneaks elegantly through its territory, sniffs at grasses, and listens attentively to every sound.'),
(91795, 117, 'de', 'Mähnenwolf', 'Der Mähnenwolf ist kein echter Wolf, sondern eine eigene Wildhundart mit sehr langen Beinen und leuchtend rotem Fell. Er lebt in den Graslandschaften Südamerikas und ist ein eher scheuer Einzelgänger. Im Zoo schleicht er elegant durch sein Revier, schnuppert an Gräsern und lauscht aufmerksam auf jedes Geräusch.'),
(91796, 117, 'da', 'Manewolf', 'Manulven er ikke en rigtig ulv, men sin egen vildthundsart med meget lange ben og lysende rødt pels. I din zoo sniger den sig elegant gennem sit territorium og lytter opmærksomt til enhver lyd.'),
(91797, 421, 'en', 'Manul', 'The manul, also known as the Pallas’s cat, has an especially dense, plushy coat and a grumpy face. It lives in the barren steppes and mountains of Asia and copes well with extreme temperatures. In your zoo it looks like a small, very fluffy wildcat with a big personality.'),
(91798, 421, 'de', 'Manul', 'Der Manul, auch Pallaskatze genannt, hat ein besonders dichtes, plüschiges Fell und ein grimmiges Gesicht. Er lebt in kargen Steppen und Gebirgen Asiens und kommt mit extremen Temperaturen zurecht. In deinem Zoo wirkt er wie eine kleine, sehr flauschige Wildkatze mit großem Charakter.'),
(91799, 421, 'da', 'Pallaskat', 'Manulkatten, også kaldet Pallaskatten, har en særlig tæt, plysagtig pels og et bistert ansigt. Den lever i de øde stepper og bjerge i Asien og klarer sig godt ved ekstreme temperaturer. I din zoo ligner den en lille, meget fluffy vildkat med stor personlighed.'),
(91800, 30213, 'en', 'Marbled Cat', 'The Marbled Cat is a small, elusive wild cat native to Southeast Asia, known for its striking marbled coat pattern resembling tree bark for camouflage. Measuring 45-60 cm (18-24 inches) in body length plus a 40-50 cm tail, and weighing 2-5 kg (4.4-11 lbs), it has a stocky build, tufted ears, and retractable claws adapted for climbing.\n\nMarbled Cats are carnivorous, preying on birds, rodents, squirrels, and small mammals; also consumes fruits and insects, making it somewhat omnivorous.\n\n'),
(91801, 30213, 'de', 'Marbled Cat', 'The Marbled Cat is a small, elusive wild cat native to Southeast Asia, known for its striking marbled coat pattern resembling tree bark for camouflage. Measuring 45-60 cm (18-24 inches) in body length plus a 40-50 cm tail, and weighing 2-5 kg (4.4-11 lbs), it has a stocky build, tufted ears, and retractable claws adapted for climbing.\n\nMarbled Cats are carnivorous, preying on birds, rodents, squirrels, and small mammals; also consumes fruits and insects, making it somewhat omnivorous.\n\n'),
(91802, 30213, 'da', 'Marbled Cat', 'The Marbled Cat is a small, elusive wild cat native to Southeast Asia, known for its striking marbled coat pattern resembling tree bark for camouflage. Measuring 45-60 cm (18-24 inches) in body length plus a 40-50 cm tail, and weighing 2-5 kg (4.4-11 lbs), it has a stocky build, tufted ears, and retractable claws adapted for climbing.\n\nMarbled Cats are carnivorous, preying on birds, rodents, squirrels, and small mammals; also consumes fruits and insects, making it somewhat omnivorous.\n\n'),
(91803, 239, 'en', 'Marbled Polecat', 'The marbled polecat is a small carnivore relative with a striking, blotched coat pattern. It is nocturnal and hides away in burrows and underground dens. In the zoo it thrives in richly structured enclosures, explores every corner and surprises visitors with its agility.'),
(91804, 239, 'de', 'Tigeriltis', 'Der Tigeriltis ist ein kleiner Raubtierverwandter mit auffälliger, gefleckter Zeichnung. Er ist nachtaktiv und lebt versteckt in Höhlen und Erdbauen. Im Zoo zeigt er sich gerne in strukturreichen Gehegen, durchstöbert jeden Winkel und überrascht Besucher mit seiner Agilität.'),
(91805, 239, 'da', 'Tigerbrud', 'Tigerbruddet er et lille rovdyr med iøjnefaldende, plettet tegningsmønster. Det er nattaktivt og lever skjult i huller og jordgrave. I din zoo trives det i strukturrige indhegninger, undersøger hvert hjørne og overrasker besøgende med sin agilitet.'),
(91806, 30214, 'en', 'Markhor', 'The Markhor is a wild goat species native to Central and South Asia, particularly found in mountainous regions of Afghanistan, Pakistan, and India. Known for its impressive twisted horns, which can grow up to 1.5 meters long, the Markhor has a distinctive shaggy coat that varies in color from light brown to dark gray. It is a skilled climber, adept at navigating steep, rocky terrains. \n\nMarkhor is a herbivore, primarily feeding on grasses, shrubs, and leaves.\n\n'),
(91807, 30214, 'de', 'Markhor', 'The Markhor is a wild goat species native to Central and South Asia, particularly found in mountainous regions of Afghanistan, Pakistan, and India. Known for its impressive twisted horns, which can grow up to 1.5 meters long, the Markhor has a distinctive shaggy coat that varies in color from light brown to dark gray. It is a skilled climber, adept at navigating steep, rocky terrains. \n\nMarkhor is a herbivore, primarily feeding on grasses, shrubs, and leaves.\n\n'),
(91808, 30214, 'da', 'Markhor', 'The Markhor is a wild goat species native to Central and South Asia, particularly found in mountainous regions of Afghanistan, Pakistan, and India. Known for its impressive twisted horns, which can grow up to 1.5 meters long, the Markhor has a distinctive shaggy coat that varies in color from light brown to dark gray. It is a skilled climber, adept at navigating steep, rocky terrains. \n\nMarkhor is a herbivore, primarily feeding on grasses, shrubs, and leaves.\n\n'),
(91809, 30215, 'en', 'Marsh Deer', 'The Marsh Deer, also known as Pampas Deer, is South America\'s largest deer species, weighing up to 150 kg (331 lbs). It inhabits wetlands and marshes, with long legs adapted for wading and swimming. Marsh Deer has reddish-brown fur with a white underbelly; short, dense hair for camouflage in wetlands.\n\nMarsh Deer are herbivorous, they feed on aquatic plants, grasses, and reeds. \n\n'),
(91810, 30215, 'de', 'Marsh Deer', 'The Marsh Deer, also known as Pampas Deer, is South America\'s largest deer species, weighing up to 150 kg (331 lbs). It inhabits wetlands and marshes, with long legs adapted for wading and swimming. Marsh Deer has reddish-brown fur with a white underbelly; short, dense hair for camouflage in wetlands.\n\nMarsh Deer are herbivorous, they feed on aquatic plants, grasses, and reeds. \n\n'),
(91811, 30215, 'da', 'Marsh Deer', 'The Marsh Deer, also known as Pampas Deer, is South America\'s largest deer species, weighing up to 150 kg (331 lbs). It inhabits wetlands and marshes, with long legs adapted for wading and swimming. Marsh Deer has reddish-brown fur with a white underbelly; short, dense hair for camouflage in wetlands.\n\nMarsh Deer are herbivorous, they feed on aquatic plants, grasses, and reeds. \n\n'),
(91812, 222, 'en', 'Masai Giraffe', 'The Masai giraffe is the largest giraffe subspecies and has an irregular, net-like pattern of spots. With its long neck it can reach even the highest leaves on the trees. In your zoo it looks out over all the other animals and calmly nibbles on the treetops.'),
(91813, 222, 'de', 'Massai-Giraffe', 'Die Massai-Giraffe ist die größte Giraffenunterart und besitzt ein unregelmäßiges, netzartiges Fleckenmuster. Mit ihrem langen Hals erreicht sie selbst die höchsten Blätter der Bäume. In deinem Zoo schaut sie über alle anderen Tiere hinweg und knabbert entspannt an den Baumkronen.'),
(91814, 222, 'da', 'Masai-giraf', 'Masai-giraffen er den største girafunderart og besidder et uregelmæssigt, netformet pletmønster. Med sin lange hals kan den nå selv de højeste blade i træerne. I din zoo kigger den over alle andre dyr.'),
(91815, 30216, 'en', 'Masked Puffer', 'The Masked Pufferfish, also known as the Panda Puffer, is a pufferfish in the family Tetraodontidae. It has black patches around both eyes, lacks pelvic fins, and has the ability to inflate its body to almost twice its normal size. Additionally, when threatened or alarmed, it holds its spines straight out from the body. Not to be overlooked, it also has a fused beak-like structure that serves as its teeth. The puffer is among the most poisonous animals in the world, ranking second, after poison dart frogs.\n\nThe Masked Puffer is an omnivore, but has a diet mainly consisting of various invertebrates such as mollusks, sponges, algae, echinoderms, and crustaceans. It has also been known to consume coral from time to time.\n\n'),
(91816, 30216, 'de', 'Masked Puffer', 'The Masked Pufferfish, also known as the Panda Puffer, is a pufferfish in the family Tetraodontidae. It has black patches around both eyes, lacks pelvic fins, and has the ability to inflate its body to almost twice its normal size. Additionally, when threatened or alarmed, it holds its spines straight out from the body. Not to be overlooked, it also has a fused beak-like structure that serves as its teeth. The puffer is among the most poisonous animals in the world, ranking second, after poison dart frogs.\n\nThe Masked Puffer is an omnivore, but has a diet mainly consisting of various invertebrates such as mollusks, sponges, algae, echinoderms, and crustaceans. It has also been known to consume coral from time to time.\n\n'),
(91817, 30216, 'da', 'Masked Puffer', 'The Masked Pufferfish, also known as the Panda Puffer, is a pufferfish in the family Tetraodontidae. It has black patches around both eyes, lacks pelvic fins, and has the ability to inflate its body to almost twice its normal size. Additionally, when threatened or alarmed, it holds its spines straight out from the body. Not to be overlooked, it also has a fused beak-like structure that serves as its teeth. The puffer is among the most poisonous animals in the world, ranking second, after poison dart frogs.\n\nThe Masked Puffer is an omnivore, but has a diet mainly consisting of various invertebrates such as mollusks, sponges, algae, echinoderms, and crustaceans. It has also been known to consume coral from time to time.\n\n'),
(91818, 811, 'en', 'Mata Mata', 'The fringed turtle has a flat body and fringed skin flaps. It is superbly camouflaged and lives in freshwater. In your zoo it looks like a living leaf drifting through the water.'),
(91819, 811, 'de', 'Fransenschildkröte', 'Die Fransenschildkröte hat einen flachen Körper und fransige Hautlappen. Sie ist hervorragend getarnt und lebt im Süßwasser. In deinem Zoo wirkt sie wie ein lebendes Blatt, das im Wasser schwebt.'),
(91820, 811, 'da', 'Havaborre', 'Havaborrens er en populær sportsfisk med et sølvskinnende udseende. Den er en aktiv jæger og lever i grupper i kystvande. Den er en vigtig kommerciel fisk i mange europæiske lande.'),
(91821, 30217, 'en', 'Matschie\'s Tree Kangaroo', 'The Matschie’s Tree Kangaroo has thick, reddish mahogany fur on its back and a dark stripe down its spine. Its limbs, feet and ear tips are yellow, and its face is white or cream-colored. As arboreal animal with a body and head length of 20 to 32 inches (51–81 cm), it spends most of its time in trees. When hopping and walking, the animal moves its limbs alternately, as opposed to other kangaroos. \n\nMatschie\'s Tree Kangaroos primarily eat tree leaves. They also consume flowers, grass shoots, ferns, moss, and bark.\n\nUnder the IUCN classification, Matschie\'s Tree Kangaroo is an endangered species.\n\n'),
(91822, 30217, 'de', 'Matschie\'s Tree Kangaroo', 'The Matschie’s Tree Kangaroo has thick, reddish mahogany fur on its back and a dark stripe down its spine. Its limbs, feet and ear tips are yellow, and its face is white or cream-colored. As arboreal animal with a body and head length of 20 to 32 inches (51–81 cm), it spends most of its time in trees. When hopping and walking, the animal moves its limbs alternately, as opposed to other kangaroos. \n\nMatschie\'s Tree Kangaroos primarily eat tree leaves. They also consume flowers, grass shoots, ferns, moss, and bark.\n\nUnder the IUCN classification, Matschie\'s Tree Kangaroo is an endangered species.\n\n'),
(91823, 30217, 'da', 'Matschie\'s Tree Kangaroo', 'The Matschie’s Tree Kangaroo has thick, reddish mahogany fur on its back and a dark stripe down its spine. Its limbs, feet and ear tips are yellow, and its face is white or cream-colored. As arboreal animal with a body and head length of 20 to 32 inches (51–81 cm), it spends most of its time in trees. When hopping and walking, the animal moves its limbs alternately, as opposed to other kangaroos. \n\nMatschie\'s Tree Kangaroos primarily eat tree leaves. They also consume flowers, grass shoots, ferns, moss, and bark.\n\nUnder the IUCN classification, Matschie\'s Tree Kangaroo is an endangered species.\n\n'),
(91824, 510, 'en', 'Meerkat', 'The Meerkat is a small savanna watchguard that likes to stand upright and keep a lookout. It lives in groups and shares the tasks of foraging and guarding. In your zoo, the meerkats with their bustling movements and curious glances are real crowd‑pleasers.'),
(91825, 510, 'de', 'Erdmännchen', 'Das Erdmännchen ist ein kleiner Wachposten der Savanne, der gern aufrecht steht und Ausschau hält. Es lebt in Gruppen und teilt sich die Aufgaben bei der Nahrungssuche und Bewachung. In deinem Zoo sind die Erdmännchen mit ihren wuseligen Bewegungen und neugierigen Blicken echte Publikumslieblinge.'),
(91826, 510, 'da', 'Leopard', 'Leoparden er en mester i camouflage og er kendt for sin evne til at bære bytte op i træer for at beskytte det mod andre rovdyr. De er yderst tilpasningsdygtige og kan leve i mange forskellige habitater.'),
(91827, 409, 'en', 'Mexican Tree Porcupine', 'The tree porcupine is a climbing porcupine that spends a lot of time in trees. Its spines serve as an effective defense against enemies. In your zoo it clamberes up branches at a leisurely pace and attracts curious glances.');
INSERT INTO `animaltext` (`id`, `animalId`, `languageCode`, `animalName`, `animalDescription`) VALUES
(91828, 409, 'de', 'Baumstachler', 'Der Baumstachler ist ein kletterndes Stachelschwein, das viel Zeit in Bäumen verbringt. Seine Stacheln dienen als effektiver Schutz gegen Feinde. In deinem Zoo erklimmt er Äste in gemächlichem Tempo und zieht neugierige Blicke auf sich.'),
(91829, 409, 'da', 'Trækpindsvin', 'Trækpindsvinet er et klatrende pindsvin, der tilbringer megen tid i træerne. Dets pigge tjener som effektivt forsvar mod fjender. I din zoo kravler det op ad grene i et roligt tempo og tiltrækker nysgerrige blikke.'),
(91830, 2205, 'en', 'Mimic Octopus', 'The carnival squid stands out with intense color changes and patterns. It uses its colors for communication and camouflage. In your zoo, it shows that the sea has its own carnival artists.'),
(91831, 2205, 'de', 'Karnevalstintenfisch', 'Der Karnevalstintenfisch fällt durch intensive Farbwechsel und Muster auf. Er nutzt seine Farben zur Kommunikation und Tarnung. In deinem Zoo zeigt er, dass das Meer seine eigenen Karnevalskünstler hat.'),
(91832, 2205, 'da', 'Moray ål', 'Morænen er en stor ål-formet fisk, der lever i revner og huler i koralrev og klipperev. Den har et sæt indre kæber, der griber og holder bytte fast. Trods sit skræmmende udseende angriber den sjældent uden provokation.'),
(91833, 820, 'en', 'Mississippi Alligator', 'The Mississippi alligator is a large crocodilian from North America. It lives in swamps and rivers and can grow very old. In your zoo it often lies seemingly lazy in the water—yet always ready for quick movements.'),
(91834, 820, 'de', 'Mississippi-Aligator', 'Der Mississippi-Alligator ist ein großer Krokodilier aus Nordamerika. Er lebt in Sümpfen und Flüssen und kann sehr alt werden. In deinem Zoo liegt er gern scheinbar träge im Wasser – aber immer bereit für schnelle Bewegungen.'),
(91835, 820, 'da', 'Lysende maneter', 'Bioluminescerende maneter er et af naturens mest fascinerende fænomener. De producerer lys gennem kemiske reaktioner i kroppen og bruger dette til at tiltrække bytte, afskrække rovdyr og kommunikere.'),
(91836, 324, 'en', 'Moon bear', 'The moon bear, also called the Asiatic black bear, wears a pale crescent‑shaped mark on its chest. It lives in Asia and spends a lot of time climbing and searching for food. In your zoo it likes to climb onto platforms and proudly shows off the moon on its chest.'),
(91837, 324, 'de', 'Mondbär', 'Der Mondbär, auch Kragenbär genannt, trägt einen hellen Halbmondfleck auf der Brust. Er lebt in Asien und verbringt viel Zeit beim Klettern und nach Nahrung suchen. In deinem Zoo klettert er gern auf Plattformen und dabei immer wieder stolz seinen Brustmond.'),
(91838, 324, 'da', 'Asiatisk sortbjørn', 'Den asiatiske sortbjørn bærer en lys halvmåneformet plet på brystet. Den lever i Asien og bruger megen tid på at klatre og søge efter mad. I din zoo klatrer den gerne op på platforme og viser stolt sin brystplet frem.'),
(91839, 308, 'en', 'Moose', 'The moose is the largest member of the deer family and is easily recognized by its broad palmate antlers. It lives in northern forests and loves marshy areas and ponds. In your zoo its sheer size and calm nature make it especially impressive.'),
(91840, 308, 'de', 'Elch', 'Der Elch ist das größte Mitglied der Hirschfamilie und an seinem breiten Schaufelgeweih leicht zu erkennen. Er lebt in nordischen Wäldern und liebt sumpfige Gebiete und Wasserstellen. In deinem Zoo wirkt er mit seiner Größe und Gelassenheit besonders beeindruckend.'),
(91841, 308, 'da', 'Elg', 'Elgen er det største hjortedyr i verden og er let genkendelig på sine brede, skovlformede gevirer. Den lever i nordiske skove og elsker sumpede områder. I din zoo imponerer den med sin størrelse og rolige natur, der giver besøgende en sand naturfornemmelse.'),
(91842, 603, 'en', 'Mountain Gorilla', 'The mountain gorilla is a gentle giant that lives in the misty forests of Central Africa. It feeds mainly on plants and lives in close family groups. In your zoo it is an impressive ambassador for rainforest protection.'),
(91843, 603, 'de', 'Berggorilla', 'Der Berggorilla ist ein sanfter Riese, der in den Nebelwäldern Zentralafrikas lebt. Er ernährt sich hauptsächlich von Pflanzen und lebt in Familienverbänden. In deinem Zoo ist er ein eindrucksvoller Botschafter für den Regenwaldschutz.'),
(91844, 603, 'da', 'Schimpanse', 'Chimpanser deler omkring 98,7% af deres DNA med mennesker og er vores nærmeste levende slægtninge. De bruger redskaber, løser komplekse problemer og har rige sociale liv.'),
(91845, 410, 'en', 'Mountain Nyala', 'The mountain nyala is a rare antelope from the highland regions of Ethiopia. It has dark fur and striking white markings. In your zoo it appears especially elegant as it calmly walks through the enclosure.'),
(91846, 410, 'de', 'Bergnyala', 'Die Bergnyala ist eine seltene Antilope aus den Hochlandregionen Äthiopiens. Sie besitzt ein dunkel gefärbtes Fell und auffällige weiße Markierungen. In deinem Zoo wirkt sie besonders elegant, wenn sie ruhig durch das Gehege schreitet.'),
(91847, 410, 'da', 'Bjergnyala', 'Bjergnyalaen er en sjælden antilope fra højlandsregionerne i Etiopien. Den har mørkt pels og iøjnefaldende hvide markeringer. I din zoo fremstår den særligt elegant, når den roligt skræder igennem sit anlæg.'),
(91851, 712, 'en', 'Musk Deer', 'The musk deer is a small, deer‑like mammal without antlers. He used to be hunted for his musk. In your zoo, he appears shy and prefers to stay near cover.'),
(91852, 712, 'de', 'Moschustier', 'Das Moschustier ist ein kleines, hirschähnliches Säugetier ohne Geweih. Früher wurde es für seinen Moschus gejagt. In deinem Zoo zeigt es sich zurückhaltend und bleibt lieber in der Nähe von Deckung.'),
(91853, 712, 'da', 'Lemming', 'Lemmingen er et lille nager, der er berømt for sine massive migrationer og fejlagtigt berygtet for at kaste sig ud fra klipper. Deres bestande svinger dramatisk i cykler, der påvirker hele det arktiske fødekæde.'),
(91854, 711, 'en', 'Musk Ox', 'The muskox is an ancient‑looking animal with long, shaggy fur. He lives in the Arctic tundra and braves icy winds. In your zoo, he looks like an ice‑age relic standing calmly in the enclosure.'),
(91855, 711, 'de', 'Moschusochse', 'Der Moschusochse ist ein urtümlich wirkendes Tier mit langem, zottigem Fell. Er lebt in der arktischen Tundra und trotzt dort eisigen Winden. In deinem Zoo wirkt er wie ein Relikt aus der Eiszeit, das gelassen im Gehege steht.'),
(91856, 711, 'da', 'Hare (arktisk)', 'Den arktiske hare er en stor hare tilpasset til de kolde arktiske forholder. Dens pels skifter farve fra hvid om vinteren til grå-brun om sommeren. Den er en hurtig løber og kan nå hastigheder på 60 km/t.'),
(91857, 30218, 'en', 'Narwhal', 'Narwhal is a small, toothed whale found along coasts and in rivers throughout the Arctic. Males possess a long, straight tusk that projects forward from above the mouth. The tusk is a tooth that grows out of the male\'s upper jaw. Narwhals lack a dorsal fin, and in adults the flippers are turned upward at the tips. Adult narwhals typically have black and white spots on the dorsal parts of their body, and older narwhals can be almost entirely white. Calves are typically a blotchy gray.\n\nNarwhals are carnivores that hunt live prey and have highly specialized dietary needs. They eat halibut, cod, squids, shrimp, and other marine life. \n\n'),
(91858, 30218, 'de', 'Narwhal', 'Narwhal is a small, toothed whale found along coasts and in rivers throughout the Arctic. Males possess a long, straight tusk that projects forward from above the mouth. The tusk is a tooth that grows out of the male\'s upper jaw. Narwhals lack a dorsal fin, and in adults the flippers are turned upward at the tips. Adult narwhals typically have black and white spots on the dorsal parts of their body, and older narwhals can be almost entirely white. Calves are typically a blotchy gray.\n\nNarwhals are carnivores that hunt live prey and have highly specialized dietary needs. They eat halibut, cod, squids, shrimp, and other marine life. \n\n'),
(91859, 30218, 'da', 'Narwhal', 'Narwhal is a small, toothed whale found along coasts and in rivers throughout the Arctic. Males possess a long, straight tusk that projects forward from above the mouth. The tusk is a tooth that grows out of the male\'s upper jaw. Narwhals lack a dorsal fin, and in adults the flippers are turned upward at the tips. Adult narwhals typically have black and white spots on the dorsal parts of their body, and older narwhals can be almost entirely white. Calves are typically a blotchy gray.\n\nNarwhals are carnivores that hunt live prey and have highly specialized dietary needs. They eat halibut, cod, squids, shrimp, and other marine life. \n\n'),
(91860, 634, 'en', 'Nile Crocodile', 'The Nile crocodile is a large, fearsome river predator from Africa. It often lies motionless in the water before snapping at lightning speed. In your zoo it often seems lazily sunbathing on the bank, then suddenly shows surprisingly fast movements.'),
(91861, 634, 'de', 'Nilkrokodil', 'Das Nilkrokodil ist ein großer, furchteinflößender Flussräuber Afrikas. Es lauert oft regungslos im Wasser, bevor es blitzschnell zuschnappt. In deinem Zoo liegt es meist scheinbar träge am Ufer und zeigt dann überraschend schnelle Bewegungen.'),
(91862, 634, 'da', 'Tropisk insekt', 'Tropiske insekter udgør en utrolig mangfoldighed af liv i regnskoven. Fra gigantiske biller til iøjnefaldende sommerfugle er de en afgørende del af ekonomerne og essentielle for bestøvning og nedbrydning.'),
(91863, 121, 'en', 'Nile Monitor', 'The Nile monitor is a large, powerful lizard living along African waterways. With its forked tongue, it senses prey and is a skilled hunter both on land and in water. In the zoo, it lounges lazily in the sun, then suddenly dashes off at surprising speed.'),
(91864, 121, 'de', 'Nilwaran', 'Der Nilwaran ist eine große, kräftige Echse, die entlang afrikanischer Gewässer lebt. Mit seiner gespaltenen Zunge spürt er Beute auf und ist sowohl an Land als auch im Wasser ein guter Jäger. Im Zoo liegt er gerne träge in der Sonne, um dann plötzlich erstaunlich schnell loszulaufen.'),
(91865, 121, 'da', 'Nilvaraner', 'Nilvaraneren er et stort, kraftigt øgle, der lever langs afrikanske vandløb. Med sin kløvede tunge sporer den sit bytte og er en dygtig jæger på både land og i vand. I din zoo nyder den solen, men er altid klar til at stikke af.'),
(91866, 120, 'en', 'Nilgai', 'The Nilgau antelope is Asia\'s largest antelope species and almost resembles a small horse with its sturdy build. Males sport bluish-gray fur, while females are more brownish. In your zoo, they graze peacefully in their enclosure, happily letting visitors watch them chew their cud.'),
(91867, 120, 'de', 'Nilgauantilope', 'Die Nilgauantilope ist die größte Antilopenart Asiens und erinnert mit ihrem kräftigen Körperbau fast an ein kleines Pferd. Männchen tragen ein graublaues Fell, während Weibchen eher braun gefärbt sind. In deinem Zoo grasen sie ruhig im Gehege und lassen sich von Besuchern gerne beim Wiederkäuen beobachten.'),
(91868, 120, 'da', 'Nilgau', 'Nilgauen er Asiens største antilopeart og minder med sin kraftige kropsbygning næsten om en lille hest. I din zoo græsser den roligt i indhegningen og lader sig gerne iagttage af besøgende.'),
(91869, 137, 'en', 'Northern Bald Ibis', 'The Northern Bald Ibis is a rare ibis with glossy black plumage and a bare head. It used to live in Europe too, but today it\'s being resettled through breeding programs. In your zoo, it likes to sit on elevated spots and shows off its distinctive contours to guests.'),
(91870, 137, 'de', 'Waldrapp', 'Der Waldrapp ist ein selten gewordener Ibis mit glänzend schwarzem Gefieder und kahlem Kopf. Früher lebte er auch in Europa, heute wird er durch Zuchtprogramme wieder angesiedelt. In deinem Zoo sitzt er gerne auf erhöhten Plätzen und zeigt seinen Gästen seine markanten Konturen.'),
(91871, 137, 'da', 'Eremitibis', 'Eremitibisen er en sjælden ibis med glansende sort fjerdragt og karakteristisk skaldet hoved. Den understøttes aktivt af avlsprogrammer. I din zoo sidder den gerne på forhøjede steder og viser sin markante silhuet frem.'),
(91872, 30219, 'en', 'Northern Pudu', 'The Northern Pudu is the smallest deer species in the world, native to the temperate rainforests of the Andes in northern Chile and southern Argentina. Adult Northern Pudus typically stand about 30 to 40 cm (12 to 16 inches) tall at the shoulder and weigh between 6 to 10 kg (13 to 22 lbs). They have a compact body, short legs, and a reddish-brown coat with white spots, which helps them blend into their forested habitat.\n\nTheir diet consists mainly of leaves, fruits, and other vegetation. \n\n'),
(91873, 30219, 'de', 'Northern Pudu', 'The Northern Pudu is the smallest deer species in the world, native to the temperate rainforests of the Andes in northern Chile and southern Argentina. Adult Northern Pudus typically stand about 30 to 40 cm (12 to 16 inches) tall at the shoulder and weigh between 6 to 10 kg (13 to 22 lbs). They have a compact body, short legs, and a reddish-brown coat with white spots, which helps them blend into their forested habitat.\n\nTheir diet consists mainly of leaves, fruits, and other vegetation. \n\n'),
(91874, 30219, 'da', 'Northern Pudu', 'The Northern Pudu is the smallest deer species in the world, native to the temperate rainforests of the Andes in northern Chile and southern Argentina. Adult Northern Pudus typically stand about 30 to 40 cm (12 to 16 inches) tall at the shoulder and weigh between 6 to 10 kg (13 to 22 lbs). They have a compact body, short legs, and a reddish-brown coat with white spots, which helps them blend into their forested habitat.\n\nTheir diet consists mainly of leaves, fruits, and other vegetation. \n\n'),
(91875, 523, 'en', 'Northern Red-Billed Hornbill', 'The red‑billed turaco is a small hornbill with a brightly colored red bill. It is inquisitive and skillfully uses its bill when feeding. In your zoo it hops from branch to branch and calls out with its distinctive calls.'),
(91876, 523, 'de', 'Rotschnabeltoko', 'Der Rotschnabeltoko ist ein kleiner Nashornvogel mit leuchtend rotem Schnabel. Er ist neugierig und nutzt seinen Schnabel geschickt beim Fressen. In deinem Zoo hüpft er von Ast zu Ast und lässt seine markanten Rufe hören.'),
(91877, 523, 'da', 'Dikdik', 'Dikdikken er en af verdens mindste antilopearter og er ikke meget større end en hare. Den er monogam og lever i permanente par, der forsvarer et fast territorium.'),
(91878, 1205, 'en', 'Numbat', 'The numbat is an Australian anteater with a striped back. It is active during the day and highly specialized in finding termites. In your zoo, it’s a rare but especially charming resident.'),
(91879, 1205, 'de', 'Numbat', 'Der Numbat ist ein australischer Ameisenfresser mit gestreiftem Rücken. Er ist tagaktiv und sehr spezialisiert auf Termiten. In deinem Zoo ist er ein seltener, aber besonders charmanter Bewohner.'),
(91880, 1205, 'da', 'Ørkenmår', 'Ørkenpindsvin er et nattaktivt pattedyr dækket af skarpe pigge. Det er en plantespiser og lever i tørre klipperige habitater. Dens pigge er faktisk ændrede hår og falder ikke ud, men hvinker om nødvendigt.'),
(91881, 825, 'en', 'Oarfish', 'The ribbonfish is a very long, ribbon‑like deep‑sea fish. It is rarely seen and has inspired many sea legends. In your zoo it shows just how mysterious the deep sea can be.'),
(91882, 825, 'de', 'Riemenfisch', 'Der Riemenfisch ist ein sehr langer, bandförmiger Tiefseefisch. Er wird selten gesehen und sorgt für viele Meereslegenden. In deinem Zoo zeigt er, wie geheimnisvoll die Tiefsee sein kann.'),
(91883, 825, 'da', 'Havkat', 'Sepiaen er et bløddyr tæt beslægtet med blæksprutter. Den er en mester i camouflage og kan ændre sin hud-farve og mønster på millisekunder. Den bruger en indre skal som opdriftskontrol.'),
(91884, 2109, 'en', 'Occellate River Stingray', 'The peacock-spotted stingray has striking eye spots on its back. It lives in freshwater and glides over the bottom. In your zoo, it looks like a floating patterned carpet.'),
(91885, 2109, 'de', 'Pfauenaugen-Stechrochen', 'Der Pfauenaugen-Stechrochen hat auffällige Augenflecken auf dem Rücken. Er lebt im Süßwasser und gleitet über den Boden. In deinem Zoo wirkt er wie ein schwebender Teppich mit Muster.'),
(91886, 2109, 'da', 'Flodaber', 'Proboscis-aben er en usædvanlig primat fra Borneo med en karakteristisk stor, bulet næse hos hannerne. Den er en dygtig svømmer og lever primært i skovene langs floderne og i mangrover.'),
(91887, 30220, 'en', 'Ocean Sunfish', 'The Ocean Sunfish, also known as the Mola or sunfish, is the heaviest bony fish in the world. It inhabits tropical and temperate oceans globally, from surface waters to depths of 600 meters (2,000 feet). Adults can grow up to 4.2 meters (14 feet) in height and 3.2 meters (10.5 feet) in length. The Ocean Sunfish has a distinctive flattened, disk-like body with a truncated tail fin (clavus) and long dorsal and anal fins that it uses for propulsion.\n\nOcean Sunfish feeds primarily on jellyfish, plankton, small fish, and crustaceans, consuming large quantities due to their low nutritional value. \n\n'),
(91888, 30220, 'de', 'Ocean Sunfish', 'The Ocean Sunfish, also known as the Mola or sunfish, is the heaviest bony fish in the world. It inhabits tropical and temperate oceans globally, from surface waters to depths of 600 meters (2,000 feet). Adults can grow up to 4.2 meters (14 feet) in height and 3.2 meters (10.5 feet) in length. The Ocean Sunfish has a distinctive flattened, disk-like body with a truncated tail fin (clavus) and long dorsal and anal fins that it uses for propulsion.\n\nOcean Sunfish feeds primarily on jellyfish, plankton, small fish, and crustaceans, consuming large quantities due to their low nutritional value. \n\n'),
(91889, 30220, 'da', 'Ocean Sunfish', 'The Ocean Sunfish, also known as the Mola or sunfish, is the heaviest bony fish in the world. It inhabits tropical and temperate oceans globally, from surface waters to depths of 600 meters (2,000 feet). Adults can grow up to 4.2 meters (14 feet) in height and 3.2 meters (10.5 feet) in length. The Ocean Sunfish has a distinctive flattened, disk-like body with a truncated tail fin (clavus) and long dorsal and anal fins that it uses for propulsion.\n\nOcean Sunfish feeds primarily on jellyfish, plankton, small fish, and crustaceans, consuming large quantities due to their low nutritional value. \n\n'),
(91890, 423, 'en', 'Ocelot', 'The ocelot is a medium‑sized wild cat with beautifully spotted fur. It lives in the forests of the Americas and is an agile climber and hunter. In your zoo it moves elegantly through its enclosure and repeatedly displays its distinctly feline grace.'),
(91891, 423, 'de', 'Ozelot', 'Der Ozelot ist eine mittelgroße Wildkatze mit wunderschön geflecktem Fell. Er lebt in den Wäldern Amerikas und ist ein geschickter Kletterer und Jäger. In deinem Zoo streift er elegant durch sein Gehege und zeigt immer wieder seine katzengleiche Anmut.'),
(91892, 423, 'da', 'Ozelot', 'Ozeloten er en mellemstor vildkat med smukt plettet pels. Den lever i skovene i Amerika og er en smidig klatrer og jæger. I din zoo bevæger den sig elegant igennem sit anlæg og viser gentagne gange sin karakteristisk katteagtige ynde.'),
(91893, 326, 'en', 'Okapi', 'The okapi is a close relative of the giraffe, even though it looks more like a mix of horse and zebra. It lives in the dense rainforests of the Congo and is very shy. In your zoo it appreciates quiet retreats and surprises visitors with its striped legs.'),
(91894, 326, 'de', 'Okapi', 'Das Okapi ist ein naher Verwandter der Giraffe, auch wenn es eher wie eine Mischung aus Pferd und Zebra wirkt. Es lebt in den dichten Regenwäldern des Kongo und ist sehr scheu. In deinem Zoo schätzt es ruhige Rückzugsorte und überrascht Besucher mit seinen gestreiften Beinen.'),
(91895, 326, 'da', 'Okapi', 'Okapien er en nær slægtning til giraffen, selv om den mere ligner en blanding af hest og zebra. Den lever i de tætte regnskove i Congo og er meget sky. I din zoo sætter den pris på rolige tilflugtssteder og overrasker besøgende med sine stribede ben.'),
(91896, 537, 'en', 'Onager', 'The Asian wild ass lives in dry steppes and semi‑deserts of Asia. It is adapted to life with little water and intense heat. In your zoo it looks robust and alert, carefully watching its surroundings.'),
(91897, 537, 'de', 'Asiatischer Esel', 'Der Asiatische Esel lebt in trockenen Steppen und Halbwüsten Asiens. Er ist an ein Leben mit wenig Wasser und großer Hitze angepasst. In deinem Zoo wirkt er robust und wachsam, während er die Umgebung aufmerksam beobachtet.'),
(91898, 537, 'da', 'Jordulv', 'Jordsvin ligner en lille hyæne, men er faktisk en insektæder. Den lever primært af termitter og kan spise op til 300.000 termitter om natten. Den er et nattaktivt og fredeligt dyr.'),
(91899, 635, 'en', 'Orangutan', 'The orang‑utan is a highly intelligent great ape that lives in the rainforests of Borneo and Sumatra. Its name means \'forest person\', and it spends almost its entire life in the trees. In your zoo it builds nests for itself and cleverly solves tricky feeding puzzles.'),
(91900, 635, 'de', 'Orang Utan', 'Der Orang-Utan ist ein hochintelligenter Menschenaffe, der in den Regenwäldern Borneos und Sumatras lebt. Sein Name bedeutet „Waldmensch“, und er verbringt fast sein ganzes Leben in den Bäumen. In deinem Zoo bastelt er sich Nester und löst geschickt knifflige Futterrätsel.'),
(91901, 635, 'da', 'Tarantula', 'Tarantulaer er de største edderkopper i verden og er fundet i varme, tropiske og subtropiske regioner verden over. Trods deres skræmmende udseende er de fleste arter ufarlige for mennesker.'),
(91902, 822, 'en', 'Orca', 'The orca, also known as the killer whale, is an intelligent top predator of the oceans. It lives in family groups and hunts in teams. In your zoo it impresses with powerful swimming strokes and clever playfulness.'),
(91903, 822, 'de', 'Orca', 'Der Orca, auch Schwertwal genannt, ist ein intelligenter Spitzenprädator der Ozeane. Er lebt in Familienverbänden und jagt im Team. In deinem Zoo beeindruckt er mit kraftvollen Schwimmbewegungen und kluger Verspieltheit.'),
(91904, 822, 'da', 'Dugong', 'Dugongen er tæt beslægtet med havkoen og er den eneste nulevende repræsentant for familien Dugongidae. Den lever af havgræs og er et fredeligt dyr. Dens forside lemmer minder om arme, hvilket kan have inspireret sirene-legender.'),
(91905, 30221, 'en', 'Ornate Wobbegong', 'The Ornate Wobbegong is a species of carpet shark found in the shallow waters of the western Pacific Ocean. It has a flattened body, a broad head, and a unique pattern of intricate markings that help it blend into its surroundings. The Ornate Wobbegong has a mottled coloration with various shades of brown, yellow, and green. It can grow up to 3 meters (about 10 feet) in length, although most individuals are smaller.\n\nOrnate Wobbegongs are carnivorous, primarily feeding on fish and invertebrates.\n\n'),
(91906, 30221, 'de', 'Ornate Wobbegong', 'The Ornate Wobbegong is a species of carpet shark found in the shallow waters of the western Pacific Ocean. It has a flattened body, a broad head, and a unique pattern of intricate markings that help it blend into its surroundings. The Ornate Wobbegong has a mottled coloration with various shades of brown, yellow, and green. It can grow up to 3 meters (about 10 feet) in length, although most individuals are smaller.\n\nOrnate Wobbegongs are carnivorous, primarily feeding on fish and invertebrates.\n\n'),
(91907, 30221, 'da', 'Ornate Wobbegong', 'The Ornate Wobbegong is a species of carpet shark found in the shallow waters of the western Pacific Ocean. It has a flattened body, a broad head, and a unique pattern of intricate markings that help it blend into its surroundings. The Ornate Wobbegong has a mottled coloration with various shades of brown, yellow, and green. It can grow up to 3 meters (about 10 feet) in length, although most individuals are smaller.\n\nOrnate Wobbegongs are carnivorous, primarily feeding on fish and invertebrates.\n\n'),
(91908, 223, 'en', 'Oryx', 'The oryx antelope, with its long straight horns and pale coat, is perfectly adapted to deserts and semi-deserts. It can go for long periods without water and uses its body energy very efficiently. In your zoo its clean markings make it look especially elegant as it rests in the shade.'),
(91909, 223, 'de', 'Oryxantilope', 'Die Oryxantilope ist mit ihren langen, geraden Hörnern und dem hellen Fell perfekt an Wüsten und Halbwüsten angepasst. Sie kann lange Zeit ohne Wasser auskommen und nutzt ihren Körper sehr sparsam. In deinem Zoo wirkt sie mit ihrer klaren Zeichnung besonders edel und ruht gerne im Schatten.'),
(91910, 223, 'da', 'Oryx', 'Oryxantilopen er med sine lange, rette horn og lyse pels perfekt tilpasset ørkner og halvørkner. Den kan klare sig længe uden vand og udnytter sin krop meget sparsomt. I din zoo virker den særlig fornem og hviler gerne i skyggen.'),
(91911, 30222, 'en', 'Owston\'s Palm Civet', 'The Owston\'s Palm Civet is a medium sized civet, a little larger than a typical house cat.  It is native to southeast Asia. Distantly related to cats, civets have half retractable claws. It has a tawny buff-grey body with highly contrasted black markings on its back and tail. They usually only have 4 bands on their back. The last two-thirds of the tail is completely black. \n\nWhile most civet are omnivorous, Owston\'s Palm Civets are almost entirely plant and fruit eaters.\n\n'),
(91912, 30222, 'de', 'Owston\'s Palm Civet', 'The Owston\'s Palm Civet is a medium sized civet, a little larger than a typical house cat.  It is native to southeast Asia. Distantly related to cats, civets have half retractable claws. It has a tawny buff-grey body with highly contrasted black markings on its back and tail. They usually only have 4 bands on their back. The last two-thirds of the tail is completely black. \n\nWhile most civet are omnivorous, Owston\'s Palm Civets are almost entirely plant and fruit eaters.\n\n'),
(91913, 30222, 'da', 'Owston\'s Palm Civet', 'The Owston\'s Palm Civet is a medium sized civet, a little larger than a typical house cat.  It is native to southeast Asia. Distantly related to cats, civets have half retractable claws. It has a tawny buff-grey body with highly contrasted black markings on its back and tail. They usually only have 4 bands on their back. The last two-thirds of the tail is completely black. \n\nWhile most civet are omnivorous, Owston\'s Palm Civets are almost entirely plant and fruit eaters.\n\n'),
(91914, 636, 'en', 'Pacarana', 'The Pakarana is a rare, large rodent from South America. It moves rather slowly and lives mostly secluded. In your zoo, it shows a calm, peaceful side and is happily watched while cozily nibbling.'),
(91915, 636, 'de', 'Pakarana', 'Das Pakarana ist ein seltenes, großes Nagetier aus Südamerika. Es bewegt sich eher langsam und lebt meist zurückgezogen. In deinem Zoo zeigt es eine ruhige, friedliche Seite und wird gern beim gemütlichen Knabbern beobachtet.'),
(91916, 636, 'da', 'Kæmpe-regnorm', 'Kæmpe-regnorm fra tropiske regioner kan blive op til 3 meter lange. De er afgørende for jordens sundhed, da de blander og lufter jord, og deres udskillelser er rig på næringsstoffer.'),
(91917, 30223, 'en', 'Pacific Sea Eagle', 'The Pacific Sea Eagle, also known as the White-bellied Sea Eagle, is a large bird of prey found primarily in coastal regions of the Indian and Pacific Oceans. They have a distinctive plumage, featuring a white head and belly, dark brown wings and back, and a pale grayish-brown body. They possess a strong, hooked beak and powerful talons, which are essential for catching and holding onto their prey.\n\nThese eagles are skilled hunters, primarily feeding on fish, but they also prey on birds, small mammals, and carrion. \n\n'),
(91918, 30223, 'de', 'Pacific Sea Eagle', 'The Pacific Sea Eagle, also known as the White-bellied Sea Eagle, is a large bird of prey found primarily in coastal regions of the Indian and Pacific Oceans. They have a distinctive plumage, featuring a white head and belly, dark brown wings and back, and a pale grayish-brown body. They possess a strong, hooked beak and powerful talons, which are essential for catching and holding onto their prey.\n\nThese eagles are skilled hunters, primarily feeding on fish, but they also prey on birds, small mammals, and carrion. \n\n'),
(91919, 30223, 'da', 'Pacific Sea Eagle', 'The Pacific Sea Eagle, also known as the White-bellied Sea Eagle, is a large bird of prey found primarily in coastal regions of the Indian and Pacific Oceans. They have a distinctive plumage, featuring a white head and belly, dark brown wings and back, and a pale grayish-brown body. They possess a strong, hooked beak and powerful talons, which are essential for catching and holding onto their prey.\n\nThese eagles are skilled hunters, primarily feeding on fish, but they also prey on birds, small mammals, and carrion. \n\n'),
(91920, 30224, 'en', 'Pacman Frog', 'The Pacman frog, also known as the South American horned frog, is a stout, colorful amphibian native to the grasslands and forests of South America. Renowned for its wide, round mouth that resembles the video game character Pac-Man, it has a robust body up to 15 cm (6 inches) long, vibrant green or brown skin with red markings, and horn-like projections above its eyes.\n\nAs an ambush predator, it buries itself in soil or leaf litter to catch insects, small rodents, and even other frogs with its powerful jaws.\n\n'),
(91921, 30224, 'de', 'Pacman Frog', 'The Pacman frog, also known as the South American horned frog, is a stout, colorful amphibian native to the grasslands and forests of South America. Renowned for its wide, round mouth that resembles the video game character Pac-Man, it has a robust body up to 15 cm (6 inches) long, vibrant green or brown skin with red markings, and horn-like projections above its eyes.\n\nAs an ambush predator, it buries itself in soil or leaf litter to catch insects, small rodents, and even other frogs with its powerful jaws.\n\n'),
(91922, 30224, 'da', 'Pacman Frog', 'The Pacman frog, also known as the South American horned frog, is a stout, colorful amphibian native to the grasslands and forests of South America. Renowned for its wide, round mouth that resembles the video game character Pac-Man, it has a robust body up to 15 cm (6 inches) long, vibrant green or brown skin with red markings, and horn-like projections above its eyes.\n\nAs an ambush predator, it buries itself in soil or leaf litter to catch insects, small rodents, and even other frogs with its powerful jaws.\n\n'),
(91923, 637, 'en', 'Panamanian White-Faced Capuchin', 'The Panama Capuchin Monkey is an intelligent New World monkey with striking black-and-white coloration. It loves using its dexterous hands to climb, grasp, and employ tools. In your zoo, it\'s always on the move, devising creative ways to get food.'),
(91924, 637, 'de', 'Panama-Kapuzineraffe', 'Der Panama-Kapuzineraffe ist ein intelligenter Neu­welt­affe mit kontrastreicher Schwarz-Weiß-Färbung. Er nutzt gerne seine geschickten Hände, um zu klettern, zu greifen und Werkzeuge einzusetzen. In deinem Zoo ist er immer in Bewegung und denkt sich kreative Wege aus, an Futter zu kommen.'),
(91925, 637, 'da', 'Hornbil', 'Hornbilen er en markant fugl med et enormt, buet næb og en iøjnefaldende knold på det. De er kendte for en usædvanlig redeatfærd, hvor hunnen forsegles i en træhule under rugning.'),
(91926, 638, 'en', 'Panther', 'The Panther is a black variant of leopards or jaguars. The typical spots are still recognizable under the dark fur. In your zoo, it appears mysterious, gliding silently through shadows and light.'),
(91927, 638, 'de', 'Panter', 'Der Panter ist eine schwarz gefärbte Variante von Leoparden oder Jaguaren. Unter dem dunklen Fell sind die typischen Flecken noch erkennbar. In deinem Zoo wirkt er geheimnisvoll und gleitet lautlos durch Schatten und Licht.'),
(91928, 638, 'da', 'Pavian', 'Den heilige bavian er en primat med en lang, hundlignende snude. Den er en af de mest udbredte bavianarter og lever i savanner, åbne skove og endda i byer. Den lever i store sociale grupper.'),
(91929, 30225, 'en', 'Parson\'s Chameleon', 'Parson\'s Chameleon is a large species of chameleon and are among the largest chameleons in the world (usually considered the largest by weight, but shorter than the Malagasy giant chameleon which holds the title for the largest by length). Males are overall green or turquoise. Females of both subspecies are smaller than the males and overall greenish, yellowish or brownish (often with an orange tinge). The Parson\'s Chameleon is one of the longest-lived chameleon species with a highest minimum age of 9 years for males and 8 years for females.\n\nParson’s Chameleons have an omnivorous diet and feed on various plants, insects, and some small birds.\n\n'),
(91930, 30225, 'de', 'Parson\'s Chameleon', 'Parson\'s Chameleon is a large species of chameleon and are among the largest chameleons in the world (usually considered the largest by weight, but shorter than the Malagasy giant chameleon which holds the title for the largest by length). Males are overall green or turquoise. Females of both subspecies are smaller than the males and overall greenish, yellowish or brownish (often with an orange tinge). The Parson\'s Chameleon is one of the longest-lived chameleon species with a highest minimum age of 9 years for males and 8 years for females.\n\nParson’s Chameleons have an omnivorous diet and feed on various plants, insects, and some small birds.\n\n'),
(91931, 30225, 'da', 'Parson\'s Chameleon', 'Parson\'s Chameleon is a large species of chameleon and are among the largest chameleons in the world (usually considered the largest by weight, but shorter than the Malagasy giant chameleon which holds the title for the largest by length). Males are overall green or turquoise. Females of both subspecies are smaller than the males and overall greenish, yellowish or brownish (often with an orange tinge). The Parson\'s Chameleon is one of the longest-lived chameleon species with a highest minimum age of 9 years for males and 8 years for females.\n\nParson’s Chameleons have an omnivorous diet and feed on various plants, insects, and some small birds.\n\n'),
(91932, 106, 'en', 'Patagonian Mara', 'The Greater Pampa Hare, also known as Mara, looks like a mix between a rabbit and a small deer. It hails from the grasslands of South America and often moves in pairs across the terrain. In the zoo, it darts curiously around or relaxes in the sun, always ready for the next sprint.'),
(91933, 106, 'de', 'Großer Pampashase', 'Der Große Pampashase, auch Mara genannt, sieht aus wie eine Mischung aus Kaninchen und kleinem Reh. Er stammt aus den Graslandschaften Südamerikas und bewegt sich oft in Paaren durchs Gelände. Im Zoo flitzt er neugierig umher oder ruht entspannt in der Sonne, immer bereit für den nächsten Sprint.'),
(91934, 106, 'da', 'Mara', 'Maraen ser ud som en krydsning mellem en kanin og et lille rådyr og er hjemmehørende i Sydamerikas grassletter. I din zoo farer den nysgerrigt rundt eller slapper af i solen.'),
(91935, 111, 'en', 'Patas Monkey', 'The Patrol Monkey is one of the fastest primates in the world and can reach impressive speeds when fleeing. With its reddish fur and light face, it\'s easy to recognize and always looks a bit serious. In the zoo, it\'s mostly on the move, climbing, running, and curiously watching what its visitors are up to.'),
(91936, 111, 'de', 'Husarenaffe', 'Der Husarenaffe ist einer der schnellsten Primaten der Welt und kann auf der Flucht beeindruckende Geschwindigkeiten erreichen. Mit seinem rötlichen Fell und dem hellen Gesicht ist er leicht zu erkennen und wirkt immer ein wenig ernst. Im Zoo ist er meist in Bewegung, klettert, rennt und beobachtet neugierig, was seine Besucher so treiben.'),
(91937, 111, 'da', 'Pataabe', 'Pataaben er en af de hurtigste primater i verden og kan nå imponerende hastigheder under flugt. I din zoo er den næsten altid i bevægelse, klatrer, løber og observerer nysgerrigt sine besøgende.'),
(91938, 2105, 'en', 'Peacock Eel', 'The peacock spiny eel is a slender fish with distinctive eye spots along its body. It likes to hide in the substrate during the day. In your zoo, careful observers might spot it cautiously peeking out from its hiding place.'),
(91939, 2105, 'de', 'Pfauen-Stachelaal', 'Der Pfauen-Stachelaal ist ein langgestreckter Fisch mit auffälligen Augenflecken. Er versteckt sich tagsüber gerne im Boden. In deinem Zoo können aufmerksame Betrachter ihn beim vorsichtigen Hervorlugen beobachten.'),
(91940, 2105, 'da', 'Flodhingst', 'Flodsøhesten er en sjælden og lille fisk fra Sydøst-Asiens floder og mangrover. Den er truet af habitatødelæggelse og overfiskning til traditionel medicin. Den lever i et nært familieliv.'),
(91941, 224, 'en', 'Peafowl', 'The peacock is world-famous for its magnificent fan, which the male displays to win the favor of the females. Its shimmering plumage shines in blue and green tones and is decorated with eye-like spots. In your zoo it delights visitors when it spreads its tail and proudly parades through the enclosure.'),
(91942, 224, 'de', 'Pfau', 'Der Pfau ist weltberühmt für sein prächtiges Rad, mit dem das Männchen um die Gunst der Weibchen wirbt. Sein schillerndes Gefieder leuchtet in Blau- und Grüntönen und ist mit Augenflecken geschmückt. In deinem Zoo erfreut er die Besucher, wenn er sein Rad schlägt und stolz durch das Gehege schreitet.'),
(91943, 224, 'da', 'Påfugl', 'Påfuglen er verdensberømt for sit pragtfulde hjul, som hannen breder ud for at vinde hunnen. Dens skinnende fjerdragt lyser i blå og grønne toner prydet med øjeformede pletter. I din zoo glæder den besøgende, når den breder sit hjul.'),
(91944, 30226, 'en', 'Pearl-Spotted Owlet', 'The Pearl-Spotted Owlet is a small bird of prey found in sub-Saharan Africa. They are commonly referred to as \'owlets\' due to their diminutive size. The Pearl-Spotted Owlet is one of the smallest owls in Africa (17–21 cm or 0,55-0,68 ft). Both males and females have similar plumage colouration. The upper parts are cinnamon-brown with white spots. The facial disc is off-white and the eyes are yellow. At the back of the head there are two striking false black \'eyes\' with a white outline.\n\nPearl-Spotted Owlets predominantly eat arthropods - especially grasshoppers, crickets, and solifuges - but are capable of hunting small vertebrates such as rodents, bats, lizards, snakes and small birds.\n\n'),
(91945, 30226, 'de', 'Pearl-Spotted Owlet', 'The Pearl-Spotted Owlet is a small bird of prey found in sub-Saharan Africa. They are commonly referred to as \'owlets\' due to their diminutive size. The Pearl-Spotted Owlet is one of the smallest owls in Africa (17–21 cm or 0,55-0,68 ft). Both males and females have similar plumage colouration. The upper parts are cinnamon-brown with white spots. The facial disc is off-white and the eyes are yellow. At the back of the head there are two striking false black \'eyes\' with a white outline.\n\nPearl-Spotted Owlets predominantly eat arthropods - especially grasshoppers, crickets, and solifuges - but are capable of hunting small vertebrates such as rodents, bats, lizards, snakes and small birds.\n\n'),
(91946, 30226, 'da', 'Pearl-Spotted Owlet', 'The Pearl-Spotted Owlet is a small bird of prey found in sub-Saharan Africa. They are commonly referred to as \'owlets\' due to their diminutive size. The Pearl-Spotted Owlet is one of the smallest owls in Africa (17–21 cm or 0,55-0,68 ft). Both males and females have similar plumage colouration. The upper parts are cinnamon-brown with white spots. The facial disc is off-white and the eyes are yellow. At the back of the head there are two striking false black \'eyes\' with a white outline.\n\nPearl-Spotted Owlets predominantly eat arthropods - especially grasshoppers, crickets, and solifuges - but are capable of hunting small vertebrates such as rodents, bats, lizards, snakes and small birds.\n\n'),
(91947, 30227, 'en', 'Pel\'s Fishing Owl', 'Pel\'s Fishing Owl is one of Africa\'s largest owls, known for its exceptional fishing skills and striking appearance. With a wingspan of up to 1.5 meters (5 feet) and weighing 2-3 kg (4.4-6.6 lbs), it has mottled brown and white plumage, piercing yellow eyes, and powerful talons adapted for grasping slippery prey.\n\nPel\'s Fishing Owls are piscivorous (fish-eating), supplemented by frogs, crabs, and small rodents; hunts by perching near water and plunging in.\n\n'),
(91948, 30227, 'de', 'Pel\'s Fishing Owl', 'Pel\'s Fishing Owl is one of Africa\'s largest owls, known for its exceptional fishing skills and striking appearance. With a wingspan of up to 1.5 meters (5 feet) and weighing 2-3 kg (4.4-6.6 lbs), it has mottled brown and white plumage, piercing yellow eyes, and powerful talons adapted for grasping slippery prey.\n\nPel\'s Fishing Owls are piscivorous (fish-eating), supplemented by frogs, crabs, and small rodents; hunts by perching near water and plunging in.\n\n'),
(91949, 30227, 'da', 'Pel\'s Fishing Owl', 'Pel\'s Fishing Owl is one of Africa\'s largest owls, known for its exceptional fishing skills and striking appearance. With a wingspan of up to 1.5 meters (5 feet) and weighing 2-3 kg (4.4-6.6 lbs), it has mottled brown and white plumage, piercing yellow eyes, and powerful talons adapted for grasping slippery prey.\n\nPel\'s Fishing Owls are piscivorous (fish-eating), supplemented by frogs, crabs, and small rodents; hunts by perching near water and plunging in.\n\n'),
(91950, 30228, 'en', 'Perentie', 'The Perentie is Australia\'s largest monitor lizard, reaching up to 2.5 meters in length. It inhabits arid regions, preying on small animals with its speed and intelligence. It can grow up to 2.5 meters (8 feet) in length and weigh up to 20 kg (44 lbs), with a robust body, long tail, and powerful limbs. Its skin is patterned with yellow and brown scales for camouflage in arid environments.\n\nPerentie is a diurnal predator that hunts small mammals, birds, reptiles, and eggs.\n\n'),
(91951, 30228, 'de', 'Perentie', 'The Perentie is Australia\'s largest monitor lizard, reaching up to 2.5 meters in length. It inhabits arid regions, preying on small animals with its speed and intelligence. It can grow up to 2.5 meters (8 feet) in length and weigh up to 20 kg (44 lbs), with a robust body, long tail, and powerful limbs. Its skin is patterned with yellow and brown scales for camouflage in arid environments.\n\nPerentie is a diurnal predator that hunts small mammals, birds, reptiles, and eggs.\n\n'),
(91952, 30228, 'da', 'Perentie', 'The Perentie is Australia\'s largest monitor lizard, reaching up to 2.5 meters in length. It inhabits arid regions, preying on small animals with its speed and intelligence. It can grow up to 2.5 meters (8 feet) in length and weigh up to 20 kg (44 lbs), with a robust body, long tail, and powerful limbs. Its skin is patterned with yellow and brown scales for camouflage in arid environments.\n\nPerentie is a diurnal predator that hunts small mammals, birds, reptiles, and eggs.\n\n'),
(91953, 30229, 'en', 'Pesquet\'s Parrot', 'Pesquet\'s Parrot  is a unique-looking parrot that can be found only in New Guinea. It is the only member of its genus. The Pesquet\'s Parrot is also known as the Vulture Parrot due to its vulture-like appearance. Pesquet\'s Parrot is a large parrot with a total length of approximately 46 cm (18 in) and a weight of 680–800 g (24–28 oz). Its plumage is black, with greyish scaling to the chest, and a red belly, uppertail coverts and wing-panels.\n\nPesquet\'s Parrot is a highly specialised frugivore, feeding almost exclusively on a few species of figs. Flowers and nectar have also been reported. The bare part of the head is presumably an adaptation to avoid feather-matting from sticky fruits.\n\n'),
(91954, 30229, 'de', 'Pesquet\'s Parrot', 'Pesquet\'s Parrot  is a unique-looking parrot that can be found only in New Guinea. It is the only member of its genus. The Pesquet\'s Parrot is also known as the Vulture Parrot due to its vulture-like appearance. Pesquet\'s Parrot is a large parrot with a total length of approximately 46 cm (18 in) and a weight of 680–800 g (24–28 oz). Its plumage is black, with greyish scaling to the chest, and a red belly, uppertail coverts and wing-panels.\n\nPesquet\'s Parrot is a highly specialised frugivore, feeding almost exclusively on a few species of figs. Flowers and nectar have also been reported. The bare part of the head is presumably an adaptation to avoid feather-matting from sticky fruits.\n\n'),
(91955, 30229, 'da', 'Pesquet\'s Parrot', 'Pesquet\'s Parrot  is a unique-looking parrot that can be found only in New Guinea. It is the only member of its genus. The Pesquet\'s Parrot is also known as the Vulture Parrot due to its vulture-like appearance. Pesquet\'s Parrot is a large parrot with a total length of approximately 46 cm (18 in) and a weight of 680–800 g (24–28 oz). Its plumage is black, with greyish scaling to the chest, and a red belly, uppertail coverts and wing-panels.\n\nPesquet\'s Parrot is a highly specialised frugivore, feeding almost exclusively on a few species of figs. Flowers and nectar have also been reported. The bare part of the head is presumably an adaptation to avoid feather-matting from sticky fruits.\n\n'),
(91956, 1201, 'en', 'Pink Fairy Armadillo', 'The Pink Fairy Armadillo is a tiny armadillo with a delicate shell. It lives underground in South America. In your zoo, it’s a mysterious digger that rarely comes to the surface.'),
(91957, 1201, 'de', 'Kleiner Gürtelmull', 'Der Kleine Gürtelmull ist ein winziges Gürteltier mit zartem Panzer. Er lebt unterirdisch in Südamerika. In deinem Zoo ist er ein geheimnisvoller Buddler, der selten an die Oberfläche kommt.'),
(91958, 1201, 'da', 'Klippeørn', 'Kongeørnen er et af verdens mest imponerende rovfugle med et vingefang på op til 2,4 meter. Den er berømt for sin kraft og præcision og lever i bjerg- og åbent landskab i den nordlige halvkugle.'),
(91959, 1104, 'en', 'Pink-Winged Stick Insect', 'The Winged Stick Insect camouflages perfectly as a twig or leaf. Only when flying do you notice its wings. In your zoo, it\'s a master of camouflage in the insectarium.'),
(91960, 1104, 'de', 'Geflügelte Stabschrecke', 'Die Geflügelte Stabschrecke tarnt sich perfekt als Zweig oder Blatt. Erst beim Fliegen erkennt man ihre Flügel. In deinem Zoo ist sie ein Meister der Tarnung im Insektarium.'),
(91961, 1104, 'da', 'Kameleon-gekko', 'Jungle-kamæleonen er en ekspert i at skifte farve til kommunikation og temperaturregulering. Den bevæger sig langsomt og beregnet, med øjne der roterer uafhængigt, og en lang, klistret tunge til at fange insekter.'),
(91962, 237, 'en', 'Plains Zebra', 'The plains zebra lives in the open savannas of Africa and is unmistakable thanks to its striped pattern. Every zebra’s stripes are unique, like a fingerprint. In your zoo they trot through the enclosure in family groups and create a lively black-and-white spectacle.'),
(91963, 237, 'de', 'Steppenzebra', 'Das Steppenzebra bewohnt die offenen Savannen Afrikas und ist durch sein Streifenmuster unverwechselbar. Jede Zebrazeichnung ist einzigartig, wie ein Fingerabdruck. In deinem Zoo traben sie im Familienverband durchs Gehege und bieten ein lebendiges Schwarz-Weiß-Schauspiel.'),
(91964, 237, 'da', 'Steppezebra', 'Steppezebra en bor i Afrikas åbne savannen og er umiskendeligt takket være sit stribede mønster. Hvert zebras striber er unikke, ligesom et fingeraftryk. I din zoo traver de i familiegrupper igennem indhegningen og byder på et levende sort-hvid-skue.'),
(91965, 833, 'en', 'Platypus', 'The platypus is a unique egg-laying mammal. It has a duck’s bill, a beaver’s tail, and webbed feet. In your zoo, it’s a true exotic and a favorite curiosity among visitors.'),
(91966, 833, 'de', 'Schnabeltier', 'Das Schnabeltier ist ein einzigartiger Eierleger unter den Säugetieren. Es besitzt Entenschnabel, Biberschwanz und Schwimmhäute. In deinem Zoo ist es ein echter Exot und Lieblingsrätsel vieler Besucher.'),
(91967, 833, 'da', 'Søanemone', 'Søanemoner ligner blomster, men er faktisk rovdyr. De bruger deres gifttige tentakler til at paralysere og fange fisk og krebsdyr. Klovnefisk lever i symbiose med søanemoner og er immune over for deres gift.'),
(91968, 125, 'en', 'Poitou Donkey', 'The Poitou Donkey is easily recognized by its long, shaggy fur and big ears. It comes from France and is one of the oldest and rarest donkey breeds in the world. In the zoo, it delights with its cozy nature and somewhat tousled charm.'),
(91969, 125, 'de', 'Poitou-Esel', 'Der Poitou-Esel ist an seinem langen, zotteligen Fell und den großen Ohren leicht zu erkennen. Er stammt aus Frankreich und gehört zu den ältesten und seltensten Eselrassen der Welt. Im Zoo begeistert er mit seinem gemütlichen Wesen und seinem etwas strubbeligen Charme.'),
(91970, 125, 'da', 'Poitou-æsel', 'Poitou-æslet kendes på sit lange, pjuskede pels og store ører. Det stammer fra Frankrig og er en af verdens ældste og sjældneste æselracer. I din zoo begejstrer det med sit hyggelige væsen og snavsede charme.'),
(91971, 703, 'en', 'Polar Bear', 'The polar bear is the largest land predator of the Arctic and an excellent swimmer. His white fur camouflages him in the snow, hiding dark skin underneath. In your zoo, he enjoys cold pools, ice blocks, and plenty of long rest breaks.'),
(91972, 703, 'de', 'Eisbär', 'Der Eisbär ist der größte Landraubt der Arktis und ein ausgezeichneter Schwimmer. Sein weißes Fell tarnt ihn im Schnee, darunter verbirgt sich dunkle Haut. In deinem Zoo genießt er Kältebecken, Eisblöcke und ausgiebige Ruhepausen.');
INSERT INTO `animaltext` (`id`, `animalId`, `languageCode`, `animalName`, `animalDescription`) VALUES
(91973, 703, 'da', 'Sæl', 'Sæler er exceptionelt tilpasset til livet i kolde have. Under vand er de hurtige og graciøse svømmere, men på land er de klodsede. De er vigtige byttedyr for isbjørne og orcaer.'),
(91974, 30230, 'en', 'Pot-Bellied Pig', 'The Pot-Bellied Pig is a small breed of domestic pig known for its distinctive round belly and short legs. These pigs typically weigh between 45 to 90 kilograms (100 to 200 pounds) and can live for 12 to 20 years. They have a friendly and social temperament, making them popular as pets. Pot-Bellied Pigs come in various colors, including black, white, and spotted.\n\nPot-Bellied Pigs require a balanced diet that primarily consists of high-quality pig pellets, fresh vegetables, and occasional fruits.\n\n'),
(91975, 30230, 'de', 'Pot-Bellied Pig', 'The Pot-Bellied Pig is a small breed of domestic pig known for its distinctive round belly and short legs. These pigs typically weigh between 45 to 90 kilograms (100 to 200 pounds) and can live for 12 to 20 years. They have a friendly and social temperament, making them popular as pets. Pot-Bellied Pigs come in various colors, including black, white, and spotted.\n\nPot-Bellied Pigs require a balanced diet that primarily consists of high-quality pig pellets, fresh vegetables, and occasional fruits.\n\n'),
(91976, 30230, 'da', 'Pot-Bellied Pig', 'The Pot-Bellied Pig is a small breed of domestic pig known for its distinctive round belly and short legs. These pigs typically weigh between 45 to 90 kilograms (100 to 200 pounds) and can live for 12 to 20 years. They have a friendly and social temperament, making them popular as pets. Pot-Bellied Pigs come in various colors, including black, white, and spotted.\n\nPot-Bellied Pigs require a balanced diet that primarily consists of high-quality pig pellets, fresh vegetables, and occasional fruits.\n\n'),
(91977, 630, 'en', 'Proboscis Monkey', 'The proboscis monkey is famous for its big, long nose. It lives in the mangrove forests of Southeast Asia and spends much of its time in the trees. In your zoo its distinctive profile regularly brings smiles and amazed faces.'),
(91978, 630, 'de', 'Nasenaffe', 'Der Nasenaffe ist für seine große, hängende Nase berühmt. Er lebt in Mangrovenwäldern Südostasiens und verbringt viel Zeit in den Bäumen. In deinem Zoo sorgt sein markantes Profil regelmäßig für Schmunzeln und staunende Gesichter.'),
(91979, 630, 'da', 'Bærby', 'Aye-ayen er en usædvanlig primat fra Madagaskar med en lang, tynd mellemfinger, der bruges til at hakke insekter ud af træ. Den er nattaktiv og er set som et dårligt varsel i lokal folklore.'),
(91980, 212, 'en', 'Pronghorn', 'The pronghorn is a typical resident of the North American prairies and can reach incredible speeds. Its horns branch like a fork, which is how it got its name. In your zoo, it runs gracefully across the enclosure, full of energy and elegance.'),
(91981, 212, 'de', 'Gabelbock', 'Der Gabelbock ist ein typischer Bewohner der nordamerikanischen Prärien und kann enorme Geschwindigkeiten erreichen. Seine Hörner verzweigen sich wie eine Gabel, was ihm seinen Namen eingebracht hat. In deinem Zoo läuft er mit Leichtigkeit über die Anlage und zeigt, wie viel Energie in ihm steckt.'),
(91982, 212, 'da', 'Gaffelantilope', 'Gaffelantilopen er en typisk beboer af de nordamerikanske prærier og kan nå enorme hastigheder. Dens horn forgrener sig som en gaffel, hvilket har givet den sit navn. I din zoo løber den med lethed over anlægget.'),
(91983, 30231, 'en', 'Przewalski\'s Horse', 'Przewalski\'s Horse is a rare and endangered wild horse native to the steppes of Central Asia. Recognized for its stocky build, short legs, and distinctive dorsal stripe, it is the only true wild horse species that has never been domesticated. Przewalski\'s Horse has a unique coat that varies from sandy to dark brown, with a lighter mane and underbelly.\n\nPrzewalski\'s Horse is known for its hardiness and adaptability to harsh environments, primarily grazing on grasses and shrubs in its natural habitat.\n\n'),
(91984, 30231, 'de', 'Przewalski\'s Horse', 'Przewalski\'s Horse is a rare and endangered wild horse native to the steppes of Central Asia. Recognized for its stocky build, short legs, and distinctive dorsal stripe, it is the only true wild horse species that has never been domesticated. Przewalski\'s Horse has a unique coat that varies from sandy to dark brown, with a lighter mane and underbelly.\n\nPrzewalski\'s Horse is known for its hardiness and adaptability to harsh environments, primarily grazing on grasses and shrubs in its natural habitat.\n\n'),
(91985, 30231, 'da', 'Przewalski\'s Horse', 'Przewalski\'s Horse is a rare and endangered wild horse native to the steppes of Central Asia. Recognized for its stocky build, short legs, and distinctive dorsal stripe, it is the only true wild horse species that has never been domesticated. Przewalski\'s Horse has a unique coat that varies from sandy to dark brown, with a lighter mane and underbelly.\n\nPrzewalski\'s Horse is known for its hardiness and adaptability to harsh environments, primarily grazing on grasses and shrubs in its natural habitat.\n\n'),
(91986, 823, 'en', 'Puffin', 'The puffin is a small seabird with a colorful beak. It breeds in burrows on steep coasts. In your zoo it looks with its bright beak almost like a cartoon bird.'),
(91987, 823, 'de', 'Papageintaucher', 'Der Papageitaucher ist ein kleiner Meeresvogel mit buntem Schnabel. Er brütet in Erdhöhlen an steilen Küsten. In deinem Zoo wirkt er mit seinem farbigen Schnabel fast wie ein Comic‑Vogel.'),
(91988, 823, 'da', 'Rokke', 'Rokker er brusk-fisk nært beslægtede med hajer. De er tilpasset til et liv på havbunden og er flade for at skjule sig i sand. De fleste arter har giftige sporer i halen som forsvar.'),
(91989, 654, 'en', 'Pygmy Hippopotamus', 'The pygmy hippopotamus is the smaller, shyer relative of the common hippo. It lives in the forests of West Africa and spends much of its time in the water. In your zoo, it’s a quiet yet utterly charming aquatic resident.'),
(91990, 654, 'de', 'Zwergflusspferd', 'Das Zwergflusspferd ist die kleinere, scheuere Verwandte des Flusspferds. Es lebt in den Wäldern Westafrikas und verbringt viel Zeit im Wasser. In deinem Zoo ist es ein eher ruhiger, aber sehr charmanter Wasserbewohner.'),
(91991, 654, 'da', 'Kæmpe-glubsk', 'Galápagos-kæmpe-skildpadden er en af verdens ældste og største reptiler og kan leve over 150 år. Den er ikonisk for Darwins observationer og er et af verdens mest kendte beskyttelses-succeser.'),
(91992, 225, 'en', 'Quokka', 'The quokka is a small kangaroo from Australia that became famous for its seemingly smiling face. It is curious, usually friendly and almost legendary for its selfie poses. In your zoo it hops around happily and melts hearts everywhere with its charm.'),
(91993, 225, 'de', 'Quokka', 'Das Quokka ist ein kleines Känguru aus Australien, das durch sein scheinbar lächelndes Gesicht berühmt wurde. Es ist neugierig, meist freundlich und für Selfies fast schon berüchtigt. In deinem Zoo hüpft es fröhlich umher und bringt mit seinem Charme alle Herzen zum Schmelzen.'),
(91994, 225, 'da', 'Quokka', 'Quokkaen er en lille kænguruart fra Australien, der er blevet berømt for sit tilsyneladende smilende ansigt. Den er nysgerrig, normalt venlig og nærmest legendarisk for selfies. I din zoo hopper den glad rundt og smelter alles hjerter.'),
(91995, 30232, 'en', 'Quoll', 'Quolls are carnivorous marsupials native to Australia and New Guinea. They are primarily nocturnal and spend most of the day in a den. Of the six species of quoll, four are found in Australia and two in New Guinea. The six species vary in weight and size, from 300 g (11 oz) to 7 kg (15 lb). They have brown or black fur and pink noses. They are largely solitary, but come together for a few social interactions such as mating which occurs during the winter season. A female gives birth to up to 30 pups.\n\nQuolls eat smaller mammals, small birds, lizards, and insects. \n\n'),
(91996, 30232, 'de', 'Quoll', 'Quolls are carnivorous marsupials native to Australia and New Guinea. They are primarily nocturnal and spend most of the day in a den. Of the six species of quoll, four are found in Australia and two in New Guinea. The six species vary in weight and size, from 300 g (11 oz) to 7 kg (15 lb). They have brown or black fur and pink noses. They are largely solitary, but come together for a few social interactions such as mating which occurs during the winter season. A female gives birth to up to 30 pups.\n\nQuolls eat smaller mammals, small birds, lizards, and insects. \n\n'),
(91997, 30232, 'da', 'Quoll', 'Quolls are carnivorous marsupials native to Australia and New Guinea. They are primarily nocturnal and spend most of the day in a den. Of the six species of quoll, four are found in Australia and two in New Guinea. The six species vary in weight and size, from 300 g (11 oz) to 7 kg (15 lb). They have brown or black fur and pink noses. They are largely solitary, but come together for a few social interactions such as mating which occurs during the winter season. A female gives birth to up to 30 pups.\n\nQuolls eat smaller mammals, small birds, lizards, and insects. \n\n'),
(91998, 108, 'en', 'Rabbit', 'The hare is a fast escape specialist with long hind legs and large floppy ears. It lives in open landscapes and relies on its speed and vigilance to evade dangers. In the zoo, it hops swiftly through the enclosure, grooms itself thoroughly, and elicits many \'Oh, how cute!\' moments from children.'),
(91999, 108, 'de', 'Hase', 'Der Hase ist ein schneller Fluchtspezialist mit langen Hinterbeinen und großen Lauscherohren. Er lebt in offenen Landschaften und verlässt sich auf seine Schnelligkeit und Wachsamkeit, um Gefahren zu entkommen. Im Zoo hoppelt er flink durchs Gehege, putzt sich ausgiebig und sorgt bei Kindern für viele „Oh wie süß!“-Momente.'),
(92000, 108, 'da', 'Hare', 'Haren er en hurtig flygtningsspecialist med lange bagben og store ører. I din zoo hopper den rask rundt i indhegningen og fremkalder mange søde øjeblikke hos børnene.'),
(92001, 138, 'en', 'Raccoon', 'The raccoon is a clever little bandit that stands out immediately with its \'mask\' on its face. In nature, it rummages through rivers, trash cans, and anything that looks like food. In the zoo, it skillfully climbs trees and food toys, impressing visitors with its dexterity.'),
(92002, 138, 'de', 'Waschbär', 'Der Waschbär ist ein cleverer Kleinräuber, der durch seine „Maske“ im Gesicht sofort auffällt. In der Natur durchsucht er Flüsse, Mülltonnen und alles, was nach Futter aussieht. Im Zoo entert er geschickt Kletterbäume und Futterspielzeuge und beeindruckt die Besucher mit seiner Geschicklichkeit.'),
(92003, 138, 'da', 'Vaskebjørn', 'Vaskebjørnen er en klog lille røver, der straks falder i øjnene med sin \"maske\" i ansigtet. I sin natur søger den i floder, skraldespande og alt, der ligner mad. I din zoo klatrer den dygtigt op i klatretræer og imponerer besøgende med sin fingerfærdighed.'),
(92004, 2107, 'en', 'Ram Cichlid', 'The South American butterfly cichlid is a small, colorful fish species. It displays fascinating parental care behavior. In your zoo, it adds a lively splash of color to the smaller aquarium areas.'),
(92005, 2107, 'de', 'Südamerik. Schmetterlingsbuntbarsch', 'Der südamerikanische Schmetterlingsbuntbarsch ist ein kleiner, farbenfroher Cichlide. Er zeigt interessantes Brutpflegeverhalten. In deinem Zoo bringt er Farbe in kleinere Aquarienbereiche.'),
(92006, 2107, 'da', 'Vandsalamander', 'Salamandren er et fascinerende padde med evnen til at genskabe tabte lemmer og endda dele af hjertet. Den lever et dobbeltliv — vandmiljø om foråret til yngel, land resten af året.'),
(92007, 30233, 'en', 'Red Cardinal', 'The Northern Cardinal, commonly known as the red cardinal, is a vibrant North American bird with striking crimson plumage, a black face mask, and a prominent crest. Males are bright red overall, while females are duller brownish with red tinges. Known for its clear, whistled songs, it frequents backyards, woodlands, and gardens.\n\nThe Northern Cardinal\'s diet primarily consists of seeds, berries, and insects including beetles, caterpillars, grasshoppers, and spiders.\n\n'),
(92008, 30233, 'de', 'Red Cardinal', 'The Northern Cardinal, commonly known as the red cardinal, is a vibrant North American bird with striking crimson plumage, a black face mask, and a prominent crest. Males are bright red overall, while females are duller brownish with red tinges. Known for its clear, whistled songs, it frequents backyards, woodlands, and gardens.\n\nThe Northern Cardinal\'s diet primarily consists of seeds, berries, and insects including beetles, caterpillars, grasshoppers, and spiders.\n\n'),
(92009, 30233, 'da', 'Red Cardinal', 'The Northern Cardinal, commonly known as the red cardinal, is a vibrant North American bird with striking crimson plumage, a black face mask, and a prominent crest. Males are bright red overall, while females are duller brownish with red tinges. Known for its clear, whistled songs, it frequents backyards, woodlands, and gardens.\n\nThe Northern Cardinal\'s diet primarily consists of seeds, berries, and insects including beetles, caterpillars, grasshoppers, and spiders.\n\n'),
(92010, 30234, 'en', 'Red Deer', 'The Red Deer is one of the largest species of deer, native to Europe, parts of Asia, and North Africa. Red Deer have a reddish-brown coat that becomes darker in winter, with males sporting impressive antlers that can grow up to 1 meter (3.3 feet) long, which they shed and regrow annually. Males, known as stags, typically weigh between 160 to 240 kg (350 to 530 lbs) and can stand up to 1.2 meters (4 feet) at the shoulder, while females, or hinds, are smaller, weighing around 100 to 120 kg (220 to 265 lbs).\n\nRed Deer are herbivores, primarily grazing on grasses, leaves, and shrubs.\n\n'),
(92011, 30234, 'de', 'Red Deer', 'The Red Deer is one of the largest species of deer, native to Europe, parts of Asia, and North Africa. Red Deer have a reddish-brown coat that becomes darker in winter, with males sporting impressive antlers that can grow up to 1 meter (3.3 feet) long, which they shed and regrow annually. Males, known as stags, typically weigh between 160 to 240 kg (350 to 530 lbs) and can stand up to 1.2 meters (4 feet) at the shoulder, while females, or hinds, are smaller, weighing around 100 to 120 kg (220 to 265 lbs).\n\nRed Deer are herbivores, primarily grazing on grasses, leaves, and shrubs.\n\n'),
(92012, 30234, 'da', 'Red Deer', 'The Red Deer is one of the largest species of deer, native to Europe, parts of Asia, and North Africa. Red Deer have a reddish-brown coat that becomes darker in winter, with males sporting impressive antlers that can grow up to 1 meter (3.3 feet) long, which they shed and regrow annually. Males, known as stags, typically weigh between 160 to 240 kg (350 to 530 lbs) and can stand up to 1.2 meters (4 feet) at the shoulder, while females, or hinds, are smaller, weighing around 100 to 120 kg (220 to 265 lbs).\n\nRed Deer are herbivores, primarily grazing on grasses, leaves, and shrubs.\n\n'),
(92013, 331, 'en', 'Red Fox', 'The red fox is an adaptable predator that lives in forests, fields and even cities. Its reddish fur and bushy tail make it easy to recognize. In your zoo it shows its clever, curious side and keeps a close eye on everything that happens.'),
(92014, 331, 'de', 'Rotfuchs', 'Der Rotfuchs ist ein anpassungsfähiges Raubtier, das in Wäldern, Feldern und sogar Städten lebt. Mit seinem roten Fell und der buschigen Rute ist er leicht zu erkennen. In deinem Zoo zeigt er seine schlaue, neugierige Seite und beobachtet das Geschehen ganz genau.'),
(92015, 331, 'da', 'Rødræv', 'Rødræven er et tilpasningsdygtigt rovdyr, der lever i skove, marker og endda byer. Dens røde pels og buskede hale gør den let genkendelig. I din zoo viser den sin kløgtige, nysgerrige side og holder nøje øje med alt, hvad der sker.'),
(92016, 829, 'en', 'Red Giant Octopus', 'The giant Pacific octopus is a large cephalopod with eight arms. It’s intelligent and curious. In your zoo, it enjoys solving feeding puzzles and shows just how dexterous tentacles can be.'),
(92017, 829, 'de', 'Rote Riesenkrake', 'Die Rote Riesenkrake ist ein großes Kopffüßer mit acht Armen. Sie ist intelligent und neugierig. In deinem Zoo nutzt sie gerne Futterrätsel und zeigt, wie geschickt Tentakel sein können.'),
(92018, 829, 'da', 'Søpindsvin', 'Søpindsvinet er et fascinerende dyr med et rundt, pigbeklædt ydre skelet. Det er et nyttigt havøkosystem-dyr, der lever af alger og organisk materiale. Dets \"tænder\" er et komplekst system kaldet Aristoteles lanterne.'),
(92019, 229, 'en', 'Red Kangaroo', 'The red kangaroo is the largest of all kangaroos and a true symbol of Australia’s wildlife. It moves with powerful hops and uses its tail for balance. In the zoo it likes to rest in the shade before bounding across its enclosure again in long, effortless jumps.'),
(92020, 229, 'de', 'Rotes Riesenkänguru', 'Das Rotes Riesenkänguru ist das größte aller Kängurus und ein Symbol für Australiens Tierwelt. Es bewegt sich mit kräftigen Sprüngen fort und nutzt seinen Schwanz als Balancehilfe. Im Zoo ruht es gerne im Schatten, um dann wieder in weiten Sprüngen durchs Gehege zu hüpfen.'),
(92021, 229, 'da', 'Rødt kæmpekanguru', 'Det røde kæmpekanguru er det største af alle kænguruerne og et symbol på Australiens dyreliv. Det bevæger sig med kraftige spring og bruger sin hale som balanceredskab. I din zoo hviler det gerne i skyggen og hopper så igen i vide spring.'),
(92022, 329, 'en', 'Red Panda', 'The red panda is a small, tree‑loving bamboo fan with a fluffy tail. It lives in the mountain forests of Asia and spends most of its time in the trees. In your zoo it skilfully climbs along branches and sleeps curled up like a cuddly ball of fur.'),
(92023, 329, 'de', 'Roter Panda', 'Der Rote Panda ist ein kleiner, kletterfreudiger Bambusliebhaber mit flauschigem Schwanz. Er lebt in den Bergwäldern Asiens und ist vor allem in Bäumen unterwegs. In deinem Zoo turnt er geschickt auf Ästen herum und schläft eingerollt wie ein kuscheliges Fellknäuel.'),
(92024, 329, 'da', 'Rød panda', 'Den røde panda er en lille, trækladrende bambusentusiast med en busket hale. Den lever i bjergskove i Asien og er mest til finde i træerne. I din zoo tripper den dygtigt langs grenene og sover sammenrullet som et hyggeligt fnugkugle.'),
(92025, 327, 'en', 'Red River Hog', 'The red river hog is a colorful wild pig from Africa with striking facial markings. It gets its name from the long tufts of hair on its ears. In your zoo it loves wallowing in the mud and uses its snout to rummage through every corner.'),
(92026, 327, 'de', 'Pinselohrschwein', 'Das Pinselohrschwein ist ein farbenfrohes Wildschwein aus Afrika mit auffälligen Gesichtszeichnungen. Seinen Namen verdankt es den langen Haarpinseln an den Ohren. In deinem Zoo suhlt es sich begeistert im Schlamm und durchstöbert mit der Schnauze jeden Winkel.'),
(92027, 327, 'da', 'Penselørsvinsvin', 'Det rødbrune flodsvin er et farverigt vildsvin fra Afrika med iøjnefaldende ansigtstegninger. Det har sit navn fra de lange hårduskke på ørerne. I din zoo suhler det begejstret i mudderet og stikker sin snude ind i enhver krog.'),
(92028, 30235, 'en', 'Red Ruffed Lemur', 'The Red Ruffed Lemur (also known as Red Vari) is one of two species in the genus Varecia, the ruffed lemurs; the other is the Black-and-White Ruffed Lemur. Like all lemurs, it is native to Madagascar. They are unique, medium-sized lemurs with a primate-like appearance. They exhibit thick, soft, reddish coat with a long, black and heavily furred tail. They have black faces and long snouts.\n\nThe Black-and-White Ruffed Lemur is classified as critically endangered. It is one of the largest lemurs and the second loudest primate after the  from central and South America.\n\nThese Lemurs are herbivores (frugivore, nectarivores). As much as 75% of their diet is made up of fruits. They also consume pollen, nectar, seeds, leaves and flowers.\n\n'),
(92029, 30235, 'de', 'Red Ruffed Lemur', 'The Red Ruffed Lemur (also known as Red Vari) is one of two species in the genus Varecia, the ruffed lemurs; the other is the Black-and-White Ruffed Lemur. Like all lemurs, it is native to Madagascar. They are unique, medium-sized lemurs with a primate-like appearance. They exhibit thick, soft, reddish coat with a long, black and heavily furred tail. They have black faces and long snouts.\n\nThe Black-and-White Ruffed Lemur is classified as critically endangered. It is one of the largest lemurs and the second loudest primate after the  from central and South America.\n\nThese Lemurs are herbivores (frugivore, nectarivores). As much as 75% of their diet is made up of fruits. They also consume pollen, nectar, seeds, leaves and flowers.\n\n'),
(92030, 30235, 'da', 'Red Ruffed Lemur', 'The Red Ruffed Lemur (also known as Red Vari) is one of two species in the genus Varecia, the ruffed lemurs; the other is the Black-and-White Ruffed Lemur. Like all lemurs, it is native to Madagascar. They are unique, medium-sized lemurs with a primate-like appearance. They exhibit thick, soft, reddish coat with a long, black and heavily furred tail. They have black faces and long snouts.\n\nThe Black-and-White Ruffed Lemur is classified as critically endangered. It is one of the largest lemurs and the second loudest primate after the  from central and South America.\n\nThese Lemurs are herbivores (frugivore, nectarivores). As much as 75% of their diet is made up of fruits. They also consume pollen, nectar, seeds, leaves and flowers.\n\n'),
(92031, 30236, 'en', 'Red Swamp Crayfish', 'The Red Swamp Crayfish is a freshwater crustacean native to the southeastern United States and northeastern Mexico. They have bright red to reddish-brown body with dark spots or stripes, long antennae, stalked eyes, and a segmented body with a fan-shaped tail for swimming. Their claws are large and powerful.\n\nRed Swamp Crayfish eats plants, insects, small fish, and detritus; can be aggressive and territorial.\n\n'),
(92032, 30236, 'de', 'Red Swamp Crayfish', 'The Red Swamp Crayfish is a freshwater crustacean native to the southeastern United States and northeastern Mexico. They have bright red to reddish-brown body with dark spots or stripes, long antennae, stalked eyes, and a segmented body with a fan-shaped tail for swimming. Their claws are large and powerful.\n\nRed Swamp Crayfish eats plants, insects, small fish, and detritus; can be aggressive and territorial.\n\n'),
(92033, 30236, 'da', 'Red Swamp Crayfish', 'The Red Swamp Crayfish is a freshwater crustacean native to the southeastern United States and northeastern Mexico. They have bright red to reddish-brown body with dark spots or stripes, long antennae, stalked eyes, and a segmented body with a fan-shaped tail for swimming. Their claws are large and powerful.\n\nRed Swamp Crayfish eats plants, insects, small fish, and detritus; can be aggressive and territorial.\n\n'),
(92034, 2106, 'en', 'Red-Bellied Piranha', 'The red piranha is a South American schooling fish with sharp teeth. Its reputation is fiercer than its real nature. In your zoo, it swims in synchronized groups, showing how impressive coordinated fish can look.'),
(92035, 2106, 'de', 'Roter Piranha', 'Der Rote Piranha ist ein südamerikanischer Schwarmfisch mit scharfen Zähnen. Sein Ruf ist wilder als sein tatsächliches Verhalten. In deinem Zoo schwimmt er im Schwarm und zeigt, wie beeindruckend koordinierte Fische wirken können.'),
(92036, 2106, 'da', 'Flodmåge', 'Lattermågen er en af Europas hyppigste og mest kendte mågearter. Den er kendetegnet ved sin sorte hætte om sommeren og er oftest set ved søer, floder, fiskehavne og marker. Den er opportunistisk.'),
(92037, 118, 'en', 'Red-Crowned Crane', 'The Red-crowned Crane is a majestic bird with white-black plumage and a red patch on its head. In many Asian cultures, it symbolizes luck and a long life. In your zoo, it shows its graceful dances and impresses visitors with its wide wing beats.'),
(92038, 118, 'de', 'Mandschurenkranich', 'Der Mandschurenkranich ist ein majestätischer Vogel mit weiß-schwarzem Gefieder und einem roten Fleck auf dem Kopf. In vielen asiatischen Kulturen gilt er als Symbol für Glück und ein langes Leben. In deinem Zoo zeigt er seine anmutigen Tänze und beeindruckt Besucher mit seinen weiten Flügelschlägen.'),
(92039, 118, 'da', 'Rødkronet trane', 'Den rødkronede trane er en majestætisk fugl med hvid-sort fjerdragt og en rød plet på hovedet. I mange asiatiske kulturer er den et symbol på lykke og langt liv. I din zoo viser den sine yndefulde danse.'),
(92040, 1115, 'en', 'Red-Eyed Tree Frog', 'The Red-Eyed Tree Frog is a tropical star with its bright red eyes and vibrant green body. By day it rests quietly on leaves, coming to life at night. In your zoo, it looks like a small piece of living art.'),
(92041, 1115, 'de', 'Rotaugenlaubfrosch', 'Der Rotaugenlaubfrosch ist mit seinen knallroten Augen und grünen Körper ein Tropenstar. Er sitzt tagsüber ruhig auf Blättern und wird nachts aktiv. In deinem Zoo wirkt er wie ein kleines, lebendiges Kunstwerk.'),
(92042, 1115, 'da', 'Tropisk sommerfugl', 'Tropiske sommerfugle er kendte for deres fantastiske farvepragtige vinger. I regnskovene fungerer disse som camouflage, kommunikation og advarsel til rovdyr. Mange mimikerer gifttige arter for at beskytte sig.'),
(92043, 620, 'en', 'Red-Footed Tortoise', 'The Köhler’s tortoise is a tropical land turtle with a dark shell and yellow spots. It lives in South America and enjoys eating fruit and vegetables. In your zoo it moves leisurely between plants and feeding spots.'),
(92044, 620, 'de', 'Köhlerschildkröte', 'Die Köhlerschildkröte ist eine tropische Landschildkröte mit dunklem Panzer und gelben Flecken. Sie lebt in Südamerika und frisst gerne Obst und Gemüse. In deinem Zoo bewegt sie sich gemütlich zwischen Pflanzen und Futterstellen.'),
(92045, 620, 'da', 'Glasvinge-sommerfugl', 'Glasvinge-sommerfuglen har gennemsigtige vinger, der næsten er usynlige. Denne form for camouflage er sjælden i fuglekongen og giver den beskyttelse i sin regnskovshjem. Den er hjemmehørende i Mellemamerika.'),
(92046, 643, 'en', 'Red-Necked Pademelon', 'The red-necked wallaby is a medium-sized kangaroo with a reddish neck. It lives in Australia and prefers rocky or wooded areas. In your zoo, it hops gracefully around and loves to rest in shady spots.'),
(92047, 643, 'de', 'Rothalsfilander', 'Der Rothalsfilander ist ein mittelgroßes Känguru mit rötlicher Halsfärbung. Er lebt in Australien und bevorzugt felsige oder bewaldete Gebiete. In deinem Zoo hüpft er leichtfüßig und ruht sich gern in schattigen Ecken aus.'),
(92048, 643, 'da', 'Kæmpe-vandbi', 'Wallaces kæmpe-bi er verdens største bi og kan blive op til 4 cm lang med et vingefang på 6 cm. Den blev troet at være uddød i årtier, men blev genopdaget på en ø i Indonesien i 2019.'),
(92049, 828, 'en', 'Reef Manta Ray', 'The reef manta is smaller than the giant manta but just as graceful. It lives around coral reefs and filters plankton. In your zoo, it glides in graceful circles, adding a tropical touch to the aquarium.'),
(92050, 828, 'de', 'Riffmanta', 'Der Riffmanta ist kleiner als der Riesenmanta, aber ebenso elegant. Er lebt an Korallenriffen und filtert Plankton. In deinem Zoo zieht er elegante Kreise und verleiht dem Aquarium tropisches Flair.'),
(92051, 828, 'da', 'Makrelfisk', 'Makrellen er en sølvglinsende, hurtig stimmefisk fra Nordatlanten. Den er let genkendelig på sine karakteristiske grønne bølgemønstre på ryggen. Den danner store stimer for at beskytte sig mod rovdyr.'),
(92052, 226, 'en', 'Reindeer', 'The reindeer is perfectly adapted to cold regions and plays a starring role in many winter tales. Both males and females grow antlers, which is unusual for deer. In your zoo it plods calmly through its enclosure, shakes the snow from its fur and instantly puts visitors in a winter mood.'),
(92053, 226, 'de', 'Rentier', 'Das Rentier ist perfekt an kalte Regionen angepasst und spielt in vielen Wintergeschichten eine Hauptrolle. Sowohl Männchen als auch Weibchen tragen Geweihe, was bei Hirschen ungewöhnlich ist. In deinem Zoo trottet es gemächlich durchs Gehege, schüttelt den Schnee aus dem Fell und versetzt Besucher in Winterstimmung.'),
(92054, 226, 'da', 'Rensdyr', 'Rensdyret er perfekt tilpasset kolde regioner og spiller en vigtig rolle i mange vintereventyr. Både hanner og hunner bærer gevir, hvilket er usædvanligt for hjorte. I din zoo trotter det roligt igennem indhegningen og sætter besøgende i vinterhurnør.'),
(92055, 30237, 'en', 'Resplendent Quetzal', 'The Resplendent Quetzal is a stunning Central American bird with iridescent green plumage, a crimson belly, and (in males) a flowing 65 cm (26 inch) tail covert streaming like green silk. Shy and elusive, it perches quietly before darting for fruit and nests in tree cavities.\n\nResplendent Quetzal\'s diet mainly consists of wild avocados, fruits, insects, small lizards, and frogs.\n\n'),
(92056, 30237, 'de', 'Resplendent Quetzal', 'The Resplendent Quetzal is a stunning Central American bird with iridescent green plumage, a crimson belly, and (in males) a flowing 65 cm (26 inch) tail covert streaming like green silk. Shy and elusive, it perches quietly before darting for fruit and nests in tree cavities.\n\nResplendent Quetzal\'s diet mainly consists of wild avocados, fruits, insects, small lizards, and frogs.\n\n'),
(92057, 30237, 'da', 'Resplendent Quetzal', 'The Resplendent Quetzal is a stunning Central American bird with iridescent green plumage, a crimson belly, and (in males) a flowing 65 cm (26 inch) tail covert streaming like green silk. Shy and elusive, it perches quietly before darting for fruit and nests in tree cavities.\n\nResplendent Quetzal\'s diet mainly consists of wild avocados, fruits, insects, small lizards, and frogs.\n\n'),
(92058, 521, 'en', 'Reticulated Giraffe', 'The Reticulated Giraffe has a particularly fine, net‑like spotted pattern. It lives in Africa and uses its long neck to reach leaves high up in the trees. In your zoo, it towers above all other animals and enjoys fresh branches.'),
(92059, 521, 'de', 'Netzgiraffe', 'Die Netzgiraffe besitzt ein besonders feinmaschiges Fleckenmuster, das an ein Netz erinnert. Sie lebt in Afrika und nutzt ihren langen Hals, um Blätter hoch oben zu erreichen. In deinem Zoo ragt sie über alle anderen Tiere hinaus und lässt sich frische Zweige schmecken.'),
(92060, 521, 'da', 'Marabu-stork', 'Marabustorken er en af Afrikas største fugle med et vingefang på op til 3,7 meter. Det er en ådselæder og en vigtig del af savanneøkosystemet, da den rydder op efter andre rovdyr.'),
(92061, 633, 'en', 'Reticulated Python', 'The reticulated python is one of the longest snake species in the world. Its net‑like pattern helps it stay well camouflaged in the jungle. In your zoo it winds slowly and majestically through its terrarium.'),
(92062, 633, 'de', 'Netzpython', 'Der Netzpython ist eine der längsten Schlangenarten der Welt. Sein Netz-Muster hilft ihm, im Dschungel gut getarnt zu bleiben. In deinem Zoo windet er sich langsam und majestätisch durch sein Terrarium.'),
(92063, 633, 'da', 'Vandpyton', 'Vandpytoner er store slanger, der er tilpasset til et semi-akvatisk liv. De er dygtige svømmere og kan forblive under vand i lang tid. De kvæler deres bytte og sluger det helt.'),
(92064, 802, 'en', 'Ribbon Seal', 'The band seal has a pale ring of fur around its body, which gives it its name. It lives in the Arctic seas and uses ice floes as resting spots. In your zoo it swims elegantly through the pool and likes to rest on cool rocks.'),
(92065, 802, 'de', 'Bandrobbe', 'Die Bandrobbe trägt einen hellen Ring um den Körper, der ihr den Namen gibt. Sie lebt in arktischen Meeren und nutzt Eisflächen zum Ruhen. In deinem Zoo schwimmt sie elegant durchs Becken und ruht sich gern auf kühlen Felsen aus.'),
(92066, 802, 'da', 'Hummer', 'Hummeren er et fascinerende krebsdyr med et hårdt ydre skelet. Den er udødelighedsbevidst og vokser faktisk hele livet igennem — biologisk ældes den næsten ikke. Den kan leve i over 100 år.'),
(92067, 417, 'en', 'Ring-Tailed Lemur', 'The ring‑tailed lemur is a lemur from Madagascar, best known for its ringed tail. It lives in groups and enjoys sunbathing with its arms spread wide. In your zoo it playfully leaps from branch to branch and puts on a true lemur theater with its group.'),
(92068, 417, 'de', 'Katta', 'Der Katta ist ein Lemur aus Madagaskar und vor allem für seinen geringelten Schwanz bekannt. Er lebt in Gruppen und genießt gern Sonnenbäder mit ausgebreiteten Armen. In deinem Zoo springt er verspielt von Ast zu Ast und veranstaltet mit seiner Gruppe ein wahres Lemurentheater.'),
(92069, 417, 'da', 'Ringhalevet lemur', 'Ringhalelémuren er en lemur fra Madagaskar, bedst kendt for sin ringstribede hale. Den lever i grupper og nyder gerne at sole sig med udbredte arme. I din zoo hopper den legesygt fra gren til gren og opfører med sin gruppe et sandt lemurteater.'),
(92070, 220, 'en', 'Ringtail', 'The linsang belongs to the viverrid family and looks a bit like a mix between a cat and a marten. It is nocturnal and prefers dense vegetation to hide in. In the zoo it likes to appear at dusk and curiously explores every corner of its enclosure.'),
(92071, 220, 'de', 'Katzenfrett', 'Das Katzenfrett gehört zur Familie der Schleichkatzen und erinnert ein wenig an eine Mischung aus Katze und Marder. Es ist nachtaktiv und schätzt dichte Vegetation zum Verstecken. Im Zoo zeigt es sich gerne in der Dämmerung und erkundet neugierig jede Ecke seines Geheges.'),
(92072, 220, 'da', 'Ringhalsdyr', 'Katteferreten tilhører Desmerdyrfamilien og minder lidt om en krydsning mellem en kat og en mår. Det er nattaktivt og sætter pris på tæt vegetation til at gemme sig i. I din zoo dukker det op i tusmørket og udforsker nysgerrigt hvert hjørne.'),
(92073, 30238, 'en', 'Rockhopper Penguin', 'Rockhopper penguins are among the smaller species of penguin. After reaching full growth, they are about 20 inches or 50 centimetres in height. Males and females cannot be distinguished visually. Like many penguins, rockhopper penguins have a white belly and the rest of their body is black. Some characteristics that differentiate them from the other penguins are their red eyes, orange beak, pink webbed feet, and the yellow and black spiky feathers they have on their head.\n\nRockhopper Penguins are carnivorous (piscivorous). The diet of these penguins primarily consists of fish, octopus, cuttlefish, krill, squid, mollusks, planktons as well as crustaceans.\n\n'),
(92074, 30238, 'de', 'Rockhopper Penguin', 'Rockhopper penguins are among the smaller species of penguin. After reaching full growth, they are about 20 inches or 50 centimetres in height. Males and females cannot be distinguished visually. Like many penguins, rockhopper penguins have a white belly and the rest of their body is black. Some characteristics that differentiate them from the other penguins are their red eyes, orange beak, pink webbed feet, and the yellow and black spiky feathers they have on their head.\n\nRockhopper Penguins are carnivorous (piscivorous). The diet of these penguins primarily consists of fish, octopus, cuttlefish, krill, squid, mollusks, planktons as well as crustaceans.\n\n'),
(92075, 30238, 'da', 'Rockhopper Penguin', 'Rockhopper penguins are among the smaller species of penguin. After reaching full growth, they are about 20 inches or 50 centimetres in height. Males and females cannot be distinguished visually. Like many penguins, rockhopper penguins have a white belly and the rest of their body is black. Some characteristics that differentiate them from the other penguins are their red eyes, orange beak, pink webbed feet, and the yellow and black spiky feathers they have on their head.\n\nRockhopper Penguins are carnivorous (piscivorous). The diet of these penguins primarily consists of fish, octopus, cuttlefish, krill, squid, mollusks, planktons as well as crustaceans.\n\n'),
(92076, 719, 'en', 'Rocky Mountain Goat', 'The mountain goat is a high‑altitude animal from North America with thick, white fur. She climbs safely up steep slopes. In your zoo, she shows her climbing skills on rocky structures and keeps an eye on everything from above.'),
(92077, 719, 'de', 'Schneeziege', 'Die Schneeziege ist ein Bergtier Nordamerikas mit dichtem, weißem Fell. Sie klettert sicher an steilen Hängen. In deinem Zoo zeigt sie ihre Kletterkünste auf felsigen Strukturen und behält von dort alles im Blick.'),
(92078, 719, 'da', 'Albatros', 'Albatrosserne har det største vingefang af alle fugle og kan nå op til 3,7 meter. De er mestre i at glide på havsvinds og kan tilbagelægge tusindvis af kilometer uden at slå med vingerne.'),
(92079, 311, 'en', 'Roe Deer', 'The European roe deer is a typical inhabitant of our forests and fields. It is delicately built and always alert to notice danger early. In your zoo it appears especially gentle and can be easily observed while grazing and ruminating.'),
(92080, 311, 'de', 'Europäisches Reh', 'Das Europäische Reh ist ein typischer Bewohner unserer Wälder und Felder. Es ist zierlich gebaut und immer aufmerksam, um Gefahren früh zu erkennen. In deinem Zoo wirkt es besonders sanft und lässt sich beim Äsen und Wiederkäuen gut beobachten.'),
(92081, 311, 'da', 'Europæisk rådyr', 'Det europæiske rådyr er et typisk skovdyr med slankt bygget og altid på vagt. Det er delikat i sin fremtræden og altid klar til at opdage farer. I din zoo virker det særligt blødt og lader sig nemt observere mens det græsser og tygger drøv.'),
(92082, 116, 'en', 'Roseate Spoonbill', 'The Spoonbill is an elegant wading bird with a characteristic spoon-shaped bill. With it, it combs through shallow waters to detect small fish and invertebrates. In your zoo, it strides leisurely through the water basin and gently swings its unusual bill back and forth.'),
(92083, 116, 'de', 'Löffler', 'Der Löffler ist ein eleganter Watvogel mit einem charakteristischen löffelförmigen Schnabel. Mit diesem durchkämmt er flache Gewässer, um kleine Fische und Wirbellose aufzuspüren. In deinem Zoo schreitet er gemächlich durchs Wasserbecken und lässt seinen ungewöhnlichen Schnabel sanft hin und her pendeln.'),
(92084, 116, 'da', 'Skestork', 'Skestorken er en elegant vadefugl med et karakteristisk skeformet næb. Den er hjemmehørende i Amerika og er nem at kende på sin lyserøde farve. I din zoo skrider den roligt igennem vandbassinet og svinger sit usædvanlige næb.'),
(92085, 30239, 'en', 'Royal Blue Tang', 'Royal Blue Tangs are small fish native to coral reefs in the Indo-Pacific. They have a royal blue body, yellow tail, and black \"palette\" design. Juvenile blue tangs are bright yellow. And as adults, the fish will flush deeper blues and violets as a sign of stress. It grows to 30 cm (12 in). Adults typically weigh around 600 g (21 oz) and males are generally larger than females.\n\nWhile blue tangs are omnivores and have been known to chow down on tiny aquatic creatures known as plankton, the bulk of their diet comes from algae. The fish use small, sharp teeth to nip and scrape algae off the coral reef.\n\n'),
(92086, 30239, 'de', 'Royal Blue Tang', 'Royal Blue Tangs are small fish native to coral reefs in the Indo-Pacific. They have a royal blue body, yellow tail, and black \"palette\" design. Juvenile blue tangs are bright yellow. And as adults, the fish will flush deeper blues and violets as a sign of stress. It grows to 30 cm (12 in). Adults typically weigh around 600 g (21 oz) and males are generally larger than females.\n\nWhile blue tangs are omnivores and have been known to chow down on tiny aquatic creatures known as plankton, the bulk of their diet comes from algae. The fish use small, sharp teeth to nip and scrape algae off the coral reef.\n\n'),
(92087, 30239, 'da', 'Royal Blue Tang', 'Royal Blue Tangs are small fish native to coral reefs in the Indo-Pacific. They have a royal blue body, yellow tail, and black \"palette\" design. Juvenile blue tangs are bright yellow. And as adults, the fish will flush deeper blues and violets as a sign of stress. It grows to 30 cm (12 in). Adults typically weigh around 600 g (21 oz) and males are generally larger than females.\n\nWhile blue tangs are omnivores and have been known to chow down on tiny aquatic creatures known as plankton, the bulk of their diet comes from algae. The fish use small, sharp teeth to nip and scrape algae off the coral reef.\n\n'),
(92088, 535, 'en', 'Royal Sable Antelope', 'The giant eland is a rare and very impressive antelope with large, curved horns. Its dark coat contrasts strongly with its light markings. In your zoo it radiates dignity and strength and is a true highlight for visitors.'),
(92089, 535, 'de', 'Riesen-Rappenantilope', 'Die Riesen-Rappenantilope ist eine seltene und sehr beeindruckende Antilope mit großen, geschwungenen Hörnern. Ihr dunkles Fell steht in starkem Kontrast zu den hellen Abzeichen. In deinem Zoo strahlt sie Würde und Kraft aus und ist ein echtes Highlight für Besucher.'),
(92090, 535, 'da', 'Gepard-gazelle (Thomsons)', 'Elanden er den største antilope i verden. På trods af sin størrelse er den overraskende agil og kan hoppe over hegn på mere end 1,5 meters højde med lethed.'),
(92091, 30240, 'en', 'Rusty-Spotted Cat', 'The Rusty-Spotted Cat is a small wild cat native to India and Sri Lanka. It is one of the smallest cat species in the world, measuring about 48-65 cm (19-26 inches) in length, with a distinctive rusty or reddish-brown coat adorned with dark spots and stripes. The Rusty-Spotted Cat is a solitary and nocturnal hunter that is known for its agility and climbing skills.\n\nThe diet of the Rusty-Spotted Cat primarily consists of small mammals, birds, and reptiles.\n\n'),
(92092, 30240, 'de', 'Rusty-Spotted Cat', 'The Rusty-Spotted Cat is a small wild cat native to India and Sri Lanka. It is one of the smallest cat species in the world, measuring about 48-65 cm (19-26 inches) in length, with a distinctive rusty or reddish-brown coat adorned with dark spots and stripes. The Rusty-Spotted Cat is a solitary and nocturnal hunter that is known for its agility and climbing skills.\n\nThe diet of the Rusty-Spotted Cat primarily consists of small mammals, birds, and reptiles.\n\n'),
(92093, 30240, 'da', 'Rusty-Spotted Cat', 'The Rusty-Spotted Cat is a small wild cat native to India and Sri Lanka. It is one of the smallest cat species in the world, measuring about 48-65 cm (19-26 inches) in length, with a distinctive rusty or reddish-brown coat adorned with dark spots and stripes. The Rusty-Spotted Cat is a solitary and nocturnal hunter that is known for its agility and climbing skills.\n\nThe diet of the Rusty-Spotted Cat primarily consists of small mammals, birds, and reptiles.\n\n'),
(92094, 725, 'en', 'Sable', 'The sable is a small mustelid with very soft, prized fur. He lives in northern forests and is a skillful hunter. In your zoo, he moves quickly and curiously, usually staying close to hiding spots.'),
(92095, 725, 'de', 'Zobel', 'Der Zobel ist ein kleiner Marder mit sehr weichem, begehrtem Fell. Er lebt in nordischen Wäldern und ist ein geschickter Jäger. In deinem Zoo bewegt er sich flink und neugierig, meist in der Nähe von Verstecken.'),
(92096, 725, 'da', 'Kryolitisk fisk', 'Isfisken er en usædvanlig fisk fra de kolde sydpolske have. Den har ikke hemoglobin i blodet men har i stedet specialiserede proteiner, der forhindrer dens blod i at fryse. Dens blod er bogstaveligt talt gennemsigtigt.'),
(92097, 30241, 'en', 'Saffron Toucanet', 'The Saffron Toucanet is a colorful, small-to-medium toucan native to the Andean cloud forests of South America, renowned for its vibrant saffron-yellow plumage, black facial mask, and oversized beak used for foraging and display. Measuring 35-40 cm (14-16 inches) in length and weighing 150-200 grams (5-7 oz), it has a lifespan of 10-15 years in the wild.\n\nSaffron Toucanets are primarily frugivorous, feeding on fruits, berries, and insects.\n\n'),
(92098, 30241, 'de', 'Saffron Toucanet', 'The Saffron Toucanet is a colorful, small-to-medium toucan native to the Andean cloud forests of South America, renowned for its vibrant saffron-yellow plumage, black facial mask, and oversized beak used for foraging and display. Measuring 35-40 cm (14-16 inches) in length and weighing 150-200 grams (5-7 oz), it has a lifespan of 10-15 years in the wild.\n\nSaffron Toucanets are primarily frugivorous, feeding on fruits, berries, and insects.\n\n'),
(92099, 30241, 'da', 'Saffron Toucanet', 'The Saffron Toucanet is a colorful, small-to-medium toucan native to the Andean cloud forests of South America, renowned for its vibrant saffron-yellow plumage, black facial mask, and oversized beak used for foraging and display. Measuring 35-40 cm (14-16 inches) in length and weighing 150-200 grams (5-7 oz), it has a lifespan of 10-15 years in the wild.\n\nSaffron Toucanets are primarily frugivorous, feeding on fruits, berries, and insects.\n\n'),
(92100, 832, 'en', 'Saimaa Ringed Seal', 'The Salmaa ringed seal is a small seal species with circular patterns on its fur. It inhabits arctic waters. In your zoo, it showcases the wonderful diversity of the seal family.'),
(92101, 832, 'de', 'Salmaa-Ringelrobbe', 'Die Salmaa-Ringelrobbe ist eine kleine Robbenart mit ringförmigen Mustern im Fell. Sie lebt in arktischen Gewässern. In deinem Zoo zeigt sie, wie vielfältig die Robbenwelt ist.'),
(92102, 832, 'da', 'Sardin', 'Sardinen lever i store stimer i det Atlantiske og Middelhavsfarvan. De er et vigtigt led i havets fødekæde og er energirig mad for mange rovfisk, havpattedyr og havfugle. De er vigtige kommercielt.'),
(92103, 843, 'en', 'Saltwater Crocodile', 'The saltwater crocodile is one of the largest crocodile species in the world. It lives in estuaries and coastal waters of the Indo-Pacific region. In your zoo, it often lies still in the water, like a living fossil.'),
(92104, 843, 'de', 'Leistenkrokodil', 'Das Leistenkrokodil ist eines der größten Krokodile der Welt. Es lebt in Flussmündungen und Küstengewässern im indo-pazifischen Raum. In deinem Zoo ruht es oft reglos im Wasser und wirkt wie ein lebendes Fossil.'),
(92105, 843, 'da', 'Søslange', 'Havsslangerne er en gruppe gifttige slanger, der er fuldt tilpasset til havlivet. De har en flad hale til at svømme og kan opholde sig under vand i timer. De meeste arter er fredeligt og bider sjældent mennesker.'),
(92106, 524, 'en', 'Sand Cat', 'The sand cat is perfectly adapted to life in the desert and has dense fur on its paws, allowing it to walk even on hot sand. In your zoo it looks like a small, noble desert princess that likes to lurk in the sand.'),
(92107, 524, 'de', 'Sandkatze', 'Die Sandkatze ist perfekt an das Leben in der Wüste angepasst und besitzt ein dichtes Fell an den Pfoten. So kann sie auch über heißen Sand laufen. In deinem Zoo wirkt sie wie eine kleine, edle Wüstenprinzessin, die gern im Sand lauert.'),
(92108, 524, 'da', 'Impala', 'Implaen er en af Afrikas mest almindelige og elegante antilopearter. Den er berømt for sine imponerende spring på op til 3 meter i højden og 10 meter i længden.'),
(92109, 644, 'en', 'Saola', 'The saola is a very rare forest-dwelling bovine species from Vietnam and Laos. Sometimes called the \'Asian unicorn\', it actually has two horns. In your zoo, it represents the mysterious forest creatures we still have much to learn about.'),
(92110, 644, 'de', 'Saola', 'Die Saola ist eine sehr seltene, waldbewohnende Rinderart aus Vietnam und Laos. Sie wird manchmal „asiatisches Einhorn“ genannt, obwohl sie zwei Hörner trägt. In deinem Zoo steht sie stellvertretend für geheimnisvolle Waldbewohner, von denen wir noch viel lernen müssen.'),
(92111, 644, 'da', 'Kæmpepyton', 'Det nettede python er verdens længste slange og kan blive over 7 meter lang. Det er en kvælerslange og lever i regnskove i Sydøstasien. Den er en dygtig svømmer og klatrer i træer.'),
(92112, 1208, 'en', 'Savannah Monitor', 'The savannah monitor is a strong lizard from the dry regions of Africa. It is active during the day and a skilled hunter. In your zoo, it enjoys basking in the sun and curiously explores every corner of its terrarium.'),
(92113, 1208, 'de', 'Steppenwaran', 'Der Steppenwaran ist ein kräftiger Waran aus trockenen Regionen Afrikas. Er ist tagaktiv und ein geschickter Jäger. In deinem Zoo nutzt er gern warme Sonnenplätze und erkundet neugierig jede Ecke seines Terrariums.'),
(92114, 1208, 'da', 'Arabisk spindelvæv', 'Klippe-edderkopper lever i sprækker og under sten i klippede og ørkenmiljøer. De er nattaktive jægere, der lurer på insekter og andre ledyr. Mange har usædvanlige jagt-strategier tilpasset det tørre miljø.'),
(92115, 30242, 'en', 'Sawfish', 'Sawfish are a family of rays characterized by a long, narrow, flattened rostrum, or nose extension, lined with sharp transverse teeth, arranged in a way that resembles a saw. They are among the largest fish with some species reaching lengths of about 7–7.6m (23–25 ft). Their bodies are somewhat shark-shaped, but their pectoral, or front fins, have a flat, triangular shape to them. They are found worldwide in tropical and subtropical regions in coastal marine and brackish estuarine waters, as well as freshwater rivers and lakes. All species are endangered.\n\nSawfish eat fish and crustaceans. The saw is key to catching and killing prey—in addition to its use as a weapon or digging tool, the saw has small pores that can detect electric fields produced by prey. \n\nPlayers can get up to 6 Sawfish in the same enclosure:\n{| class=\"article-table\"\n!Animals\n! Enclosure size\n|-\n|1\n|9\n|-\n|2\n|9\n|-\n|3\n|14\n|-\n|4\n|18\n|-\n|5\n|22\n|-\n| 6\n|27\n|}\n\n');
INSERT INTO `animaltext` (`id`, `animalId`, `languageCode`, `animalName`, `animalDescription`) VALUES
(92116, 30242, 'de', 'Sawfish', 'Sawfish are a family of rays characterized by a long, narrow, flattened rostrum, or nose extension, lined with sharp transverse teeth, arranged in a way that resembles a saw. They are among the largest fish with some species reaching lengths of about 7–7.6m (23–25 ft). Their bodies are somewhat shark-shaped, but their pectoral, or front fins, have a flat, triangular shape to them. They are found worldwide in tropical and subtropical regions in coastal marine and brackish estuarine waters, as well as freshwater rivers and lakes. All species are endangered.\n\nSawfish eat fish and crustaceans. The saw is key to catching and killing prey—in addition to its use as a weapon or digging tool, the saw has small pores that can detect electric fields produced by prey. \n\nPlayers can get up to 6 Sawfish in the same enclosure:\n{| class=\"article-table\"\n!Animals\n! Enclosure size\n|-\n|1\n|9\n|-\n|2\n|9\n|-\n|3\n|14\n|-\n|4\n|18\n|-\n|5\n|22\n|-\n| 6\n|27\n|}\n\n'),
(92117, 30242, 'da', 'Sawfish', 'Sawfish are a family of rays characterized by a long, narrow, flattened rostrum, or nose extension, lined with sharp transverse teeth, arranged in a way that resembles a saw. They are among the largest fish with some species reaching lengths of about 7–7.6m (23–25 ft). Their bodies are somewhat shark-shaped, but their pectoral, or front fins, have a flat, triangular shape to them. They are found worldwide in tropical and subtropical regions in coastal marine and brackish estuarine waters, as well as freshwater rivers and lakes. All species are endangered.\n\nSawfish eat fish and crustaceans. The saw is key to catching and killing prey—in addition to its use as a weapon or digging tool, the saw has small pores that can detect electric fields produced by prey. \n\nPlayers can get up to 6 Sawfish in the same enclosure:\n{| class=\"article-table\"\n!Animals\n! Enclosure size\n|-\n|1\n|9\n|-\n|2\n|9\n|-\n|3\n|14\n|-\n|4\n|18\n|-\n|5\n|22\n|-\n| 6\n|27\n|}\n\n'),
(92118, 655, 'en', 'Scarlet Ibis', 'The scarlet ibis is a bright red bird from the wetlands of South America. It gets its vivid color from its diet. In your zoo, it looks like a living splash of red as it gracefully wades through the water.'),
(92119, 655, 'de', 'Scharlachsichler', 'Der Scharlachsichler ist ein leuchtend roter Vogel aus den Feuchtgebieten Südamerikas. Seine intensiven Farben erhält er durch die Nahrung. In deinem Zoo wirkt er wie ein kleiner roter Farbtupfer, der durchs Wasser watet.'),
(92120, 655, 'da', 'Frø (giftig)', 'Giftige pilefrøer er farverige frøer fra de tropiske regnskove i Mellem- og Sydamerika. Deres lyse farver advarer rovdyr om, at de er giftige. Nogle er af de mest giftige dyr på Jorden.'),
(92121, 1207, 'en', 'Scarlet Kingsnake', 'The red kingsnake is a brightly banded snake. Its colors mimic venomous species, although it is harmless itself. In your zoo, it’s a striking example of how clever mimicry and deception can be.'),
(92122, 1207, 'de', 'Rote Königsnatter', 'Die Rote Königsnatter ist eine bunt geringelte Schlange. Ihre Färbung imitiert giftige Arten, obwohl sie selbst ungiftig ist. In deinem Zoo zeigt sie eindrucksvoll, wie clever Tarnung und Täuschung sein können.'),
(92123, 1207, 'da', 'Bjerg-koyote', 'Prærieulven er et opportunistisk rovdyr, der er tilpasset til mange habitater, inklusiv ørkenklipperegioner. Den er meget intelligent og har koloniseret store dele af Nordamerika, herunder forstæder.'),
(92124, 614, 'en', 'Scarlet Macaw', 'The scarlet macaw is a vividly colorful parrot from the tropics of the Americas. It is intelligent, noisy, and forms lifelong pair bonds. In your zoo it flies brightly through the aviary and creates a true tropical atmosphere.'),
(92125, 614, 'de', 'Hellroter Ara', 'Der Hellrote Ara ist ein leuchtend bunter Papagei aus den Tropen Amerikas. Er ist intelligent, lautstark und lebt in lebenslangen Paarbindungen. In deinem Zoo fliegt er farbenfroh durch die Voliere und sorgt für echte Tropenatmosphäre.'),
(92126, 614, 'da', 'Leguan', 'Den grønne leguan er en stor firben, der lever i trætoppene i tropiske regnskove. Den er en planteæder og bruger sin hale til at svømme og forsvare sig. De kan blive over 2 meter lange.'),
(92127, 30243, 'en', 'Schleswig Coldblood', 'The Schleswig Coldblood is a robust and versatile horse breed originating from the Schleswig region of Germany. Known for its strength and endurance, this breed typically stands between 15.2 to 16.3 hands high. Schleswig Coldbloods come in a variety of colors, including bay, black, chestnut, and gray. Some may also exhibit markings such as blazes or socks.\n\nSchleswig Coldbloods primarily graze on grasses and forage in pastures. They consume a variety of plants, including herbs and shrubs.\n\n'),
(92128, 30243, 'de', 'Schleswig Coldblood', 'The Schleswig Coldblood is a robust and versatile horse breed originating from the Schleswig region of Germany. Known for its strength and endurance, this breed typically stands between 15.2 to 16.3 hands high. Schleswig Coldbloods come in a variety of colors, including bay, black, chestnut, and gray. Some may also exhibit markings such as blazes or socks.\n\nSchleswig Coldbloods primarily graze on grasses and forage in pastures. They consume a variety of plants, including herbs and shrubs.\n\n'),
(92129, 30243, 'da', 'Schleswig Coldblood', 'The Schleswig Coldblood is a robust and versatile horse breed originating from the Schleswig region of Germany. Known for its strength and endurance, this breed typically stands between 15.2 to 16.3 hands high. Schleswig Coldbloods come in a variety of colors, including bay, black, chestnut, and gray. Some may also exhibit markings such as blazes or socks.\n\nSchleswig Coldbloods primarily graze on grasses and forage in pastures. They consume a variety of plants, including herbs and shrubs.\n\n'),
(92130, 30244, 'en', 'Scimitar Oryx', 'The Scimitar Oryx is a striking antelope once native to the Sahara Desert and Sahel regions of North Africa. Distinguished by its long, curved horns that resemble scimitars, white coat with reddish-brown markings, and black facial stripes, it was adapted for arid environments with a lifespan of 15-20 years. They are adapted to harsh desert conditions and can survive for months or even years without drinking water.\n\nThe Scimitar Oryx is herbivorous, grazing on grasses, herbs, and shrubs.\n\n'),
(92131, 30244, 'de', 'Scimitar Oryx', 'The Scimitar Oryx is a striking antelope once native to the Sahara Desert and Sahel regions of North Africa. Distinguished by its long, curved horns that resemble scimitars, white coat with reddish-brown markings, and black facial stripes, it was adapted for arid environments with a lifespan of 15-20 years. They are adapted to harsh desert conditions and can survive for months or even years without drinking water.\n\nThe Scimitar Oryx is herbivorous, grazing on grasses, herbs, and shrubs.\n\n'),
(92132, 30244, 'da', 'Scimitar Oryx', 'The Scimitar Oryx is a striking antelope once native to the Sahara Desert and Sahel regions of North Africa. Distinguished by its long, curved horns that resemble scimitars, white coat with reddish-brown markings, and black facial stripes, it was adapted for arid environments with a lifespan of 15-20 years. They are adapted to harsh desert conditions and can survive for months or even years without drinking water.\n\nThe Scimitar Oryx is herbivorous, grazing on grasses, herbs, and shrubs.\n\n'),
(92133, 837, 'en', 'Sea Otter', 'The sea otter is famous for floating on its back while resting. It uses stones as tools to crack open shellfish. In your zoo, it’s a playful crowd favorite.'),
(92134, 837, 'de', 'Seeotter', 'Der Seeotter ist bekannt dafür, beim Ruhen auf dem Rücken im Wasser zu treiben. Er nutzt Steine als Werkzeuge, um Muscheln aufzubrechen. In deinem Zoo ist er ein verspielter Publikumsliebling.'),
(92135, 837, 'da', 'Torsk', 'Torsken er en af de vigtigste kommercielle fisk i verden og har haft stor betydning for europæisk og nordamerikansk historia. Den har en karakteristisk skæg under hagen og lever i kolde nordatlantiske farvande.'),
(92136, 232, 'en', 'Secretarybird', 'The secretary bird is a large bird of prey that, unlike many of its relatives, spends most of its time on the ground. With its long legs it strides through the savanna hunting snakes and other small animals. In the zoo its proud posture and the feather \"crown\" on the back of its head earn it plenty of admiration.'),
(92137, 232, 'de', 'Sekretär', 'Der Sekretär ist ein großer Greifvogel, der anders als viele Verwandte meist am Boden unterwegs ist. Mit seinen langen Beinen schreitet er durch die Savanne und jagt Schlangen und andere Kleintiere. Im Zoo sorgt seine stolze Haltung und die „Federkrone“ am Hinterkopf für viel Bewunderung.'),
(92138, 232, 'da', 'Sekretærfugl', 'Sekretærfuglen er en stor rovfugl, der i modsætning til mange slægtninge primært opholder sig på jorden. Med sine lange ben skrider den gennem savannen og jager slanger. I din zoo giver dens stolte holdning og fjerkrone på baghovedet megen beundring.'),
(92139, 233, 'en', 'Serval', 'The serval is a slender, long-legged wild cat with large ears and spotted fur. It can knock birds out of the air with impressive leaps and listens for the faintest sounds in the grass. In your zoo it prowls alertly through its enclosure, jumps onto high perches and keeps a close eye on everything.'),
(92140, 233, 'de', 'Serval', 'Der Serval ist eine schlanke, hochbeinige Wildkatze mit großen Ohren und geflecktem Fell. Er kann mit beeindruckenden Sprüngen Vögel aus der Luft schlagen und lauscht feinsten Geräuschen im Gras. In deinem Zoo schleicht er aufmerksam durchs Gehege, springt auf erhöhte Plätze und beobachtet alles ganz genau.'),
(92141, 233, 'da', 'Serval', 'Servalen er en slank, langbenet vildkat med store ører og plettet pels. Den kan med imponerende spring slå fugle ud af luften og lytter til de fineste lyde i græsset. I din zoo smutter den opmærksomt igennem indhegningen og observerer alt nøje.'),
(92142, 128, 'en', 'Sheep', 'The sheep is a classic farm animal kept mainly for its wool, milk, and meat. It feels particularly comfortable in flocks and likes to follow a leader. In your zoo, it bleats friendly, lets the wind blow through its wool, and rejoices over fresh hay.'),
(92143, 128, 'de', 'Schaf', 'Das Schaf ist ein klassisches Nutztier, das vor allem für seine Wolle, Milch und sein Fleisch gehalten wird. In Herden fühlt es sich besonders wohl und folgt gerne einem Leittier. In deinem Zoo blökt es freundlich, lässt sich den Wind durch die Wolle pusten und freut sich über frisches Heu.'),
(92144, 128, 'da', 'Får', 'Fåret er et klassisk nyttedyr, der primært holdes for sin uld, mælk og kød. I flokke trives det bedst. I din zoo bræger det venligt, lader vinden blæse igennem ulden og fryder sig over frisk hø.'),
(92145, 133, 'en', 'Shetland Pony', 'The Shetland Pony is small, robust, and surprisingly strong for its size. It comes from the windy Shetland Islands and has thick fur that protects it well. In the zoo, it enjoys stroking children\'s hands and trots merrily through its enclosure.'),
(92146, 133, 'de', 'Shetlandpony', 'Das Shetlandpony ist klein, robust und erstaunlich kräftig für seine Größe. Es stammt von den windigen Shetlandinseln und hat ein dichtes Fell, das es gut schützt. Im Zoo freut es sich über streichelnde Kinderhände und trabt munter durch sein Gehege.'),
(92147, 133, 'da', 'Shetlandspony', 'Shetlandsponyten er lille, robust og overraskende stærk for sin størrelse. Den stammer fra de blæsende Shetlandsøer og har en tyk pels. I din zoo nyder den strygende barnehænder og travler livlig igennem sit indhegning.'),
(92148, 30245, 'en', 'Shima Enaga', 'The Shima Enaga, or Taiwan white-eye, is a tiny, fluffy Japanese songbird with pure white plumage, black eyes, and a short black bill, resembling a cotton ball or snowball, especially the young with extra fluff. They are native to remote islands off Kyushu, Japan (hence \"shima\" = island). Endangered due to predation and habitat loss. \n\nShima Enaga feeds on insects, spiders, nectar, and small fruits.\n\n'),
(92149, 30245, 'de', 'Shima Enaga', 'The Shima Enaga, or Taiwan white-eye, is a tiny, fluffy Japanese songbird with pure white plumage, black eyes, and a short black bill, resembling a cotton ball or snowball, especially the young with extra fluff. They are native to remote islands off Kyushu, Japan (hence \"shima\" = island). Endangered due to predation and habitat loss. \n\nShima Enaga feeds on insects, spiders, nectar, and small fruits.\n\n'),
(92150, 30245, 'da', 'Shima Enaga', 'The Shima Enaga, or Taiwan white-eye, is a tiny, fluffy Japanese songbird with pure white plumage, black eyes, and a short black bill, resembling a cotton ball or snowball, especially the young with extra fluff. They are native to remote islands off Kyushu, Japan (hence \"shima\" = island). Endangered due to predation and habitat loss. \n\nShima Enaga feeds on insects, spiders, nectar, and small fruits.\n\n'),
(92151, 131, 'en', 'Shoebill', 'The Shoebill gets its name from its huge, shoe-shaped bill that gives it an almost prehistoric appearance. It lives in African swamps, patiently waiting for fish and other prey. In the zoo, it often stands motionless in the water, astonishing visitors with its stoic calm.'),
(92152, 131, 'de', 'Schuhschnabel', 'Der Schuhschnabel verdankt seinen Namen seinem riesigen, schuhförmigen Schnabel, der ihm ein fast urzeitliches Aussehen verleiht. Er lebt in afrikanischen Sümpfen und lauert dort geduldig auf Fische und andere Beute. Im Zoo steht er oft regungslos im Wasser und verblüfft Besucher mit seiner stoischen Ruhe.'),
(92153, 131, 'da', 'Skosknæbbet stork', 'Skostork-næbbet stork skylder sit navn til det gigantiske, skoformet næb, der giver det et nærmest urtidssagn udseende. Det lever i afrikanske sumpe og venter tålmodigt på fisk. I din zoo står det ofte ubevægeligt i vandet.'),
(92154, 114, 'en', 'Short-Beaked Echidna', 'The Short-beaked Echidna is a spiny insectivore from Australia that somewhat resembles a spiky anteater. With its long tongue, it detects ants and termites in their nests. In your zoo, it sniffs curiously through the enclosure, digs small holes, and rolls into a prickly ball when in danger.'),
(92155, 114, 'de', 'Kurzschnabeligel', 'Der Kurzschnabeligel ist ein stacheliger Insektenfresser aus Australien, der ein wenig an einen stacheligen Ameisenbär erinnert. Mit seiner langen Zunge spürt er Ameisen und Termiten in ihren Nestern auf. In deinem Zoo schnüffelt er neugierig durch das Gehege, gräbt kleine Löcher und rollt sich bei Gefahr zu einer piksigen Kugel zusammen.'),
(92156, 114, 'da', 'Kortsnabelpigsvin', 'Kortsnabelpigsvinget er et pigget insektæder fra Australien, der ligner en pindsvin-myresluger. Med sin lange tunge finder den myrer og termitter i deres reder. I din zoo snuser den nysgerrigt rundt og ruller sig til en bold ved fare.'),
(92157, 624, 'en', 'Short-Eared Zorro', 'The short‑eared fox, as its name suggests, has unusually short ears for a fox. It lives in South America and is a crepuscular hunter. In your zoo it moves quietly through the enclosure and shows its curious, cautious side.'),
(92158, 624, 'de', 'Kurzohrfuchs', 'Der Kurzohrfuchs hat, wie der Name sagt, ungewöhnlich kurze Ohren für einen Fuchs. Er lebt in Südamerika und ist ein dämmerungsaktiver Jäger. In deinem Zoo schleicht er leise durchs Gehege und zeigt seine neugierige, vorsichtige Seite.'),
(92159, 624, 'da', 'Flagermus', 'Flagermus er de eneste pattedyr, der kan flyve rigtigt. De bruger ekkolokation til at navigere og jage insekter om natten. Mange arter er vigtige bestøvere og frøspredere i tropiske skove.'),
(92160, 30246, 'en', 'Short-Snouted Seahorse', 'The Short-Snouted Seahorse, scientific name Hippocampus Hippocampus, is a species of seahorse within the family Syngnathidae. They have potential to be up to 15 centimetres (5.9 in) long. Seahorse bodies might be black, purple, orange, brown, green or yellow coloration permitting them to cover among the many vegetation. The Short-Snouted Seahorses have a tail that’s unable to bend backward however is taken into account semi-flexible. They use it as an anchor by wrapping it around coral or seagrass.\n\nShort-Snouted Seahorses are known to be ambush predators whom feed on live, moving food. On average the adult seahorse will eat roughly between 30 and 50 tiny shrimp a day. They will remain still until a small animal passes within reach and then grab it.\n\n'),
(92161, 30246, 'de', 'Short-Snouted Seahorse', 'The Short-Snouted Seahorse, scientific name Hippocampus Hippocampus, is a species of seahorse within the family Syngnathidae. They have potential to be up to 15 centimetres (5.9 in) long. Seahorse bodies might be black, purple, orange, brown, green or yellow coloration permitting them to cover among the many vegetation. The Short-Snouted Seahorses have a tail that’s unable to bend backward however is taken into account semi-flexible. They use it as an anchor by wrapping it around coral or seagrass.\n\nShort-Snouted Seahorses are known to be ambush predators whom feed on live, moving food. On average the adult seahorse will eat roughly between 30 and 50 tiny shrimp a day. They will remain still until a small animal passes within reach and then grab it.\n\n'),
(92162, 30246, 'da', 'Short-Snouted Seahorse', 'The Short-Snouted Seahorse, scientific name Hippocampus Hippocampus, is a species of seahorse within the family Syngnathidae. They have potential to be up to 15 centimetres (5.9 in) long. Seahorse bodies might be black, purple, orange, brown, green or yellow coloration permitting them to cover among the many vegetation. The Short-Snouted Seahorses have a tail that’s unable to bend backward however is taken into account semi-flexible. They use it as an anchor by wrapping it around coral or seagrass.\n\nShort-Snouted Seahorses are known to be ambush predators whom feed on live, moving food. On average the adult seahorse will eat roughly between 30 and 50 tiny shrimp a day. They will remain still until a small animal passes within reach and then grab it.\n\n'),
(92163, 30247, 'en', 'Siamang', 'The Siamang is the largest of the gibbons, an endangered arboreal ape. Siamangs have long, shaggy black fur with some pale hairs around the mouth and chin. Both males and females look similar, and infants share the same dark coloration. A distinctive grayish or pinkish throat sac inflates during vocalizations and can grow as large as a grapefruit.\n\nTheir diet consists mainly of leaves, fruits, and flowers, with leaves making up a larger portion than in other gibbon species.\n\n'),
(92164, 30247, 'de', 'Siamang', 'The Siamang is the largest of the gibbons, an endangered arboreal ape. Siamangs have long, shaggy black fur with some pale hairs around the mouth and chin. Both males and females look similar, and infants share the same dark coloration. A distinctive grayish or pinkish throat sac inflates during vocalizations and can grow as large as a grapefruit.\n\nTheir diet consists mainly of leaves, fruits, and flowers, with leaves making up a larger portion than in other gibbon species.\n\n'),
(92165, 30247, 'da', 'Siamang', 'The Siamang is the largest of the gibbons, an endangered arboreal ape. Siamangs have long, shaggy black fur with some pale hairs around the mouth and chin. Both males and females look similar, and infants share the same dark coloration. A distinctive grayish or pinkish throat sac inflates during vocalizations and can grow as large as a grapefruit.\n\nTheir diet consists mainly of leaves, fruits, and flowers, with leaves making up a larger portion than in other gibbon species.\n\n'),
(92166, 30248, 'en', 'Siamese Fighting Fish', 'Siamese Fighting Fish (Betta splendens) is an aggressive, colorful fish that is native to Thailand, Vietnam, and Cambodia by way of the Mekong Delta. They are labyrinth fish, meaning they have a lung-like organ known as a labyrinth which they use to gulp air near the surface of the water and allows them to live in low-oxygen habitats. They are small fish that can have several possible colors. While dark blue and dark red are common colors, they may also be grey, black, red, orange, yellow, gold, blue, white, violet, or even multicolored.\n\nBettas are carnivorous and consume zooplankton, brine shrimp, daphnia, and other small crustaceans, bloodworms, and the larvae of aquatic insects, including that mosquitos. \n\nSeveral Betta species have a Vulnerable conservation status according to the IUCN Red List. \n\n'),
(92167, 30248, 'de', 'Siamese Fighting Fish', 'Siamese Fighting Fish (Betta splendens) is an aggressive, colorful fish that is native to Thailand, Vietnam, and Cambodia by way of the Mekong Delta. They are labyrinth fish, meaning they have a lung-like organ known as a labyrinth which they use to gulp air near the surface of the water and allows them to live in low-oxygen habitats. They are small fish that can have several possible colors. While dark blue and dark red are common colors, they may also be grey, black, red, orange, yellow, gold, blue, white, violet, or even multicolored.\n\nBettas are carnivorous and consume zooplankton, brine shrimp, daphnia, and other small crustaceans, bloodworms, and the larvae of aquatic insects, including that mosquitos. \n\nSeveral Betta species have a Vulnerable conservation status according to the IUCN Red List. \n\n'),
(92168, 30248, 'da', 'Siamese Fighting Fish', 'Siamese Fighting Fish (Betta splendens) is an aggressive, colorful fish that is native to Thailand, Vietnam, and Cambodia by way of the Mekong Delta. They are labyrinth fish, meaning they have a lung-like organ known as a labyrinth which they use to gulp air near the surface of the water and allows them to live in low-oxygen habitats. They are small fish that can have several possible colors. While dark blue and dark red are common colors, they may also be grey, black, red, orange, yellow, gold, blue, white, violet, or even multicolored.\n\nBettas are carnivorous and consume zooplankton, brine shrimp, daphnia, and other small crustaceans, bloodworms, and the larvae of aquatic insects, including that mosquitos. \n\nSeveral Betta species have a Vulnerable conservation status according to the IUCN Red List. \n\n'),
(92169, 720, 'en', 'Siberian Tiger', 'The Siberian tiger is the largest tiger subspecies and lives in the forests of Russia. His thick coat protects him from the cold. In your zoo, he looks especially impressive as he walks through snowy enclosures.'),
(92170, 720, 'de', 'Sibirischer Tiger', 'Der Sibirische Tiger ist die größte Tigerunterart und lebt in den Wäldern Russlands. Sein dichtes Fell schützt ihn vor Kälte. In deinem Zoo wirkt er besonders imposant, wenn er durch verschneite Gehege schreitet.'),
(92171, 720, 'da', 'Vidunderlig fugl', 'Den arktiske lom er en fremragende dykker og svømmer og tilpasser sig perfekt til livet på det kolde hav. Den er kendetegnet ved sin karakteristiske skakternede sort-hvide plovning og sin melankolske sang.'),
(92172, 1119, 'en', 'Silky Anteater', 'The Pygmy Anteater is a small, tree-dwelling insect-eater. It spends much of its time among the branches. In your zoo, it proves that even tiny animals can be true specialists.'),
(92173, 1119, 'de', 'Zwergameisenbär', 'Der Zwergameisenbär ist ein kleiner, kletternder Ameisenfresser. Er verbringt viel Zeit in Bäumen. In deinem Zoo zeigt er, dass auch kleine Tiere große Spezialisten sein können.'),
(92174, 1119, 'da', 'Skovugle', 'Skovskovuglen er et nataktivt rovdyr med exceptionelt syn og hørelse. Den kan rotere sit hoved næsten 270 grader og er i stand til at høre mus under sne. Den er en vigtig del af skovøkosystemet.'),
(92175, 235, 'en', 'Silvery Greater Galago', 'The silver galago is a nocturnal jumping acrobat with big eyes and long hind legs. It lives in trees and moves in wide leaps from branch to branch. In your zoo it is most active in the evening and its quiet jumps never fail to amaze onlookers.'),
(92176, 235, 'de', 'Silberner Riesengalago', 'Der Silberne Riesengalago ist ein nachtaktiver Sprungakrobat mit großen Augen und langen Hinterbeinen. Er lebt in Bäumen und bewegt sich mit weiten Sprüngen von Ast zu Ast. In deinem Zoo ist er vor allem abends aktiv und sorgt mit seinen leisen Sprüngen für staunende Blicke.'),
(92177, 235, 'da', 'Sølvgalago', 'Den sølvgrå galago er en nattaktiv springakrobat med store øjne og lange bagben. Den lever i træer og bevæger sig med vide spring fra gren til gren. I din zoo er den primært aktiv om aftenen og fremkalder forundring med sine stille spring.'),
(92178, 140, 'en', 'Sitatunga', 'The Waterbuck is a large antelope species that prefers wetlands and dense vegetation. Its twisted horns and striped coat make it particularly striking. In the zoo, it moves calmly and vigilantly through its territory, causing awe with its majestic appearance.'),
(92179, 140, 'de', 'Wasserkudu', 'Der Wasserkudu ist eine große Antilopenart, die Feuchtgebiete und dichte Vegetation bevorzugt. Seine gedrehten Hörner und das gestreifte Fell machen ihn besonders auffällig. Im Zoo bewegt er sich ruhig und wachsam durch sein Revier und sorgt mit seiner majestätischen Erscheinung für Staunen.'),
(92180, 140, 'da', 'Situtunga', 'Situtunga er en stor antilopeart, der foretrækker vådområder og tæt vegetation. Dens snoede horn og stribede pels gør den særligt iøjnefaldende. I din zoo bevæger den sig roligt og opmærksomt og imponerer med sit majestætiske udseende.'),
(92181, 609, 'en', 'Sloth', 'The sloth is famous for its slow pace and relaxed nature. It hangs upside‑down in trees most of the time and moves only when necessary. In your zoo it shows that life can also be enjoyed at a very slow pace.'),
(92182, 609, 'de', 'Faultier', 'Das Faultier ist berühmt für sein langsames Tempo und sein entspanntes Wesen. Es hängt die meiste Zeit kopfüber in Bäumen und bewegt sich nur, wenn nötig. In deinem Zoo zeigt es, dass man das Leben auch mal ganz langsam genießen darf.'),
(92183, 609, 'da', 'Anaconda', 'Anacondaen er en af verdens største slanger og kan blive over 8 meter lang. Den er en kvælerslange og lever i og nær vand i Sydamerikas regnskove. Den føder levende unger.'),
(92184, 115, 'en', 'Sloth Bear', 'The Sloth Bear has shaggy fur and a long, flexible snout with which it sucks insects from their nests. It\'s mainly at home in India and loves termite mounds and sweet fruits. In the zoo, you can watch it smack its lips as it sucks in food and happily snuffle.'),
(92185, 115, 'de', 'Lippenbär', 'Der Lippenbär hat ein zottiges Fell und eine lange, bewegliche Schnauze, mit der er Insekten aus ihren Nestern saugt. Er ist vor allem in Indien zuhause und liebt Termitenhügel und süße Früchte. Im Zoo kann man ihn dabei beobachten, wie er mit den Lippen schmatzend die Nahrung einsaugt und dabei fröhlich schnauft.'),
(92186, 115, 'da', 'Slikkebjørn', 'Slikkebjørnen har en pjusket pels og en lang, bevægelig tryne, som den suger insekter ud af deres reder med. I din zoo kan man se den smadsende suge næring ind og snøfte lystigt.'),
(92187, 30249, 'en', 'Slow Loris', 'Slow Lorises are a group of several species of nocturnal primates. They are small, compact creatures with a short tail, a short, rounded muzzle, round eyes that are directed forward, and fur that is short and dense. They are mostly brown, gray, or reddish-brown. Between their eyes are white lines, with dark markings encircling them, and a faint medial stripe on the crown. Additionally, they have large eyes that assist them in finding food. \n\nSlow Loris is an omnivore, eating ants, insects, and a wide variety of fruits and plants, preferring soft fruits and gums.\n\n'),
(92188, 30249, 'de', 'Slow Loris', 'Slow Lorises are a group of several species of nocturnal primates. They are small, compact creatures with a short tail, a short, rounded muzzle, round eyes that are directed forward, and fur that is short and dense. They are mostly brown, gray, or reddish-brown. Between their eyes are white lines, with dark markings encircling them, and a faint medial stripe on the crown. Additionally, they have large eyes that assist them in finding food. \n\nSlow Loris is an omnivore, eating ants, insects, and a wide variety of fruits and plants, preferring soft fruits and gums.\n\n'),
(92189, 30249, 'da', 'Slow Loris', 'Slow Lorises are a group of several species of nocturnal primates. They are small, compact creatures with a short tail, a short, rounded muzzle, round eyes that are directed forward, and fur that is short and dense. They are mostly brown, gray, or reddish-brown. Between their eyes are white lines, with dark markings encircling them, and a faint medial stripe on the crown. Additionally, they have large eyes that assist them in finding food. \n\nSlow Loris is an omnivore, eating ants, insects, and a wide variety of fruits and plants, preferring soft fruits and gums.\n\n'),
(92190, 716, 'en', 'Snow Goose', 'The snow goose is a migratory bird with light plumage. She breeds in Arctic regions and winters further south. In your zoo, she brings a wintry vibe to open water areas.'),
(92191, 716, 'de', 'Schneegans', 'Die Schneegans ist ein Zugvogel mit hellem Gefieder. Sie brütet in arktischen Regionen und überwintert weiter südlich. In deinem Zoo sorgt sie auf Wasserflächen für winterliche Stimmung.'),
(92192, 716, 'da', 'Ork (Spækhugger)', 'Orcaen, eller spækhuggeren, er den største delfin i verden og er en mester rovdyr på toppen af havets fødekæde. Dens intelligens og sociale kompleksitet har gjort den til et ikonisk symbol på havets kraft.'),
(92193, 717, 'en', 'Snow Hare', 'The snowshoe hare changes his fur from brown in summer to white in winter. That way he stays well camouflaged all year. In your zoo, he hops quickly through snowy enclosures and blends perfectly into the winter landscape.'),
(92194, 717, 'de', 'Schneehase', 'Der Schneehase wechselt sein Fell zwischen Sommer und Winter von braun zu weiß. So ist er das ganze Jahr über gut getarnt. In deinem Zoo hoppelt er flink durch Schneegehege und fügt sich perfekt in die Winterlandschaft ein.'),
(92195, 717, 'da', 'Søløve', 'Søløver er kendetegnet ved deres evne til at bevæge sig på alle fire lemmer på land, hvilket adskiller dem fra sæler. De er ekstremt lydige og bruges til marineopgaver og akrobatiske shows.'),
(92196, 718, 'en', 'Snow Leopard', 'The snow leopard lives in the high mountains of Asia and wears a thick, spotted coat. His long tail serves as a balance aid and a cozy blanket. In your zoo, he moves gracefully over rocks and looks like a ghost of the mountains.'),
(92197, 718, 'de', 'Schneeleopard', 'Der Schneeleopard lebt in den Hochgebirgen Asiens und besitzt ein dichtes, geflecktes Fell. Sein langer Schwanz dient als Balancierhilfe und Kuscheldecke. In deinem Zoo bewegt er sich elegant über Felsen und wirkt wie ein Geist des Gebirges.'),
(92198, 718, 'da', 'Pungdyr (antarktisk)', 'Den sydlige søelefant er det største rovdyr i ordenen Pinnipedia og kan veje op til 4 ton. Hannerne har en karakteristisk snabelagtig næse og kæmper voldsomt om territorium og hunner i yngletiden.'),
(92202, 841, 'en', 'Snowy Albatross', 'The wandering albatross has the largest wingspan of any bird. It can glide for hours over the ocean with barely a flap. In your zoo, it symbolizes the freedom of the open seas.'),
(92203, 841, 'de', 'Wander-Albatros', 'Der Wanderalbatros hat die größte Flügelspannweite aller Vögel. Er kann stundenlang über dem Meer segeln, ohne viel zu schlagen. In deinem Zoo symbolisiert er die Freiheit der Weltmeere.'),
(92204, 841, 'da', 'Havbars', 'Havulven er en stor, rovagtig fisk med kraftige kæber fuld af skarpe tænder. Den lever i det kolde nordatlantiske hav og er tilpasset til at knuse hårde skaller fra byttedyr som krabber og muslinger.'),
(92205, 30251, 'en', 'Snowy Owl', 'Snowy Owls are a large owl native to arctic regions in both North America and Eurasia. They are mostly white. They are purer white than predatory mammals like Polar bears and Arctic foxes. Often when seen in the field, these owls can resemble a pale rock or a lump of snow on the ground. Juvenile Snowy Owls have black feathers that turn white as they age. While Most owls sleep during the day and hunt at night, the Snowy Owl is often active during the day and they defend their and their neighbour\'s nests from predeators.\n\nSnowy Owls are carnivores. They feed on a wide variety of small mammals such as lemmings, meadow voles, and deer mice, but will also take advantage of larger prey. \n\n'),
(92206, 30251, 'de', 'Snowy Owl', 'Snowy Owls are a large owl native to arctic regions in both North America and Eurasia. They are mostly white. They are purer white than predatory mammals like Polar bears and Arctic foxes. Often when seen in the field, these owls can resemble a pale rock or a lump of snow on the ground. Juvenile Snowy Owls have black feathers that turn white as they age. While Most owls sleep during the day and hunt at night, the Snowy Owl is often active during the day and they defend their and their neighbour\'s nests from predeators.\n\nSnowy Owls are carnivores. They feed on a wide variety of small mammals such as lemmings, meadow voles, and deer mice, but will also take advantage of larger prey. \n\n'),
(92207, 30251, 'da', 'Snowy Owl', 'Snowy Owls are a large owl native to arctic regions in both North America and Eurasia. They are mostly white. They are purer white than predatory mammals like Polar bears and Arctic foxes. Often when seen in the field, these owls can resemble a pale rock or a lump of snow on the ground. Juvenile Snowy Owls have black feathers that turn white as they age. While Most owls sleep during the day and hunt at night, the Snowy Owl is often active during the day and they defend their and their neighbour\'s nests from predeators.\n\nSnowy Owls are carnivores. They feed on a wide variety of small mammals such as lemmings, meadow voles, and deer mice, but will also take advantage of larger prey. \n\n'),
(92208, 526, 'en', 'Somali Ostrich', 'The Somali ostrich is a subspecies of the ostrich with bluish legs and neck. It lives in the dry regions of the Horn of Africa. In your zoo it strolls through the enclosure and keeps an eye on everything with its large eyes.'),
(92209, 526, 'de', 'Somalistrauß', 'Der Somalistrauß ist eine Unterart des Straußes mit bläulichen Beinen und Hals. Er lebt in den Trockengebieten am Horn von Afrika. In deinem Zoo flaniert er durch das Gehege und hält mit seinen großen Augen alles im Blick.'),
(92210, 526, 'da', 'Springbok', 'Springbokken er Sydafrikas nationalemblem og er berømt for sin imponerende adfærd kaldet \"pronking\", hvor den hopper lodret op i luften for at demonstrere sin vitalitet for rovdyr.'),
(92211, 30252, 'en', 'South China Tiger', 'The South China Tiger is a critically endangered subspecies. Once found in the forests of southern China, it is now considered functionally extinct in the wild, with no confirmed sightings for over 25 years. The South China tiger has a distinctive coat with broad, closely spaced black stripes on a yellowish-orange background. It is smaller than other tiger subspecies, with males weighing between 100 kg and 195 kg (221 lb - 430 lb) and measuring about 2.3 m to 2.8 m (7.5 ft - 9 ft) in length.\n\nAs carnivorous predators, South China tigers primarily hunt large ungulates such as deer and wild boar.\n\n'),
(92212, 30252, 'de', 'South China Tiger', 'The South China Tiger is a critically endangered subspecies. Once found in the forests of southern China, it is now considered functionally extinct in the wild, with no confirmed sightings for over 25 years. The South China tiger has a distinctive coat with broad, closely spaced black stripes on a yellowish-orange background. It is smaller than other tiger subspecies, with males weighing between 100 kg and 195 kg (221 lb - 430 lb) and measuring about 2.3 m to 2.8 m (7.5 ft - 9 ft) in length.\n\nAs carnivorous predators, South China tigers primarily hunt large ungulates such as deer and wild boar.\n\n'),
(92213, 30252, 'da', 'South China Tiger', 'The South China Tiger is a critically endangered subspecies. Once found in the forests of southern China, it is now considered functionally extinct in the wild, with no confirmed sightings for over 25 years. The South China tiger has a distinctive coat with broad, closely spaced black stripes on a yellowish-orange background. It is smaller than other tiger subspecies, with males weighing between 100 kg and 195 kg (221 lb - 430 lb) and measuring about 2.3 m to 2.8 m (7.5 ft - 9 ft) in length.\n\nAs carnivorous predators, South China tigers primarily hunt large ungulates such as deer and wild boar.\n\n'),
(92214, 615, 'en', 'Southern Cassowary', 'The helmeted cassowary is a large flightless bird from Australia and New Guinea with a helmet‑like crest on its head. It lives in rainforests and can deliver very powerful kicks. In your zoo it looks with its colors and impressive helmet almost like a mythical creature.'),
(92215, 615, 'de', 'Helmkasuar', 'Der Helmkasuar ist ein großer Laufvogel aus Australien und Neuguinea mit helmartigem Kopfschmuck. Er lebt in Regenwäldern und kann sehr kräftig zutreten. In deinem Zoo wirkt er mit seinen Farben und seinem eindrucksvollen Helm fast wie ein Fabelwesen.'),
(92216, 615, 'da', 'Neontetra', 'Neontetraen er en lille, livlig tropisk fisk fra Sydamerikas regnskovfloder. Den metalliske blå-røde stribe giver den et karakteristisk glimt i akvariet. Den lever i store stimer.'),
(92217, 30253, 'en', 'Southern Muriqui', 'The Southern Muriqui, also known as the woolly spider monkey, is a critically endangered primate native to the Atlantic Forest of Brazil. It is one of the largest New World monkeys, characterized by its long limbs, prehensile tail, and a distinctive coat of thick, woolly fur that ranges in color from light brown to dark brown. Adult males typically weigh between 40 to 50 pounds (18 to 23 kg), while females are slightly smaller.\n\nSouthern Muriquis are herbivores (folivores, frugivores). They eat mostly leaves and fruits, but also will eat flowers, seeds, bark, and buds.\n\n'),
(92218, 30253, 'de', 'Southern Muriqui', 'The Southern Muriqui, also known as the woolly spider monkey, is a critically endangered primate native to the Atlantic Forest of Brazil. It is one of the largest New World monkeys, characterized by its long limbs, prehensile tail, and a distinctive coat of thick, woolly fur that ranges in color from light brown to dark brown. Adult males typically weigh between 40 to 50 pounds (18 to 23 kg), while females are slightly smaller.\n\nSouthern Muriquis are herbivores (folivores, frugivores). They eat mostly leaves and fruits, but also will eat flowers, seeds, bark, and buds.\n\n'),
(92219, 30253, 'da', 'Southern Muriqui', 'The Southern Muriqui, also known as the woolly spider monkey, is a critically endangered primate native to the Atlantic Forest of Brazil. It is one of the largest New World monkeys, characterized by its long limbs, prehensile tail, and a distinctive coat of thick, woolly fur that ranges in color from light brown to dark brown. Adult males typically weigh between 40 to 50 pounds (18 to 23 kg), while females are slightly smaller.\n\nSouthern Muriquis are herbivores (folivores, frugivores). They eat mostly leaves and fruits, but also will eat flowers, seeds, bark, and buds.\n\n'),
(92220, 818, 'en', 'Southern Sea Lion', 'The lion seal has a dense fur collar that looks like a mane. It lives along coasts of the Southern Hemisphere. In your zoo it likes to sunbathe and shows its agility in the water during feeding time.'),
(92221, 818, 'de', 'Mähnenrobbe', 'Die Mähnenrobbe hat einen dichten Fellkragen, der wie eine Mähne wirkt. Sie lebt an den Küsten der Südhalbkugel. In deinem Zoo ruht sie gern in der Sonne und zeigt bei Fütterungen ihre Wendigkeit im Wasser.'),
(92222, 818, 'da', 'Havmåge', 'Sølvmågen er en af de mest kendte og udbredte mågearter i Europa. Den er et opportunistisk dyr, der lever af alt fra fisk til affald. Den er ekspert i at bruge termik til at svæve i timesvis.'),
(92223, 30254, 'en', 'Southern Three-Banded Armadillo', 'The Southern Three-Banded Armadillo is an armadillo species from South America. Southern Three-Banded Armadillos are the only species of armadillos that can roll into a complete ball to defend themselves. They have three bands that cover the back of the animal, its tail and head together. This allows it to protect its underbelly, limbs, eyes, nose and ears from predators. The shell covering its body is armored and the outer layer is made out of keratin. \n\nThese armadillos are carnivores (insectivores). They feed on different species of insects, typically ants and termites.\n\n'),
(92224, 30254, 'de', 'Southern Three-Banded Armadillo', 'The Southern Three-Banded Armadillo is an armadillo species from South America. Southern Three-Banded Armadillos are the only species of armadillos that can roll into a complete ball to defend themselves. They have three bands that cover the back of the animal, its tail and head together. This allows it to protect its underbelly, limbs, eyes, nose and ears from predators. The shell covering its body is armored and the outer layer is made out of keratin. \n\nThese armadillos are carnivores (insectivores). They feed on different species of insects, typically ants and termites.\n\n'),
(92225, 30254, 'da', 'Southern Three-Banded Armadillo', 'The Southern Three-Banded Armadillo is an armadillo species from South America. Southern Three-Banded Armadillos are the only species of armadillos that can roll into a complete ball to defend themselves. They have three bands that cover the back of the animal, its tail and head together. This allows it to protect its underbelly, limbs, eyes, nose and ears from predators. The shell covering its body is armored and the outer layer is made out of keratin. \n\nThese armadillos are carnivores (insectivores). They feed on different species of insects, typically ants and termites.\n\n'),
(92226, 305, 'en', 'Spectacled Bear', 'The spectacled bear is the only bear native to South America and has light markings around its eyes. These patterns resemble glasses and give it a friendly look. In your zoo it loves to climb, play with tree trunks and enjoy long, lazy breaks.'),
(92227, 305, 'de', 'Brillenbär', 'Der Brillenbär ist der einzige in Südamerika heimische Bär und trägt helle Zeichnungen um die Augen. Diese Muster erinnern an eine Brille und geben ihm ein freundliches Aussehen. In deinem Zoo klettert er gerne, spielt mit Baumstämmen und gönnt sich ausgiebige Ruhepausen.'),
(92228, 305, 'da', 'Brillebjørn', 'Brillebjørnen er den eneste bjørn hjemmehørende i Sydamerika og kendes på de lyse tegninger rundt om øjnene. I din zoo klatrer den gerne, leger med træstammer og nyder lange, dovne pauser.'),
(92229, 30255, 'en', 'Sperm Whale', 'The Sperm Whale  is the largest toothed hale and one of the most recognizable marine mammals, known for its distinctive large, block-shaped head. Adult males can reach lengths of up to 20.5 meters (67 feet) and weigh as much as 57,000 kilograms (125,000 pounds), while females are smaller, averaging around 11 meters (36 feet) in length. Their coloration is typically a dark gray or blue-gray, with lighter patches on their bodies. \n\nSperm whales primarily feed on squid, including giant squid, as well as fish and other deep-sea creatures. \n\n'),
(92230, 30255, 'de', 'Sperm Whale', 'The Sperm Whale  is the largest toothed hale and one of the most recognizable marine mammals, known for its distinctive large, block-shaped head. Adult males can reach lengths of up to 20.5 meters (67 feet) and weigh as much as 57,000 kilograms (125,000 pounds), while females are smaller, averaging around 11 meters (36 feet) in length. Their coloration is typically a dark gray or blue-gray, with lighter patches on their bodies. \n\nSperm whales primarily feed on squid, including giant squid, as well as fish and other deep-sea creatures. \n\n'),
(92231, 30255, 'da', 'Sperm Whale', 'The Sperm Whale  is the largest toothed hale and one of the most recognizable marine mammals, known for its distinctive large, block-shaped head. Adult males can reach lengths of up to 20.5 meters (67 feet) and weigh as much as 57,000 kilograms (125,000 pounds), while females are smaller, averaging around 11 meters (36 feet) in length. Their coloration is typically a dark gray or blue-gray, with lighter patches on their bodies. \n\nSperm whales primarily feed on squid, including giant squid, as well as fish and other deep-sea creatures. \n\n'),
(92232, 30256, 'en', 'Spix\'s Macaw', 'Spix\'s Macaw is a critically endangered parrot native to Brazil, known for its striking blue plumage and distinctive yellow eye rings. It measures about 55 cm (22 inches) in length and has a long tail. Once thought to be extinct in the wild, conservation efforts have led to captive breeding programs aimed at reintroducing this species. \n\nSpix\'s Macaw primarily feeds on seeds, fruits, and nuts.\n\n'),
(92233, 30256, 'de', 'Spix\'s Macaw', 'Spix\'s Macaw is a critically endangered parrot native to Brazil, known for its striking blue plumage and distinctive yellow eye rings. It measures about 55 cm (22 inches) in length and has a long tail. Once thought to be extinct in the wild, conservation efforts have led to captive breeding programs aimed at reintroducing this species. \n\nSpix\'s Macaw primarily feeds on seeds, fruits, and nuts.\n\n'),
(92234, 30256, 'da', 'Spix\'s Macaw', 'Spix\'s Macaw is a critically endangered parrot native to Brazil, known for its striking blue plumage and distinctive yellow eye rings. It measures about 55 cm (22 inches) in length and has a long tail. Once thought to be extinct in the wild, conservation efforts have led to captive breeding programs aimed at reintroducing this species. \n\nSpix\'s Macaw primarily feeds on seeds, fruits, and nuts.\n\n'),
(92235, 632, 'en', 'Spot-Bellied Eagle-Owl', 'The Nepal scops‑owl is an owl species from the mountainous regions of Nepal. With its ear tufts and penetrating gaze it is a typical night hunter. In your zoo it sleeps during the day and wakes up when dusk falls.'),
(92236, 632, 'de', 'Nepaluhu', 'Der Nepaluhu ist eine Eulenart aus den bergigen Regionen Nepals. Mit seinen Federohren und dem durchdringenden Blick ist er ein typischer Nachtjäger. In deinem Zoo schläft er tagsüber und wird bei Einbruch der Dunkelheit munter.'),
(92237, 632, 'da', 'Gepard-fisk', 'Arapaïmaen er en af verdens største ferskvandsfisk og kan blive op til 3 meter lang. Den er en luftåndende fisk og kan overleve i vand med lavt iltindhold. Den har fast plads i Sydamerikansk folklore.'),
(92238, 529, 'en', 'Spotted Hyena', 'The spotted hyena is a social predator with a real sense of humor—at least her call sounds that way. She is one of the most successful hunters of the savanna. In your zoo she creates excitement with her vocalizations and fiery temperament.'),
(92239, 529, 'de', 'Tüpfelhyäne', 'Die Tüpfelhyäne ist ein sozialer Beutegreifer mit echtem Sinn fürs Lachen – zumindest klingt ihr Ruf so. Sie ist eine der erfolgreichsten Jägerinnen der Savanne. In deinem Zoo sorgt sie mit ihrer Lautsprache und ihrem temperamentvollen Verhalten für Spannung.'),
(92240, 529, 'da', 'Emu', 'Emuen er verdens næststørste fugl og er hjemmehørende i Australien. Den kan ikke flyve men er en hurtig løber. Hannerne udruger æggene og tager sig primært af ungerne.'),
(92241, 412, 'en', 'Spotted Skunk', 'The spotted skunk is smaller than the striped skunk, but more vividly patterned. It also possesses the famous scent defense, which it uses only in emergencies. In your zoo it is mostly nocturnal and mainly appears in the evening hours.'),
(92242, 412, 'de', 'Fleckenskunk', 'Der Fleckenskunk ist kleiner als der Streifenskunk, dafür aber bunt gescheckt. Auch er besitzt die berühmte Duftverteidigung, die er nur im Notfall einsetzt. In deinem Zoo ist er meist nachtaktiv und lässt sich vor allem in den Abendstunden blicken.'),
(92243, 412, 'da', 'Pletskunk', 'Pletskunken er mindre end stribedskunksen men mere levende plettet. Den besidder også det berømte duftforsvar, som den kun bruger i nødsituationer. I din zoo er den mest nattaktiv og lader sig primært se i aftentimerne.'),
(92244, 30257, 'en', 'Springhare', 'The Springhare is a medium-sized terrestrial and burrowing rodent. Despite the name, it is not a hare. The Springhare resembles a small kangaroo, with well-developed hind legs. The color of this mammal varies from a reddish-brown to a pale grey, with a black tip on the tail. The Springhare also has large eyes, and its ears have a tragus that prevents sand from entering when it is digging.\n\nSpringhares are herbivores (graminivores, folivores) and feed mainly on grasses, leaves, stems, roots, and seeds of many plants and may even occasionally eat insects.\n\n'),
(92245, 30257, 'de', 'Springhare', 'The Springhare is a medium-sized terrestrial and burrowing rodent. Despite the name, it is not a hare. The Springhare resembles a small kangaroo, with well-developed hind legs. The color of this mammal varies from a reddish-brown to a pale grey, with a black tip on the tail. The Springhare also has large eyes, and its ears have a tragus that prevents sand from entering when it is digging.\n\nSpringhares are herbivores (graminivores, folivores) and feed mainly on grasses, leaves, stems, roots, and seeds of many plants and may even occasionally eat insects.\n\n');
INSERT INTO `animaltext` (`id`, `animalId`, `languageCode`, `animalName`, `animalDescription`) VALUES
(92246, 30257, 'da', 'Springhare', 'The Springhare is a medium-sized terrestrial and burrowing rodent. Despite the name, it is not a hare. The Springhare resembles a small kangaroo, with well-developed hind legs. The color of this mammal varies from a reddish-brown to a pale grey, with a black tip on the tail. The Springhare also has large eyes, and its ears have a tragus that prevents sand from entering when it is digging.\n\nSpringhares are herbivores (graminivores, folivores) and feed mainly on grasses, leaves, stems, roots, and seeds of many plants and may even occasionally eat insects.\n\n'),
(92247, 336, 'en', 'Squirrel Monkey', 'The squirrel monkey is small and nimble and has facial markings that resemble a skull. It lives in the forests of Central and South America and is rarely seen alone. In your zoo it dashes through the enclosure in a lively group, constantly climbing, jumping and squeaking.'),
(92248, 336, 'de', 'Totenkopfäffchen', 'Das Totenkopfäffchen ist klein, flink und trägt eine Gesichtszeichnung, die an einen Schädel erinnert. Es lebt in mittel- und südamerikanischen Wäldern und ist selten allein unterwegs. In deinem Zoo saust es in der Gruppe durch das Gehege und ist ständig am Klettern, Springen und Quietschen.'),
(92249, 336, 'da', 'Egernabe', 'Egernaben er lille, hurtig og har ansigtstegninger, der minder om en kranium. Den lever i skovene i Mellem- og Sydamerika og ses sjældent alene. I din zoo suser den i gruppen gennem sit anlæg og er konstant travl med at klatre, hoppe og klynke.'),
(92250, 30258, 'en', 'Stanley Bustard', 'Stanley Bustard is a large bird in the bustard family. Its back is brown, darker and plainer in the male, and the underparts are white. The neck is pale grey with an orange nape. Its grey crown is bordered with black, and a black line runs through the eye with a white line forming an eyebrow above. The long legs are pale yellow. The wings are strikingly patterned in brown, white and black.\n\nDenham’s Bustard is primarily herbivorous, consuming a variety of plant matter. It feeds on grasses, seeds, fruits, and even leaves, allowing it to adapt to the diverse vegetation in its habitat. \n\n'),
(92251, 30258, 'de', 'Stanley Bustard', 'Stanley Bustard is a large bird in the bustard family. Its back is brown, darker and plainer in the male, and the underparts are white. The neck is pale grey with an orange nape. Its grey crown is bordered with black, and a black line runs through the eye with a white line forming an eyebrow above. The long legs are pale yellow. The wings are strikingly patterned in brown, white and black.\n\nDenham’s Bustard is primarily herbivorous, consuming a variety of plant matter. It feeds on grasses, seeds, fruits, and even leaves, allowing it to adapt to the diverse vegetation in its habitat. \n\n'),
(92252, 30258, 'da', 'Stanley Bustard', 'Stanley Bustard is a large bird in the bustard family. Its back is brown, darker and plainer in the male, and the underparts are white. The neck is pale grey with an orange nape. Its grey crown is bordered with black, and a black line runs through the eye with a white line forming an eyebrow above. The long legs are pale yellow. The wings are strikingly patterned in brown, white and black.\n\nDenham’s Bustard is primarily herbivorous, consuming a variety of plant matter. It feeds on grasses, seeds, fruits, and even leaves, allowing it to adapt to the diverse vegetation in its habitat. \n\n'),
(92253, 416, 'en', 'Stoat', 'The stoat is a small predator that often turns snow‑white in winter. In former times it was seen as a symbol of purity and highly valued. In your zoo it changes fur color over the course of the year and shows how effective camouflage can be.'),
(92254, 416, 'de', 'Hermelin', 'Das Hermelin ist ein kleines Raubtier, das im Winter oft ein schneeweißes Fell bekommt. In dieser Zeit galt es früher als Symbol für Reinheit und wurde sehr geschätzt. In deinem Zoo wechselt es im Jahresverlauf die Fellfarbe und zeigt, wie gut Tarnung funktionieren kann.'),
(92255, 416, 'da', 'Hermelin', 'Hermejlet er et lille rovdyr, der ofte får et snehvidt pels om vinteren. Tidligere gjaldt det som symbol på renhed og var meget værdsat. I din zoo skifter det pelfarve i løbet af året og viser, hvor effektiv camouflage kan fungere.'),
(92256, 134, 'en', 'Straw-Necked Ibis', 'The Bald Ibis is an oddly looking bird with a bare head and shiny dark plumage. It was once widespread in Europe, but today it\'s rare and protected. In your zoo, it likes to perch on rocks and lets its feathers shimmer in the sun.'),
(92257, 134, 'de', 'Stachelibis', 'Der Stachelibis ist ein eigenwillig aussehender Vogel mit nacktem Kopf und glänzend dunklem Gefieder. Früher war er in Europa weit verbreitet, heute ist er selten geworden und steht unter Schutz. In deinem Zoo zeigt er sich gerne auf Felsen sitzend und lässt seine Federn in der Sonne schimmern.'),
(92258, 134, 'da', 'Nordlig skaldet ibis', 'Den nordlige skaldede ibis er en sjælden ibis med glansende sort fjerdragt og skaldet hoved. Den var engang udbredt i Europa, men avlsprogrammer hjælper den tilbage. I din zoo sidder den gerne på forhøjede steder.'),
(92259, 411, 'en', 'Striated Caracara', 'The Falkland caique is a bird from the Falkland Islands, well adapted to the harsh island life. It is curious and likes to make use of structures created by humans. In your zoo it appears as a lively, intelligent animal full of energy.'),
(92260, 411, 'de', 'Falklandkaraka', 'Der Falklandkaraka ist ein Vogel der Falklandinseln und an das raue Inselleben gewöhnt. Er ist neugierig und nutzt gerne vom Menschen geschaffene Strukturen. In deinem Zoo zeigt er sich als lebhaftes, kluges Tier mit viel Bewegungsdrang.'),
(92261, 411, 'da', 'Falklandkarakter', 'Falklandkarakaraen er en fugl fra Falklandsøerne, vant til det barske øeliv. Den er nysgerrig og udnytter gerne menneskeskabte strukturer. I din zoo viser den sig som et livligt, intelligent dyr med masser af bevægeenergi.'),
(92262, 30259, 'en', 'Striated Frogfish', 'The Striated Frogfish (Antennarius striatus), also known as the Hairy Frogfish, is a unique marine fish characterized by its short, globular body and rough skin covered in bifurcated spinules. They are typically orange-brown with black streaks, capable of changing color to blend into its surroundings. Masters of disguise, Striated Frogfish often mimick coral or sponges to avoid predators and ambush prey.\n\nThe Striated Frogfish primarily feeds on small marine organisms, with a diet that mainly consists of crustaceans, small fish and other Invertebrates.\n\n'),
(92263, 30259, 'de', 'Striated Frogfish', 'The Striated Frogfish (Antennarius striatus), also known as the Hairy Frogfish, is a unique marine fish characterized by its short, globular body and rough skin covered in bifurcated spinules. They are typically orange-brown with black streaks, capable of changing color to blend into its surroundings. Masters of disguise, Striated Frogfish often mimick coral or sponges to avoid predators and ambush prey.\n\nThe Striated Frogfish primarily feeds on small marine organisms, with a diet that mainly consists of crustaceans, small fish and other Invertebrates.\n\n'),
(92264, 30259, 'da', 'Striated Frogfish', 'The Striated Frogfish (Antennarius striatus), also known as the Hairy Frogfish, is a unique marine fish characterized by its short, globular body and rough skin covered in bifurcated spinules. They are typically orange-brown with black streaks, capable of changing color to blend into its surroundings. Masters of disguise, Striated Frogfish often mimick coral or sponges to avoid predators and ambush prey.\n\nThe Striated Frogfish primarily feeds on small marine organisms, with a diet that mainly consists of crustaceans, small fish and other Invertebrates.\n\n'),
(92265, 1109, 'en', 'Sugar Glider', 'The Short-headed Glider is a tiny marsupial equipped with thin skin membranes for gliding. It soars silently from tree to tree in search of food. In your zoo, it’s a quiet acrobat of the night.'),
(92266, 1109, 'de', 'Kurzkopfgleitbeutler', 'Der Kurzkopfgleitbeutler ist ein kleiner Gleiter mit häutigen Flugmembranen. Er segelt von Baum zu Baum auf der Suche nach Nahrung. In deinem Zoo ist er ein leiser Akrobat der Nacht.'),
(92267, 1109, 'da', 'Skovspurv', 'Skovfugle er en bred kategori af mange fuglearter, der er tilpasset til livet i tætte skove. De er typisk mestre i kamouflage og har komplekse sang-repertoirer til at kommunikere gennem den tætte vegetation.'),
(92268, 314, 'en', 'Sulphur-Crested Cockatoo', 'The sulphur‑crested cockatoo is a lively parrot with white plumage and a bright yellow crest. It is very social, loud and remarkably intelligent. In your zoo its calls, climbing antics and playful behavior provide first‑class entertainment.'),
(92269, 314, 'de', 'Gelbhauben Kakadu', 'Der Gelbhauben-Kakadu ist ein lebhafter Papagei mit weißem Gefieder und leuchtend gelber Federhaube. Er ist sehr gesellig, lautstark und ausgesprochen intelligent. In deinem Zoo sorgt er mit Rufen, Klettern und spielerischem Verhalten für beste Unterhaltung.'),
(92270, 314, 'da', 'Guldkammet kakadu', 'Den guldkammede kakadu er en livlig papegøje med hvide fjer og en lysende gul fjerhat. Den er meget social, højlydt og bemærkelsesværdigt intelligent. I din zoo giver den underholdning med sine råb, klatreakrobatik og legesyge adfærd.'),
(92271, 333, 'en', 'Sumatran Rhinoceros', 'The Sumatran rhinoceros is the smallest living rhino species and is critically endangered. It usually has two horns and lives in dense rainforests. In your zoo it is a true highlight and a powerful ambassador for the protection of tropical habitats.'),
(92272, 333, 'de', 'Sumatra-Naßhorn', 'Das Sumatra-Nashorn ist das kleinste lebende Nashorn und stark bedroht. Es trägt meist zwei Hörner und lebt in dichten Regenwäldern. In deinem Zoo ist es ein echtes Highlight und Botschafter für den Schutz tropischer Lebensräume.'),
(92273, 333, 'da', 'Sumatra-næsehorn', 'Sumatra-næsehornet er det mindste levende næsehorn og stærkt truet. Det bærer normalt to horn og lever i tætte regnskove. I din zoo er det et ægte højdepunkt og en kraftfuld ambassadør for beskyttelsen af tropiske levesteder.'),
(92274, 647, 'en', 'Sumatran Tiger', 'The Sumatran tiger is the smallest tiger subspecies and is strictly protected. It lives in the rainforests of Sumatra and is a master of camouflage. In your zoo, it stands as a symbol of endangered big cats and captivates visitors with its majestic presence.'),
(92275, 647, 'de', 'Sumatra-Tiger', 'Der Sumatra-Tiger ist die kleinste Tigerunterart und streng geschützt. Er lebt in den Regenwäldern Sumatras und ist ein Meister der Tarnung. In deinem Zoo steht er als Symbol für bedrohte Großkatzen und zieht Besucher mit seiner Präsenz in den Bann.'),
(92276, 647, 'da', 'Vandløber', 'Basilisken, også kaldet \"Jesu Kristus-firben\", er berømt for sin evne til at løbe på vandet. Denne utrolige færdighed opnås ved hurtigt at slå ud med dens store bagfødder på vandoverfladen.'),
(92277, 30260, 'en', 'Sun Bear', 'The Sun Bear is the smallest bear species, native to the tropical forests of Southeast Asia. It has a short, sleek black coat with a distinctive orange or cream-colored chest patch shaped like a crescent. They are primarily nocturnal and excellent climbers. \n\nSun Bears are omnivorous, feeding on fruits, insects, and small animals, and they use their long tongue to extract honey and insects.\n\n'),
(92278, 30260, 'de', 'Sun Bear', 'The Sun Bear is the smallest bear species, native to the tropical forests of Southeast Asia. It has a short, sleek black coat with a distinctive orange or cream-colored chest patch shaped like a crescent. They are primarily nocturnal and excellent climbers. \n\nSun Bears are omnivorous, feeding on fruits, insects, and small animals, and they use their long tongue to extract honey and insects.\n\n'),
(92279, 30260, 'da', 'Sun Bear', 'The Sun Bear is the smallest bear species, native to the tropical forests of Southeast Asia. It has a short, sleek black coat with a distinctive orange or cream-colored chest patch shaped like a crescent. They are primarily nocturnal and excellent climbers. \n\nSun Bears are omnivorous, feeding on fruits, insects, and small animals, and they use their long tongue to extract honey and insects.\n\n'),
(92280, 132, 'en', 'Swan', 'The swan is a symbol of elegance and grace, gliding seemingly effortlessly over the water. With its long neck and white plumage, it draws eyes everywhere. In your zoo, it forms a picturesque backdrop on the pond and provides calm, romantic moments.'),
(92281, 132, 'de', 'Schwan', 'Der Schwan ist ein Symbol für Eleganz und Anmut und gleitet scheinbar mühelos über das Wasser. Mit seinem langen Hals und dem weißen Gefieder zieht er überall die Blicke auf sich. In deinem Zoo bildet er auf dem Teich eine malerische Kulisse und sorgt für ruhige, romantische Momente.'),
(92282, 132, 'da', 'Svane', 'Svanen er et symbol på elegance og ynde og glider tilsyneladende ubesværet hen over vandet. Med sin lange hals og hvide fjerdragt tiltrækker den opmærksomhed overalt. I din zoo danner den en pittoresk kulisse på søen.'),
(92283, 30261, 'en', 'Takahē', 'The Takahē is a large, flightless bird native to New Zealand, known for its vibrant blue and green plumage with a red bill and legs. It is an endangered species, with fewer than 500 individuals remaining in the wild, primarily in predator-free sanctuaries like Fiordland and offshore islands. They play a key role in alpine tussock ecosystems.\n\nTakahē are herbivorous, feeding on grasses and sedges.\n\n'),
(92284, 30261, 'de', 'Takahē', 'The Takahē is a large, flightless bird native to New Zealand, known for its vibrant blue and green plumage with a red bill and legs. It is an endangered species, with fewer than 500 individuals remaining in the wild, primarily in predator-free sanctuaries like Fiordland and offshore islands. They play a key role in alpine tussock ecosystems.\n\nTakahē are herbivorous, feeding on grasses and sedges.\n\n'),
(92285, 30261, 'da', 'Takahē', 'The Takahē is a large, flightless bird native to New Zealand, known for its vibrant blue and green plumage with a red bill and legs. It is an endangered species, with fewer than 500 individuals remaining in the wild, primarily in predator-free sanctuaries like Fiordland and offshore islands. They play a key role in alpine tussock ecosystems.\n\nTakahē are herbivorous, feeding on grasses and sedges.\n\n'),
(92286, 648, 'en', 'Tamandua', 'The tamandua is a smaller relative of the giant anteater. A skilled climber, it uses its long tongue to reach insects hidden in crevices. In your zoo, it curiously explores climbing structures and food puzzles.'),
(92287, 648, 'de', 'Tamandua', 'Der Tamandua ist ein kleinerer Verwandter des Großen Ameisenbären. Er klettert gut und nutzt seine lange Zunge, um Insekten aus Ritzen zu holen. In deinem Zoo erkundet er neugierig Kletterstrukturen und Futterverstecke.'),
(92288, 648, 'da', 'Kæmpe-brølabe', 'Brølabeørne er de højlydeste landdyr på Jordend og kan høres over 5 km væk. Hannerne bruger disse brøl til at kommunikere territorium og til at koordinere flokbevægelse.'),
(92289, 649, 'en', 'Tamaraw', 'The tamaraw is a small buffalo native to the Philippine island of Mindoro. It is highly endangered and lives in forest and grassland habitats. In your zoo, it is a rare sight that highlights the importance of island ecosystems.'),
(92290, 649, 'de', 'Tamarau', 'Der Tamarau ist ein kleiner Büffel von der Philippineninsel Mindoro. Er ist stark bedroht und lebt in Wald- und Graslandschaften. In deinem Zoo ist er ein seltener Gast und macht auf die Wichtigkeit von Inselökosystemen aufmerksam.'),
(92291, 649, 'da', 'Spejder-abe', 'Spindelaberne er store New World-aber, der er kendte for deres ekstremt lange arme og præhensilehale, der bruges som en femte hånd. De er vitale frøspredere i tropiske regnskove.'),
(92292, 334, 'en', 'Tanuki', 'The tanuki, also called raccoon dog, comes from East Asia and looks like a mix between a raccoon and a dog. In Japanese folklore it is seen as a cheerful, mischievous shapeshifter. In your zoo it is more laid‑back, sniffs around curiously and loves cuddling up with its companions.'),
(92293, 334, 'de', 'Tanuki', 'Der Tanuki, auch Marderhund genannt, stammt aus Ostasien und sieht aus wie eine Mischung aus Waschbär und Hund. In der japanischen Folklore gilt er als fröhlicher, schelmischer Gestaltwandler. In deinem Zoo zeigt er sich eher gemütlich, schnuppert neugierig und kuschelt gern mit Artgenossen.'),
(92294, 334, 'da', 'Vaskebjørnehund', 'Tanukien, også kaldet vaskebjørnehund, stammer fra Østasien og ser ud som en blanding af vaskebjørn og hund. I japansk folklore er den set som en glad, skælmsk formskifter. I din zoo er den mere afslappet, snuser nysgerrigt rundt og elsker at kugle sig op med sine artsfæller.'),
(92295, 136, 'en', 'Tapir', 'The Tapir looks like a mix of pig and little trunk with its short proboscis. It lives in tropical forests and loves bathing breaks in rivers and puddles. In the zoo, it strolls leisurely through its terrain, nibbles leaves, and enjoys lavish mud baths.'),
(92296, 136, 'de', 'Tapir', 'Der Tapir wirkt wie eine Mischung aus Schwein und kleiner Nase mit seinem kurzen Rüssel. Er lebt in tropischen Wäldern und liebt Badepausen in Flüssen und Tümpeln. Im Zoo schlendert er gemütlich durch sein Gelände, knabbert Blätter und genießt ausgiebige Schlammbäder.'),
(92297, 136, 'da', 'Tapir', 'Tapiren ligner en blanding af svin og lille elefantsnude med sin korte snabel. Den lever i tropiske skove og elsker badepause i floder og vandpytter. I din zoo slentre den roligt rundt og nyder lange mudderbade.'),
(92298, 335, 'en', 'Tasmanian Devil', 'The Tasmanian devil is a sturdy marsupial with loud snarls and an impressive bite. It lives in Tasmania and feeds mainly on carrion, but is also a swift hunter. In your zoo it can work itself into a real feeding frenzy, leaving visitors staring in amazement.'),
(92299, 335, 'de', 'Tasmanischer Teufel', 'Der Tasmanische Teufel ist ein kräftiges Beuteltier mit lautem Gebissknurren und beeindruckender Beißkraft. Er lebt in Tasmanien und frisst vor allem Aas, ist aber auch ein schneller Jäger. In deinem Zoo rollt er sich beim Fressen in echte Futterrausche, was bei Besuchern für staunende Gesichter sorgt.'),
(92300, 335, 'da', 'Tasmansk djævel', 'Den tasmanske djævel er et kraftigt pungdyr med høje gnydenbrøl og imponerende bidekraft. Den lever i Tasmanien og ernærer sig primært af ådsler, men er også en rask jæger. I din zoo kan den arbejde sig op i en rigtig foderraptus, hvilket får besøgende til at stare forbløffede.'),
(92301, 30262, 'en', 'Tawny Frogmouth', 'Tawny Frogmouth are large, big-headed birds native to Australia that are often mistaken for an owl due to their nocturnal habits and similar coloring. These are stocky and compact birds with rounded wings and short legs. They have wide, heavy, olive-grey to blackish bills that are hooked at the tip and topped with distinctive tufts of bristles. Their eyes are large and yellow in color. Tawny Frogmouths have three distinct color morphs, grey being the most common in both sexes. \n\nTawny Frogmouths are carnivores and feed mainly on large nocturnal insects, such as moths, as well as spiders, worms, slugs, and snails.\n\n'),
(92302, 30262, 'de', 'Tawny Frogmouth', 'Tawny Frogmouth are large, big-headed birds native to Australia that are often mistaken for an owl due to their nocturnal habits and similar coloring. These are stocky and compact birds with rounded wings and short legs. They have wide, heavy, olive-grey to blackish bills that are hooked at the tip and topped with distinctive tufts of bristles. Their eyes are large and yellow in color. Tawny Frogmouths have three distinct color morphs, grey being the most common in both sexes. \n\nTawny Frogmouths are carnivores and feed mainly on large nocturnal insects, such as moths, as well as spiders, worms, slugs, and snails.\n\n'),
(92303, 30262, 'da', 'Tawny Frogmouth', 'Tawny Frogmouth are large, big-headed birds native to Australia that are often mistaken for an owl due to their nocturnal habits and similar coloring. These are stocky and compact birds with rounded wings and short legs. They have wide, heavy, olive-grey to blackish bills that are hooked at the tip and topped with distinctive tufts of bristles. Their eyes are large and yellow in color. Tawny Frogmouths have three distinct color morphs, grey being the most common in both sexes. \n\nTawny Frogmouths are carnivores and feed mainly on large nocturnal insects, such as moths, as well as spiders, worms, slugs, and snails.\n\n'),
(92304, 30263, 'en', 'Thresher Shark', 'The Thresher Shark is a large species of shark known for its extremely long caudal fin (tail fin), which can be as long as its body. Adults typically measure 3–6 meters (10–20 feet) in length and weigh up to 500 kg (1,100 lbs). They have a streamlined body, a short pointed snout, and curved pectoral fins. \n\nTheir diet consists mainly of small fish, squid, and octopuses, which they hunt using their long tail to stun prey. \n\n'),
(92305, 30263, 'de', 'Thresher Shark', 'The Thresher Shark is a large species of shark known for its extremely long caudal fin (tail fin), which can be as long as its body. Adults typically measure 3–6 meters (10–20 feet) in length and weigh up to 500 kg (1,100 lbs). They have a streamlined body, a short pointed snout, and curved pectoral fins. \n\nTheir diet consists mainly of small fish, squid, and octopuses, which they hunt using their long tail to stun prey. \n\n'),
(92306, 30263, 'da', 'Thresher Shark', 'The Thresher Shark is a large species of shark known for its extremely long caudal fin (tail fin), which can be as long as its body. Adults typically measure 3–6 meters (10–20 feet) in length and weigh up to 500 kg (1,100 lbs). They have a streamlined body, a short pointed snout, and curved pectoral fins. \n\nTheir diet consists mainly of small fish, squid, and octopuses, which they hunt using their long tail to stun prey. \n\n'),
(92307, 721, 'en', 'Tibetan Fox', 'The Tibetan fox has a characteristically angular face and lives in highland regions. His thick fur protects him from wind and cold. In your zoo, he stands out with his distinctive features and calm manner.'),
(92308, 721, 'de', 'Tibetfuchs', 'Der Tibetfuchs hat einen charakteristisch kantigen Kopf und lebt in Hochlandregionen. Sein dichtes Fell schützt ihn vor Wind und Kälte. In deinem Zoo fällt er durch sein besonderes Gesicht und seine ruhige Art auf.'),
(92309, 721, 'da', 'Hvalros (unge)', 'Unge hvalrosser er afhængige af deres mødre i op til to år og er sociale dyr, der er hurtige til at lære. De tilbringer meget tid i vandet og øver sig i at svømme og dykke under beskyttelse af flokken.'),
(92310, 838, 'en', 'Tiger Shark', 'The tiger shark is a large shark with a striped body pattern. It’s not picky when it comes to food. In your zoo, it swims majestic circles and impresses with its sheer power.'),
(92311, 838, 'de', 'Tigerhai', 'Der Tigerhai ist ein großer Hai mit Streifenmuster auf dem Körper. Er ist wenig wählerisch bei der Nahrung. In deinem Zoo zieht er majestätisch seine Runden und beeindruckt durch seine Kraft.'),
(92312, 838, 'da', 'Søstjerne', 'Søstjernen er et fascinerende pignehudsdyr med fem arme (eller flere). Den har en unik evne til at genskabe tabte arme. Den fordøjer sit bytte delvist udenfor kroppen ved at krampe sin mave ud.'),
(92313, 641, 'en', 'Toco Toucan', 'The toco toucan is a tropical bird with an enormous, brightly colored beak. It uses it to pick fruit and even to help cool down. In your zoo, its fascinating beak makes it a true eye-catcher as it perches among the branches.'),
(92314, 641, 'de', 'Riesentukan', 'Der Riesentukan ist ein tropischer Vogel mit riesigem, farbenprächtigem Schnabel. Er nutzt diesen, um Früchte zu greifen und sich abzukühlen. In deinem Zoo ist er mit seinem Schnabel ein echter Hingucker, wenn er auf Ästen sitzt.'),
(92315, 641, 'da', 'Kamgekko', 'Geckoen er en fascinerende firben med enestående egenskaber. Dens fødder er dækket af millioner af bittesmå hår, der giver den mulighed for at klatre på næsten enhver overflade, selv glas.'),
(92316, 30264, 'en', 'Tokay Gecko', 'The Tokay Gecko is a nocturnal arboreal gecko in the genus Gekko, the true geckos. It is one of the largest gecko species. The skin of Tokay Geckos is soft to the touch and is generally gray with red speckles. However, Tokay Geckos can change the color of their skin to blend into the environment. They are strong climbers with foot pads that can support the entire weight of the body on a vertical surface for a long period of time.\n\nTokay Geckos are carnivores (insectivores) that feed mainly on insects and small vertebrates. Their diet consists of beetles, ants, spiders, moths, grasshoppers, termites, crickets, and mosquitos. \n\n'),
(92317, 30264, 'de', 'Tokay Gecko', 'The Tokay Gecko is a nocturnal arboreal gecko in the genus Gekko, the true geckos. It is one of the largest gecko species. The skin of Tokay Geckos is soft to the touch and is generally gray with red speckles. However, Tokay Geckos can change the color of their skin to blend into the environment. They are strong climbers with foot pads that can support the entire weight of the body on a vertical surface for a long period of time.\n\nTokay Geckos are carnivores (insectivores) that feed mainly on insects and small vertebrates. Their diet consists of beetles, ants, spiders, moths, grasshoppers, termites, crickets, and mosquitos. \n\n'),
(92318, 30264, 'da', 'Tokay Gecko', 'The Tokay Gecko is a nocturnal arboreal gecko in the genus Gekko, the true geckos. It is one of the largest gecko species. The skin of Tokay Geckos is soft to the touch and is generally gray with red speckles. However, Tokay Geckos can change the color of their skin to blend into the environment. They are strong climbers with foot pads that can support the entire weight of the body on a vertical surface for a long period of time.\n\nTokay Geckos are carnivores (insectivores) that feed mainly on insects and small vertebrates. Their diet consists of beetles, ants, spiders, moths, grasshoppers, termites, crickets, and mosquitos. \n\n'),
(92319, 839, 'en', 'Trumpeter Swan', 'The trumpeter swan is a large species with a deep, trumpet-like call. It lives in North America. In your zoo, its resonant calls create memorable acoustic moments.'),
(92320, 839, 'de', 'Trompetenschwan', 'Der Trompetenschwan ist eine große Schwanenart mit tiefem, trompetenähnlichem Ruf. Er lebt in Nordamerika. In deinem Zoo sorgt sein Gesang für besondere akustische Momente.'),
(92321, 839, 'da', 'Havsnegl', 'Nøgensneglene er en gruppe havsnegles mangfoldige og farverige farvepragt. De bruger disse farver til at advare rovdyr om, at de er giftige. De mister deres skal tidligt i udviklingen.'),
(92322, 337, 'en', 'Tundra Wolf', 'The tundra wolf lives in the cold regions of the far north and has a dense, pale winter coat. It hunts in packs and covers long distances across the open tundra. In your zoo it shows off its social skills within the group and impresses everyone with its haunting howls.'),
(92323, 337, 'de', 'Tundrawolf', 'Der Tundrawolf lebt in den kalten Regionen des Nordens und besitzt ein dichtes, helles Winterfell. Er jagt im Rudel und legt große Strecken in der Weite der Tundra zurück. In deinem Zoo zeigt er in der Gruppe seine sozialen Fähigkeiten und beeindruckt mit durchdringendem Heulen.'),
(92324, 337, 'da', 'Tundrauf', 'Tundrauven lever i de kolde nordlige egne og har et tykt, lyst vinterpels. Den jager i flokke og tilbagelægger store afstande hen over den åbne tundra. I din zoo viser den sin sociale kompetence i flokken og imponerer alle med sit spøgelsesfyldte hyl.'),
(92325, 428, 'en', 'Valais Blacknose', 'The Valais Blacknose sheep stands out with its black facial markings and curly white fleece. Originating from the Swiss Alps, it is known for its hardiness. In your zoo, it charms visitors with its gentle expression and cuddly, plush-like appearance.'),
(92326, 428, 'de', 'Walliser Schwarznasenschaf', 'Das Walliser Schwarznasenschaf ist mit seiner schwarzen Gesichtszeichnung und dem weißen, lockigen Fell besonders auffällig. Es stammt aus den Schweizer Alpen und gilt als sehr robust. In deinem Zoo verzaubert es Besucher mit seinem freundlichen Blick und der plüschigen Erscheinung.'),
(92327, 428, 'da', 'Valaisisk sortnesedfar', 'Det valesiske sortnesedfår skiller sig ud med sine sorte ansigtstegninger og krøllede hvide uld. Det stammer fra de schweiziske Alper og er kendt for sin robusthed. I din zoo tryllebinder det besøgende med sit venlige udtryk og plysagtige fremtræden.'),
(92328, 30265, 'en', 'Vampire Squid', 'The Vampire Squid is a unique deep-sea cephalopod found in the dark depths of the ocean, typically at depths of 2,000 to 3,000 feet (600 to 1,200 meters). Despite its name, it is not a true squid but rather belongs to its own order, Vampyromorphida. The Vampire Squid has a distinctive appearance, featuring large, red eyes, a cloak-like web of skin connecting its arms, and bioluminescent capabilities. \n\nThe Vampire Squid primarily feeds on detritus and organic matter that falls from the upper layers of the ocean, using its specialized feeding apparatus to capture food.\n\n'),
(92329, 30265, 'de', 'Vampire Squid', 'The Vampire Squid is a unique deep-sea cephalopod found in the dark depths of the ocean, typically at depths of 2,000 to 3,000 feet (600 to 1,200 meters). Despite its name, it is not a true squid but rather belongs to its own order, Vampyromorphida. The Vampire Squid has a distinctive appearance, featuring large, red eyes, a cloak-like web of skin connecting its arms, and bioluminescent capabilities. \n\nThe Vampire Squid primarily feeds on detritus and organic matter that falls from the upper layers of the ocean, using its specialized feeding apparatus to capture food.\n\n'),
(92330, 30265, 'da', 'Vampire Squid', 'The Vampire Squid is a unique deep-sea cephalopod found in the dark depths of the ocean, typically at depths of 2,000 to 3,000 feet (600 to 1,200 meters). Despite its name, it is not a true squid but rather belongs to its own order, Vampyromorphida. The Vampire Squid has a distinctive appearance, featuring large, red eyes, a cloak-like web of skin connecting its arms, and bioluminescent capabilities. \n\nThe Vampire Squid primarily feeds on detritus and organic matter that falls from the upper layers of the ocean, using its specialized feeding apparatus to capture food.\n\n'),
(92331, 816, 'en', 'Vaquita', 'The California porpoise is one of the smallest whales and lives along the west coast of North America. It is inconspicuous and often stays close to shore. In your zoo it quietly glides through the water and shows that greatness does not always mean big size.'),
(92332, 816, 'de', 'Kalifornischer Schweinswal', 'Der Kalifornische Schweinswal ist einer der kleinsten Wale und lebt an der Westküste Nordamerikas. Er ist unauffällig und bleibt oft in Küstennähe. In deinem Zoo zieht er leise seine Bahnen und zeigt, dass Großes nicht immer groß sein muss.'),
(92333, 816, 'da', 'Sæl (monket)', 'Munksælen er en af de mest truede havpattedyr i verden. I modsætning til andre sæler trives den i varme Middelhavsomgivelser. Den er et sjældent syn og kræver aktiv bevaringsindsats for at overleve.'),
(92334, 30266, 'en', 'Variegated Squirrel', 'The Variegated Squirrel is a medium-sized rodent native to Central America. Characterized by its striking fur, which features a mix of gray, brown, and reddish hues, this squirrel has a bushy tail and large, expressive eyes. This diurnal and arboreal species is generally solitary, building nests high in trees from twigs and leaves. It is an agile climber, adept at navigating its forested habitat.\n\nThe Variegated Squirrel primarily feeds on fruits, seeds, and flowers, and is known for its preference for soft fruits.\n\n'),
(92335, 30266, 'de', 'Variegated Squirrel', 'The Variegated Squirrel is a medium-sized rodent native to Central America. Characterized by its striking fur, which features a mix of gray, brown, and reddish hues, this squirrel has a bushy tail and large, expressive eyes. This diurnal and arboreal species is generally solitary, building nests high in trees from twigs and leaves. It is an agile climber, adept at navigating its forested habitat.\n\nThe Variegated Squirrel primarily feeds on fruits, seeds, and flowers, and is known for its preference for soft fruits.\n\n'),
(92336, 30266, 'da', 'Variegated Squirrel', 'The Variegated Squirrel is a medium-sized rodent native to Central America. Characterized by its striking fur, which features a mix of gray, brown, and reddish hues, this squirrel has a bushy tail and large, expressive eyes. This diurnal and arboreal species is generally solitary, building nests high in trees from twigs and leaves. It is an agile climber, adept at navigating its forested habitat.\n\nThe Variegated Squirrel primarily feeds on fruits, seeds, and flowers, and is known for its preference for soft fruits.\n\n'),
(92337, 325, 'en', 'Virginia Opossum', 'The Virginia opossum is the only marsupial native to North America and a true survival artist. When threatened, it sometimes plays dead to fool its enemies. In your zoo it nosedives into food hiding places and shows how versatile such a small marsupial can be.'),
(92338, 325, 'de', 'Nordopossum', 'Das Nordopossum ist das einzige Beuteltier Nordamerikas und ein echter Überlebenskünstler. Es stellt sich bei Gefahr manchmal tot, um Feinde zu täuschen. In deinem Zoo durchstöbert es neugierig Futterverstecke und zeigt, wie vielseitig ein kleiner Beutler sein kann.'),
(92339, 325, 'da', 'Virginiaopossum', 'Virginiaopossumen er det eneste pungdyr i Nordamerika og en ægte overlevelseskunstner. Når det trues, spiller det somme tider død for at narre sine fjender. I din zoo stikker det nysgerrigt næsen ind i madgemmer og viser, hvor alsidig et lille pungdyr kan være.'),
(92340, 840, 'en', 'Walrus', 'The walrus is a large marine mammal with impressive tusks. It loves resting together on ice floes. In your zoo, its sounds and appearance bring a true arctic atmosphere.'),
(92341, 840, 'de', 'Walross', 'Das Walross ist ein großes Meeressäugetier mit riesigen Stoßzähnen. Es liebt Eisschollen und ruht gern in Gruppen. In deinem Zoo sorgt es mit seinen Lauten und seiner Erscheinung für arktisches Flair.'),
(92342, 840, 'da', 'Havsval', 'Havsvalerne er en gruppe pignehudsdyr, der lever på havbunden og spiser organisk materiale fra sedimentet. Når de er truede, kaster de deres indre organer ud som et forsvarsmiddel og kan gro nye.'),
(92343, 429, 'en', 'Wapiti', 'The wapiti, or elk, is a North American deer with an impressive set of antlers. During the mating season, its distinctive high-pitched call echoes through the forests. In your zoo, it impresses with its size and majestic presence.'),
(92344, 429, 'de', 'Wapiti', 'Das Wapiti ist ein nordamerikanischer Hirsch mit beeindruckendem Geweih. Zur Brunftzeit ertönt sein charakteristischer, heller Ruf weit durch die Wälder. In deinem Zoo beeindruckt er mit seiner Größe und seiner majestätischen Ausstrahlung.'),
(92345, 429, 'da', 'Wapiti', 'Wapitien er en nordamerikansk hjort med et imponerende gevir. I brunstiden lyder dens karakteristiske, klare råb vidt gennem skovene. I din zoo imponerer den med sin størrelse og majestætiske udstråling.'),
(92346, 530, 'en', 'Warthog', 'The warthog has striking skin ridges on its face and impressive tusks. It lives in Africa and is a good runner with lots of character. In your zoo it happily roots in the soil and thoroughly turns over every muddy spot.'),
(92347, 530, 'de', 'Warzenschwein', 'Das Warzenschwein trägt auffällige Hautwülste im Gesicht und beeindruckende Hauer. Es lebt in Afrika und ist ein guter Läufer mit viel Charakter. In deinem Zoo wühlt es fröhlich im Boden und räumt jeden Schlammplatz gründlich um.'),
(92348, 530, 'da', 'Grevys sebra', 'Grévy\'s zebra er den største zebraart og kan kendes på sine tætte, smalle striber og store, afrundede ører. Den er stærkt truet og lever primært i Kenya og Etiopien.'),
(92349, 30267, 'en', 'Water Deer', 'Water Deer is small, secretive deer native to East Asia. Its most striking feature is the pair of long, protruding tusks from the upper jaw in both sexes, used for combat and defense. Coat is coarse, reddish-brown in summer fading to grayish in winter, with a paler belly. Ears are short and rounded, eyes large and alert.\n\nThe Water Deer is a herbivore, primarily feeding on soft green grasses, herbs, sedges, and aquatic plants.\n\n'),
(92350, 30267, 'de', 'Water Deer', 'Water Deer is small, secretive deer native to East Asia. Its most striking feature is the pair of long, protruding tusks from the upper jaw in both sexes, used for combat and defense. Coat is coarse, reddish-brown in summer fading to grayish in winter, with a paler belly. Ears are short and rounded, eyes large and alert.\n\nThe Water Deer is a herbivore, primarily feeding on soft green grasses, herbs, sedges, and aquatic plants.\n\n'),
(92351, 30267, 'da', 'Water Deer', 'Water Deer is small, secretive deer native to East Asia. Its most striking feature is the pair of long, protruding tusks from the upper jaw in both sexes, used for combat and defense. Coat is coarse, reddish-brown in summer fading to grayish in winter, with a paler belly. Ears are short and rounded, eyes large and alert.\n\nThe Water Deer is a herbivore, primarily feeding on soft green grasses, herbs, sedges, and aquatic plants.\n\n'),
(92352, 113, 'en', 'Wattled Crane', 'The Demoiselle Crane gets its name from the striking ornamental feathers and skin flaps on its head and neck. Like all cranes, it\'s an elegant dancer that impresses with wing beats and jumps. In the zoo, the birds strut through the enclosure and love to be admired while preening their magnificent plumage.'),
(92353, 113, 'de', 'Klunkerkranich', 'Der Klunkerkranich trägt seinen Namen wegen der auffälligen Schmuckfedern und Hautlappen an Kopf und Hals. Wie alle Kraniche ist er ein eleganter Tänzer, der mit Flügelschlägen und Sprüngen imponiert. Im Zoo stolzieren die Tiere durch das Gehege und lassen sich beim Putzen ihres prachtvollen Gefieders gerne bestaunen.'),
(92354, 113, 'da', 'Klunketrane', 'Klunketranen bærer sit navn på grund af de iøjnefaldende prydfjere og hudlapper på hoved og hals. I din zoo marcherer den stolt gennem indhegningen og viser sine elegante dansetrin frem for publikum.'),
(92355, 304, 'en', 'Western Crowned Pigeon', 'The Victoria crowned pigeon is one of the largest pigeon species in the world and wears a splendid feather crown. It comes from the rainforests of New Guinea and usually moves calmly along the forest floor. In your zoo it walks dignifiedly through its enclosure, proudly showing off its elegant headpiece.'),
(92356, 304, 'de', 'Blauschopf Krontaube', 'Die Blauschopf-Krontaube zählt zu den größten Taubenarten der Welt und trägt eine prächtige Federkrone. Sie stammt aus den Regenwäldern Neuguineas und bewegt sich meist ruhig am Boden. In deinem Zoo schreitet sie würdevoll durchs Gehege und zeigt stolz ihre elegante Kopfbedeckung.'),
(92357, 304, 'da', 'Vestlig krondue', 'Den vestlige krondue er en af de største duearter i verden med en pragtfuld fjerhat. Den stammer fra Ny Guineas regnskove. I din zoo skærer den ærværdigt gennem sit anlæg og viser stolt sin elegante fjerhat frem.'),
(92358, 652, 'en', 'Western Lowland Gorilla', 'The western lowland gorilla is one of the best-known gorilla subspecies and is critically endangered. It inhabits the rainforests of Africa and mainly feeds on plants. In your zoo, it’s a gentle giant whose family life creates deeply touching moments.'),
(92359, 652, 'de', 'Westlicher Flachlandgorilla', 'Der Westliche Flachlandgorilla ist eine der bekannten Gorilla-Unterarten und stark bedroht. Er lebt in den Regenwäldern Afrikas und ernährt sich vorwiegend von Pflanzen. In deinem Zoo ist er ein sanfter Gigant, der mit seiner Familie für viele bewegende Momente sorgt.'),
(92360, 652, 'da', 'Kæmpe-tapir', 'Den malaysiske tapir er den største af tapirarterne og er kendetegnet ved sin markante to-farvede farve — sort foran og hvid bagpå. Den er stærkt truet på grund af habitatsødelæggelse.'),
(92361, 30268, 'en', 'Whale Shark', 'The Whale Shark is the largest fish species in the world, reaching lengths of up to 12 meters (39 feet) or more. They are Characterized by their massive size, wide mouth, and distinctive pattern of white spots and stripes on a dark gray body. Found in warm, tropical oceans, Whale Sharks are known for their migratory behavior and often gather in large numbers at feeding sites. Despite their size, they pose no threat to humans and are often sought after for ecotourism.\n\nWhale Shark is a gentle filter feeder that primarily consumes plankton, small fish, and other tiny marine organisms.\n\n'),
(92362, 30268, 'de', 'Whale Shark', 'The Whale Shark is the largest fish species in the world, reaching lengths of up to 12 meters (39 feet) or more. They are Characterized by their massive size, wide mouth, and distinctive pattern of white spots and stripes on a dark gray body. Found in warm, tropical oceans, Whale Sharks are known for their migratory behavior and often gather in large numbers at feeding sites. Despite their size, they pose no threat to humans and are often sought after for ecotourism.\n\nWhale Shark is a gentle filter feeder that primarily consumes plankton, small fish, and other tiny marine organisms.\n\n'),
(92363, 30268, 'da', 'Whale Shark', 'The Whale Shark is the largest fish species in the world, reaching lengths of up to 12 meters (39 feet) or more. They are Characterized by their massive size, wide mouth, and distinctive pattern of white spots and stripes on a dark gray body. Found in warm, tropical oceans, Whale Sharks are known for their migratory behavior and often gather in large numbers at feeding sites. Despite their size, they pose no threat to humans and are often sought after for ecotourism.\n\nWhale Shark is a gentle filter feeder that primarily consumes plankton, small fish, and other tiny marine organisms.\n\n'),
(92364, 319, 'en', 'Whiptail Wallaby', 'The pretty‑faced wallaby is a small kangaroo with an especially gentle facial expression. It lives in Australia and prefers bushy habitats. In your zoo it hops quietly through its enclosure and looks at visitors with big, curious eyes.'),
(92365, 319, 'de', 'Hübschgesichtwallaby', 'Das Hübschgesichtwallaby ist ein kleines Känguru mit besonders sanftem Gesichtsausdruck. Es lebt in Australien und bevorzugt buschige Lebensräume. In deinem Zoo hüpft es leise durch das Gehege und schaut die Besucher mit großen Augen neugierig an.'),
(92366, 319, 'da', 'Blegtfacewallaby', 'Det blegnede wallaby er en lille kenguru med et særligt blidt ansigtsudtryk. Det lever i Australien og foretrækker buskede levesteder. I din zoo hopper det stille igennem sit anlæg og kigger nysgerrigt på besøgende med store øjne.'),
(92367, 844, 'en', 'White Pelican', 'The pink pelican is a large water bird with delicately rose-colored plumage. It catches fish using its large throat pouch. In your zoo, it glides gracefully across the water and dries its wings in the sun.'),
(92368, 844, 'de', 'Rosa Pelikan', 'Der Rosa Pelikan ist ein großer Wasservogel mit zart rosafarbenem Gefieder. Er fischt mit seinem großen Kehlsack nach Beute. In deinem Zoo gleitet er elegant über die Wasserfläche und trocknet seine Flügel in der Sonne.'),
(92369, 844, 'da', 'Mandarinfisk', 'Mandarinfisken er en af de smukkeste fisk i verden med sit lysende blå og orange mønster. Den er hjemmehørende i det vestlige Stillehav og lever i lavt koralrev-vand. Den er aktiv om natten.'),
(92370, 506, 'en', 'White Rhinoceros', 'The White Rhinoceros has a broad, square muzzle that is ideal for grazing. It lives in Africa and spends much of its time eating and resting. In your zoo, it is an impressive giant, yet usually appears surprisingly calm.'),
(92371, 506, 'de', 'Breitmaulnashorn', 'Das Breitmaulnashorn hat ein breites, quadratisches Maul, das ideal zum Grasen ist. Es lebt in Afrika und verbringt viel Zeit mit Fressen und Ruhen. In deinem Zoo ist es ein beeindruckender Gigant, der jedoch meist überraschend gelassen wirkt.'),
(92372, 506, 'da', 'Flodhest', 'På trods af sit massive udseende er flodhesten et af Afrikas farligste dyr. Den tilbringer det meste af dagen i vand for at holde sig kølig og beskyttet mod solen.'),
(92373, 139, 'en', 'White Stork', 'The White Stork is known to many as a bringer of luck who supposedly delivers babies. It likes to breed on high roofs and chimneys and returns to its nests year after year. In your zoo, it stalks through the enclosure, clatters its beak, and keeps an eye out for treats.'),
(92374, 139, 'de', 'Weißstorch', 'Der Weißstorch ist vielen als Glücksbringer bekannt, der angeblich Babys bringt. Er brütet gerne auf hohen Dächern und Schornsteinen und kehrt Jahr für Jahr an seine Nester zurück. In deinem Zoo stakst er durch das Gehege, klappert mit dem Schnabel und hält nach Leckerbissen Ausschau.'),
(92375, 139, 'da', 'Hvid stork', 'Den hvide stork er for mange et symbol på lykke og fortælles at bringe babyer. Den ruger gerne på høje tage og skorstene og vender år efter år tilbage til sine reder. I din zoo stalker den igennem indhegningen og holder øje med lækkerier.'),
(92376, 504, 'en', 'White-Backed Vulture', 'The White‑backed African Vulture is a scavenger that plays an important role in the ecosystem. It keeps the savanna clean by quickly removing carcasses. In your zoo, it impressively shows that even less popular animals are true environmental helpers.'),
(92377, 504, 'de', 'Afrikanischer Weissrückengeier', 'Der Afrikanische Weißrückengeier ist ein Aasfresser, der eine wichtige Rolle im Ökosystem spielt. Er hält die Savanne sauber, indem er Kadaver schnell beseitigt. In deinem Zoo zeigt er eindrucksvoll, dass auch weniger beliebte Tiere echte Umwelthelfer sind.'),
(92378, 504, 'da', 'Hyæne', 'Hyænen er en af Afrikas mest misforståede dyr. De er faktisk dygtige jægere og lever i komplekse matrilineære samfund med strenge hierarkier.'),
(92379, 30269, 'en', 'White-Beaked Dolphin', 'The White‑Beaked Dolphin is a robust, muscular dolphin with a short, thick beak that is usually pale gray or white, giving the species its name. Its body is dark gray to black on top with lighter gray patches along the sides and a white belly. It has a tall, curved dorsal fin and a strong, compact build adapted for cold North Atlantic waters.\n\nWhite‑Beaked Dolphins mainly eat small schooling fish, such as cod, haddock, herring, and whiting, along with squid and crustaceans.\n\n'),
(92380, 30269, 'de', 'White-Beaked Dolphin', 'The White‑Beaked Dolphin is a robust, muscular dolphin with a short, thick beak that is usually pale gray or white, giving the species its name. Its body is dark gray to black on top with lighter gray patches along the sides and a white belly. It has a tall, curved dorsal fin and a strong, compact build adapted for cold North Atlantic waters.\n\nWhite‑Beaked Dolphins mainly eat small schooling fish, such as cod, haddock, herring, and whiting, along with squid and crustaceans.\n\n'),
(92381, 30269, 'da', 'White-Beaked Dolphin', 'The White‑Beaked Dolphin is a robust, muscular dolphin with a short, thick beak that is usually pale gray or white, giving the species its name. Its body is dark gray to black on top with lighter gray patches along the sides and a white belly. It has a tall, curved dorsal fin and a strong, compact build adapted for cold North Atlantic waters.\n\nWhite‑Beaked Dolphins mainly eat small schooling fish, such as cod, haddock, herring, and whiting, along with squid and crustaceans.\n\n'),
(92382, 531, 'en', 'White-Faced Owl', 'The white‑faced owl stands out with its contrasting face and large eyes. It is a silent night hunter that surprises small prey. In your zoo it likes to stay hidden by day and turns into a silent hunter by night.'),
(92383, 531, 'de', 'Weissgesichtseule', 'Die Weißgesichtseule fällt durch ihr kontrastreiches Gesicht und die großen Augen auf. Sie ist ein lautloser Nachtjäger, der kleine Beutetiere überrascht. In deinem Zoo sitzt sie tagsüber gern versteckt und wird nachts zur lautlosen Jägerin.'),
(92384, 531, 'da', 'Kamel', 'Kamelens pukkel indeholder ikke vand, som mange tror, men fedt. Dette fedt kan omdannes til energi og vand, når mad og drikke er knappe. Kamelet kan drikke op til 200 liter vand på én gang.'),
(92385, 533, 'en', 'White-Headed Vulture', 'The lappet‑faced vulture has, as the name suggests, a woolly‑looking head plumage. It is an important scavenger and helps keep nature clean. In your zoo it soars above the enclosure and shows that even vultures can radiate impressive majesty.'),
(92386, 533, 'de', 'Wollkopfgeier', 'Der Wollkopfgeier hat, wie der Name sagt, ein wollig wirkendes Kopfgefieder. Er ist ein wichtiger Aasfresser und sorgt für Sauberkeit in der Natur. In deinem Zoo kreist er über dem Gehege und zeigt, dass auch Geier beeindruckende Majestät ausstrahlen können.'),
(92387, 533, 'da', 'Warthog', 'Det almindelige vortesvin er et robust og opportunistisk dyr, der lever i savanner og åbne skove. Det er kendetegnet ved sine knoglede ansigtsvorter og sable-lignende hugtænder.'),
(92388, 532, 'en', 'White-Tailed Mongoose', 'The white‑tailed mongoose is a small carnivore with a light tip on its tail. It lives in groups and is very active. In your zoo it darts curiously through the enclosure and examines everything closely.'),
(92389, 532, 'de', 'Weissschwanzmanguste', 'Die Weißschwanzmanguste ist eine kleine Raubtierart mit hellem Schwanzende. Sie lebt in Gruppen und ist sehr aktiv. In deinem Zoo flitzt sie neugierig durch das Gehege und untersucht alles ganz genau.');
INSERT INTO `animaltext` (`id`, `animalId`, `languageCode`, `animalName`, `animalDescription`) VALUES
(92390, 532, 'da', 'Dromader', 'Dromedaren, eller enkeltpuklede kamel, er et mesterligt tilpasset ørkendyr. Den er beregnet til transport og har tjent mennesker i tusinder af år som pakkehest i tørre regioner.'),
(92391, 340, 'en', 'Wild Boar', 'The wild boar is the wild relative of our domestic pig and feels at home in forests and fields. It is a powerful digger and loves mud and moist soil. In your zoo it wallows cheerfully and grunts with satisfaction when it finds tasty roots.'),
(92392, 340, 'de', 'Wildschwein', 'Das Wildschwein ist der wilde Verwandte unseres Hausschweins und fühlt sich in Wäldern und Feldern wohl. Es ist ein kräftiger Wühler und liebt Schlamm und feuchtes Erdreich. In deinem Zoo suhlt es sich vergnügt und grunzt zufrieden, wenn es leckere Wurzeln findet.'),
(92393, 340, 'da', 'Vildsvin', 'Vildsvienet er den vilde slægtning til vores tamgris og trives i skove og marker. Det er en kraftig graver og elsker mudder og fugtig jord. I din zoo roder det glad i jorden og grynter tilfreds, når det finder lækre rødder.'),
(92394, 431, 'en', 'Wolf', 'The wolf is a highly social pack animal with a strong hunting instinct. It communicates through sounds, body language, and scent. In your zoo, the pack impressively demonstrates just how vital cooperation can be in the animal world.'),
(92395, 431, 'de', 'Wolf', 'Der Wolf ist ein hochsoziales Rudeltier mit ausgeprägtem Jagdinstinkt. Er kommuniziert über Laute, Körpersprache und Gerüche. In deinem Zoo zeigt das Rudel eindrucksvoll, wie wichtig Zusammenhalt im Tierreich sein kann.'),
(92396, 431, 'da', 'Ulv', 'Ulven er et yderst socialt flokvæsen med en stærk jagtinstinkt. Den kommunikerer via lyde, kropssprog og duft. I din zoo viser flokken imponerende, hvor vigtig sammenholdet er i dyreriget.'),
(92397, 722, 'en', 'Wolverine', 'The wolverine is a sturdy, muscular mustelid with impressive stamina. He roams large territories and is a clever scavenger and hunter. In your zoo, he shows that plenty of temper fits into a relatively small body.'),
(92398, 722, 'de', 'Vielfraß', 'Der Vielfraß ist ein kräftiger Marder mit beeindruckender Ausdauer. Er durchstreift große Gebiete und ist ein geschickter Aasfresser und Jäger. In deinem Zoo zeigt er, dass viel Temperament in einem relativ kleinen Körper stecken kann.'),
(92399, 722, 'da', 'Arktisk tern', 'Den arktiske terne holder verdens længste migration og rejser hvert år fra Arktis til Antarktis og tilbage — en tur på op til 90.000 km. Den ser mere dagslys end noget andet dyr på Jordend.'),
(92400, 30270, 'en', 'Yacare Caiman', 'The Yacare Caiman is a medium-sized crocodilian found primarily in the freshwater habitats of South America. It has a robust body with a broad snout, and its coloration ranges from dark brown to olive green, often featuring lighter spots or stripes. The Yacare Caiman typically grows to about 2 to 2.5 meters (6.5 to 8.2 feet) in length. It inhabits rivers, lakes, and wetlands, often preferring areas with abundant vegetation.\n\nThis caiman primarily feeds on fish, crustaceans, and small mammals, using its powerful jaws to catch prey.\n\n'),
(92401, 30270, 'de', 'Yacare Caiman', 'The Yacare Caiman is a medium-sized crocodilian found primarily in the freshwater habitats of South America. It has a robust body with a broad snout, and its coloration ranges from dark brown to olive green, often featuring lighter spots or stripes. The Yacare Caiman typically grows to about 2 to 2.5 meters (6.5 to 8.2 feet) in length. It inhabits rivers, lakes, and wetlands, often preferring areas with abundant vegetation.\n\nThis caiman primarily feeds on fish, crustaceans, and small mammals, using its powerful jaws to catch prey.\n\n'),
(92402, 30270, 'da', 'Yacare Caiman', 'The Yacare Caiman is a medium-sized crocodilian found primarily in the freshwater habitats of South America. It has a robust body with a broad snout, and its coloration ranges from dark brown to olive green, often featuring lighter spots or stripes. The Yacare Caiman typically grows to about 2 to 2.5 meters (6.5 to 8.2 feet) in length. It inhabits rivers, lakes, and wetlands, often preferring areas with abundant vegetation.\n\nThis caiman primarily feeds on fish, crustaceans, and small mammals, using its powerful jaws to catch prey.\n\n'),
(92403, 724, 'en', 'Yak', 'The yak is a high‑altitude bovid from Asia with thick, long fur. He is perfectly adapted to thin air and cold. In your zoo, he looks like a cozy fur mountain calmly crossing the enclosure.'),
(92404, 724, 'de', 'Yak', 'Das Yak ist ein Rind aus den Hochlagen Asiens mit dichtem, langem Fell. Es ist perfekt an dünne Luft und Kälte angepasst. In deinem Zoo wirkt es wie ein gemütlicher Fellberg, der ruhig über das Gehege zieht.'),
(92405, 724, 'da', 'Arktisk hund (Samojet)', 'Samoyeden er en hunderace med oprindelse hos de sibiriske samojed-nomader. Den bruges traditionelt til slæde- og vogterhunde og har en tyk, hvid dobbeltpels der holder dem varme i ekstreme kulde.'),
(92406, 706, 'en', 'Yakutian Horse', 'The Yakutian horse lives in extremely cold regions of Siberia and is very robust. His thick winter coat withstands temperatures far below freezing. In your zoo, he calmly braves cooler temperatures and looks especially plush and cuddly.'),
(92407, 706, 'de', 'Jakuten-Pferd', 'Das Jakuten-Pferd lebt in extrem kalten Regionen Sibiriens und ist sehr robust. Sein dichtes Winterfell hält Temperaturen weit unter dem Gefrierpunkt stand. In deinem Zoo trotzt es auch kühleren Temperaturen gelassen und sieht dabei besonders plüschig aus.'),
(92408, 706, 'da', 'Sneugle', 'Sneuglens hvide fjerdragt giver fremragende camouflage i det snedækkede arktiske landskab. I modsætning til de fleste ugler er den aktiv om dagen. Den jager primært lemminger.'),
(92409, 30271, 'en', 'Yellow Boxfish', 'The Yellow Boxfish (Ostracion cubicum) is a species of boxfish found in reefs throughout the Pacific, Indianand the southeastern Atlantic Ocean. Itreaches a maximum length of 45 centimetres (18 in). As the name suggests, it is box-shaped. Boxfish are also known for their armored and rigid body which in most cases would inhibit locomotion. When juvenile, it is bright yellow in color, as it ages, the brightness fades. When stressed or injured it releases the neurotoxin tetrodotoxin (TTX) from its skin, which may prove lethal to fish in surrounding waters.\n\nThe Yellow Boxfish\'s diet consists mainly of marine algae, but it may also feed on worms, sponges, crustaceans, molluscs, and small fish.\n\n'),
(92410, 30271, 'de', 'Yellow Boxfish', 'The Yellow Boxfish (Ostracion cubicum) is a species of boxfish found in reefs throughout the Pacific, Indianand the southeastern Atlantic Ocean. Itreaches a maximum length of 45 centimetres (18 in). As the name suggests, it is box-shaped. Boxfish are also known for their armored and rigid body which in most cases would inhibit locomotion. When juvenile, it is bright yellow in color, as it ages, the brightness fades. When stressed or injured it releases the neurotoxin tetrodotoxin (TTX) from its skin, which may prove lethal to fish in surrounding waters.\n\nThe Yellow Boxfish\'s diet consists mainly of marine algae, but it may also feed on worms, sponges, crustaceans, molluscs, and small fish.\n\n'),
(92411, 30271, 'da', 'Yellow Boxfish', 'The Yellow Boxfish (Ostracion cubicum) is a species of boxfish found in reefs throughout the Pacific, Indianand the southeastern Atlantic Ocean. Itreaches a maximum length of 45 centimetres (18 in). As the name suggests, it is box-shaped. Boxfish are also known for their armored and rigid body which in most cases would inhibit locomotion. When juvenile, it is bright yellow in color, as it ages, the brightness fades. When stressed or injured it releases the neurotoxin tetrodotoxin (TTX) from its skin, which may prove lethal to fish in surrounding waters.\n\nThe Yellow Boxfish\'s diet consists mainly of marine algae, but it may also feed on worms, sponges, crustaceans, molluscs, and small fish.\n\n'),
(92412, 30272, 'en', 'Yellow-Throated Marten', 'The Yellow-Throated Marten is a marten species native to Asia. They are large, robust, muscular and flexible animals with an elongated thorax, a small pointed head, and a long neck. Its fur is brightly colored, consisting of a unique blend of black, white, golden-yellow and brown. The color becomes browner on the hindquarters. The flanks and belly are bright yellowish in tone. The chest and lower part of the throat area brighter, orange-golden color than the back and belly. The tail is of a shiny pure black color, though the tip has a light, violet wash.\n\nYellow-Throated Martens are omnivores, whose sources of food range from fruit and nectar to small deer. Their diet includes rats, mice, hares, snakes, lizards, eggs and ground-nesting birds.\n\n'),
(92413, 30272, 'de', 'Yellow-Throated Marten', 'The Yellow-Throated Marten is a marten species native to Asia. They are large, robust, muscular and flexible animals with an elongated thorax, a small pointed head, and a long neck. Its fur is brightly colored, consisting of a unique blend of black, white, golden-yellow and brown. The color becomes browner on the hindquarters. The flanks and belly are bright yellowish in tone. The chest and lower part of the throat area brighter, orange-golden color than the back and belly. The tail is of a shiny pure black color, though the tip has a light, violet wash.\n\nYellow-Throated Martens are omnivores, whose sources of food range from fruit and nectar to small deer. Their diet includes rats, mice, hares, snakes, lizards, eggs and ground-nesting birds.\n\n'),
(92414, 30272, 'da', 'Yellow-Throated Marten', 'The Yellow-Throated Marten is a marten species native to Asia. They are large, robust, muscular and flexible animals with an elongated thorax, a small pointed head, and a long neck. Its fur is brightly colored, consisting of a unique blend of black, white, golden-yellow and brown. The color becomes browner on the hindquarters. The flanks and belly are bright yellowish in tone. The chest and lower part of the throat area brighter, orange-golden color than the back and belly. The tail is of a shiny pure black color, though the tip has a light, violet wash.\n\nYellow-Throated Martens are omnivores, whose sources of food range from fruit and nectar to small deer. Their diet includes rats, mice, hares, snakes, lizards, eggs and ground-nesting birds.\n\n'),
(92415, 341, 'en', 'Zebra Duiker', 'The zebra duiker is a rare forest‑dwelling antelope from Africa. Its name sounds like something tiny, and in fact it is rather small and very shy. In your zoo it relies on dense planting and only shows itself to lucky visitors.'),
(92416, 341, 'de', 'Zebraducker', 'Der Zebraducker ist eine seltene, waldlebende Antilope aus Afrika. Sein Name erinnert an Zwerge, und tatsächlich ist er eher klein und scheu. In deinem Zoo schätzt er dichte Bepflanzung und lässt sich nur mit etwas Glück blicken.'),
(92417, 341, 'da', 'Zebraduker', 'Zebraduikeren er en sjælden, skovlevende antilope fra Afrika. Den er sky og holder sig mest til tæt vegetation. I din zoo sætter den pris på tæt beplantning og lader sig kun se af heldige besøgende.'),
(92430, 202, 'en', 'American Bison', 'The American Bison once roamed North America\'s prairies in huge herds. With its massive body and thick fur, it braves wind and weather. In the zoo, it stomps powerfully through the enclosure, rolls in the dust, and shows just how imposing herd animals can be.'),
(92431, 202, 'de', 'Amerikanischer Bison', 'Der Amerikanische Bison war einst in riesigen Herden in den Prärien Nordamerikas unterwegs. Mit seinem massigen Körper und dem dichten Fell trotzt er Wind und Wetter. Im Zoo stapft er kraftvoll durch das Gehege, wälzt sich im Staub und zeigt, wie imposant Herdentiere sein können.'),
(92432, 202, 'da', 'Amerikansk bison', 'Den amerikanske bison vandrede engang i gigantiske hjorder over prærierne i Nordamerika. Med sin massive krop og tykke pels trodser den vind og vejr. I din zoo stamper den kraftigt igennem indhegningen og vælter sig i støvet.'),
(92475, 30300, 'da', 'Akhal-Teke', 'Akhal-Teke er en af de ældste væddeløbshesteracer, der stammer fra Turkmenistan. Hestens navn blev taget fra \"Akhal\", en række oaser af Kopet Dag-bjergene i Centralasien, og hesten blev raseret af \"Teke \"-stammen i Turkmenistan. Det er et mellemstort dyr med et dybt bryst og veldefinerede ben. Hesten, der findes, varierer i farver og markeringer på hoved, krop og ben. Den metalliske glans af hestens fine pels kombineret med disse farver får dyret til at se ud som om det gløder, hvilket gør det til monikeren \"Golden Horse\".\n\nSom en ørkenhest med lidt græs til rådighed, udviklede Akhal-Teke sig til at leve af en sparsom kost. I dag kan hestene få en tilsvarende afbalanceret kost med kvalitetsgræs, hø og noget korn.'),
(92476, 30300, 'de', 'Akhal-Teke', 'Akhal-Teke ist eine der ältesten Rennpferderassen, die ihren Ursprung in Turkmenistan hat. Der Name des Pferdes stammt von \"Akhal\", einer Reihe von Oasen des Kopet Dag-Gebirges in Zentralasien, und das Pferd wurde vom \"Teke\" -Stamm Turkmenistans heimgesucht. Es handelt sich um ein mittelgroßes Tier mit tiefer Brust und wohldefinierten Beinen. Das gefundene Pferd variiert in Farben und Markierungen auf Kopf, Körper und Beinen. Der metallische Glanz des feinen Fells des Pferdes in Kombination mit diesen Farben lässt das Tier leuchten, was ihm den Spitznamen \"Goldenes Pferd\" einbringt.\n\nAls Wüstenpferd mit wenig Gras entwickelte sich der Akhal-Teke zu einer spärlichen Ernährung. Heute können die Pferde eine ähnlich ausgewogene Ernährung mit hochwertigem Gras, Heu und etwas Getreide erhalten.'),
(92477, 30300, 'en', 'Akhal-Teke', 'Akhal-Teke is one of the oldest racing horse breeds that originated in Turkmenistan. Horse’s name was taken from \"Akhal\", a series of oases of Kopet Dag Mountains of Central Asia, and the horse was rared by the \"Teke\" tribe of Turkmenistan. It is a medium-sized animal with a deep chest and well-defined legs. The horse found varies of colors and markings on their head, body, and legs. The metallic sheen of the horse’s fine coat combined with these colors makes the animal appear as if it is glowing, earning it the moniker \"Golden Horse\".\n\nAs a desert horse with little grass available, the Akhal-Teke evolved to subsist on a sparse diet. Today, the horses may receive a similarly balanced diet with quality grass, hay, and some grain.'),
(92478, 30300, 'es', 'Akhal-Teke', 'Akhal-Teke es una de las razas de caballos de carreras más antiguas que se originó en Turkmenistán. El nombre del caballo fue tomado de \"Akhal\", una serie de oasis de las montañas Kopet Dag de Asia Central, y el caballo fue criado por la tribu \"Teke\" de Turkmenistán. Es un animal de tamaño mediano con un pecho profundo y patas bien definidas. El caballo encontrado varía de colores y marcas en la cabeza, el cuerpo y las piernas. El brillo metálico del pelaje fino del caballo combinado con estos colores hace que el animal parezca como si estuviera brillando, ganándose el apodo de \"Caballo Dorado\".\n\nComo caballo del desierto con poca hierba disponible, el Akhal-Teke evolucionó para subsistir con una dieta escasa. Hoy en día, los caballos pueden recibir una dieta equilibrada similar con pasto de calidad, heno y algo de grano.'),
(92479, 30300, 'fr', 'Akhal-Teke', 'Akhal-Teke est l\'une des plus anciennes races de chevaux de course originaire du Turkménistan. Le nom du cheval provient de \"Akhal\", une série d\'oasis des montagnes de Kopet Dag en Asie centrale, et le cheval a été élevé par la tribu \"Teke\" du Turkménistan. C\'est un animal de taille moyenne avec une poitrine profonde et des pattes bien définies. Le cheval a trouvé des couleurs et des marques variées sur sa tête, son corps et ses jambes. L\'éclat métallique du pelage fin du cheval combiné à ces couleurs donne l\'impression que l\'animal brille, ce qui lui vaut le surnom de « cheval d\'or ».\n\nEn tant que cheval du désert avec peu d\'herbe disponible, l\'Akhal-Teke a évolué pour survivre avec une alimentation clairsemée. Aujourd\'hui, les chevaux peuvent recevoir une alimentation tout aussi équilibrée avec de l\'herbe de qualité, du foin et des céréales.'),
(92480, 30300, 'nl', 'Akhal-Teke', 'Akhal-Teke is een van de oudste renpaardenrassen die in Turkmenistan is ontstaan. De naam van het paard is ontleend aan \"Akhal\", een reeks oases van het Kopet Dag-gebergte in Centraal-Azië, en het paard werd gekweekt door de \"Teke\" -stam van Turkmenistan. Het is een middelgroot dier met een diepe borst en goed gedefinieerde poten. Het paard vond verschillende kleuren en markeringen op hun hoofd, lichaam en benen. De metallic glans van de fijne vacht van het paard in combinatie met deze kleuren zorgt ervoor dat het dier lijkt alsof het gloeit, waardoor het de bijnaam \"Gouden Paard\" krijgt.\n\nAls een woestijnpaard met weinig gras beschikbaar, evolueerde de Akhal-Teke om te overleven op een schaars dieet. Tegenwoordig kunnen de paarden een vergelijkbaar uitgebalanceerd dieet krijgen met kwaliteitsgras, hooi en wat graan.'),
(92499, 30302, 'da', 'andes-bjergkat', 'Andesbjergkatten er en lille vildkat med tyk, askegrå pels mønstret med rustne brune pletter, der står 25–35 cm (10–14 tommer) ved skulderen og vejer 4-5,5 kg (9–12 lbs). Dens mest karakteristiske træk er en lang, busket hale, som den bruger til balance på stejle bjergklipper og omslutter sig selv for varme.\n\nDens kost er højt specialiseret og lever næsten udelukkende af bjergvizcachas (store kaninlignende gnavere), selvom den lejlighedsvis spiser mindre gnavere, fugle og firben afhængigt af tilgængelighed.'),
(92500, 30302, 'de', 'Bergkatze', 'Die Anden-Bergkatze ist eine kleine Wildkatze mit dickem, aschgrauem Fell, das mit rostbraunen Flecken gemustert ist, 25–35 cm (10–14 Zoll) an der Schulter steht und 4-5,5 kg (9–12 lbs) wiegt. Sein markantestes Merkmal ist ein langer, buschiger Schwanz, den er für das Gleichgewicht auf steilen Bergfelsen verwendet und für Wärme um sich selbst wickelt.\n\nSeine Ernährung ist hochspezialisiert und jagt fast ausschließlich Bergvizcachas (große kaninchenartige Nagetiere), obwohl es je nach Verfügbarkeit gelegentlich kleinere Nagetiere, Vögel und Eidechsen frisst.'),
(92501, 30302, 'en', 'Andean Mountain Cat', 'The Andean Mountain Cat is a small wild cat with thick, ash-gray fur patterned with rusty-brown spots, standing 25–35 cm (10–14 inches) at the shoulder and weighing 4–5.5 kg (9–12 lbs). Its most distinct feature is a long, bushy tail, which it uses for balance on steep mountain rocks and wraps around itself for warmth.\n\nIts diet is highly specialized, preying almost exclusively on mountain vizcachas (large rabbit-like rodents), though it occasionally eats smaller rodents, birds, and lizards depending on availability.'),
(92502, 30302, 'es', 'gato andino', 'El gato de montaña andino es un pequeño gato salvaje con un pelaje grueso de color gris ceniza con manchas de color marrón oxidado, que mide 25–35 cm (10–14 pulgadas) en el hombro y pesa 4-5,5 kg (9–12 lbs). Su característica más distintiva es una cola larga y espesa, que utiliza para mantener el equilibrio en las rocas escarpadas de la montaña y se envuelve alrededor de sí misma para calentarse.\n\nSu dieta es altamente especializada, ya que se alimenta casi exclusivamente de vizcachas de montaña (grandes roedores parecidos a conejos), aunque ocasionalmente come roedores, aves y lagartos más pequeños, dependiendo de la disponibilidad.'),
(92503, 30302, 'fr', 'chat des Andes', 'Le chat des montagnes andines est un petit chat sauvage avec une fourrure épaisse et gris cendré à motifs de taches brun rouille, mesurant 25 à 35 cm (10 à 14 pouces) à l\'épaule et pesant 4 à 5,5 kg (9 à 12 lb). Sa caractéristique la plus distinctive est une longue queue touffue, qu\'il utilise pour l\'équilibre sur les rochers escarpés de la montagne et s\'enroule autour de lui-même pour la chaleur.\n\nSon régime alimentaire est hautement spécialisé, s\'attaquant presque exclusivement aux vizcachas de montagne (grands rongeurs ressemblant à des lapins), bien qu\'il mange occasionnellement des rongeurs, des oiseaux et des lézards plus petits en fonction de la disponibilité.'),
(92504, 30302, 'nl', 'Bergkat', 'De Andesbergkat is een kleine wilde kat met een dikke, asgrijze vacht met een patroon van roestbruine vlekken, die 25–35 cm (10–14 inch) op de schouder staat en 4-5,5 kg (9–12 lbs) weegt. Het meest opvallende kenmerk is een lange, bossige staart, die hij gebruikt voor balans op steile bergrotsen en om zich heen wikkelt voor warmte.\n\nHet dieet is zeer gespecialiseerd en jaagt bijna uitsluitend op bergvizcachas (grote konijnachtige knaagdieren), hoewel het af en toe kleinere knaagdieren, vogels en hagedissen eet, afhankelijk van de beschikbaarheid.'),
(92505, 30292, 'da', 'Aye-Aye', 'The Aye-aye is a long-fingered lemur that inhabits the rainforests in Madagascar. It is the world’s largest nocturnal primate and has a unique appearance. Young aye-ayes typically are silver colored on their front and have a stripe down their back. However, as the aye-ayes begin to reach maturity, their bodies will be completely covered in thick fur and are typically not one solid color. Among the aye-aye\'s signature traits are its fingers. The third finger, which is much thinner than the others, is used for tapping, while the fourth finger, the longest, is used for pulling grubs and insects out of trees, using the hooked nail. \n\nAye-Ayes are omnivorous animals. They eat a variety of fruits, nectar, honey, fungi, seeds, larvae, insects, and eggs.\n\n'),
(92506, 30292, 'de', 'Aye-Aye', 'The Aye-aye is a long-fingered lemur that inhabits the rainforests in Madagascar. It is the world’s largest nocturnal primate and has a unique appearance. Young aye-ayes typically are silver colored on their front and have a stripe down their back. However, as the aye-ayes begin to reach maturity, their bodies will be completely covered in thick fur and are typically not one solid color. Among the aye-aye\'s signature traits are its fingers. The third finger, which is much thinner than the others, is used for tapping, while the fourth finger, the longest, is used for pulling grubs and insects out of trees, using the hooked nail. \n\nAye-Ayes are omnivorous animals. They eat a variety of fruits, nectar, honey, fungi, seeds, larvae, insects, and eggs.\n\n'),
(92507, 30292, 'en', 'Aye-Aye', 'The Aye-aye is a long-fingered lemur that inhabits the rainforests in Madagascar. It is the world’s largest nocturnal primate and has a unique appearance. Young aye-ayes typically are silver colored on their front and have a stripe down their back. However, as the aye-ayes begin to reach maturity, their bodies will be completely covered in thick fur and are typically not one solid color. Among the aye-aye\'s signature traits are its fingers. The third finger, which is much thinner than the others, is used for tapping, while the fourth finger, the longest, is used for pulling grubs and insects out of trees, using the hooked nail. \n\nAye-Ayes are omnivorous animals. They eat a variety of fruits, nectar, honey, fungi, seeds, larvae, insects, and eggs.'),
