(92509, 30292, 'fr', 'Aye-Aye', 'The Aye-aye is a long-fingered lemur that inhabits the rainforests in Madagascar. It is the world’s largest nocturnal primate and has a unique appearance. Young aye-ayes typically are silver colored on their front and have a stripe down their back. However, as the aye-ayes begin to reach maturity, their bodies will be completely covered in thick fur and are typically not one solid color. Among the aye-aye\'s signature traits are its fingers. The third finger, which is much thinner than the others, is used for tapping, while the fourth finger, the longest, is used for pulling grubs and insects out of trees, using the hooked nail. \n\nAye-Ayes are omnivorous animals. They eat a variety of fruits, nectar, honey, fungi, seeds, larvae, insects, and eggs.\n\n'),
(92510, 30292, 'nl', 'Aye-Aye', 'The Aye-aye is a long-fingered lemur that inhabits the rainforests in Madagascar. It is the world’s largest nocturnal primate and has a unique appearance. Young aye-ayes typically are silver colored on their front and have a stripe down their back. However, as the aye-ayes begin to reach maturity, their bodies will be completely covered in thick fur and are typically not one solid color. Among the aye-aye\'s signature traits are its fingers. The third finger, which is much thinner than the others, is used for tapping, while the fourth finger, the longest, is used for pulling grubs and insects out of trees, using the hooked nail. \n\nAye-Ayes are omnivorous animals. They eat a variety of fruits, nectar, honey, fungi, seeds, larvae, insects, and eggs.\n\n'),
(92517, 30293, 'da', 'Grévy\'s Zebra', 'Grévy\'s Zebra, also known as the Imperial zebra, is the largest living wild equid (horse) and the most threatened species of zebras. Compared to other zebra species, Grévy’s are the tallest; they have mule-like, larger ears, and have the tightest stripes of all zebras. They have distinctively erect manes, and more slender snouts. It differs from the other zebra species in that it does not live in harems and has few long-lasting social bonds.\n\nThe diet of these herbivorous mammals primarily consists of grasses, supplemented by fruits, tree bark, shrubs, roots, leaves and buds.\n\n'),
(92518, 30293, 'de', 'Grévy\'s Zebra', 'Grévy\'s Zebra, also known as the Imperial zebra, is the largest living wild equid (horse) and the most threatened species of zebras. Compared to other zebra species, Grévy’s are the tallest; they have mule-like, larger ears, and have the tightest stripes of all zebras. They have distinctively erect manes, and more slender snouts. It differs from the other zebra species in that it does not live in harems and has few long-lasting social bonds.\n\nThe diet of these herbivorous mammals primarily consists of grasses, supplemented by fruits, tree bark, shrubs, roots, leaves and buds.\n\n'),
(92519, 30293, 'en', 'Grévy\'s Zebra', 'Grévy\'s Zebra, also known as the Imperial zebra, is the largest living wild equid (horse) and the most threatened species of zebras. Compared to other zebra species, Grévy’s are the tallest; they have mule-like, larger ears, and have the tightest stripes of all zebras. They have distinctively erect manes, and more slender snouts. It differs from the other zebra species in that it does not live in harems and has few long-lasting social bonds.\n\nThe diet of these herbivorous mammals primarily consists of grasses, supplemented by fruits, tree bark, shrubs, roots, leaves and buds.'),
(92520, 30293, 'es', 'Grévy\'s Zebra', 'Grévy\'s Zebra, also known as the Imperial zebra, is the largest living wild equid (horse) and the most threatened species of zebras. Compared to other zebra species, Grévy’s are the tallest; they have mule-like, larger ears, and have the tightest stripes of all zebras. They have distinctively erect manes, and more slender snouts. It differs from the other zebra species in that it does not live in harems and has few long-lasting social bonds.\n\nThe diet of these herbivorous mammals primarily consists of grasses, supplemented by fruits, tree bark, shrubs, roots, leaves and buds.\n\n'),
(92521, 30293, 'fr', 'Grévy\'s Zebra', 'Grévy\'s Zebra, also known as the Imperial zebra, is the largest living wild equid (horse) and the most threatened species of zebras. Compared to other zebra species, Grévy’s are the tallest; they have mule-like, larger ears, and have the tightest stripes of all zebras. They have distinctively erect manes, and more slender snouts. It differs from the other zebra species in that it does not live in harems and has few long-lasting social bonds.\n\nThe diet of these herbivorous mammals primarily consists of grasses, supplemented by fruits, tree bark, shrubs, roots, leaves and buds.\n\n'),
(92522, 30293, 'nl', 'Grévy\'s Zebra', 'Grévy\'s Zebra, also known as the Imperial zebra, is the largest living wild equid (horse) and the most threatened species of zebras. Compared to other zebra species, Grévy’s are the tallest; they have mule-like, larger ears, and have the tightest stripes of all zebras. They have distinctively erect manes, and more slender snouts. It differs from the other zebra species in that it does not live in harems and has few long-lasting social bonds.\n\nThe diet of these herbivorous mammals primarily consists of grasses, supplemented by fruits, tree bark, shrubs, roots, leaves and buds.\n\n'),
(92523, 30301, 'da', 'Steenbok', 'Steenbok er en lille, slank antilope, der er hjemmehørende i de åbne savanner og græsarealer i det sydlige og østlige Afrika. Kendt for sine store, radarlignende ører og en blank, murstensrød til fawnfarvet pels, står voksne kun 45–60 cm (18–24 tommer) høje ved skulderen og vejer mellem 7–16 kg (15–35 lbs). Kun hannerne får horn, som er korte, lige og glatte.\n\nSteenbok er en selektiv browser, der spiser blade, skud, blomster, frugt og svampe af høj kvalitet.'),
(92524, 30301, 'de', 'Steenbok', 'Der Steenbok ist eine zierliche, schlanke Antilope, die in den offenen Savannen und Wiesen des südlichen und östlichen Afrikas beheimatet ist. Bekannt für seine großen, radarähnlichen Ohren und ein glänzendes, ziegelrotes bis rehbraunes Fell, stehen Erwachsene nur 45–60 cm (18–24 Zoll) hoch an der Schulter und wiegen zwischen 7–16 kg (15–35 lbs). Nur die Männchen wachsen Hörner, die kurz, gerade und glatt sind.\n\nDer Steenbok ist ein selektiver Browser, der hochwertige Blätter, Triebe, Blüten, Früchte und Pilze isst.'),
(92525, 30301, 'en', 'Steenbok', 'The Steenbok is a petite, slender antelope native to the open savannas and grasslands of southern and eastern Africa. Known for its large, radar-like ears and a glossy, brick-red to fawn-colored coat, adults stand just 45–60 cm (18–24 inches) tall at the shoulder and weigh between 7–16 kg (15–35 lbs). Only the males grow horns, which are short, straight, and smooth.\n\nThe Steenbok is a selective browser that eats high-quality leaves, shoots, flowers, fruits, and fungi.'),
(92526, 30301, 'es', 'Steenbok', 'El Steenbok es un pequeño y delgado antílope nativo de las sabanas y pastizales abiertos del sur y este de África. Conocidos por sus grandes orejas parecidas a un radar y un abrigo brillante de color rojo ladrillo a marrón, los adultos miden solo 45–60 cm (18–24 pulgadas) de altura en el hombro y pesan entre 7–16 kg (15–35 lbs). Solo a los machos les crecen cuernos, que son cortos, rectos y lisos.\n\nEl Steenbok es un navegador selectivo que se alimenta de hojas, brotes, flores, frutas y hongos de alta calidad.'),
(92527, 30301, 'fr', 'Raphicerus campestris', 'Le Steenbok est une petite antilope mince originaire des savanes ouvertes et des prairies d\'Afrique australe et orientale. Connu pour ses grandes oreilles en forme de radar et son manteau brillant de couleur rouge brique à fauve, les adultes ne mesurent que 45 à 60 cm (18 à 24 pouces) de haut à l\'épaule et pèsent entre 7 et 16 kg (15 à 35 lb). Seuls les mâles ont des cornes courtes, droites et lisses.\n\nLe Steenbok est un navigateur sélectif qui mange des feuilles, des pousses, des fleurs, des fruits et des champignons de haute qualité.'),
(92528, 30301, 'nl', 'Steenbokantilope', 'De Steenbok is een kleine, slanke antilope die inheems is in de open savannes en graslanden van zuidelijk en oostelijk Afrika. Bekend om zijn grote, radarachtige oren en een glanzende, baksteenrode tot fawnkleurige vacht, staan volwassenen slechts 45–60 cm (18–24 inch) hoog op de schouder en wegen ze tussen de 7–16 kg (15–35 lbs). Alleen de mannetjes groeien hoorns, die kort, recht en glad zijn.\n\nDe Steenbok is een selectieve browser die bladeren, scheuten, bloemen, fruit en schimmels van hoge kwaliteit eet.'),
(92547, 342, 'da', 'Amerikansk sortbjørn', 'Den amerikanske sortbjørn er en mellemstor bjørn, der er endemisk i Nordamerika. Sorte bjørne kan være sorte, men har også forskellige farver, lige fra brun eller mørk rød til en lys tan, afhængigt af hvor de bor. Deres pels er kort og tyk og dækker alle deres stærkt byggede kroppe. Sortbjørne har små øjne og en spids næse, og deres ører er større og mere spidse end deres brunbjørns slægtninge. \n\nAmerikanske sorte bjørne er altædende og ådsler. De fodrer efter nødder og frugter i træerne, plukker dem med deres slidstærke læber, og på jorden spiser de græs, løg og rødder samt små dyr som gnavere og insekter.'),
(92548, 342, 'de', 'Amerikanischer Schwarzbär', 'Der Amerikanische Schwarzbär ist ein mittelgroßer Bär, der in Nordamerika endemisch ist. Schwarzbären können schwarz sein, haben aber auch verschiedene Farben, von braun oder dunkelrot bis hellbraun, je nachdem, wo sie leben. Ihr Fell ist kurz und dick und bedeckt alle ihre schwer gebauten Körper. Schwarzbären haben kleine Augen und eine spitze Schnauze, und ihre Ohren sind größer und spitzer als die ihrer Braunbärenverwandten. \n\nAmerikanische Schwarzbären sind Allesfresser und Plünderer. Sie suchen nach Nüssen und Früchten in den Bäumen, pflücken sie mit ihren Greiflippen und auf dem Boden essen sie Gräser, Zwiebeln und Wurzeln sowie kleine Tiere wie Nagetiere und Insekten.'),
(92549, 342, 'en', 'American Black Bear', 'The American Black Bear is a medium-sized bear endemic to North America. Black Bears can be black but are also different colors, ranging from brown or dark red to a light tan, depending on where they live. Their fur is short and thick and covers all of their heavily built bodies. Black Bears have small eyes and a pointed muzzle, and their ears are larger and more pointed than those of their brown bear relatives. \n\nAmerican Black Bears are omnivores and scavengers. They forage for nuts and fruits in the trees, plucking them with their prehensile lips, and on the ground, they eat grasses, bulbs, and roots, as well as small animals like rodents and insects.'),
(92550, 342, 'es', 'Ursus americanus', 'El oso negro americano es un oso de tamaño mediano endémico de América del Norte. Los osos negros pueden ser negros, pero también son de diferentes colores, desde marrón o rojo oscuro hasta un bronceado claro, dependiendo de dónde vivan. Su pelaje es corto y grueso y cubre todos sus cuerpos fuertemente construidos. Los osos negros tienen ojos pequeños y un hocico puntiagudo, y sus orejas son más grandes y puntiagudas que las de sus parientes los osos pardos. \n\nLos osos negros americanos son omnívoros y carroñeros. Buscan nueces y frutas en los árboles, arrancándolas con sus labios prensiles, y en el suelo comen hierbas, bulbos y raíces, así como pequeños animales como roedores e insectos.'),
(92551, 342, 'fr', 'Ours noir', 'L\'ours noir d\'Amérique est un ours de taille moyenne endémique de l\'Amérique du Nord. Les ours noirs peuvent être noirs, mais ils sont également de couleurs différentes, allant du brun ou du rouge foncé au beige clair, selon l\'endroit où ils vivent. Leur fourrure est courte et épaisse et recouvre tous leurs corps fortement construits. Les ours noirs ont de petits yeux et un museau pointu, et leurs oreilles sont plus grandes et plus pointues que celles de leurs parents ours bruns. \n\nLes ours noirs américains sont des omnivores et des charognards. Ils cherchent des noix et des fruits dans les arbres, les cueillent avec leurs lèvres préhensile, et sur le sol, ils mangent des herbes, des bulbes et des racines, ainsi que de petits animaux comme les rongeurs et les insectes.'),
(92552, 342, 'nl', 'Baribal', 'De Amerikaanse zwarte beer is een middelgrote beer die endemisch is in Noord-Amerika. Zwarte beren kunnen zwart zijn, maar zijn ook verschillende kleuren, variërend van bruin of donkerrood tot een lichte kleur, afhankelijk van waar ze wonen. Hun vacht is kort en dik en bedekt al hun zwaar gebouwde lichamen. Zwarte beren hebben kleine ogen en een puntige snuit, en hun oren zijn groter en puntiger dan die van hun bruine berenverwanten. \n\nAmerikaanse zwarte beren zijn alleseters en aaseters. Ze zoeken naar noten en fruit in de bomen, plukken ze met hun prehensiele lippen en op de grond eten ze grassen, bollen en wortels, evenals kleine dieren zoals knaagdieren en insecten.'),
(92571, 312, 'da', 'Fiskekat', 'Fiskerikatten (Prionailurus viverrinus) er en mellemstor vildkat i Syd- og Sydøstasien. Det er en truet art, hvis bestand er faldet kraftigt i løbet af det sidste årti. Dens videnskabelige navn kommer fra dens viverrine eller civet-lignende udseende snarere end nogen tilpasning til fiskeri. Fiskekatten er en \"lille\" kat af mellemstørrelse og tæt konstruktion med korte ben, en kort hale og et ansigt, der er rundt, men aflangt. De har en olivengrå frakke, der har et mønster af rækker af parallelle sorte pletter, som ofte danner striber på ryggen. Hunnerne er mærkbart mindre end hannerne.\n\nFiskerikatte er kødædende og spiser hovedsageligt fisk, frøer, vandinsekter, krabber, slanger, krebs, gnavere og fugle.'),
(92572, 312, 'de', 'Fischkatze', 'Die Fischerkatze (Prionailurus viverrinus) ist eine mittelgroße Wildkatze Süd- und Südostasiens. Es handelt sich um eine bedrohte Art, deren Population in den letzten zehn Jahren stark zurückgegangen ist. Sein wissenschaftlicher Name kommt von seinem viverrinen oder zibetartigen Aussehen und nicht von irgendeiner Anpassung für den Fischfang. Die Fischerkatze ist eine \"kleine\" Katze von mittlerer Größe und stämmigem Körperbau, mit kurzen Beinen, einem kurzen Schwanz und einem runden, aber länglichen Gesicht. Sie haben ein olivgraues Fell mit einem Muster aus Reihen paralleler schwarzer Flecken, die oft Streifen auf dem Rücken bilden. Weibchen sind deutlich kleiner als Männchen.\n\nAngeln Katzen sind Fleischfresser (Fischfresser) und fressen hauptsächlich Fische, Frösche, Wasserinsekten, Krabben, Schlangen, Krebse, Nagetiere und Vögel.'),
(92573, 312, 'en', 'Fishing Cat', 'The Fishing Cat (Prionailurus viverrinus) is a medium-sized wild cat of South and Southeast Asia. It is a threatened species whose population has declined severely over the last decade. Its scientific name comes from its viverrine or civet-like appearance rather than any adaptation for fishing. The Fishing Cat is a “small” cat of medium size and stocky build, with short legs, a short tail, and a face that is round but elongated. They have an olive-gray coat that has a pattern of rows of parallel black spots which will often form stripes on their back. Females are noticeably smaller than males.\n\nFishing Cats are carnivores (piscivores) and mainly eat fish, frogs, water insects, crabs, snakes, crayfish, rodents, and birds.'),
(92574, 312, 'es', 'Pesca del gato', 'El gato pescador (Prionailurus viverrinus) es un gato salvaje de tamaño mediano del sur y sudeste de Asia. Es una especie amenazada cuya población ha disminuido severamente en la última década. Su nombre científico proviene de su apariencia de viverrina o civeta en lugar de cualquier adaptación para la pesca. El gato pescador es un gato \"pequeño\" de tamaño mediano y constitución robusta, con patas cortas, una cola corta y una cara redonda pero alargada. Tienen un pelaje de color gris oliva que tiene un patrón de filas de puntos negros paralelos que a menudo forman rayas en la espalda. Las hembras son notablemente más pequeñas que los machos.\n\nLos gatos pescadores son carnívoros (piscívoros) y se alimentan principalmente de peces, ranas, insectos acuáticos, cangrejos, serpientes, cangrejos de río, roedores y aves.'),
(92575, 312, 'fr', 'Chat pêcheur', 'Le chat pêcheur (Prionailurus viverrinus) est un chat sauvage de taille moyenne d\'Asie du Sud et du Sud-Est. C\'est une espèce menacée dont la population a fortement décliné au cours de la dernière décennie. Son nom scientifique vient de son aspect de viverrine ou de civette plutôt que de toute adaptation à la pêche. Le chat pêcheur est un « petit » chat de taille moyenne et trapu, avec des pattes courtes, une queue courte et un visage rond mais allongé. Ils ont un manteau gris olive qui a un motif de rangées de taches noires parallèles qui formeront souvent des rayures sur leur dos. Les femelles sont nettement plus petites que les mâles.\n\nPêche Les chats sont des carnivores (piscivores) et mangent principalement des poissons, des grenouilles, des insectes aquatiques, des crabes, des serpents, des écrevisses, des rongeurs et des oiseaux.'),
(92576, 312, 'nl', 'Vissende kat', 'De Vissende Kat (Prionailurus viverrinus) is een middelgrote wilde kat uit Zuid- en Zuidoost-Azië. Het is een bedreigde soort waarvan de populatie de afgelopen tien jaar ernstig is afgenomen. De wetenschappelijke naam komt van het viverrine- of civetachtige uiterlijk in plaats van een aanpassing voor de visserij. De viskat is een \"kleine\" kat van gemiddelde grootte en gedrongen bouw, met korte poten, een korte staart en een gezicht dat rond maar langwerpig is. Ze hebben een olijfgrijze vacht met een patroon van rijen parallelle zwarte vlekken die vaak strepen op hun rug vormen. Vrouwtjes zijn merkbaar kleiner dan mannetjes.\n\nViskatten zijn carnivoren (piscivoren) en eten voornamelijk vis, kikkers, waterinsecten, krabben, slangen, rivierkreeften, knaagdieren en vogels.'),
(92583, 424, 'da', 'Bavian', 'Bavianer er aber, der er hjemmehørende i Afrika og en del af Den Arabiske Halvø. De er blandt de største primater, der ikke er aber. I modsætning til mange aber er bavianer for det meste jordbaserede (lever på jorden), selvom nogle sover i træer. De har kortere haler, men større snuder end andre aber. Voksne hanner har en udtalt kappe (manke og kappe), sølvhvid i farven, som de udvikler omkring en alder af ti, mens hunnerne er kapsløse og brune overalt. Der er traditionelt 5 arter af bavianer,selvom Kinda-bavianen,en underart af den gule bavian, der findes i Zambia, undertiden hævdes at være en separat art. Den ene i Zoo 2 dyrepark ligner Hamadryas-bavianen(Papio Hamadryas).\n\nSom en altædende bruger Hamadryas-bavianen mad af både animalsk og vegetabilsk oprindelse, såsom frugter, trægummi, akaciefrø, akacieblomster, frø, græs, jordstængler, stamme og rødder.'),
(92584, 424, 'de', 'Pavian', 'Paviane sind Affen, die in Afrika und einem Teil der Arabischen Halbinsel beheimatet sind. Sie gehören zu den größten Nonap-Primaten. Im Gegensatz zu vielen Affen sind Paviane meist terrestrisch (leben auf dem Boden), obwohl einige in Bäumen schlafen. Sie haben kürzere Schwänze, aber größere Schnauzen als andere Affen. Erwachsene Männchen haben ein ausgeprägtes, silberweiß gefärbtes Cape (Mähne und Mantel), das sie etwa im Alter von zehn Jahren entwickeln, während die Weibchen kappenlos und überall braun sind. Es gibt traditionell 5 Arten von Pavianen,obwohl der Kinda-Pavian,eine Unterart des gelben Pavians in Sambia, manchmal als separate Art bezeichnet wird. Die im Zoo 2 Tierpark ähnelt dem Hamadryas-Pavian (Papio Hamadryas).\n\nAls Allesfresser verzehrt der Hamadryas-Pavian Lebensmittel tierischen und pflanzlichen Ursprungs wie Früchte, Baumgummis, Akaziensamen, Akazienblüten, Samen, Gras, Rhizome, Knollen und Wurzeln.'),
(92585, 424, 'en', 'Baboon', 'Baboons are monkeys native to Africa and part of the Arabian Peninsula. They are among the largest non-ape primates. Unlike many monkeys Baboons are mostly terrestrial (living on the ground) though some do sleep in trees. They have shorter tails, but larger snouts than other monkeys. Adult males have a pronounced cape (mane and mantle), silver-white in color, which they develop around the age of ten, while the females are capeless and brown all over. There are traditionally 5 species of baboons,though the Kinda baboon,a subspecies of the yellow baboon found in Zambia,is sometimes argued as a seperate species.The one in Zoo 2 animal park resembles the Hamadryas Baboon(Papio Hamadryas).\n\nAs an omnivore, the Hamadryas baboon consumes food of both animal and plant origin such as fruits, tree gums, acacia seeds, acacia flowers, seeds, grass, rhizomes, corms and roots.'),
(92586, 424, 'es', 'Babuino', 'Los babuinos son monos nativos de África y parte de la Península Arábiga. Se encuentran entre los primates no simios más grandes. A diferencia de muchos monos, los babuinos son en su mayoría terrestres (viven en el suelo), aunque algunos duermen en los árboles. Tienen colas más cortas, pero hocicos más grandes que otros monos. Los machos adultos tienen una capa pronunciada (melena y manto), de color blanco plateado, que desarrollan alrededor de los diez años, mientras que las hembras no tienen capa y son marrones por todas partes. Tradicionalmente hay 5 especies de babuinos,aunque el babuino Kinda,una subespecie del babuino amarillo que se encuentra en Zambia, a veces se discute como una especie separada. El del parque de animales Zoo 2 se asemeja al babuino Hamadryas (Papio Hamadryas).\n\nComo omnívoro, el babuino Hamadryas consume alimentos de origen animal y vegetal como frutas, gomas de árboles, semillas de acacia, flores de acacia, semillas, pasto, rizomas, cormos y raíces.'),
(92587, 424, 'fr', 'Babouin', 'Les babouins sont des singes originaires d\'Afrique et de la péninsule arabique. Ils sont parmi les plus grands primates non-ap. Contrairement à de nombreux singes, les babouins sont principalement terrestres (vivant sur le sol), bien que certains dorment dans les arbres. Ils ont une queue plus courte, mais un museau plus large que les autres singes. Les mâles adultes ont une cape prononcée (crinière et manteau), de couleur blanc argenté, qu\'ils développent vers l\'âge de dix ans, tandis que les femelles sont sans cape et brunes partout. Il existe traditionnellement 5 espèces de babouins,bien que le babouin Kinda,une sous-espèce du babouin jaune que l\'on trouve en Zambie,soit parfois considéré comme une espèce distincte. Celui du parc animalier Zoo 2 ressemble au babouin Hamadryas (Papio Hamadryas).\n\nEn tant qu\'omnivore, le babouin Hamadryas consomme des aliments d\'origine animale et végétale tels que des fruits, des gommes d\'arbres, des graines d\'acacia, des fleurs d\'acacia, des graines, de l\'herbe, des rhizomes, des cormes et des racines.'),
(92588, 424, 'nl', 'Bavianen', 'Bavianen zijn apen die inheems zijn in Afrika en deel uitmaken van het Arabische schiereiland. Ze behoren tot de grootste niet-aapachtige primaten. In tegenstelling tot veel apen zijn bavianen meestal landdieren (die op de grond leven), hoewel sommigen in bomen slapen. Ze hebben kortere staarten, maar grotere snuiten dan andere apen. Volwassen mannetjes hebben een uitgesproken cape (manen en mantel), zilverwit van kleur, die ze rond de leeftijd van tien ontwikkelen, terwijl de vrouwtjes overal kaploos en bruin zijn. Er zijn traditioneel 5 soorten bavianen,hoewel de Kinda-baviaan,een ondersoort van de gele baviaan die in Zambia wordt gevonden, soms wordt betoogd als een aparte soort. De soort in dierentuin 2 lijkt op de Hamadryas-baviaan(Papio Hamadryas).\n\nAls omnivoor consumeert de Hamadryas-baviaan voedsel van zowel dierlijke als plantaardige oorsprong, zoals fruit, boomgom, acaciazaden, acaciabloemen, zaden, gras, wortelstokken, knollen en wortels.'),
(92589, 2201, 'da', 'Klovnfisk', 'Klovnefisk eller anemonefisk er fisk fra underfamilien Amphiprioninae i familien Pomacentridae. Afhængigt af arten er de generelt gule, orange eller en rødlig eller sortlig farve, og mange viser hvide bjælker eller pletter. Den største kan nå en længde på 17 cm (6+1/2 tommer), mens den mindste knap nok når 7–8 cm (2+3/4-3+1/4 tommer). Overraskende nok er alle klovnefisk født som hanner. De har evnen til at skifte køn, men vil kun gøre det for at blive den dominerende kvinde i en gruppe. Ændringen er irreversibel.\n\nI naturen spiser klovnefisk for det meste små hvirvelløse dyr, såsom rejer, krabber og dyreplankton. De spiser også alger og andet plantemateriale.'),
(92590, 2201, 'de', 'Anemonenfisch', 'Clownfische oder Anemonenfische sind Fische aus der Unterfamilie Amphiprioninae in der Familie Pomacentridae. Je nach Art sind sie insgesamt gelb, orange oder rötlich oder schwärzlich gefärbt, und viele zeigen weiße Balken oder Flecken. Die Größten können eine Länge von 17 cm (6+1⁄2 Zoll) erreichen, während die Kleinsten kaum 7–8 cm (2+3⁄4–3+1⁄4 Zoll) erreichen. Überraschenderweise sind alle Clownfische männlich geboren. Sie haben die Fähigkeit, ihr Geschlecht zu wechseln, werden dies aber nur tun, um die dominierende Frau einer Gruppe zu werden. Die Änderung ist irreversibel.\n\nIn freier Wildbahn fressen Clownfische meist kleine wirbellose Tiere wie Garnelen, Krabben und Zooplankton. Sie konsumieren auch Algen und andere Pflanzenstoffe.');
INSERT INTO `animaltext` (`id`, `animalId`, `languageCode`, `animalName`, `animalDescription`) VALUES
(92591, 2201, 'en', 'Clownfish', 'Clownfish or anemonefish are fishes from the subfamily Amphiprioninae in the family Pomacentridae. Depending on the species, they are overall yellow, orange, or a reddish or blackish color, and many show white bars or patches. The largest can reach a length of 17 cm (6+1⁄2 in), while the smallest barely achieve 7–8 cm (2+3⁄4–3+1⁄4 in). Surprisingly, all clownfish are born male. They have the ability to switch their sex, but will do so only to become the dominant female of a group. The change is irreversible.\n\nIn the wild, Clownfish mostly eat small invertebrates, such as shrimp, crabs, and zooplankton. They also consume algae and other plant matter.'),
(92592, 2201, 'es', 'Pez payaso', 'El pez payaso o pez anémona son peces de la subfamilia Amphiprioninae de la familia Pomacentridae. Dependiendo de la especie, son en general de color amarillo, naranja o rojizo o negruzco, y muchos muestran barras o parches blancos. El más grande puede alcanzar una longitud de 17 cm (6+1⁄2 in), mientras que el más pequeño apenas alcanza los 7–8 cm (2+3⁄4–3+1⁄4 in). Sorprendentemente, todos los peces payaso nacen machos. Tienen la capacidad de cambiar de sexo, pero lo harán solo para convertirse en la hembra dominante de un grupo. El cambio es irreversible.\n\nEn la naturaleza, el pez payaso come principalmente pequeños invertebrados, como camarones, cangrejos y zooplancton. También consumen algas y otras materias vegetales.'),
(92593, 2201, 'fr', 'Poisson-clown', 'Les poissons-clowns ou poissons-anémones sont des poissons de la sous-famille des Amphiprioninae de la famille des Pomacentridae. Selon les espèces, elles sont généralement de couleur jaune, orange ou rougeâtre ou noirâtre, et beaucoup présentent des barres ou des taches blanches. Le plus grand peut atteindre une longueur de 17 cm (6+1⁄2 po), tandis que le plus petit atteint à peine 7–8 cm (2+3⁄4–3+1⁄4 po). Étonnamment, tous les poissons-clowns naissent mâles. Elles ont la capacité de changer de sexe, mais ne le feront que pour devenir la femme dominante d\'un groupe. Le changement est irréversible.\n\nDans la nature, les poissons-clowns mangent principalement de petits invertébrés, tels que les crevettes, les crabes et le zooplancton. Ils consomment également des algues et d\'autres matières végétales.'),
(92594, 2201, 'nl', 'Anemoonvis', 'Clownvissen of anemoonvissen zijn vissen uit de onderfamilie Amphiprioninae in de familie Pomacentridae. Afhankelijk van de soort zijn ze over het algemeen geel, oranje of een roodachtige of zwartachtige kleur, en veel hebben witte strepen of vlekken. De grootste kan een lengte bereiken van 17 cm (6+1⁄2 in), terwijl de kleinste nauwelijks 7–8 cm (2+3⁄4–3+1⁄4 in) bereiken. Verrassend genoeg worden alle clownvissen als man geboren. Ze hebben de mogelijkheid om van geslacht te veranderen, maar zullen dit alleen doen om de dominante vrouw van een groep te worden. De verandering is onomkeerbaar.\n\nIn het wild eten clownvissen meestal kleine ongewervelde dieren, zoals garnalen, krabben en zoöplankton. Ze consumeren ook algen en ander plantaardig materiaal.'),
(92595, 621, 'da', 'komodovaran', 'Komodovaranen er medlem af øglefamilien Varanidae. Det er den største bevarede art af firben. Som et resultat af deres størrelse er komodovaraner toprovdyr og dominerer de økosystemer, de lever i. Komodo Dragons har en hale så lang som deres krop og en lang, gul, dybt kløvet tunge. Deres hud er normalt grå i farven forstærket af pansrede skæl, som indeholder bittesmå knogler kaldet osteodermer, der fungerer som en slags naturlig ringbrynje.\n\nKomodovaraner er kødædere. Deres kost er omfattende og omfatter hvirvelløse dyr, andre krybdyr (herunder mindre komodovaraner), fugle, fugleæg, små pattedyr, aber, vildsvin, geder, hjorte, heste og vandbøfler.'),
(92596, 621, 'de', 'Komodo-Waran', 'Der Komodowaran ist ein Mitglied der Warane-Familie Varanidae. Es ist die größte erhaltene Eidechsenart. Komodowarane sind aufgrund ihrer Größe Spitzenprädatoren und beherrschen die Ökosysteme, in denen sie leben. Komodowarane haben einen körperlangen Schwanz und eine lange, gelbe, tief gespaltene Zunge. Ihre Haut ist in der Regel grau gefärbt und durch gepanzerte Schuppen verstärkt, die winzige Knochen enthalten, die als Osteoderme bezeichnet werden und als eine Art natürliches Kettenhemd fungieren.\n\nKomodowarane sind Fleischfresser. Ihre Ernährung ist vielfältig und umfasst Wirbellose, andere Reptilien (einschließlich kleiner Komodowarane), Vögel, Vogeleier, kleine Säugetiere, Affen, Wildschweine, Ziegen, Hirsche, Pferde und Wasserbüffel.'),
(92597, 621, 'en', 'Komodo dragon', 'The Komodo Dragon is a member of the monitor lizard family Varanidae. It is the largest extant species of lizard. As a result of their size, Komodo dragons are apex predators and dominate the ecosystems in which they live. Komodo Dragons have a tail as long as their body and a long, yellow, deeply forked tongue. Their skin is usually gray in color reinforced by armored scales, which contain tiny bones called osteoderms that function as a sort of natural chain mail.\n\nKomodo Dragons are carnivores. Their diet is wide-ranging and includes invertebrates, other reptiles (including smaller Komodo Dragons), birds, bird eggs, small mammals, monkeys, wild boars, goats, deer, horses, and water buffalo.'),
(92598, 621, 'es', 'Dragón de Komodo', 'El dragón de Komodo es miembro de la familia de los lagartos monitores Varanidae. Es la especie de lagarto más grande que existe. Como resultado de su tamaño, los dragones de Komodo son depredadores ápice y dominan los ecosistemas en los que viven. Los dragones de Komodo tienen una cola tan larga como su cuerpo y una lengua larga, amarilla y profundamente bifurcada. Su piel suele ser de color gris reforzada por escamas blindadas, que contienen pequeños huesos llamados osteodermos que funcionan como una especie de cota de malla natural.\n\nLos dragones de Komodo son carnívoros. Su dieta es amplia e incluye invertebrados, otros reptiles (incluidos los dragones de Komodo más pequeños), aves, huevos de aves, pequeños mamíferos, monos, jabalíes, cabras, ciervos, caballos y búfalos de agua.'),
(92599, 621, 'fr', 'Varan de Komodo, dragon de Komodo', 'Le dragon de Komodo est un membre de la famille des varanidés. C\'est la plus grande espèce de lézard existante. En raison de leur taille, les dragons de Komodo sont des prédateurs de pointe et dominent les écosystèmes dans lesquels ils vivent. Les dragons de Komodo ont une queue aussi longue que leur corps et une longue langue jaune profondément fourchue. Leur peau est généralement de couleur grise renforcée par des écailles blindées, qui contiennent de minuscules os appelés ostéodermes qui fonctionnent comme une sorte de cotte de mailles naturelle.\n\nLes dragons de Komodo sont des carnivores. Leur alimentation est variée et comprend des invertébrés, d\'autres reptiles (y compris de petits dragons de Komodo), des oiseaux, des œufs d\'oiseaux, de petits mammifères, des singes, des sangliers, des chèvres, des cerfs, des chevaux et des buffles d\'eau.'),
(92600, 621, 'nl', 'Komodo-varaan', 'De Komodovaraan behoort tot de hagedissenfamilie Varanidae. Het is de grootste nog bestaande soort hagedis. Als gevolg van hun grootte zijn Komodovaranen toppredatoren en domineren ze de ecosystemen waarin ze leven. Komodovaranen hebben een staart zo lang als hun lichaam en een lange, gele, diep gevorkte tong. Hun huid is meestal grijs van kleur versterkt door gepantserde schubben, die kleine botten bevatten die osteodermen worden genoemd en die als een soort natuurlijke kettingpost functioneren.\n\nKomodovaranen zijn carnivoren. Hun dieet is breed en omvat ongewervelde dieren, andere reptielen (waaronder kleinere Komodovaranen), vogels, vogeleieren, kleine zoogdieren, apen, wilde zwijnen, geiten, herten, paarden en waterbuffels.'),
(92601, 30250, 'da', 'Snow Sheep', 'The Snow Sheep, also known as the Siberian Snow Sheep or the Kamchatka Sheep, is a subspecies of wild sheep found primarily in the mountainous regions of eastern Siberia. They have a thick, woolly coat that provides insulation against harsh winter conditions. The coat is usually a mix of brown, gray, and white, helping them blend into their snowy surroundings. Males possess large, curved horns that can grow up to 30 inches (76 cm) long, while females have smaller, less pronounced horns.\n\nThey are herbivorous grazers, feeding on grasses, sedges, and other vegetation. \n\n'),
(92602, 30250, 'de', 'Snow Sheep', 'The Snow Sheep, also known as the Siberian Snow Sheep or the Kamchatka Sheep, is a subspecies of wild sheep found primarily in the mountainous regions of eastern Siberia. They have a thick, woolly coat that provides insulation against harsh winter conditions. The coat is usually a mix of brown, gray, and white, helping them blend into their snowy surroundings. Males possess large, curved horns that can grow up to 30 inches (76 cm) long, while females have smaller, less pronounced horns.\n\nThey are herbivorous grazers, feeding on grasses, sedges, and other vegetation. \n\n'),
(92603, 30250, 'en', 'Snow Sheep', 'The Snow Sheep, also known as the Siberian Snow Sheep or the Kamchatka Sheep, is a subspecies of wild sheep found primarily in the mountainous regions of eastern Siberia. They have a thick, woolly coat that provides insulation against harsh winter conditions. The coat is usually a mix of brown, gray, and white, helping them blend into their snowy surroundings. Males possess large, curved horns that can grow up to 30 inches (76 cm) long, while females have smaller, less pronounced horns.\n\nThey are herbivorous grazers, feeding on grasses, sedges, and other vegetation.'),
(92604, 30250, 'es', 'Oveja de nieve', 'La oveja de las nieves, también conocida como la oveja de las nieves siberianas o la oveja de Kamchatka, es una subespecie de oveja salvaje que se encuentra principalmente en las regiones montañosas del este de Siberia. Tienen un pelaje grueso y lanudo que proporciona aislamiento contra las duras condiciones invernales. El pelaje suele ser una mezcla de marrón, gris y blanco, lo que les ayuda a mezclarse con su entorno nevado. Los machos poseen cuernos grandes y curvos que pueden crecer hasta 30 pulgadas (76 cm) de largo, mientras que las hembras tienen cuernos más pequeños y menos pronunciados.\n\nSon herbívoros herbívoros que se alimentan de pastos, juncos y otra vegetación.'),
(92605, 30250, 'fr', 'Mouton des neiges', 'Le mouton des neiges, également connu sous le nom de mouton des neiges de Sibérie ou de mouton du Kamchatka, est une sous-espèce de moutons sauvages que l\'on trouve principalement dans les régions montagneuses de la Sibérie orientale. Ils ont un manteau épais et laineux qui offre une isolation contre les conditions hivernales difficiles. Le pelage est généralement un mélange de brun, de gris et de blanc, ce qui les aide à se fondre dans leur environnement enneigé. Les mâles possèdent de grandes cornes incurvées qui peuvent atteindre 76 cm de long, tandis que les femelles ont des cornes plus petites et moins prononcées.\n\nCe sont des herbivores qui se nourrissent d\'herbes, de carex et d\'autres végétaux.'),
(92606, 30250, 'nl', 'Sneeuwschaap', 'Het Sneeuwschaap, ook bekend als het Siberische Sneeuwschaap of het Kamtsjatka Schaap, is een ondersoort van wilde schapen die voornamelijk in de bergachtige regio\'s van Oost-Siberië voorkomt. Ze hebben een dikke, wollige vacht die isolatie biedt tegen barre winterse omstandigheden. De vacht is meestal een mix van bruin, grijs en wit, waardoor ze in hun besneeuwde omgeving opgaan. Mannetjes hebben grote, gebogen hoorns die tot 76 cm lang kunnen worden, terwijl vrouwtjes kleinere, minder uitgesproken hoorns hebben.\n\nHet zijn plantenetende grazers die zich voeden met grassen, zegges en andere vegetatie.'),
(92607, 1113, 'da', 'Murin mus opossum', 'Linnés Mouse Opossum, også kendt som Common eller Murine Mouse Opossum, er en sydamerikansk pungdyr af familien Didelphidae. Den er bleg beige til grå på undersiden med kort, glat pels. Ansigtet ser ud til at have en sort maske på, øjnene er fremtrædende, og ørerne er meget oprejste. Halen, som hunnerne bruger til at bære blade, er meget længere end resten af kroppen. Det er et natligt væsen, der gemmer sig i løbet af dagen i et net af kviste på en trægren, et træhul eller en gammel fuglerede.\n\nMurine Mouse Opossums lever af insekter, edderkopper og nogle små hvirveldyr som firben, fugleæg og kyllinger. De vil også spise noget frugt.'),
(92608, 1113, 'de', 'Maus-Maus-Opossum', 'Linnaeus \'Maus-Opossum, auch bekannt als Gewöhnliches oder Maus-Maus-Opossum, ist ein südamerikanisches Beuteltier aus der Familie der Didelphidae. Es ist blassbeige bis grau an den Unterteilen mit kurzem, glattem Fell. Sein Gesicht scheint eine schwarze Maske zu tragen, seine Augen sind auffällig und seine Ohren sind sehr aufrecht. Sein Schwanz, den Weibchen verwenden, um Blätter zu tragen, ist viel länger als der Rest seines Körpers. Eine nächtliche Kreatur, die sich tagsüber in einem Netz von Zweigen auf einem Baumzweig, einem Baumloch oder einem alten Vogelnest versteckt.\n\nMaus-Opossums ernähren sich von Insekten, Spinnen und einigen kleinen Wirbeltieren wie Eidechsen, Vogeleiern und Küken. Sie werden auch etwas Obst essen.'),
(92609, 1113, 'en', 'Murine Mouse Opossum', 'Linnaeus\'s Mouse Opossum, also known as the Common or Murine Mouse Opossum, is a South American marsupial of the family Didelphidae. It is pale beige to grey on its underparts with short, smooth fur. Its face appears to have a black mask on it, its eyes are prominent, and its ears are very upright. Its tail, which females use to carry leaves, is much longer than the rest of its body. A nocturnal creature, it shelters during the day in a mesh of twigs on a tree branch, a tree hole, or an old bird\'s nest.\n\nMurine Mouse Opossums feed on insects, spiders, and some small vertebrates like lizards, bird eggs, and chicks. They will also eat some fruit.'),
(92610, 1113, 'es', 'Zarigüeya de ratón murino', 'El zarigüeyo de Linneo, también conocido como zarigüeya común o murina, es un marsupial sudamericano de la familia Didelphidae. Es de color beige pálido a gris en sus partes inferiores con pelo corto y liso. Su cara parece tener una máscara negra, sus ojos son prominentes y sus orejas están muy erguidas. Su cola, que las hembras utilizan para transportar hojas, es mucho más larga que el resto de su cuerpo. Una criatura nocturna, se refugia durante el día en una malla de ramitas en una rama de árbol, un agujero de árbol o un viejo nido de pájaro.\n\nLos zarigüeyas murinas se alimentan de insectos, arañas y algunos pequeños vertebrados como lagartos, huevos de aves y polluelos. También comerán algo de fruta.'),
(92611, 1113, 'fr', 'Opossum de souris murine', 'L\'opossum de souris de Linnaeus, également connu sous le nom d\'opossum de souris commune ou murine, est un marsupial sud-américain de la famille des Didelphidae. Il est beige pâle à gris sur ses parties inférieures avec une fourrure courte et lisse. Son visage semble porter un masque noir, ses yeux sont proéminents et ses oreilles sont très droites. Sa queue, que les femelles utilisent pour porter les feuilles, est beaucoup plus longue que le reste de son corps. Créature nocturne, elle s\'abrite pendant la journée dans un filet de brindilles sur une branche d\'arbre, un trou d\'arbre ou un vieux nid d\'oiseau.\n\nLes opossums de souris murines se nourrissent d\'insectes, d\'araignées et de certains petits vertébrés comme les lézards, les œufs d\'oiseaux et les poussins. Ils mangeront également des fruits.'),
(92612, 1113, 'nl', 'Muizenmuis Opossum', 'Linnaeus \'muizenopossum, ook bekend als de gewone of muizenmuisopossum, is een Zuid-Amerikaanse buideldier van de familie Didelphidae. Het is lichtbeige tot grijs aan de onderkant met een korte, gladde vacht. Zijn gezicht lijkt een zwart masker te hebben, zijn ogen zijn prominent aanwezig en zijn oren staan erg rechtop. Zijn staart, die vrouwtjes gebruiken om bladeren te dragen, is veel langer dan de rest van zijn lichaam. Een nachtelijk wezen, het beschermt zich overdag in een net van twijgen op een boomtak, een boomgat of een oud vogelnest.\n\nMuizenmuisopossums voeden zich met insecten, spinnen en enkele kleine gewervelde dieren zoals hagedissen, vogeleieren en kuikens. Ze zullen ook wat fruit eten.'),
(92613, 30169, 'da', 'Dwarf Hamster', 'Dwarf Hamsters are small mammals with stout bodies, short tails, and stubby legs. They are usually two to three inches (5-7.6 cm) in length, although some can be smaller. While these animals do not hibernate in the winter, they will enter a period of inactivity called torpor, which can range from a few days to several weeks. The young are born hairless and blind and depend on the female to take care of them. Dwarf Hamsters have become a popular pet over the years due to their relatively low maintenance. They are also fairly easy to tame and are more social than other hamsters.\n\nThese mammals are omnivores and feed on a variety of food, including seeds, grains, fruits, berries, and invertebrates. \n\n'),
(92614, 30169, 'de', 'Dwarf Hamster', 'Dwarf Hamsters are small mammals with stout bodies, short tails, and stubby legs. They are usually two to three inches (5-7.6 cm) in length, although some can be smaller. While these animals do not hibernate in the winter, they will enter a period of inactivity called torpor, which can range from a few days to several weeks. The young are born hairless and blind and depend on the female to take care of them. Dwarf Hamsters have become a popular pet over the years due to their relatively low maintenance. They are also fairly easy to tame and are more social than other hamsters.\n\nThese mammals are omnivores and feed on a variety of food, including seeds, grains, fruits, berries, and invertebrates. \n\n'),
(92615, 30169, 'en', 'Dwarf Hamster', 'Dwarf Hamsters are small mammals with stout bodies, short tails, and stubby legs. They are usually two to three inches (5-7.6 cm) in length, although some can be smaller. While these animals do not hibernate in the winter, they will enter a period of inactivity called torpor, which can range from a few days to several weeks. The young are born hairless and blind and depend on the female to take care of them. Dwarf Hamsters have become a popular pet over the years due to their relatively low maintenance. They are also fairly easy to tame and are more social than other hamsters.\n\nThese mammals are omnivores and feed on a variety of food, including seeds, grains, fruits, berries, and invertebrates.'),
(92616, 30169, 'es', 'Cricetulus migratorius', 'Los hámsters enanos son pequeños mamíferos con cuerpos robustos, colas cortas y patas rechonchas. Por lo general, miden de dos a tres pulgadas (5-7,6 cm) de largo, aunque algunos pueden ser más pequeños. Si bien estos animales no hibernan en el invierno, entrarán en un período de inactividad llamado letargo, que puede variar desde unos pocos días hasta varias semanas. Los jóvenes nacen sin pelo y ciegos y dependen de la hembra para cuidarlos. Los hámsters enanos se han convertido en una mascota popular a lo largo de los años debido a su mantenimiento relativamente bajo. También son bastante fáciles de domesticar y son más sociables que otros hámsters.\n\nEstos mamíferos son omnívoros y se alimentan de una variedad de alimentos, incluyendo semillas, granos, frutas, bayas e invertebrados.'),
(92617, 30169, 'fr', 'Cricetulus migratorius', 'Les hamsters nains sont de petits mammifères au corps robuste, à la queue courte et aux pattes trapues. Ils mesurent généralement de deux à trois pouces (5 à 7,6 cm) de longueur, bien que certains puissent être plus petits. Bien que ces animaux n\'hibernent pas en hiver, ils entreront dans une période d\'inactivité appelée torpeur, qui peut aller de quelques jours à plusieurs semaines. Les jeunes naissent sans poils et aveugles et dépendent de la femelle pour prendre soin d\'eux. Les hamsters nains sont devenus un animal de compagnie populaire au fil des ans en raison de leur entretien relativement faible. Ils sont également assez faciles à apprivoiser et sont plus sociaux que les autres hamsters.\n\nCes mammifères sont omnivores et se nourrissent d\'une variété d\'aliments, notamment de graines, de céréales, de fruits, de baies et d\'invertébrés.'),
(92618, 30169, 'nl', 'Dwerghamster', 'Dwerghamsters zijn kleine zoogdieren met stevige lichamen, korte staarten en stompe poten. Ze zijn meestal 5-7,6 cm lang, hoewel sommige kleiner kunnen zijn. Hoewel deze dieren in de winter geen winterslaap houden, zullen ze een periode van inactiviteit ingaan die torpor wordt genoemd, die kan variëren van een paar dagen tot enkele weken. De jongen worden haarloos en blind geboren en zijn afhankelijk van het vrouwtje om voor hen te zorgen. Dwerghamsters zijn door de jaren heen een populair huisdier geworden vanwege hun relatief lage onderhoudskosten. Ze zijn ook vrij gemakkelijk te temmen en zijn socialer dan andere hamsters.\n\nDeze zoogdieren zijn alleseters en voeden zich met een verscheidenheid aan voedsel, waaronder zaden, granen, fruit, bessen en ongewervelde dieren.');

